#[test]
fn advanced_formations_link_breach_support_to_a_military_escort() {
    let mut game = Game::new_full(1, 20, 14, 71_001, 30, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    let position = *game
        .map
        .tiles
        .iter()
        .find(|(_, tile)| game.rules.is_passable(tile) && !game.rules.is_water(tile))
        .map(|(position, _)| position)
        .unwrap();
    let ram = game.spawn_test_unit("battering_ram", 0, position);
    let cavalry = game.spawn_test_unit("heavy_chariot", 0, position);
    let spear = game.spawn_test_unit("spearman", 0, position);

    let ai = AdvancedAi::new();
    ai.advanced_formations(&mut game, 0);

    let escort = game.units[&ram]
        .linked_to
        .expect("the support unit is paired with an available military escort");
    assert!(
        [cavalry, spear].contains(&escort),
        "the generic support rule selects one of the available military escorts"
    );
    assert_eq!(game.units[&escort].linked_to, Some(ram));
    let unpaired = if escort == cavalry { spear } else { cavalry };
    assert_eq!(game.units[&unpaired].linked_to, None);
}

/// The same separation applies on land, where the current live game was
/// repeatedly issuing `ENTER_FORMATION`, `EXIT_FORMATION`, then a delayed
/// march.  A deployment controller keeps the native gene off and instead
/// sends the guard through the ordinary shadow path.
#[test]
fn deployed_live_shadow_does_not_link_a_land_settler_after_the_native_gene_is_withheld() {
    let mut game = Game::new_full(1, 20, 14, 71_002, 30, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    let land = *game
        .map
        .tiles
        .iter()
        .find(|(_, tile)| game.rules.is_passable(tile) && !game.rules.is_water(tile))
        .map(|(position, _)| position)
        .expect("the board has passable land");
    let settler = game.spawn_test_unit("settler", 0, land);
    let escort = game.spawn_test_unit("heavy_chariot", 0, land);

    let mut historical = AdvancedAi::new();
    historical.settlement_safety = true;
    historical.settler_targets.insert(settler, land);
    historical.settler_blocked_turns.insert(settler, 1);
    historical.advanced_formations(&mut game, 0);
    assert_eq!(game.units[&settler].linked_to, Some(escort));
    let _ = game.apply(0, &Action::UnlinkUnits { unit: settler });

    let mut deployed = AdvancedAi::new();
    deployed.enable_live_bridge();
    deployed.settler_targets.insert(settler, land);
    deployed.settler_blocked_turns.insert(settler, 1);
    assert!(deployed.live_formationless_settler_shadow);
    deployed.advanced_formations(&mut game, 0);
    assert_eq!(game.units[&settler].linked_to, None);
    assert_eq!(game.units[&escort].linked_to, None);
}

/// ★★★★ Several viable caravels existed in run
/// civvis-20260816T223457Z, but only the lowest-id one was assigned to
/// explore; the others stood down or circled while six city-states stayed
/// uncontacted. See `BasicAi::naval_recon` and `naval_explorer`. A lone
/// unlinked ship on an unexplored sea explores; a spare eligible hull joins
/// it; a charted sea has none; the withheld arm names none.
#[test]
fn up_to_two_eligible_ships_on_an_unexplored_sea_are_the_empires_explorers() {
    // At war: the wartime unit path is the one the live seat spends most
    // of its turns in, and it is where a ship never explored before.
    let mut game = Game::new_full(2, 20, 14, 71_001, 30, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    game.at_war.insert((0, 1));
    game.current = 0;
    game.players[0].techs.insert(crate::name!("sailing"));
    // A water tile the galley can actually sail out of (coast, not an
    // ocean it cannot enter yet): probe candidates on the board.
    let mut waters: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(_, tile)| game.rules.is_water(tile) && game.rules.is_passable(tile))
        .map(|(position, _)| *position)
        .collect();
    waters.sort_unstable();
    let mut placed = None;
    for water in waters {
        let galley = game.spawn_test_unit("galley", 0, water);
        if game
            .nbrs(water)
            .into_iter()
            .any(|n| game.can_move(galley, n))
        {
            placed = Some((water, galley));
            break;
        }
        game.remove_unit(galley);
    }
    let (water, galley) = placed.expect("some water tile lets a galley sail");
    // Only the ship's own neighbourhood is known; the rest of the sea is dark.
    let near: Vec<Pos> = game.wdisk(water, 2);
    game.players[0].explored.clear();
    game.players[0].explored.extend(near);

    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    // The Firaxis order adapter also commits explorers to separated fog
    // goals, so exercise the two-hull branch under its shipped settings.
    live.enable_explore_commit();
    assert!(live.naval_recon(), "the live seat carries the treatment");
    assert_eq!(
        live.naval_explorer(&game, 0),
        vec![galley],
        "the lone ship explores"
    );

    // A second hull joins the first. Both are already built, unlinked, and
    // can chart; this does not ask production for another one.
    let second = game.spawn_test_unit("galley", 0, water);
    let mut expected = vec![galley, second];
    expected.sort_unstable();
    assert_eq!(live.naval_explorer(&game, 0), expected);

    // The withheld arm at war leaves the same ship where it is: the war
    // path never explored before this treatment.
    {
        let mut idle = game.clone();
        let idle_galley = idle.units.keys().copied().min().unwrap();
        let start = idle.units[&idle_galley].pos;
        let mut withheld = AdvancedAi::new();
        withheld.enable_live_bridge_universe();
        withheld.disable_naval_recon();
        let plan = withheld.assess(&idle, 0);
        let _ =
            withheld.advanced_military_step_with_decline(&mut idle, 0, idle_galley, &plan, false);
        assert_eq!(
            idle.units[&idle_galley].pos, start,
            "without the treatment the war path does not send the ship exploring"
        );
    }

    let plan = live.assess(&game, 0);
    let before = game.units[&galley].pos;
    let explored_before = game.players[0].explored.len();
    assert!(
        live.advanced_military_step_with_decline(&mut game, 0, galley, &plan, false),
        "the explorer acts"
    );
    let after = game.units[&galley].pos;
    assert!(
        after != before || game.players[0].explored.len() > explored_before,
        "it moved toward the dark water ({before:?} -> {after:?})"
    );
    let plan = live.assess(&game, 0);
    let second_before = game.units[&second].pos;
    let explored_before = game.players[0].explored.len();
    assert!(
        live.advanced_military_step_with_decline(&mut game, 0, second, &plan, false),
        "the second explorer acts"
    );
    assert!(
        game.units[&second].pos != second_before
            || game.players[0].explored.len() > explored_before,
        "the second hull also moves toward dark water"
    );

    // A charted sea has no explorer; the withheld arm names none.
    let mut charted = game.clone();
    let all: Vec<Pos> = charted.map.tiles.keys().copied().collect();
    charted.players[0].explored.extend(all);
    assert!(live.naval_explorer(&charted, 0).is_empty());
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge_universe();
    withheld.disable_naval_recon();
    assert!(withheld.naval_explorer(&game, 0).is_empty());
    // Production carries the fleet since the 2026-08-17 promotion; the
    // frozen anchor still sails nothing.
    assert!(AdvancedAi::new().naval_recon());
    assert!(!AdvancedAi::legacy().naval_recon());
}

/// ★★★★★ THE ARM WAS DEAD ON THE SEAT IT WAS BUILT FOR. Every test above
/// runs on a native board, where the whole sea exists and `explored` is the
/// part of it the seat has looked at. The Civilization VI mirror writes only
/// the plots the host revealed, `explored` IS that set, and the rest of the
/// world is `unknown` terrain — not water — so "a water tile outside
/// `explored`" was false on every live turn of every live game: 25 runs on
/// 2026-08-18, zero sea-scout reservations, and run `civvis-20260818T225716Z`
/// at t169 with Cartography and Square Rigging in hand, a coastal Ostia since
/// t44, 559 of 3404 plots seen, two of five rivals met, and NO SHIP EVER
/// BUILT. On a mirrored board the arm now reads the sea's frontier — the fog
/// the mirror grows past charted water — reserves the hull, and sails it.
#[test]
fn on_a_mirrored_board_the_sea_scout_arm_reads_the_fog_past_charted_water() {
    use crate::mirror::{apply_explored, grow_frontier, rebuild_game, Snapshot, TilesChunk};
    let center = crate::hex::offset_to_axial(12, 10);
    let mut plots = Vec::new();
    for y in 0..24 {
        for x in 0..24 {
            let here = crate::hex::offset_to_axial(x, y);
            let d = crate::hex::distance(here, center);
            let terrain = match d {
                0..=1 => "TERRAIN_GRASS",
                2..=4 => "TERRAIN_COAST",
                _ => continue,
            };
            plots.push(serde_json::json!({"x": x, "y": y, "t": terrain}));
        }
    }
    let chunk: TilesChunk = serde_json::from_value(serde_json::json!({
        "turn": 44, "width": 24, "height": 24, "chunk": 1, "plots": plots,
    }))
    .expect("the fixture chunk parses like a mod export");
    let snapshot = Snapshot::from_chunks(&[chunk]);
    let mut game = rebuild_game(&snapshot, 4, 7);
    // The rebuilt board keeps the generated seats' opening units; the mirror
    // proper replaces them with the host's roster. Clear them so the only
    // hostile in sight is the one this fixture places, which is none.
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    game.current = 0;
    apply_explored(&mut game, &snapshot);
    game.players[0].techs.insert(crate::name!("sailing"));
    // The city stands on the island's rim, its centre touching the coast.
    let rim = game
        .nbrs(center)
        .into_iter()
        .min()
        .expect("the island has a rim");
    let city = game.place_city(0, rim, None);
    assert!(crate::ai::BasicAi::empire_is_coastal(&game, 0));
    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    // The Firaxis order adapter commits explorers to fog goals; run under
    // its shipped settings so the held goal can be read back.
    live.enable_explore_commit();
    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };

    // The board as every live game saw it: no frontier at the water's edge.
    // Nothing reads as unseen water, so nothing is missing and nothing sails.
    assert!(
        !live.base.naval_recon_is_the_missing_arm(&game, 0),
        "with no sea frontier the world reads as charted — the live seat's dead gate"
    );
    let shore = game
        .map
        .tiles
        .iter()
        .filter(|(_, tile)| game.rules.is_water(tile))
        .map(|(pos, _)| *pos)
        .max_by_key(|pos| (crate::hex::distance(*pos, center), *pos))
        .expect("the island has charted coast");
    let galley = game.spawn_test_unit("galley", 0, shore);
    assert!(live.naval_explorer(&game, 0).is_empty());
    game.remove_unit(galley);

    // The mirror grows the sea's prior past the charted water.
    grow_frontier(&mut game, &snapshot, 6);
    assert!(crate::ai::BasicAi::unseen_water_remains(&game, 0));
    assert!(
        live.base.naval_recon_is_the_missing_arm(&game, 0),
        "fog past the coast and no hull afloat: the sea scout is the missing arm"
    );

    // V3 aligns the advanced reservation path with the Basic picker: when a
    // land eye is also missing, the broader continental frontier takes the
    // one idle queue before the sea scout. Keep this on a clone so the v1
    // mirror regression below still proves that its ordinary reservation is
    // available.
    let mut land_gap = game.clone();
    land_gap.players[0].explored.remove(&center);
    let mut land_first = AdvancedAi::new();
    land_first.enable_live_bridge_universe();
    land_first.enable_naval_recon_3();
    assert!(
        land_first.base.recon_is_the_missing_arm(&land_gap, 0),
        "the fixture gives v3 an uncharted land frontier as well as the sea fog"
    );
    land_first.reserve_idle_naval_recon(&mut land_gap, 0, &plan);
    assert!(
        land_gap.cities[&city].queue.is_empty(),
        "v3 leaves the idle coastal queue for the simultaneous land eye"
    );
    land_first.reserve_idle_land_recon(&mut land_gap, 0, &plan);
    assert!(
        matches!(
            land_gap.cities[&city].queue.first(),
            Some(Item::Unit { unit }) if unit == "scout"
        ),
        "the land scout can claim the queue that v3 declined"
    );

    live.reserve_idle_naval_recon(&mut game, 0, &plan);
    assert!(
        matches!(
            game.cities[&city].queue.first(),
            Some(Item::Unit { unit }) if game.rules.units[unit].domain.as_deref() == Some("sea")
        ),
        "the idle coastal city lays the hull down: {:?}",
        game.cities[&city].queue
    );

    // And a hull on the shore is the empire's explorer, sailing for the fog.
    let galley = game.spawn_test_unit("galley", 0, shore);
    assert_eq!(live.naval_explorer(&game, 0), vec![galley]);
    assert!(
        !live.base.naval_recon_is_the_missing_arm(&game, 0),
        "one eye afloat completes the peacetime arm"
    );
    // At peace — no major at war, no raider at home — which is the path that
    // never sailed a ship before: `BasicAi::military_step`'s enemy list holds
    // the barbarian seat on every turn, so it took the hull to
    // `peacetime_step` at war, where a non-Recon unit never explores.
    let journal = crate::reasoning::Journal::recording();
    live.attach_journal(journal.handle());
    let plan = live.assess(&game, 0);
    let before = game.units[&galley].pos;
    let explored_before = game.players[0].explored.len();
    assert!(
        live.advanced_military_step_with_decline(&mut game, 0, galley, &plan, false),
        "the explorer acts"
    );
    let after = game.units[&galley].pos;
    assert!(
        after != before || game.players[0].explored.len() > explored_before,
        "it sailed toward the fog at peace ({before:?} -> {after:?})"
    );
    let goal = live
        .base
        .explore_goal
        .borrow()
        .get(&galley)
        .map(|(goal, _)| *goal);
    let said: Vec<String> = journal
        .since(0)
        .thoughts
        .iter()
        .map(|t| format!("{} | {}", t.headline, t.detail))
        .collect();
    let goal = goal.unwrap_or_else(|| {
        panic!("the committed explorer holds a goal; {before:?} -> {after:?}, journal {said:#?}")
    });
    let tile = &game.map.tiles[&goal];
    assert!(
        game.rules.is_unknown(tile) && tile.assumed_navigable,
        "and the goal is the sea's frontier, not charted water: {goal:?}"
    );
}

#[test]
fn a_wartime_naval_recon_arm_reserves_one_idle_coastal_city() {
    let mut game = Game::new_full(2, 30, 18, 71_003, 100, 0, false);
    game.current = 0;
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|uid| game.units[uid].kind == "settler")
        .expect("the first major starts with a Settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("the fixture founds a capital");
    for uid in game.player_unit_ids(0) {
        game.remove_unit(uid);
    }
    let city = game.player_city_ids(0)[0];
    let city_pos = game.cities[&city].pos;
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
        tile.resource = None;
        tile.improvement = None;
    }
    let mut waterway = Vec::new();
    let mut current = city_pos;
    for distance in 1..=super::super::NAVAL_RECON_MIN_WATERWAY_TILES {
        current = game
            .nbrs(current)
            .into_iter()
            .find(|pos| {
                game.map.tiles.contains_key(pos) && game.wdist(city_pos, *pos) == distance as i32
            })
            .expect("an interior city has a straight coastal launch route");
        game.map.tiles.get_mut(&current).unwrap().terrain = crate::name!("coast");
        waterway.push(current);
    }
    game.players[0].explored.remove(waterway.last().unwrap());
    game.players[0].techs.insert(crate::name!("sailing"));
    game.at_war.insert((0, 1));
    game.spawn_test_unit("galley", 1, *waterway.last().unwrap());
    game.spawn_test_unit("galley", 0, waterway[0]);

    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    assert!(live.base.naval_recon_is_the_missing_arm(&game, 0));

    // The spare eye must not leapfrog the shared recovery rule. One
    // existing Galley covers the emergency-garrison exception on this
    // one-city war, so a bankrupt empire repairs its balance first.
    let mut bankrupt = game.clone();
    bankrupt.players[0].gold = 0.0;
    bankrupt.players[0].gold_per_turn = -1.0;
    assert!(live.live_war_economy_requires_recovery(&bankrupt, 0, &live.counts(&bankrupt, 0)));
    live.reserve_idle_naval_recon(&mut bankrupt, 0, &plan);
    assert!(
        bankrupt.cities[&city].queue.is_empty(),
        "a naval scout cannot bypass the live war-economy recovery path"
    );

    // Production reserves the hull too since the 2026-08-17 promotion;
    // only the frozen anchor keeps the historical empty queue.
    let mut frozen_game = game.clone();
    let frozen = AdvancedAi::legacy();
    frozen.reserve_idle_naval_recon(&mut frozen_game, 0, &plan);
    assert!(
        frozen_game.cities[&city].queue.is_empty(),
        "the frozen controller does not reserve a naval scout"
    );

    live.reserve_idle_naval_recon(&mut game, 0, &plan);
    assert!(matches!(
        game.cities[&city].queue.first(),
        Some(Item::Unit { unit }) if unit == "galley"
    ));
    live.reserve_idle_naval_recon(&mut game, 0, &plan);
    assert_eq!(
        game.cities[&city]
            .queue
            .iter()
            .filter(|item| matches!(item, Item::Unit { unit } if unit == "galley"))
            .count(),
        1,
        "the queued hull completes the bounded second-eye reservation"
    );
}

#[test]
fn a_lake_bound_ship_yields_the_naval_explorer_job_to_an_open_water_hull() {
    let mut game = Game::new_full(2, 20, 14, 71_002, 30, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    game.current = 0;
    game.players[0].techs.insert(crate::name!("sailing"));
    game.players[0].explored.clear();
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
        tile.resource = None;
        tile.improvement = None;
    }
    let city_positions: Vec<Pos> = game.cities.values().map(|city| city.pos).collect();
    let interiors: Vec<Pos> = game
        .map
        .tiles
        .values()
        .filter(|tile| {
            game.wdisk(tile.pos, 4).len() == 61
                && city_positions
                    .iter()
                    .all(|city| game.wdist(*city, tile.pos) >= 5)
        })
        .map(|tile| tile.pos)
        .collect();
    let lake_centre = interiors[0];
    let open_origin = interiors
        .iter()
        .copied()
        .find(|pos| game.wdist(lake_centre, *pos) >= 8)
        .expect("a separate interior patch for open water");

    let lake_neighbors = game.nbrs(lake_centre);
    let lake_first = lake_neighbors[0];
    let lake_second = lake_neighbors
        .into_iter()
        .find(|pos| *pos != lake_first && game.wdist(lake_first, *pos) == 1)
        .expect("the lake has two adjacent shore tiles");
    for pos in [lake_first, lake_second] {
        game.map.tiles.get_mut(&pos).unwrap().terrain = crate::name!("coast");
    }

    let mut open_water = Vec::new();
    let mut current = open_origin;
    for distance in 1..=super::super::NAVAL_RECON_MIN_WATERWAY_TILES {
        current = game
            .nbrs(current)
            .into_iter()
            .find(|pos| game.wdist(open_origin, *pos) == distance as i32)
            .expect("the open route stays inside the map");
        game.map.tiles.get_mut(&current).unwrap().terrain = crate::name!("coast");
        open_water.push(current);
    }

    // Spawn the stranded hull first: it has the smaller id, which is the
    // exact ordering that used to starve the later, useful scout.
    let trapped = game.spawn_test_unit("galley", 0, lake_first);
    let free = game.spawn_test_unit("galley", 0, open_water[0]);
    assert!(
        !BasicAi::naval_recon_ship_can_chart(&game, 0, trapped)
            && BasicAi::naval_recon_ship_can_chart(&game, 0, free),
        "the fixture separates a two-hex lake from an open coastal route"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    assert_eq!(
        live.naval_explorer(&game, 0),
        vec![free],
        "a trapped lower-id Galley cannot take the explorer job from the open-water hull"
    );
}

/// The measured t174 purchase: five gold in the treasury, one turn after
/// Civilization VI disbanded a third of the army to pay the upkeep bill,
/// and CIVVIS bought another Field Cannon because the gate only ever asked
/// about faith.
#[test]
fn a_broke_empire_stops_buying_soldiers_with_faith() {
    let mut game = Game::new(2, 20, 14, 91_501, 80, 0);
    let unit = game
        .rules
        .units
        .iter()
        .find(|(_, spec)| spec.class == "military" && spec.maintenance > 0.0)
        .map(|(name, _)| name.to_string())
        .expect("the ruleset has a military unit that costs upkeep");
    let upkeep = game.rules.units[unit.as_str()].maintenance;

    let mut ai = AdvancedAi::new();
    ai.enable_solvent_faith_army();

    // The measured state: broke, and losing money.
    game.players[0].gold = 5.0;
    game.players[0].gold_per_turn = -3.0;
    assert!(
        !ai.faith_military_is_affordable(&game, 0, &unit),
        "an empire on five gold and falling must not take on more upkeep"
    );

    // A deep balance carries the bill even while income is short.
    game.players[0].gold = upkeep * FAITH_ARMY_SOLVENCY_TURNS + 1.0;
    assert!(
        ai.faith_military_is_affordable(&game, 0, &unit),
        "a treasury that can pay for {FAITH_ARMY_SOLVENCY_TURNS} turns may still arm"
    );

    // And a surplus never needs the balance at all.
    game.players[0].gold = 0.0;
    game.players[0].gold_per_turn = upkeep + 1.0;
    assert!(
        ai.faith_military_is_affordable(&game, 0, &unit),
        "income that covers the new bill is sufficient on its own"
    );
}

/// The frozen controllers must keep buying exactly as they always have.
#[test]
fn the_default_controller_keeps_the_faith_army_ungated() {
    let mut game = Game::new(2, 20, 14, 91_502, 80, 0);
    let unit = game
        .rules
        .units
        .iter()
        .find(|(_, spec)| spec.class == "military" && spec.maintenance > 0.0)
        .map(|(name, _)| name.to_string())
        .expect("the ruleset has a military unit that costs upkeep");
    game.players[0].gold = 5.0;
    game.players[0].gold_per_turn = -3.0;

    for frozen in [AdvancedAi::new(), AdvancedAi::legacy()] {
        assert!(!frozen.solvent_faith_army);
        assert!(
            frozen.faith_military_is_affordable(&game, 0, &unit),
            "a tournament controller must not change what it buys"
        );
    }
    let mut live = AdvancedAi::new();
    live.enable_solvent_faith_army();
    assert!(
        !live.faith_military_is_affordable(&game, 0, &unit),
        "precondition: the same board DOES refuse once the gate is enabled"
    );
}

/// ⚠ **What the production constructor turns on, and what each part cost
/// to establish.** The assertions below pin the bundle; this ledger records
/// which parts of it have an individual outcome number, because the pin
/// alone cannot tell a measured component from an assumed one.
///
/// | flag | individual evidence |
/// |---|---|
/// | `bounded_recovery` | **NULL over 600 maps** on two disjoint seeds; removed from production 2026-08-17. The live bridge and explicit evaluator treatments retain the flag. |
/// | `city_target_floor = 6` | **REMOVED 2026-08-10.** Withholding it passed the promotion matrix — deployment-online 55.9%, Elo +41 (CI +7..+76), p=0.0000; compact-standard flat. Its solo axis had already measured null (49.6%, Elo −3, p=0.9007) before it shipped inside this composite. |
/// | `envoy_priority`, `adjacency_site_planning`, `settler_commit`, `research_economy`, `plan_city_target`, `amenity_districts`, `siege_muster`, `unit_objective_memory` | no individual outcome number located in `docs/EVAL.md`. |
///
/// A composite may legitimately pass a gate while a component is null on
/// its own, and the 2026-08-01 promotion was such a composite. The two
/// confirmed nulls above are now out of the production constructor; what
/// remains is that **most of the retained bundle has never been priced
/// apart**, and `disable_bounded_recovery`'s own doc already named that as
/// the failure mode: *"Every flag in
/// `enable_live_bridge` needs one of these or it ships unmeasured — which
/// is how five repairs reached deployment without a single outcome
/// number."*
///
/// ⚠ Adding a flag here without a withhold arm repeats it. And note the
/// trap that cost an evaluation on 2026-08-10: because this constructor
/// sets these, an arm built as `AdvancedAi::new()` **plus** one of them is a
/// byte-identical no-op. Withhold, do not add.
/// Every *retained* default this session made withholdable must be OFF on
/// the frozen anchor, and ON in production. Measured-null defaults are
/// asserted separately below so a retired arm cannot silently return.
///
/// The re-pins for those withholds were justified by comments reasoning
/// about call paths. A comment claiming a flag cannot reach the anchor is
/// worth exactly what the comment claiming native games leave
/// `bounded_recovery` disabled was worth — that one was false, and finding
/// out cost an evaluation. `the_repair_bundle_cannot_reach_the_frozen_anchor`
/// in `main.rs` makes the same argument by assertion for the engine-repair
/// bundle; this is its counterpart for the five defaults.
///
/// Both halves matter. OFF on `legacy()` is what makes a withhold arm
/// unable to move a rating anchor. ON in the relevant production
/// constructor is what makes a withhold the *only* way to price a retained
/// flag — an arm built as `new()` plus one of these is a byte-identical
/// no-op, which is how three arms in `elo.rs` came to measure nothing.
#[test]
fn the_withholdable_defaults_are_off_on_the_anchor_and_on_in_production() {
    let frozen = AdvancedAi::legacy();
    let production = AdvancedAi::new();
    for (flag, on_anchor, in_production) in [
        (
            "settlement_safety",
            frozen.settlement_safety,
            production.settlement_safety,
        ),
        (
            "battlefront_observation",
            frozen.battlefront_observation,
            production.battlefront_observation,
        ),
        (
            "amenity_districts",
            frozen.base.amenity_districts,
            production.base.amenity_districts,
        ),
        (
            "hut_collection",
            frozen.base.hut_collection,
            production.base.hut_collection,
        ),
        (
            "explore_commit",
            frozen.base.explore_commit,
            production.base.explore_commit,
        ),
        (
            "village_seeking",
            frozen.base.village_seeking,
            production.base.village_seeking,
        ),
        (
            "recon_replacement",
            frozen.base.recon_replacement,
            production.base.recon_replacement,
        ),
        (
            "naval_recon",
            frozen.base.naval_recon,
            production.base.naval_recon,
        ),
        (
            "come_ashore",
            frozen.base.come_ashore,
            production.base.come_ashore,
        ),
    ] {
        assert!(
                !on_anchor,
                "{flag} is on for advanced_v1: a withhold arm for it can move                  the frozen rating anchor, and the source-contract re-pin that                  called itself free is not"
            );
        assert!(
                in_production,
                "{flag} is off in production, so `advanced_without_{flag}` is a                  byte-identical no-op and measures nothing"
            );
    }
    // The four war flags left production on 2026-08-14 (the war-half
    // withhold passed the corrected-gate matrix: +38, CI +10..+66, seed
    // stream 18000000; see `promoted_policy_envoy`). Off in BOTH
    // constructors now: their withhold arms are declared aliases of
    // `advanced`, and the re-addition treatment is `advanced_war_half`.
    // One flag is left; the destructure keeps the table shape, so re-adding a
    // row is a `for ... in [a, b]` again rather than a rewrite.
    let (flag, on_anchor, in_production) = (
        "unit_objective_memory",
        frozen.base.unit_objective_memory,
        production.base.unit_objective_memory,
    );
    assert!(
        !on_anchor,
        "{flag} is on for advanced_v1: the war-half removal re-pinned                  the source contract as behaviour-free for the anchor, and                  this is the assertion that keeps that claim honest"
    );
    assert!(
        !in_production,
        "{flag} is on in production: the war-half removal shipped on a                  corrected-gate PASS, so turning it back on needs its own                  matrix run through `advanced_war_half`, not a default"
    );
}

#[test]
fn production_advanced_reflects_the_withheld_bounded_recovery_selection() {
    let bare = AdvancedAi::new();
    assert!(
        !bare.bounded_recovery,
        "the bare controller remains opt-in-off"
    );
    assert!(bare.envoy_priority);

    let mut production = AdvancedAi::new();
    production.enable_engine_repairs();
    assert!(!production.bounded_recovery);

    let mut live_bridge = AdvancedAi::new();
    live_bridge.enable_live_bridge();
    assert!(
        !live_bridge.bounded_recovery,
        "the explicit three-batch selection withholds this unqualified arm"
    );
}

#[test]
fn production_advanced_scales_cities_and_development_together() {
    let production = AdvancedAi::new();
    // ⚠ Three, not six. The production floor was removed on 2026-08-10
    // after the promotion matrix returned PASS for withholding it:
    // deployment-online 55.9%, Elo +41 (CI +7..+76), 125/65, p=0.0000.
    // `advanced_wide_opening` still carries six, so the axis stays
    // reachable.
    assert_eq!(production.city_target_floor, 3);
    assert_ne!(production.city_target_floor, PRODUCTION_CITY_TARGET_FLOOR);
    assert!(production.plan_city_target);
    assert_eq!(production.base.w.city_target, 4.0);
    assert_eq!(production.base.w.builder_per_city, 0.5);
    assert!(!production.bounded_recovery);
    assert!(production.settlement_safety);
    assert!(production.adjacency_site_planning);

    // Frozen and evaluator controls keep the old policy exactly, including
    // its smaller economy and default-off live-defense adapters.
    let control = AdvancedAi::pre_policy_envoy();
    assert_eq!(control.city_target_floor, 3);
    assert!(!control.plan_city_target);
    assert_eq!(control.base.w.city_target, 4.0);
    assert_eq!(control.base.w.builder_per_city, 0.5);
    assert!(!control.bounded_recovery);

    let frozen = AdvancedAi::legacy();
    assert_eq!(frozen.city_target_floor, 3);
    assert!(!frozen.plan_city_target);
    assert_eq!(frozen.base.w.city_target, 4.0);
    assert_eq!(frozen.base.w.builder_per_city, 0.5);
    assert!(!frozen.bounded_recovery);

    // Production policy never mutates a wider, better-developed genome.
    let wide = Weights {
        city_target: 10.0,
        builder_per_city: 0.9,
        ..Weights::default()
    };
    let weighted = AdvancedAi::with_weights(wide);
    assert_eq!(weighted.base.w.city_target, 10.0);
    assert_eq!(weighted.base.w.builder_per_city, 0.9);
}

#[test]
fn advanced_settlers_wait_out_a_visible_hostile_capture_envelope() {
    let mut game = Game::new(2, 20, 14, 91_480, 80, 0);
    let (hostile_pos, civilian_step) = game
        .map
        .tiles
        .iter()
        .filter(|(_, tile)| game.rules.is_passable(tile) && !game.rules.is_water(tile))
        .find_map(|(pos, _)| {
            game.nbrs(*pos)
                .into_iter()
                .find(|next| {
                    game.map.get(*next).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                })
                .map(|next| (*pos, next))
        })
        .expect("map has adjacent land");
    game.spawn_test_unit("settler", 0, civilian_step);
    game.spawn_test_unit("warrior", 1, hostile_pos);
    game.at_war.insert((0, 1));
    let ai = AdvancedAi::new();
    let visible = ai.battlefront_visibility(&game, 0);

    assert!(
        ai.settlement_tile_risk(&game, 0, None, civilian_step, &visible) > SETTLER_STEP_RISK_LIMIT
    );
    game.at_war.clear();
    assert_eq!(
        ai.settlement_tile_risk(&game, 0, None, civilian_step, &visible),
        0.0
    );
}

/// A hostile warship beside the shore threatens a settler standing on the
/// coast — and only there: the same ship is nothing to a settler inland,
/// and a coastal tile with no ship in reach reads as quiet.
#[test]
fn a_warship_off_the_coast_threatens_a_settler_on_the_shore_and_nowhere_inland() {
    let mut game = Game::new(2, 20, 14, 91_481, 80, 0);
    // A land tile with a water neighbour (the shore) and a land tile with
    // no water within two hexes (inland).
    let is_land = |game: &Game, p: Pos| {
        game.map
            .get(p)
            .is_some_and(|t| game.rules.is_passable(t) && !game.rules.is_water(t))
    };
    let is_water = |game: &Game, p: Pos| game.map.get(p).is_some_and(|t| game.rules.is_water(t));
    let mut lands: Vec<Pos> = game
        .map
        .tiles
        .keys()
        .copied()
        .filter(|p| is_land(&game, *p))
        .collect();
    lands.sort_unstable();
    let (shore, sea) = lands
        .iter()
        .copied()
        .find_map(|p| {
            game.nbrs(p)
                .into_iter()
                .find(|n| is_water(&game, *n))
                .map(|n| (p, n))
        })
        .expect("map has a shore");
    let inland = lands
        .iter()
        .copied()
        .find(|p| game.wdisk(*p, 2).into_iter().all(|q| !is_water(&game, q)))
        .expect("map has inland ground");
    let galley = game.spawn_test_unit("galley", 1, sea);
    // Our own settler on the shore, so the ship is in plain sight.
    game.spawn_test_unit("settler", 0, shore);
    game.at_war.insert((0, 1));
    let ai = AdvancedAi::new();
    let visible = ai.battlefront_visibility(&game, 0);
    assert!(game.sees(&visible, sea), "fixture: the ship is in sight");

    assert!(
        ai.settlement_tile_risk(&game, 0, None, shore, &visible) > SETTLER_STEP_RISK_LIMIT,
        "a galley beside the shore can take a civilian standing on it — the step is refused"
    );
    assert_eq!(
        ai.settlement_tile_risk(&game, 0, None, inland, &visible),
        0.0,
        "the same ship is no threat to a settler with no water in reach"
    );
    game.remove_unit(galley);
    assert_eq!(
        ai.settlement_tile_risk(&game, 0, None, shore, &visible),
        0.0,
        "a shore with no ship in reach is quiet"
    );
}

/// A settler standing on a threatened shore with no guard steps inland
/// instead of holding; the same settler inside a city stays put.
#[test]
fn a_threatened_settler_on_the_shore_retreats_inland_but_holds_inside_a_city() {
    // Find a seed with a shore tile that has a neighbour with no water
    // around it at all — the retreat must be able to lower the risk.
    let is_land = |game: &Game, p: Pos| {
        game.map
            .get(p)
            .is_some_and(|t| game.rules.is_passable(t) && !game.rules.is_water(t))
    };
    let is_water = |game: &Game, p: Pos| game.map.get(p).is_some_and(|t| game.rules.is_water(t));
    let mut found = None;
    for seed in 91_482..91_540u64 {
        let game = Game::new(2, 24, 16, seed, 80, 0);
        let mut lands: Vec<Pos> = game
            .map
            .tiles
            .keys()
            .copied()
            .filter(|p| is_land(&game, *p))
            .collect();
        lands.sort_unstable();
        let hit = lands.iter().copied().find_map(|p| {
            let sea = game.nbrs(p).into_iter().find(|n| is_water(&game, *n))?;
            let inland = game.nbrs(p).into_iter().find(|n| {
                is_land(&game, *n) && !game.nbrs(*n).into_iter().any(|m| is_water(&game, m))
            })?;
            Some((p, sea, inland))
        });
        if let Some((shore, sea, inland)) = hit {
            found = Some((seed, shore, sea, inland));
            break;
        }
    }
    let (seed, shore, sea, inland) =
        found.expect("some seed offers a shore with dry ground behind it");

    let fresh = |seed: u64| {
        let mut game = Game::new(2, 24, 16, seed, 80, 0);
        for unit in game
            .player_unit_ids(0)
            .into_iter()
            .chain(game.player_unit_ids(1))
        {
            game.remove_unit(unit);
        }
        game.at_war.insert((0, 1));
        game.current = 0;
        game
    };

    let mut game = fresh(seed);
    game.spawn_test_unit("galley", 1, sea);
    let settler = game.spawn_test_unit("settler", 0, shore);
    game.units.get_mut(&settler).unwrap().moves_left = 2.0;
    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    let journal = crate::reasoning::Journal::recording();
    live.attach_journal(journal.handle());
    assert!(
        live.advanced_settler_step(&mut game, 0, settler),
        "the settler acts"
    );
    let after = game.units[&settler].pos;
    assert_ne!(after, shore, "it does not hold on the threatened shore");
    assert!(
        !game.nbrs(after).into_iter().any(|m| m == sea) || after == inland,
        "it moved away from the ship's water"
    );
    assert!(
        journal
            .since(0)
            .thoughts
            .iter()
            .any(|thought| thought.headline.starts_with("Settler retreats from")),
        "the retreat is journaled"
    );

    // ★★★★ A target it keeps retreating from is retired. Put it back on
    // the shore, committed to a target, and let the ship stay: the third
    // retreat gives the target up (civvis-20260816T075807Z: two settlers
    // stepped back and marched in again from t33 to t87).
    let target = inland;
    live.settler_targets.insert(settler, target);
    live.settler_retreats.remove(&settler);
    let mut retreats = 0;
    for _ in 0..SETTLER_RETREAT_LIMIT {
        game.relocate(settler, shore);
        game.units.get_mut(&settler).unwrap().moves_left = 2.0;
        let before = journal.since(0).thoughts.len();
        let _ = live.advanced_settler_step(&mut game, 0, settler);
        let fresh_thoughts = &journal.since(0).thoughts[before..];
        if fresh_thoughts
            .iter()
            .any(|t| t.headline.starts_with("Settler retreats from"))
        {
            retreats += 1;
        }
    }
    assert_eq!(
        retreats, SETTLER_RETREAT_LIMIT,
        "each turn on the shore is a retreat"
    );
    assert!(
        live.settler_site_is_dead(settler, target),
        "the target it kept retreating from is retired"
    );
    assert!(
        !live.settler_targets.contains_key(&settler),
        "and the commitment is dropped so the next pick looks elsewhere"
    );
    assert!(
        journal
            .since(0)
            .thoughts
            .iter()
            .any(|thought| thought.headline.starts_with("Settler gives up on")),
        "the surrender is journaled"
    );

    // Inside a city the same threat does not move it.
    let mut fortress = fresh(seed);
    fortress.found_city_for(0, shore, None);
    fortress.spawn_test_unit("galley", 1, sea);
    let inside = fortress.spawn_test_unit("settler", 0, shore);
    fortress.units.get_mut(&inside).unwrap().moves_left = 2.0;
    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    let journal = crate::reasoning::Journal::recording();
    live.attach_journal(journal.handle());
    let _ = live.advanced_settler_step(&mut fortress, 0, inside);
    assert!(
        !journal
            .since(0)
            .thoughts
            .iter()
            .any(|thought| thought.headline.starts_with("Settler retreats from")),
        "a city centre is protection, not a tile to flee"
    );
}

#[test]
fn production_policy_envoy_default_is_distinct_from_evaluator_and_legacy_controls() {
    let production = AdvancedAi::new();
    assert_eq!(production.weights().policy_deck, PolicyDeck::Live);
    // ⚠ Asserted, not argued: the withhold added on 2026-08-11 must not be
    // able to move the frozen anchor, and the anchor must genuinely be on
    // the deck `Weights::default()` describes even though production is not.
    assert_eq!(
        AdvancedAi::legacy().weights().policy_deck,
        PolicyDeck::Legacy,
        "advanced_v1 must stay on the deck it was rated with"
    );
    assert_eq!(
        AdvancedAi::with_legacy_policy_deck().weights().policy_deck,
        PolicyDeck::Legacy,
        "the withhold must actually withhold, or its number measures nothing"
    );
    assert!(production.envoy_priority);

    let pre_promotion = AdvancedAi::pre_policy_envoy();
    assert_eq!(pre_promotion.weights().policy_deck, PolicyDeck::Legacy);
    assert!(!pre_promotion.envoy_priority);
    assert!(pre_promotion.victory_planning);

    let legacy = AdvancedAi::legacy();
    assert_eq!(legacy.weights().policy_deck, PolicyDeck::Legacy);
    assert!(!legacy.envoy_priority);
    assert!(!legacy.victory_planning);

    let weighted = Weights {
        pol_influence: 4.0,
        ..Weights::default()
    };
    let weighted_production = AdvancedAi::with_weights(weighted);
    assert_eq!(weighted_production.weights().policy_deck, PolicyDeck::Live);
    assert_eq!(weighted_production.weights().pol_influence, 4.0);
}

#[test]
fn battlefront_frame_keeps_later_reveals_out_of_turn_start_planning() {
    let mut game = Game::new_full(2, 30, 18, 411_009, 120, 0, false);
    let mut ai = AdvancedAi::new();
    let start = game.player_vision_now(0);
    let hidden = game
        .map
        .tiles
        .values()
        .filter(|tile| {
            !game.sees(&start, tile.pos)
                && game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.city_at(tile.pos).is_none()
                && game.unit_ids_at(tile.pos).is_empty()
        })
        .map(|tile| tile.pos)
        .next()
        .expect("test map needs a hidden passable tile");
    let enemy = game.spawn_test_unit("warrior", 1, hidden);
    ai.capture_battlefront_frame(&game, 0);
    assert!(!ai.battlefront_unit_visible(&game, 0, enemy));

    let scout_positions =
        game.wdisk(hidden, 2)
            .into_iter()
            .filter(|position| {
                *position != hidden
                    && game.city_at(*position).is_none()
                    && game.unit_ids_at(*position).is_empty()
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .collect::<Vec<_>>();
    let scout = scout_positions
        .into_iter()
        .find_map(|position| {
            let scout = game.spawn_test_unit("scout", 0, position);
            if game.sees(&game.player_vision_now(0), hidden) {
                Some(scout)
            } else {
                game.remove_unit(scout);
                None
            }
        })
        .expect("a nearby scout must be able to reveal the hidden tile");
    assert!(game.sees(&game.player_vision_now(0), hidden));
    assert!(game.unit_visible_to(enemy, 0));
    assert!(game.units.contains_key(&scout));
    assert!(
        !game.sees(&ai.battlefront_visibility(&game, 0), hidden)
            && !ai.battlefront_unit_visible(&game, 0, enemy),
        "a unit that an earlier move reveals is not part of the turn-start frame"
    );

    ai.battlefront_frame = None;
    assert!(game.sees(&ai.battlefront_visibility(&game, 0), hidden));
    assert!(ai.battlefront_unit_visible(&game, 0, enemy));
}

/// The screen-flagged gene repairs of 2026-08-19: each gate that was measured
/// causing losses now needs its firing condition, and stands down without it.
mod flagged_gene_repairs {
    use super::*;

    /// `housing-research`: one capped city out of many no longer owns the
    /// research slot; a majority-capped empire whose relief is already
    /// producible leaves it to production; only a tech-bound, empire-binding
    /// cap forces the goal.
    ///
    /// One fresh board per assertion: `producible_items` is memoized per
    /// city, and a test that hand-inserts a tech between two calls would
    /// read the first call's cached list.
    #[test]
    fn housing_research_needs_an_empire_binding_tech_bound_cap() {
        let board = |capped: usize, pottery: bool| {
            let mut g = Game::new_full(2, 24, 16, 61, 80, 0, false);
            if pottery {
                let granary_tech = g.rules.buildings[&crate::name!("granary")]
                    .tech
                    .expect("granary has a tech");
                g.players[0].techs.insert(granary_tech);
            }
            let cities = [
                found_test_city(&mut g, 0),
                found_test_city(&mut g, 0),
                found_test_city(&mut g, 0),
            ];
            for cid in cities.into_iter().take(capped) {
                let housing = g.city_housing(&g.cities[&cid]);
                g.cities.get_mut(&cid).unwrap().pop = housing.ceil() as i32 + 1;
            }
            g
        };
        let mut ai = AdvancedAi::new();
        ai.enable_housing_research();
        assert_eq!(
            ai.unreachable_housing_tech(&board(0, false), 0),
            None,
            "nobody capped: no goal"
        );
        assert_eq!(
            ai.unreachable_housing_tech(&board(1, false), 0),
            None,
            "one capped city of three must not own the research slot"
        );
        assert!(
            ai.unreachable_housing_tech(&board(2, false), 0).is_some(),
            "a majority-capped, tech-bound empire researches toward housing"
        );
        assert_eq!(
            ai.unreachable_housing_tech(&board(2, true), 0),
            None,
            "a granary the capped cities can already order is production's job"
        );
    }
}

fn found_test_city(game: &mut Game, pid: usize) -> u32 {
    let position = game
        .map
        .tiles
        .values()
        .filter(|tile| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && tile.district.is_none()
                && tile.wonder.is_none()
                && tile.owner_city.is_none()
                && game.city_at(tile.pos).is_none()
                && game.unit_ids_at(tile.pos).is_empty()
                && game
                    .cities
                    .values()
                    .all(|city| game.wdist(city.pos, tile.pos) >= 4)
        })
        .map(|tile| tile.pos)
        .next()
        .expect("test map needs another legal city site");
    let settler = game.spawn_test_unit("settler", pid, position);
    game.current = pid;
    game.apply(pid, &Action::FoundCity { unit: settler })
        .unwrap();
    game.city_at(position).unwrap()
}

// One test district helper in the repository. The body that stood here was
// byte-identical to `game::install_test_district`, and two copies of a fixture
// builder drift in exactly the way that makes a suite disagree with itself.
use crate::game::install_test_district as install_ai_test_district;

fn install_test_holy_site(game: &mut Game, city: u32) {
    install_ai_test_district(game, city, "holy_site");
    game.cities.get_mut(&city).unwrap().buildings =
        vec![crate::name!("shrine"), crate::name!("temple")];
}

/// A ready-to-fire late-game board with a hard conventional target and a
/// separate rival Spaceport.  The second city sits inside the ordinary ICBM
/// range but outside either city's blast disk, so the doctrine has to choose
/// rather than receiving an accidental two-city strike.
fn nuclear_war_fixture() -> (Game, u32, u32, u32, Pos) {
    let mut game = Game::new_full(2, 36, 22, 91_803, 300, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("every major starts with a Settler");
        game.found_city_for(pid, game.units[&settler].pos, None);
        game.remove_unit(settler);
    }
    // Leave nothing in either future blast ring except the infrastructure
    // deliberately installed below.
    for pid in 0..2 {
        for unit in game.player_unit_ids(pid) {
            game.remove_unit(unit);
        }
    }
    let launch_city = game.player_city_ids(0)[0];
    let fortress_city = game.player_city_ids(1)[0];
    let launch = game.cities[&launch_city].pos;
    let fortress = game.cities[&fortress_city].pos;
    // A late-game counter-program needs a city that can actually finish the
    // Manhattan/Ivy chain before the clock.  This permanent production bonus
    // keeps the fixture focused on target selection rather than the horizon
    // refusal that is correct for a one-production outpost.
    game.map.tiles.get_mut(&launch).unwrap().disaster_production = 100.0;
    let radius = game.rules.wmds["thermonuclear_device"].blast_radius;
    let spaceport_site = game
        .map
        .tiles
        .values()
        .filter(|tile| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && tile.owner_city.is_none()
                && tile.district.is_none()
                && tile.wonder.is_none()
                && game.city_at(tile.pos).is_none()
                && game.wdist(launch, tile.pos) > radius
                && game.wdist(launch, tile.pos)
                    <= game.rules.wmds["nuclear_device"].icbm_strike_range
                && game.wdist(fortress, tile.pos) > 2 * radius + 1
                && game
                    .cities
                    .values()
                    .all(|city| game.wdist(city.pos, tile.pos) >= 4)
        })
        .map(|tile| tile.pos)
        .next()
        .expect("map has a separate ICBM-range city site");
    let spaceport_city = game.found_city_for(1, spaceport_site, Some("Launch Complex".to_string()));
    let spaceport = game
        .map
        .tiles
        .values()
        .find(|position| {
            game.wdist(position.pos, spaceport_site)
                == game.rules.wmds["thermonuclear_device"].blast_radius
                && position.owner_city.is_none()
                && position.district.is_none()
                && position.wonder.is_none()
                && position.improvement.is_none()
        })
        .map(|tile| tile.pos)
        .expect("new city has a Spaceport tile inside thermonuclear but outside nuclear range");
    let tile = game.map.tiles.get_mut(&spaceport).unwrap();
    tile.owner_city = Some(spaceport_city);
    tile.district = Some(crate::name!("spaceport"));
    tile.pillaged = false;
    let city = game.cities.get_mut(&spaceport_city).unwrap();
    city.owned_tiles.push(spaceport);
    city.districts.insert(crate::name!("spaceport"), spaceport);
    install_ai_test_district(&mut game, launch_city, "industrial_zone");
    game.players[1]
        .science_projects
        .insert("exoplanet_expedition".to_string());
    game.cities.get_mut(&spaceport_city).unwrap().queue = vec![Item::Project {
        project: crate::name!("lagrange_laser_station"),
    }];
    game.players[0].explored.insert(fortress);
    game.players[0].explored.insert(spaceport_site);
    game.world_era = 4;
    (game, launch_city, fortress_city, spaceport_city, spaceport)
}

/// The research floor is a ramp on the remaining game and is absent from
/// the frozen controls, so an ablation measures a real difference.
#[test]
fn the_research_floor_ramps_with_the_horizon_and_stays_out_of_the_controls() {
    let mut early = Game::new(2, 24, 16, 5_411, 250, 0);
    early.turn = 1;
    let mut late = early.clone();
    late.turn = 240;
    let mut finished = early.clone();
    finished.turn = 251;

    let mut ai = AdvancedAi::new();
    ai.refresh_research_weight(&early);
    let early_weight = ai.research_weight;
    ai.refresh_research_weight(&late);
    let late_weight = ai.research_weight;
    ai.refresh_research_weight(&finished);
    let finished_weight = ai.research_weight;

    assert!(
        early_weight > 2.9 && early_weight <= RESEARCH_FLOOR_EARLY,
        "a beaker bought on turn 1 compounds for the whole game: {early_weight}"
    );
    assert!(
        late_weight < 1.2,
        "a beaker bought on turn 240 buys nothing that can be built: {late_weight}"
    );
    assert!(
        early_weight > late_weight,
        "the floor must decay, not sit flat"
    );
    assert_eq!(
        finished_weight, RESEARCH_FLOOR_LATE,
        "past the turn limit the horizon clamps at zero rather than going negative"
    );

    for mut control in [AdvancedAi::legacy(), AdvancedAi::pre_policy_envoy()] {
        control.refresh_research_weight(&early);
        assert_eq!(
            control.research_weight, 0.0,
            "the evaluation controls must keep the pre-treatment pricing"
        );
    }
}

/// The defect this repairs: every lane except Science priced a beaker below
/// its own least valuable ordinary yield, and the live Kongo run spent 89 of
/// 106 sampled turns in exactly those lanes.
#[test]
fn beakers_keep_a_floor_in_every_lane_but_never_outbid_the_science_lane() {
    let mut game = Game::new(2, 24, 16, 5_412, 250, 0);
    game.turn = 40;
    let mut ai = AdvancedAi::new();
    ai.refresh_research_weight(&game);
    let legacy = AdvancedAi::legacy();
    let one_science = Yields {
        science: 1.0,
        ..Yields::default()
    };

    for strategy in [
        GrandStrategy::Religion,
        GrandStrategy::Conquest,
        GrandStrategy::Recovery,
        GrandStrategy::Expansion,
        GrandStrategy::Culture,
        GrandStrategy::Diplomacy,
    ] {
        let treated = ai.yield_value(one_science, strategy);
        let control = legacy.yield_value(one_science, strategy);
        assert!(
            treated > control,
            "{strategy:?} must value research above the lane-only anchor: \
                 {treated} vs {control}"
        );
        assert!(
            treated < ai.yield_value(one_science, GrandStrategy::Science),
            "{strategy:?} must not outbid the Science lane's own currency"
        );
    }

    assert_eq!(
        ai.yield_value(one_science, GrandStrategy::Science),
        legacy.yield_value(one_science, GrandStrategy::Science),
        "the Science lane's promoted weight is untouched"
    );
    let one_faith = Yields {
        faith: 1.0,
        ..Yields::default()
    };
    assert_eq!(
        ai.yield_value(one_faith, GrandStrategy::Religion),
        legacy.yield_value(one_faith, GrandStrategy::Religion),
        "the floor is science-only: no other yield moves"
    );
}

/// Every lane asks a governor for beakers, because the lane the empire is
/// in is not evidence that research stopped mattering.
#[test]
fn every_lane_tilts_a_citizen_toward_research() {
    for strategy in [
        GrandStrategy::Expansion,
        GrandStrategy::Religion,
        GrandStrategy::Conquest,
        GrandStrategy::Recovery,
        GrandStrategy::Culture,
        GrandStrategy::Diplomacy,
    ] {
        assert_eq!(
            AdvancedAi::lane_emphasis(strategy, 0.0).science,
            0.0,
            "{strategy:?} carried no research tilt before the treatment"
        );
        assert!(
            AdvancedAi::lane_emphasis(strategy, RESEARCH_CITIZEN_TILT).science > 0.0,
            "{strategy:?} must now ask its citizens for research too"
        );
    }
    assert_eq!(
        AdvancedAi::lane_emphasis(GrandStrategy::Science, RESEARCH_CITIZEN_TILT).science,
        0.50,
        "the Science lane keeps its own larger appetite"
    );
}

/// The defect this repairs, reproduced from the live board that showed it.
///
/// Run `civvis-20260803T082856Z` finished turn 251 with seven cities, six
/// Campuses, six Universities and **zero Research Labs**, holding
/// Replaceable Parts (one of Chemistry's two prerequisites), Composites,
/// Plastics and Combined Arms — and not Sanitation, which unlocks only a
/// Sewer and a Medic. Chemistry was therefore never in `available_techs`,
/// so `tech_value` never scored it, so #958's 2.1-2.5x weight increase on
/// the Research Lab could not and did not change the outcome.
#[test]
fn a_university_empire_reaches_for_the_research_lab_across_a_worthless_prerequisite() {
    let mut game = Game::new(2, 32, 24, 8_801, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let city = game.player_city_ids(0)[0];
    install_ai_test_district(&mut game, city, "campus");
    game.cities.get_mut(&city).unwrap().buildings =
        vec![crate::name!("library"), crate::name!("university")];
    // Everything Chemistry needs except Sanitation, exactly as the live
    // empire held it.
    for tech in [
        "writing",
        "education",
        "scientific_theory",
        "economics",
        "replaceable_parts",
    ] {
        game.players[0].techs.insert(Name::new(tech));
    }

    let ai = AdvancedAi::new();
    assert_eq!(
        ai.unreachable_science_building_tech(&game, 0),
        Some("chemistry"),
        "a Campus with a University and no Research Lab wants Chemistry"
    );
    assert!(
        !game
            .available_techs(0)
            .iter()
            .any(|tech| tech == "chemistry"),
        "and the argmax cannot see it: Chemistry is not an available tech"
    );
    assert!(
        ai.tech_leads_to(&game, "sanitation", "chemistry"),
        "the bridge runs through Sanitation, which unlocks only a Sewer"
    );

    // The legacy anchor must not acquire the goal.
    assert_eq!(
        AdvancedAi::legacy().unreachable_science_building_tech(&game, 0),
        None
    );
}

