#[test]
fn coordinated_force_moves_most_routed_units_on_advance() {
    let mut g = Game::new_full(2, 24, 16, 80, 80, 0, false);
    g.at_war.insert((0, 1));
    let (target, staging) = g
        .map
        .tiles
        .iter()
        .filter(|(pos, tile)| {
            g.rules.is_passable(tile) && !g.rules.is_water(tile) && g.unit_ids_at(**pos).is_empty()
        })
        .find_map(|(target, _)| {
            let staging: Vec<Pos> = g
                .wdisk(*target, 6)
                .into_iter()
                .filter(|pos| {
                    (3..=6).contains(&g.wdist(*target, *pos))
                        && g.map.get(*pos).is_some_and(|tile| {
                            g.rules.is_passable(tile)
                                && !g.rules.is_water(tile)
                                && g.unit_ids_at(*pos).is_empty()
                        })
                })
                .take(6)
                .collect();
            (staging.len() == 6).then_some((*target, staging))
        })
        .expect("test map needs an open land campaign");
    g.spawn_test_unit("warrior", 1, target);
    let army: Vec<u32> = staging
        .into_iter()
        .map(|pos| g.spawn_test_unit("warrior", 0, pos))
        .collect();
    let orders = ForceGroup {
        id: army[0],
        domain: ForceDomain::Land,
        units: army.clone(),
        anchor: g.units[&army[0]].pos,
        objective: target,
        focus_target: None,
        posture: ForcePosture::Advance,
        readiness: 1.0,
        local_strength_ratio: 2.0,
    };
    let ai = AdvancedAi::new();
    for uid in &army {
        ai.coordinated_tactical_step(&mut g, 0, *uid, &orders, &[1], false);
    }
    let moved = army.iter().filter(|uid| g.units[uid].moved).count();
    assert!(
        moved * 2 > army.len(),
        "expected most coordinated troops to advance; moved {moved}/{}",
        army.len()
    );
}

#[test]
fn live_livelock_route_escape_can_cross_its_recorded_footprint() {
    let mut game = Game::new_full(2, 20, 14, 80_271, 80, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    // Match the router's obstacle fixture: all geometrically improving
    // first steps are mountains, so the valid route begins sideways or
    // backward. The tactical score is deliberately allowed to dislike
    // that step; six observed fruitless turns are the evidence that the
    // short detour is now better than another greedy retry.
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    let start = *game
        .map
        .tiles
        .keys()
        .find(|position| game.wdisk(**position, 3).len() == 37)
        .expect("fixture needs an interior tile");
    let target = (start.0 + 3, start.1);
    let unit = game.spawn_test_unit("warrior", 0, start);
    game.at_war.insert((0, 1));
    let direct = game
        .nbrs(start)
        .into_iter()
        .filter(|position| game.wdist(*position, target) < game.wdist(start, target))
        .collect::<Vec<_>>();
    for position in direct {
        game.map.tiles.get_mut(&position).unwrap().terrain = crate::name!("mountain");
    }
    let detour = game
        .route_step(unit, target, 1)
        .expect("the mountain wedge leaves a route to attack range");
    assert!(
        game.wdist(detour, target) >= game.wdist(start, target),
        "the first route step is a genuine geometric detour"
    );

    let mut live = AdvancedAi::new();
    live.enable_recorded_tactical_step();
    // Record the same two-tile pocket at the start of six real turns.
    // The route's first step is deliberately inside that footprint, which
    // is exactly the case `path_move` must ordinarily reject.
    for position in [start, detour, start, detour, start, detour, start] {
        let mover = game.units.get_mut(&unit).unwrap();
        mover.pos = position;
        mover.moves_left = 2.0;
        mover.moved = false;
        live.base.begin_movement_turn(&game, 0);
        game.turn += 1;
    }
    assert!(live.base.live_livelock_route_escape(unit));
    assert!(
        !live.base.tactical_apply_move(&mut game, 0, unit, detour),
        "ordinary recorded movement must keep rejecting the exhausted footprint"
    );

    let orders = ForceGroup {
        id: unit,
        domain: ForceDomain::Land,
        units: vec![unit],
        anchor: start,
        objective: target,
        focus_target: None,
        posture: ForcePosture::Advance,
        readiness: 1.0,
        local_strength_ratio: 2.0,
    };
    assert!(live.coordinated_tactical_step(&mut game, 0, unit, &orders, &[1], false));
    assert_eq!(
        game.units[&unit].pos, detour,
        "the live route exception may retrace one recorded tile only to leave the pocket"
    );
    assert!(matches!(
        game.log.last(),
        Some((0, Action::Move { unit: moved, to })) if *moved == unit && *to == detour
    ));
}

#[test]
fn coordinated_mover_ignores_a_hostile_missing_from_its_turn_start_frame() {
    let choose = |ai: &AdvancedAi, game: &mut Game, unit: u32, orders: &ForceGroup| {
        ai.coordinated_tactical_step(game, 0, unit, orders, &[1], false)
            .then_some(())?;
        match game.log.last() {
            Some((actor, Action::Move { unit: moved, to })) if *actor == 0 && *moved == unit => {
                Some(*to)
            }
            _ => None,
        }
    };

    // Find a real open tactical fork, then prove that a threat beside the
    // ordinary move is material to the legacy mover.  The production
    // mover captures its frame before that hostile exists, which is the
    // same information boundary as a hidden enemy changing position or
    // HP in the counterfactual census.
    let mut game = Game::new_full(2, 24, 16, 82_000, 80, 0, false);
    let existing: Vec<u32> = game.units.keys().copied().collect();
    for unit in existing {
        game.remove_unit(unit);
    }
    // A level plain makes this a fixed local fork rather than a search
    // over map generation. Only the tactical score varies below.
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    game.at_war.insert((0, 1));
    let positions = game.map.tiles.keys().copied().collect::<Vec<_>>();
    let origin = positions
        .iter()
        .copied()
        .find(|origin| game.nbrs(*origin).len() == 6)
        .expect("the fixed map needs an interior tactical origin");
    let (game, unit, orders, expected, hidden) = game
        .wdisk(origin, 4)
        .into_iter()
        .filter(|target| game.wdist(origin, *target) == 4)
        .find_map(|target| {
            let mut base = game.clone();
            let unit = base.spawn_test_unit("warrior", 0, origin);
            let orders = ForceGroup {
                id: unit,
                domain: ForceDomain::Land,
                units: vec![unit],
                anchor: origin,
                objective: target,
                focus_target: None,
                posture: ForcePosture::Advance,
                readiness: 1.0,
                local_strength_ratio: 2.0,
            };
            let mut unthreatened = base.clone();
            let expected = choose(&AdvancedAi::legacy(), &mut unthreatened, unit, &orders)?;
            game.wdisk(expected, 3)
                .into_iter()
                .filter(|position| game.wdist(*position, expected) == 3)
                .filter(|hidden| *hidden != origin && *hidden != target)
                .find_map(|hidden| {
                    let mut legacy = base.clone();
                    legacy.spawn_test_unit("giant_death_robot", 1, hidden);
                    let detour = choose(&AdvancedAi::legacy(), &mut legacy, unit, &orders)?;
                    (detour != expected).then_some((
                        base.clone(),
                        unit,
                        orders.clone(),
                        expected,
                        hidden,
                    ))
                })
        })
        .expect("the fixed open map needs a tactical fork affected by a hostile threat");

    let mut observed = game;
    let mut ai = AdvancedAi::new();
    ai.capture_battlefront_frame(&observed, 0);
    let enemy = observed.spawn_test_unit("giant_death_robot", 1, hidden);
    assert!(
        !ai.battlefront_unit_visible(&observed, 0, enemy),
        "the threat was added after the turn-start frame"
    );
    assert_eq!(
        choose(&ai, &mut observed, unit, &orders),
        Some(expected),
        "a hostile absent from the turn-start frame must not reroute the force"
    );
}

#[test]
fn recon_explores_independently_while_combat_roles_form_the_army() {
    let mut g = Game::new_full(2, 24, 16, 81, 80, 0, false);
    g.at_war.insert((0, 1));
    let positions: Vec<Pos> = g
        .map
        .tiles
        .iter()
        .filter(|(pos, tile)| {
            g.rules.is_passable(tile) && !g.rules.is_water(tile) && g.unit_ids_at(**pos).is_empty()
        })
        .map(|(pos, _)| *pos)
        .take(6)
        .collect();
    let scout = g.spawn_test_unit("scout", 0, positions[0]);
    let vanguard = g.spawn_test_unit("swordsman", 0, positions[1]);
    let mobile = g.spawn_test_unit("horseman", 0, positions[2]);
    let ranged = g.spawn_test_unit("archer", 0, positions[3]);
    let siege = g.spawn_test_unit("catapult", 0, positions[4]);
    let support = g.spawn_test_unit("battering_ram", 0, positions[5]);
    assert_eq!(AdvancedAi::force_role(&g, scout), ForceRole::Recon);
    assert_eq!(AdvancedAi::force_role(&g, vanguard), ForceRole::Vanguard);
    assert_eq!(AdvancedAi::force_role(&g, mobile), ForceRole::Mobile);
    assert_eq!(AdvancedAi::force_role(&g, ranged), ForceRole::Ranged);
    assert_eq!(AdvancedAi::force_role(&g, siege), ForceRole::Siege);
    assert_eq!(AdvancedAi::force_role(&g, support), ForceRole::Support);

    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: g.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.rebuild_force_groups(&g, 0, &plan);
    assert!(
        ai.force_groups()
            .iter()
            .all(|group| !group.units.contains(&scout)),
        "recon with unexplored terrain should not make the army wait to muster"
    );
    assert!(ai
        .force_groups()
        .iter()
        .any(|group| group.units.contains(&vanguard)));
}

#[test]
fn friendly_volley_reprices_a_two_unit_kill_after_the_finisher() {
    let mut base = Game::new_full(2, 24, 16, 81_700, 80, 0, false);
    for unit in base.units.keys().copied().collect::<Vec<_>>() {
        base.remove_unit(unit);
    }
    for tile in base.map.tiles.values_mut() {
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    base.current = 0;
    base.at_war.insert((0, 1));
    let target = base
        .map
        .tiles
        .keys()
        .copied()
        .find(|position| base.nbrs(*position).len() == 6)
        .expect("fixture needs an interior tile");
    let firing_lines: Vec<Pos> = base
        .wdisk(target, 2)
        .into_iter()
        .filter(|position| base.wdist(*position, target) == 2)
        .take(2)
        .collect();
    assert_eq!(
        firing_lines.len(),
        2,
        "interior tile needs two firing lines"
    );
    let opener = base.spawn_test_unit("archer", 0, firing_lines[0]);
    let finisher = base.spawn_test_unit("archer", 0, firing_lines[1]);
    let defender = base.spawn_test_unit("warrior", 1, target);
    let opening = Action::Ranged {
        unit: opener,
        target,
    };
    let finish = Action::Ranged {
        unit: finisher,
        target,
    };

    // Discover an exact seeded-damage window rather than hard-coding a
    // combat-roll amount: the first shot must leave the defender alive
    // and the next friendly shot must remove it.
    let game = (2..=100)
        .find_map(|hp| {
            let mut candidate = base.clone();
            candidate.units.get_mut(&defender).unwrap().hp = hp;
            let mut after_first = candidate.clone();
            (after_first.apply(0, &opening).is_ok() && after_first.units.contains_key(&defender))
                .then_some(after_first)
                .and_then(|mut after_first| {
                    (after_first.apply(0, &finish).is_ok()
                        && !after_first.units.contains_key(&defender))
                    .then_some(candidate)
                })
        })
        .expect("two archers must admit a nonlethal-then-lethal damage window");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    let group = ForceGroup {
        id: opener,
        domain: ForceDomain::Land,
        units: vec![opener, finisher],
        anchor: game.units[&opener].pos,
        objective: target,
        focus_target: Some(target),
        posture: ForcePosture::Engage,
        readiness: 1.0,
        local_strength_ratio: 1.0,
    };
    // Opt into the friendly-volley extension under test.
    let mut ai = AdvancedAi::new();
    ai.coordinated_finish = true;
    let first_reply = ai.forcing_reply_penalty(&game, 0, opener, &opening);
    let (bonus, paired_reply) = ai
        .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
        .expect("the engaged force has an immediate friendly finisher");
    assert_eq!(
        bonus,
        ai.base.w.kill_bonus * TACTICAL_VOLLEY_KILL_BONUS_SCALE
    );
    assert!(
            first_reply > paired_reply,
            "the defender cannot reply after its friendly-volley kill: first={first_reply}, paired={paired_reply}"
        );
    assert!(
        AdvancedAi::legacy()
            .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
            .is_none(),
        "the frozen control keeps the production-only tactical extension off"
    );

    // Give the first shot a reply price high enough that it would decline
    // in isolation, while the real two-unit line remains worthwhile.  The
    // live unit step must then use the extension rather than merely expose
    // it as a helper.
    let attack_value = ai.tactical_attack_value(&game, 0, opener, &opening, &plan);
    let threshold = ai.base.attack_threshold(&game, opener, target);
    let static_score = attack_value - threshold
        + ai.base.w.focus_fire * 10.0
        + if game
            .unit_ids_at(target)
            .iter()
            .any(|unit| game.units[unit].hp <= 35)
        {
            16.0
        } else {
            0.0
        };
    let trade_caution = (1..=128)
        .map(|value| value as f64)
        .find(|trade| {
            static_score - *trade * first_reply <= 0.0
                && static_score + bonus - *trade * paired_reply > 0.0
        })
        .expect("the friendly kill must be distinguishable from its interrupted reply");
    let mut live = AdvancedAi::new();
    live.coordinated_finish = true;
    live.base.w.trade_caution = trade_caution;
    live.force_groups = vec![group.clone()];
    let mut played = game.clone();
    assert!(live.advanced_military_step(&mut played, 0, opener, &plan));
    assert!(
        played.units.contains_key(&defender),
        "the opening shot is deliberately nonlethal"
    );
    assert!(matches!(
        played.log.last(),
        Some((0, Action::Ranged { unit, target: hit })) if *unit == opener && *hit == target
    ));

    let mut parallel = ai.clone();
    parallel.work_pool = Some(Arc::new(WorkPool::new(4)));
    assert_eq!(
        Some((bonus, paired_reply)),
        parallel.friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
    );
}

#[test]
fn friendly_volley_chains_two_finishers_onto_a_three_blow_kill() {
    let mut base = Game::new_full(2, 24, 16, 81_700, 80, 0, false);
    for unit in base.units.keys().copied().collect::<Vec<_>>() {
        base.remove_unit(unit);
    }
    for tile in base.map.tiles.values_mut() {
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    base.current = 0;
    base.at_war.insert((0, 1));
    let target = base
        .map
        .tiles
        .keys()
        .copied()
        .find(|position| base.nbrs(*position).len() == 6)
        .expect("fixture needs an interior tile");
    let firing_lines: Vec<Pos> = base
        .wdisk(target, 2)
        .into_iter()
        .filter(|position| base.wdist(*position, target) == 2)
        .take(3)
        .collect();
    assert_eq!(
        firing_lines.len(),
        3,
        "interior tile needs three firing lines"
    );
    let opener = base.spawn_test_unit("archer", 0, firing_lines[0]);
    let second = base.spawn_test_unit("archer", 0, firing_lines[1]);
    let third = base.spawn_test_unit("archer", 0, firing_lines[2]);
    let defender = base.spawn_test_unit("warrior", 1, target);
    let opening = Action::Ranged {
        unit: opener,
        target,
    };

    // Discover an exact seeded-damage window rather than hard-coding a
    // combat-roll amount: after the opening shot no lone teammate may
    // remove the defender, while either ordering of the remaining two
    // shots must — so the single-finisher search comes up empty and only
    // the chain can see the kill.
    let survives = |position: &Game, shots: &[u32]| -> Option<bool> {
        let mut speculative = position.clone();
        for shooter in shots {
            let action = Action::Ranged {
                unit: *shooter,
                target,
            };
            if speculative.apply(0, &action).is_err() {
                return None;
            }
        }
        Some(speculative.units.contains_key(&defender))
    };
    let game = (2..=100)
        .find_map(|hp| {
            let mut candidate = base.clone();
            candidate.units.get_mut(&defender).unwrap().hp = hp;
            let alive_after = |shots: &[u32]| survives(&candidate, shots);
            (alive_after(&[opener, second])?
                && alive_after(&[opener, third])?
                && !alive_after(&[opener, second, third])?
                && !alive_after(&[opener, third, second])?)
            .then_some(candidate)
        })
        .expect("three archers must admit a three-blow damage window");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    let group = ForceGroup {
        id: opener,
        domain: ForceDomain::Land,
        units: vec![opener, second, third],
        anchor: game.units[&opener].pos,
        objective: target,
        focus_target: Some(target),
        posture: ForcePosture::Engage,
        readiness: 1.0,
        local_strength_ratio: 1.0,
    };
    // `coordinated_finish` must open the volley layer on its own — the
    // war-half bundle that used to carry it stays closed.
    let mut ai = AdvancedAi::new();
    ai.coordinated_finish = true;
    let (bonus, reply) = ai
        .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
        .expect("two teammates together finish what neither can alone");
    assert_eq!(
        bonus,
        ai.base.w.kill_bonus * TACTICAL_VOLLEY_KILL_BONUS_SCALE
    );
    assert!(reply.is_finite());
    let mut withheld = AdvancedAi::new();
    withheld.coordinated_finish = true;
    withheld.volley_chain = false;
    assert!(
        withheld
            .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
            .is_none(),
        "with the chain withheld no lone finisher exists at this window"
    );
    assert!(
        AdvancedAi::new()
            .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
            .is_none(),
        "stock production keeps the volley layer dormant until it is priced"
    );
    assert!(
        AdvancedAi::legacy()
            .friendly_volley_extension(&game, 0, opener, &opening, &group, &plan)
            .is_none(),
        "the frozen control keeps the production-only tactical extension off"
    );
}

#[test]
fn tactical_melee_preflight_matches_the_engine_entry_cost_rule() {
    let mut game = Game::new_full(2, 24, 16, 81_701, 80, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    game.current = 0;
    game.at_war.insert((0, 1));
    let target = game
        .map
        .tiles
        .keys()
        .copied()
        .find(|position| game.nbrs(*position).len() == 6)
        .expect("fixture needs an interior tile");
    let origin = game.nbrs(target)[0];
    let attacker = game.spawn_test_unit("warrior", 0, origin);
    game.spawn_test_unit("warrior", 1, target);
    game.map.tiles.get_mut(&target).unwrap().feature = Some(crate::name!("forest"));
    assert!(game.map.set_river_edge(origin, target, true));
    let attack = Action::Attack {
        unit: attacker,
        target,
    };
    let engine_offers_attack = |game: &Game| {
        game.legal_actions(0)
            .into_iter()
            .any(|action| action == attack)
    };

    game.units.get_mut(&attacker).unwrap().moves_left = 1.0;
    assert!(!engine_offers_attack(&game));
    assert!(
        !AdvancedAi::tactical_melee_candidate_is_legal(&game, attacker, target),
        "the tactical scan must not score an attack that cannot pay its entry cost"
    );

    game.units.get_mut(&attacker).unwrap().moves_left = 2.0;
    assert!(engine_offers_attack(&game));
    assert!(
        AdvancedAi::tactical_melee_candidate_is_legal(&game, attacker, target),
        "the preflight must retain the full-movement attack the engine allows"
    );
}

#[test]
fn forcing_reply_search_avoids_a_poisoned_capture() {
    let mut g = Game::new_full(2, 24, 16, 8_117, 80, 0, false);
    g.at_war.insert((0, 1));
    g.current = 0;
    let (anchor, risky, safe, reply_squares) = g
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            g.rules.is_passable(tile)
                && !g.rules.is_water(tile)
                && g.unit_ids_at(**position).is_empty()
                && g.city_at(**position).is_none()
                && g.cities
                    .values()
                    .all(|city| g.wdist(**position, city.pos) > 5)
                && g.units
                    .values()
                    .filter(|unit| unit.owner != 0)
                    .all(|unit| g.wdist(**position, unit.pos) > 5)
        })
        .find_map(|(anchor, _)| {
            let targets: Vec<Pos> =
                g.nbrs(*anchor)
                    .into_iter()
                    .filter(|position| {
                        g.map.get(*position).is_some_and(|tile| {
                            g.rules.is_passable(tile) && !g.rules.is_water(tile)
                        }) && g.unit_ids_at(*position).is_empty()
                            && g.city_at(*position).is_none()
                    })
                    .collect();
            for risky in &targets {
                for safe in &targets {
                    if risky == safe || g.wdist(*risky, *safe) < 2 {
                        continue;
                    }
                    let replies: Vec<Pos> = g
                        .wdisk(*risky, 2)
                        .into_iter()
                        .filter(|reply| {
                            g.wdist(*risky, *reply) == 2
                                    // A ranged unit may move one tile before
                                    // firing. Keep the safe capture outside
                                    // both its current and move-then-fire reach
                                    // so this fixture is independent of the
                                    // generated terrain's movement costs.
                                    && g.wdist(*safe, *reply) > 3
                                    && *reply != *anchor
                                    && g.map.get(*reply).is_some_and(|tile| {
                                        g.rules.is_passable(tile) && !g.rules.is_water(tile)
                                    })
                                    && g.unit_ids_at(*reply).is_empty()
                                    && g.city_at(*reply).is_none()
                        })
                        .collect();
                    if replies.len() >= 2 {
                        return Some((*anchor, *risky, *safe, replies));
                    }
                }
            }
            None
        })
        .expect("test map has an isolated poisoned-capture geometry");

    for position in g.wdisk(risky, 2) {
        let tile = g.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    // The reply search extends one approach step, so an archer three or
    // four tiles from the safe square could still move and shoot it.
    // Moat the approach ring — water stops land approaches without
    // blocking the archers' sight lines — so the safe capture stays
    // unpunishable by construction, not by map luck.
    for position in g.wdisk(safe, 2) {
        if position == safe
            || position == anchor
            || position == risky
            || !g.unit_ids_at(position).is_empty()
            || g.city_at(position).is_some()
        {
            continue;
        }
        let tile = g.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("coast");
        tile.feature = None;
        tile.resource = None;
        tile.improvement = None;
        tile.hills = false;
    }
    let attacker = g.spawn_test_unit("swordsman", 0, anchor);
    let risky_defender = g.spawn_test_unit("warrior", 1, risky);
    let safe_defender = g.spawn_test_unit("warrior", 1, safe);
    g.units.get_mut(&risky_defender).unwrap().hp = 1;
    g.units.get_mut(&safe_defender).unwrap().hp = 1;
    g.spawn_test_unit("archer", 1, reply_squares[0]);

    let risky_action = Action::Attack {
        unit: attacker,
        target: risky,
    };
    let safe_action = Action::Attack {
        unit: attacker,
        target: safe,
    };
    let mut ai = AdvancedAi::legacy();
    let single_reply = ai.forcing_reply_penalty(&g, 0, attacker, &risky_action);
    g.spawn_test_unit("archer", 1, reply_squares[1]);
    let risky_reply = ai.forcing_reply_penalty(&g, 0, attacker, &risky_action);
    let safe_reply = ai.forcing_reply_penalty(&g, 0, attacker, &safe_action);
    assert!(
            risky_reply > single_reply + 5.0,
            "the reply extension must price coordinated focus fire: single={single_reply}, risky={risky_reply}, safe={safe_reply}"
        );
    assert!(
            risky_reply > safe_reply + 5.0,
            "the ranged recapture must make the exposed kill materially worse: single={single_reply}, risky={risky_reply}, safe={safe_reply}"
        );
    let mut parallel_ai = ai.clone();
    parallel_ai.work_pool = Some(Arc::new(WorkPool::new(4)));
    assert_eq!(
        risky_reply,
        parallel_ai.forcing_reply_penalty(&g, 0, attacker, &risky_action)
    );
    assert_eq!(
        safe_reply,
        parallel_ai.forcing_reply_penalty(&g, 0, attacker, &safe_action)
    );

    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: g.turn,
        rush: false,
    };
    let mut parallel_game = g.clone();
    assert!(ai.advanced_military_step(&mut g, 0, attacker, &plan));
    assert!(parallel_ai.advanced_military_step(&mut parallel_game, 0, attacker, &plan));
    assert_eq!(
        serde_json::to_value(&g).unwrap(),
        serde_json::to_value(&parallel_game).unwrap()
    );
    assert!(!g.units.contains_key(&safe_defender));
    assert!(g.units.contains_key(&risky_defender));
    assert_eq!(g.units[&attacker].pos, safe);
}

#[test]
fn forcing_reply_search_prices_a_move_then_attack_counter() {
    let mut game = Game::new_full(2, 24, 16, 8_118, 80, 0, false);
    game.at_war.insert((0, 1));
    game.current = 0;
    let (anchor, prize, counter) = game
        .map
        .tiles
        .iter()
        .filter(|(position, tile)| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.unit_ids_at(**position).is_empty()
                && game.city_at(**position).is_none()
                && game
                    .cities
                    .values()
                    .all(|city| game.wdist(**position, city.pos) > 5)
                && game
                    .units
                    .values()
                    .all(|unit| game.wdist(**position, unit.pos) > 5)
        })
        .find_map(|(anchor, _)| {
            game.nbrs(*anchor).into_iter().find_map(|prize| {
                let prize_tile = game.map.get(prize)?;
                if !game.rules.is_passable(prize_tile)
                    || game.rules.is_water(prize_tile)
                    || !game.unit_ids_at(prize).is_empty()
                    || game.city_at(prize).is_some()
                {
                    return None;
                }
                game.wdisk(prize, 3).into_iter().find_map(|counter| {
                    let tile = game.map.get(counter)?;
                    (game.wdist(prize, counter) == 3
                        && game.rules.is_passable(tile)
                        && !game.rules.is_water(tile)
                        && game.unit_ids_at(counter).is_empty()
                        && game.city_at(counter).is_none()
                        && game.nbrs(counter).into_iter().any(|step| {
                            game.wdist(step, prize) == 2
                                && game.map.get(step).is_some_and(|tile| {
                                    game.rules.is_passable(tile) && !game.rules.is_water(tile)
                                })
                                && game.unit_ids_at(step).is_empty()
                                && game.city_at(step).is_none()
                        }))
                    .then_some((*anchor, prize, counter))
                })
            })
        })
        .expect("test map has a one-step ranged-counter geometry");

    for position in game.wdisk(prize, 3) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    let attacker = game.spawn_test_unit("swordsman", 0, anchor);
    let defender = game.spawn_test_unit("warrior", 1, prize);
    game.units.get_mut(&defender).unwrap().hp = 1;
    let capture = Action::Attack {
        unit: attacker,
        target: prize,
    };
    let ai = AdvancedAi::new();
    let quiet = ai.forcing_reply_penalty(&game, 0, attacker, &capture);
    game.spawn_test_unit("archer", 1, counter);
    let mobile_counter = ai.forcing_reply_penalty(&game, 0, attacker, &capture);
    assert!(
            mobile_counter > quiet + 5.0,
            "a ranged unit one step outside range must still count as a forcing reply: {mobile_counter} <= {quiet}"
        );
}

#[test]
fn forcing_reply_prefilter_keeps_one_step_attackers_and_skips_remote_wars() {
    let mut game = Game::new_full(3, 24, 16, 81_181, 80, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    let target = game
        .map
        .tiles
        .keys()
        .copied()
        .find(|target| {
            game.wdisk(*target, 3)
                .iter()
                .any(|pos| game.wdist(*target, *pos) == 3)
                && game
                    .wdisk(*target, 6)
                    .iter()
                    .any(|pos| game.wdist(*target, *pos) == 6)
                && game
                    .cities
                    .values()
                    .filter(|city| city.owner == 2)
                    .all(|city| game.wdist(*target, city.pos) > 2)
        })
        .expect("fixture needs one-step and remote reply rings");
    let one_step = game
        .wdisk(target, 3)
        .into_iter()
        .find(|pos| game.wdist(target, *pos) == 3)
        .expect("fixture has a one-step ranged-counter position");
    let remote = game
        .wdisk(target, 6)
        .into_iter()
        .find(|pos| game.wdist(target, *pos) == 6)
        .expect("fixture has a remote position");
    let exposed = game.spawn_test_unit("warrior", 0, target);
    game.spawn_test_unit("archer", 1, one_step);
    game.spawn_test_unit("archer", 2, remote);

    assert!(
        AdvancedAi::enemy_can_force_a_reply_against_any(&game, 1, &[exposed]),
        "a ranged unit one step outside direct range remains a forcing branch"
    );
    assert!(
        !AdvancedAi::enemy_can_force_a_reply_against_any(&game, 2, &[exposed]),
        "a warring army outside the search geometry needs no whole-game clone"
    );
}

#[test]
fn explicit_victory_command_phase_fires_city_center_strikes() {
    let mut game = Game::new_full(2, 20, 14, 8_119, 80, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let center = game.cities[&city].pos;
    for position in game.wdisk(center, 2) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    let target = game
        .nbrs(center)
        .into_iter()
        .find(|position| {
            game.unit_ids_at(*position).is_empty()
                && game.city_at(*position).is_none()
                && game.encampment_at(*position).is_none()
        })
        .unwrap();
    game.at_war.insert((0, 1));
    game.cities.get_mut(&city).unwrap().wall_hp = 100;
    let enemy = game.spawn_test_unit("warrior", 1, target);
    let before = game.units[&enemy].hp;

    AdvancedAi::targeting(VictoryTarget::Domination).advanced_city_strikes(&mut game, 0);

    assert!(game.cities[&city].struck);
    assert!(
        game.units
            .get(&enemy)
            .is_none_or(|defender| defender.hp < before),
        "the explicit victory command phase must spend an available wall strike"
    );
}

#[test]
fn encampment_strikes_choose_the_exact_kill_over_static_unit_strength() {
    let mut game = Game::new_full(2, 20, 14, 8_120, 80, 0, false);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    let center = game.cities[&city].pos;
    let encampment = game.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| *position != center)
        .unwrap();
    for position in game.wdisk(encampment, 2) {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }
    game.map.tiles.get_mut(&encampment).unwrap().district = Some(crate::name!("encampment"));
    game.cities
        .get_mut(&city)
        .unwrap()
        .districts
        .insert(crate::name!("encampment"), encampment);
    {
        let city = game.cities.get_mut(&city).unwrap();
        city.encampment_hp = 100;
        city.encampment_wall_hp = 100;
    }
    game.at_war.insert((0, 1));
    let targets: Vec<Pos> = game
        .nbrs(encampment)
        .into_iter()
        .filter(|position| {
            *position != encampment
                && game.city_at(*position).is_none()
                && game.encampment_at(*position).is_none()
                && game.unit_ids_at(*position).is_empty()
        })
        .take(2)
        .collect();
    assert_eq!(targets.len(), 2);
    let armor = game.spawn_test_unit("modern_armor", 1, targets[0]);
    let weak = game.spawn_test_unit("warrior", 1, targets[1]);
    game.units.get_mut(&weak).unwrap().hp = 1;
    let armor_static = game.unit_strength(&game.units[&armor], true);
    let weak_static = game.unit_strength(&game.units[&weak], true) + 99.0 * 0.6;
    assert!(
        armor_static > weak_static,
        "the legacy heuristic chose the armor"
    );

    AdvancedAi::targeting(VictoryTarget::Domination).advanced_encampment_strikes(&mut game, 0);

    assert!(game.cities[&city].encampment_struck);
    assert!(game.units.contains_key(&armor));
    assert!(!game.units.contains_key(&weak));
}

#[test]
fn force_replans_focus_after_each_battlefield_action() {
    let mut g = Game::new_full(2, 24, 16, 79, 80, 0, false);
    // Only the staged attackers belong in this force. Organic starting
    // units can otherwise split them into separate command-radius groups.
    for unit in g.player_unit_ids(0) {
        g.remove_unit(unit);
    }
    g.at_war.insert((0, 1));
    let front_candidates = quietest_first(
        &g,
        g.map
            .tiles
            .iter()
            .filter(|(pos, tile)| {
                g.rules.is_passable(tile)
                    && !g.rules.is_water(tile)
                    && g.unit_ids_at(**pos).is_empty()
            })
            .map(|(pos, _)| *pos)
            .collect(),
    );
    let (first_target, second_target, firing_line) = front_candidates
        .into_iter()
        .find_map(|first| {
            g.nbrs(first).into_iter().find_map(|second| {
                let second_tile = g.map.get(second)?;
                if !g.rules.is_passable(second_tile)
                    || g.rules.is_water(second_tile)
                    || !g.unit_ids_at(second).is_empty()
                {
                    return None;
                }
                let second_neighbors = g.nbrs(second);
                let common: Vec<Pos> = g
                    .nbrs(first)
                    .into_iter()
                    .filter(|pos| second_neighbors.contains(pos))
                    .filter(|pos| {
                        g.map.get(*pos).is_some_and(|tile| {
                            g.rules.is_passable(tile)
                                && !g.rules.is_water(tile)
                                && g.unit_ids_at(*pos).is_empty()
                        })
                    })
                    .collect();
                (common.len() >= 2).then_some((first, second, common))
            })
        })
        .expect("test map has a two-target engagement with a shared front");

    // Level the arena: the test exercises replanning after a kill, and
    // must not hinge on whichever defense modifiers the organic map put
    // under the four staged tiles.
    for position in [first_target, second_target, firing_line[0], firing_line[1]] {
        let tile = g.map.tiles.get_mut(&position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
    }

    let attackers = [
        g.spawn_test_unit("warrior", 0, firing_line[0]),
        g.spawn_test_unit("warrior", 0, firing_line[1]),
    ];
    let first_enemy = g.spawn_test_unit("warrior", 1, first_target);
    g.units.get_mut(&first_enemy).unwrap().hp = 1;
    let second_enemy = g.spawn_test_unit("warrior", 1, second_target);
    g.units.get_mut(&second_enemy).unwrap().hp = 1;
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: g.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.rebuild_force_groups(&g, 0, &plan);
    let initial = ai
        .force_groups()
        .iter()
        .find(|group| attackers.iter().all(|uid| group.units.contains(uid)))
        .unwrap();
    assert_eq!(initial.focus_target, Some(first_target));

    assert!(ai.advanced_military_step(&mut g, 0, attackers[0], &plan));
    assert!(!g.units.contains_key(&first_enemy));
    assert!(ai.advanced_military_step(&mut g, 0, attackers[1], &plan));
    let replanned = ai
        .force_groups()
        .iter()
        .find(|group| group.units.contains(&attackers[1]))
        .unwrap();
    assert_eq!(replanned.focus_target, Some(second_target));
    assert!(
        matches!(
            g.log.last(),
            Some((0, Action::Attack { unit, target }))
                if *unit == attackers[1] && *target == second_target
        ),
        "unexpected replanned action log: {:?}",
        g.log
    );
}

#[test]
fn advanced_ai_votes_in_special_sessions_and_liberates_emergency_objectives() {
    let mut vote_game = Game::new_full(3, 26, 16, 73_001, 120, 0, false);
    for player in 0..3 {
        let settler = vote_game
            .player_unit_ids(player)
            .into_iter()
            .find(|unit| vote_game.units[unit].kind == "settler")
            .unwrap();
        vote_game.found_city_for(player, vote_game.units[&settler].pos, None);
    }
    let objective = vote_game.player_city_ids(0)[0];
    vote_game.pending_emergencies = vec![crate::game::EmergencyProposal {
        id: 77,
        kind: "city_state".to_string(),
        target: 0,
        city: objective,
        original_owner: 1,
        eligible: [2].into_iter().collect(),
        requested: vote_game.turn,
    }];
    vote_game.congress = Some(crate::game::CongressSession {
        convened: vote_game.turn,
        closes: vote_game.turn + 5,
        resolutions: vec![CongressResolution {
            id: "emergency:77".to_string(),
            title: "City-State Emergency".to_string(),
            choices: vec!["A:support".to_string(), "B:oppose".to_string()],
            ballots: BTreeMap::new(),
        }],
    });
    vote_game.current = 2;
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: vote_game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::targeting(VictoryTarget::Science);
    ai.advanced_diplomacy(&mut vote_game, 2, &plan);
    assert_eq!(
        vote_game.congress.as_ref().unwrap().resolutions[0].ballots[&2].0,
        "A:support"
    );
    assert_eq!(
        ai.congress_choice(
            &vote_game,
            0,
            &vote_game.congress.as_ref().unwrap().resolutions[0],
            GrandStrategy::Conquest,
        ),
        Some("B:oppose".to_string())
    );

    let mut conquest = Game::new_full(3, 26, 16, 73_002, 120, 0, false);
    for player in 0..3 {
        let settler = conquest
            .player_unit_ids(player)
            .into_iter()
            .find(|unit| conquest.units[unit].kind == "settler")
            .unwrap();
        conquest.found_city_for(player, conquest.units[&settler].pos, None);
    }
    let objective = conquest.player_city_ids(1)[0];
    {
        let city = conquest.cities.get_mut(&objective).unwrap();
        city.owner = 0;
        city.captured_from = None;
        city.occupied_from = Some(1);
    }
    conquest.active_emergencies = vec![crate::game::Emergency {
        id: 78,
        kind: "military".to_string(),
        target: 0,
        city: objective,
        original_owner: 1,
        members: [2].into_iter().collect(),
        contributions: BTreeMap::new(),
        started: conquest.turn,
        ends: conquest.turn + 30,
    }];
    conquest.current = 2;
    let emergency_plan = ai.assess(&conquest, 2);
    assert_eq!(emergency_plan.target_player, Some(0));
    assert_eq!(emergency_plan.target_city, Some(objective));
    {
        let city = conquest.cities.get_mut(&objective).unwrap();
        city.owner = 2;
        city.captured_from = Some(0);
        city.occupied_from = Some(0);
    }
    ai.resolve_city_dispositions(&mut conquest, 2, GrandStrategy::Science);
    assert_eq!(conquest.cities[&objective].owner, 1);
    assert!(conquest.active_emergencies.is_empty());
}

#[test]
fn advanced_selfplay_completes() {
    let mut g = Game::new(2, 20, 14, 73, 65, 1);
    let mut ais = AdvancedAi::fleet(&g);
    run_game(&mut g, &mut ais);
    assert!(g.winner.is_some());
    assert!(g
        .players
        .iter()
        .filter(|p| !p.is_minor && p.alive)
        .all(|p| p.techs.len() > 1));
    // Settlers lost to Barbarians or captured legitimately break any
    // lifetime produced-vs-founded accounting. Guard the behavior this
    // test actually cares about instead: the production gate only queues a
    // Settler while the player holds none, so a player must never end the
    // game sitting on a backlog of idle Settlers.
    for player in g.players.iter().filter(|p| !p.is_minor && p.alive) {
        let idle = g
            .units
            .values()
            .filter(|u| u.owner == player.id && u.kind == "settler")
            .count();
        assert!(
            idle <= 1,
            "advanced AI accumulated idle Settlers: player {} holds {idle}",
            player.id
        );
    }
}

