/// Fires-check for `city_strategy`. The control must stamp nothing at all,
/// and the treatment must stamp exactly one directive per owned city
/// carrying the lane in force. A treatment that changes no state cannot
/// change a decision, so this is the screen that has to pass before any
/// eval is worth its compute.
#[test]
fn city_strategy_stamps_one_directive_per_city_and_the_control_stamps_none() {
    let mut game = Game::new_full(2, 24, 16, 411_001, 120, 1, false);
    found_test_city(&mut game, 0);
    found_test_city(&mut game, 0);
    let cities = game.player_city_ids(0);
    assert!(cities.len() >= 2, "need a multi-city seat to type roles");

    let mut control = AdvancedAi::new();
    control.take_turn(&mut game.clone(), 0);
    assert!(
        game.players[0].city_directives.is_empty(),
        "the shipped agent must not express a directive"
    );

    let mut treated = AdvancedAi::new();
    treated.city_strategy = true;
    treated.take_turn(&mut game, 0);

    let stamped = &game.players[0].city_directives;
    assert_eq!(
        stamped.len(),
        game.player_city_ids(0).len(),
        "every owned city gets exactly one directive"
    );
    for cid in game.player_city_ids(0) {
        assert!(stamped.contains_key(&cid), "city {cid} was left unstamped");
    }
}

/// The whole point of the channel: the same city works different tiles
/// under different empire objectives. If a Science lane and a Culture lane
/// produce identical governor weights the directive is decorative.
#[test]
fn the_lane_reaches_the_tile_the_citizen_works() {
    let science = AdvancedAi::lane_emphasis(GrandStrategy::Science, 0.0);
    let culture = AdvancedAi::lane_emphasis(GrandStrategy::Culture, 0.0);
    let conquest = AdvancedAi::lane_emphasis(GrandStrategy::Conquest, 0.0);
    assert!(science.science > culture.science);
    assert!(culture.culture > science.culture);
    assert!(conquest.production > science.production);

    let mut game = Game::new_full(2, 24, 16, 411_002, 120, 1, false);
    let city = found_test_city(&mut game, 0);
    let shipped = game.citizen_strategy(city);

    game.players[0].city_directives.insert(
        city,
        CityDirective {
            emphasis: science,
            role: CityRole::Balanced,
            pressure: 0.0,
            halt_growth: false,
        },
    );
    let under_science = game.citizen_strategy(city);
    assert!(
        under_science.weights.science > shipped.weights.science,
        "a science empire must want science tiles more than the default does"
    );
    // Additive, not a takeover: everything the local evidence said is
    // still there underneath.
    assert_eq!(under_science.weights.food, shipped.weights.food);
    assert_eq!(under_science.weights.culture, shipped.weights.culture);

    game.players[0].city_directives.insert(
        city,
        CityDirective {
            emphasis: culture,
            role: CityRole::Balanced,
            pressure: 0.0,
            halt_growth: false,
        },
    );
    let under_culture = game.citizen_strategy(city);
    assert!(under_culture.weights.culture > under_science.weights.culture);
    assert!(under_culture.weights.science < under_science.weights.science);
}

/// Military awareness is per city, not per empire. A Bastion wants hammers
/// and refuses to grow into a siege; local pressure raises the hammer
/// appetite on its own axis, so a city being approached reacts before the
/// empire-wide alarm names it.
#[test]
fn a_pressed_city_wants_hammers_and_a_bastion_stops_growing() {
    let mut game = Game::new_full(2, 24, 16, 411_003, 120, 1, false);
    let city = found_test_city(&mut game, 0);
    let calm = game.citizen_strategy(city);

    game.players[0].city_directives.insert(
        city,
        CityDirective {
            emphasis: Yields::default(),
            role: CityRole::Balanced,
            pressure: 0.6,
            halt_growth: false,
        },
    );
    let approached = game.citizen_strategy(city);
    assert!(
        approached.weights.production > calm.weights.production,
        "a city with a hostile force in reach must want production"
    );
    assert_eq!(
        approached.food_target, calm.food_target,
        "pressure alone raises hammers; it does not halt growth"
    );

    game.players[0].city_directives.insert(
        city,
        CityDirective {
            emphasis: Yields::default(),
            role: CityRole::Bastion,
            pressure: 0.6,
            halt_growth: false,
        },
    );
    let besieged = game.citizen_strategy(city);
    assert!(besieged.weights.production > approached.weights.production);
    // ⚠ A Bastion wants hammers and KEEPS GROWING. The opposite -- cutting
    // its food weight and refusing a growth surplus -- reads as obviously
    // correct and is the single mechanism the per-rung bisect convicted:
    // isolated over 120 paired maps it scores 43.8%, Elo -44 at p=0.0107,
    // and costs a fifth of the empire's cities. A besieged city that stops
    // growing does not become safer, only permanently smaller.
    assert_eq!(
        besieged.food_target, calm.food_target,
        "a bastion must not trade away its own growth"
    );
    assert_eq!(besieged.weights.food, calm.weights.food);

    game.players[0].city_directives.insert(
        city,
        CityDirective {
            emphasis: Yields::default(),
            role: CityRole::Bastion,
            pressure: 0.6,
            halt_growth: true,
        },
    );
    let halted = game.citizen_strategy(city);
    assert!(halted.weights.food < calm.weights.food);
    assert_eq!(
        halted.food_target,
        2.0 * game.cities[&city].pop as f64,
        "the frozen control still expresses the measured-worse stance"
    );
    // Nutrition is never traded away, even under the losing stance.
    assert!(halted.food_target >= 2.0 * game.cities[&city].pop as f64);
}

/// `city_pressure` is the number `threatened_city` already computed and
/// discarded. It must read zero in peace, so a directive stamped every
/// turn of a quiet game costs the governor nothing.
#[test]
fn city_pressure_is_zero_with_no_hostile_force_in_reach() {
    let mut game = Game::new_full(2, 24, 16, 411_004, 120, 1, false);
    found_test_city(&mut game, 0);
    for cid in game.player_city_ids(0) {
        assert_eq!(AdvancedAi::city_pressure(&game, 0, cid), 0.0);
    }
}

#[test]
fn city_pressure_ignores_a_hidden_hostile_inside_its_radius() {
    let mut game = Game::new_full(2, 30, 18, 411_005, 120, 0, false);
    for unit in game.player_unit_ids(1) {
        game.remove_unit(unit);
    }
    let city = found_test_city(&mut game, 0);
    let city_pos = game.cities[&city].pos;
    game.at_war.insert((0, 1));

    let visible = game.player_visibility(0);
    let candidates =
        game.wdisk(city_pos, 6)
            .into_iter()
            .filter(|position| {
                *position != city_pos
                    && game.city_at(*position).is_none()
                    && game.unit_ids_at(*position).is_empty()
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .collect::<Vec<_>>();
    let hidden = candidates
        .iter()
        .copied()
        .find(|position| !visible.contains(position))
        .expect("test city has a hidden passable tile within pressure radius");
    let seen = candidates
        .iter()
        .copied()
        .find(|position| visible.contains(position))
        .expect("test city has a visible passable tile within pressure radius");

    let hidden_warrior = game.spawn_test_unit("warrior", 1, hidden);
    assert_eq!(
        AdvancedAi::city_pressure(&game, 0, city),
        0.0,
        "an unseen hostile must not contribute city pressure"
    );
    game.remove_unit(hidden_warrior);

    game.spawn_test_unit("warrior", 1, seen);
    assert!(
        AdvancedAi::city_pressure(&game, 0, city) > 0.0,
        "the same force must count once it is visible"
    );
}

#[test]
fn campaign_city_score_uses_the_last_seen_city_combat_state() {
    let mut game = Game::new_full(2, 30, 18, 411_007, 120, 0, false);
    let settler = game
        .player_unit_ids(1)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("second player has a settler");
    game.current = 1;
    game.apply(1, &Action::FoundCity { unit: settler })
        .expect("foreign city can be founded");
    let city = game.player_city_ids(1)[0];
    let city_pos = game.cities[&city].pos;
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }

    let observer = game.spawn_test_unit("scout", 0, city_pos);
    let mut ai = AdvancedAi::new();
    ai.belief.observe(&game, 0);
    assert!(
        ai.remembered_city(city).is_some(),
        "the City Center was seen"
    );
    game.remove_unit(observer);
    assert!(
        !game.player_visibility(0).contains(&city_pos),
        "the City Center returns to fog before its live state changes"
    );

    let before = ai.campaign_city_value(&game, 0, &game.cities[&city], GrandStrategy::Conquest);
    {
        let target = game.cities.get_mut(&city).unwrap();
        target.hp = 1;
        target.wall_hp = 0;
    }
    game.spawn_test_unit("giant_death_robot", 1, city_pos);
    let after = ai.campaign_city_value(&game, 0, &game.cities[&city], GrandStrategy::Conquest);

    assert_eq!(
        before, after,
        "a hidden heal, breach, or garrison cannot rewrite the remembered campaign score"
    );
}

/// The barbarian-scout exemption is a native arm: Firaxis' barbarian scouts
/// neither attack nor capture, and the native seat's provably cannot (the
/// minor-seat gate freezes its military units; the engine scout phase moves
/// by `relocate`, which has no capture hook). The explicit selection withholds
/// it, while a focused arm can still price the promotion.
#[test]
fn the_barbarian_scout_exemption_is_native() {
    assert!(AdvancedAi::new().barbarian_scouts_are_scouts);
    assert!(!AdvancedAi::legacy().barbarian_scouts_are_scouts);
    let mut withheld = AdvancedAi::new();
    withheld.disable_barbarian_scouts_are_scouts();
    assert!(!withheld.barbarian_scouts_are_scouts);
    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(
        !live.barbarian_scouts_are_scouts,
        "the explicit selection withholds this screenable repair"
    );
    live.enable_barbarian_scouts_are_scouts();
    assert!(live.barbarian_scouts_are_scouts);
}

/// ★★★★ A camp that stands for 130 turns (civvis-20260816T200454Z): the
/// home guard's recall budget is half the army with the garrison charged
/// against it — a three-unit peacetime army with one unit in the capital
/// has a cap of zero — and the camp ranks below every raider inside the
/// six-tile ring, which with a camp raising raiders is always. See
/// `BasicAi::camp_party`. In peacetime the whole field army answers: with
/// one unit garrisoned and two in the field, both field units get an
/// objective, and with a raider five tiles out and the camp at the edge of
/// the raider radius, the camp — ranked as a raider three tiles out — is
/// answered first and the raider by the next unit; a raider at the gates
/// still comes first; a scout is never sent; the withheld arm keeps its cap
/// of zero.
///
/// ⚠ The camp sat at seven tiles until 2026-08-21, which only reached the
/// guard because `enable_live_bridge_universe` also set the nine-tile
/// `camp-reach`. That gene left the code with the ranking's bottom ten (it
/// was already withheld at deployment, so this is the radius the shipped
/// seat has been playing all along); the camp moved inside the raider
/// radius so this test measures the party and not the reach. ⚠ Inside that
/// radius a held camp is TWO threat rows — the camp and the raider standing
/// on it — each sized to the same defender, so the party doubles. That
/// double-count is `barbarian_response_objective`'s, not the party's; naming it
/// here rather than tuning a number nobody could explain later.
#[test]
fn in_peacetime_the_whole_field_army_answers_and_the_camp_outranks_the_countryside() {
    let mut game = Game::new_full(2, 30, 20, 90_078, 60, 0, true);
    for player in 0..2 {
        let settler = game
            .player_unit_ids(player)
            .into_iter()
            .find(|uid| game.units[uid].kind == "settler")
            .expect("each player opens with a settler");
        game.current = player;
        game.apply(player, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    for player in 0..2 {
        for uid in game.player_unit_ids(player) {
            game.remove_unit(uid);
        }
    }
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        if game.units[&uid].owner == barb {
            game.remove_unit(uid);
        }
    }
    game.barb_camps.clear();
    game.current = 0;
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    let open = |g: &Game, pos: Pos| {
        g.map
            .get(pos)
            .is_some_and(|tile| g.rules.is_passable(tile) && !g.rules.is_water(tile))
            && g.city_at(pos).is_none()
            && g.unit_ids_at(pos).is_empty()
    };
    let ring_at = |g: &Game, distance: i32| -> Vec<Pos> {
        let mut ring: Vec<Pos> = g
            .map
            .tiles
            .keys()
            .copied()
            .filter(|pos| g.wdist(*pos, home) == distance && open(g, *pos))
            .collect();
        ring.sort_unstable();
        ring
    };
    let camp = ring_at(&game, 6)[0];
    game.barb_camps.insert(camp, game.turn);
    game.map.tiles.get_mut(&camp).unwrap().improvement = Some(crate::name!("barbarian_camp"));
    // A spearman holds the camp: the party is sized to it, so one warrior
    // is not enough.
    let _defender = game.spawn_test_unit("spearman", barb, camp);
    // Four warriors — one in the capital, three a tile out — and a scout.
    let mut field: Vec<u32> = vec![game.spawn_test_unit("warrior", 0, home)];
    let field_ring: Vec<Pos> = ring_at(&game, 1);
    field.extend(
        field_ring
            .iter()
            .take(3)
            .map(|pos| game.spawn_test_unit("warrior", 0, *pos)),
    );
    let scout = game.spawn_test_unit("scout", 0, ring_at(&game, 2)[0]);
    let objectives = |ai: &AdvancedAi, g: &Game| -> Vec<Option<Pos>> {
        field
            .iter()
            .map(|uid| ai.base.barbarian_response_objective(g, 0, *uid, &[barb]))
            .collect()
    };

    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    assert!(live.camp_party(), "the live seat carries the party");
    let sent = objectives(&live, &game);
    assert_eq!(
        sent.iter().filter(|o| **o == Some(camp)).count(),
        4,
        "a spearman-held camp inside the raider radius draws two parties of two — \
         one for the camp, one for the raider standing on it, each sized to the \
         same spearman (25 × 1.25 = 31 > one warrior's 20): {sent:?}"
    );
    assert_eq!(
        live.base
            .barbarian_response_objective(&game, 0, scout, &[barb]),
        None,
        "a scout is not sent to clear a camp"
    );

    // The withheld arm sizes a camp party at zero — exactly one unit —
    // and would send nobody at all had the capital's warrior been counted
    // as garrison (the measured game: floor(3 × 0.5) − 1 = 0).
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge_universe();
    withheld.disable_camp_party();
    let held = objectives(&withheld, &game);
    assert!(
        held.iter().filter(|o| **o == Some(camp)).count() <= 1,
        "the withheld arm sends at most one unit to a camp: {held:?}"
    );

    // A raider five tiles out ranks below the camp; one at the gates above.
    let far_pos = ring_at(&game, 5)
        .into_iter()
        .find(|pos| game.wdist(*pos, camp) >= 3)
        .expect("open ground five out, away from the camp");
    let far = game.spawn_test_unit("warrior", barb, far_pos);
    let sent = objectives(&live, &game);
    assert!(
        sent.contains(&Some(camp)) && sent.contains(&Some(far_pos)),
        "the camp is answered before a raider in the countryside, and the raider by \
             the next unit: {sent:?}"
    );
    game.remove_unit(far);
    let gate_pos = ring_at(&game, 2)
        .into_iter()
        .find(|pos| game.unit_ids_at(*pos).is_empty())
        .expect("open ground at the gates");
    let _gate = game.spawn_test_unit("warrior", barb, gate_pos);
    let sent = objectives(&live, &game);
    assert!(
        sent.contains(&Some(gate_pos)),
        "a raider at the gates is answered first: {sent:?}"
    );

    assert!(!AdvancedAi::new().camp_party());
    assert!(!AdvancedAi::legacy().camp_party());
}

/// Remove construction-time barbarians from a non-barbarian fixture. Production
/// tests that are about culture, science, or wartime ceilings should not have
/// their queue changed by a random camp that happens to spawn near the city;
/// barbarian-specific tests install their own camps and units explicitly.
fn clear_barbarian_fixture(game: &mut Game) {
    if let Some(barb) = game.barb_pid {
        for uid in game
            .units
            .values()
            .filter(|unit| unit.owner == barb)
            .map(|unit| unit.id)
            .collect::<Vec<_>>()
        {
            game.remove_unit(uid);
        }
    }
    game.barb_camps.clear();
    game.barb_naval_camps.clear();
    game.barb_camp_guards.clear();
    game.barb_scout_homes.clear();
    game.barb_scout_targets.clear();
    game.barb_camp_targets.clear();
    game.barb_alerted_until.clear();
}

/// Board for the camp-errand pins: two founded capitals, no stray units,
/// no camps, `current = 0`. Returns the game, player 0's capital, and a
/// placer for open ground at an exact distance from it.
/// ★★★★★ WE DO NOT LOSE THE FIGHTS; WE DO NOT TAKE ENOUGH OF THEM.
///
/// MEASURED over every live run since the melee bridge was repaired (#2223),
/// from `combat` events: our melee attacks **kill 119 of 225 (53 %) and lose
/// the attacker 6 times (2.7 %)**; our ranged attacks kill 34 of 65 and have
/// **never** lost the attacker. Our swings are good. The barbarians simply
/// take **867 attacks against our 290**, which is why the early window trades
/// at 0.71 in their favour.
///
/// `attack_threshold` prices a raider the way it prices Persia. It is not the
/// same fight: no war weariness, no retaliation invited, no peace to lose, the
/// camp respawns whatever we do, and killing the unit is the only exit from
/// the zone-of-control lock that strands our Settlers. `barbarian_bargain` is
/// that difference as one number.
#[test]
fn a_raider_is_cheaper_to_attack_than_a_major_and_only_for_a_soldier() {
    let (mut game, home) = camp_bounty_board(90_079);
    let barb = game.barb_pid.unwrap();
    let ring = open_ground_at(&game, home, 4);
    let beside = *crate::hex::neighbors(ring)
        .iter()
        .find(|pos| {
            game.map
                .get(**pos)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
                && game.unit_ids_at(**pos).is_empty()
                && game.city_at(**pos).is_none()
        })
        .expect("open ground beside the ring tile");
    let soldier = game.spawn_test_unit("warrior", 0, ring);
    let raider = game.spawn_test_unit("warrior", barb, beside);

    let mut plain = AdvancedAi::new();
    plain.base.barbarian_bargain = false;
    let mut priced = AdvancedAi::new();
    priced.base.barbarian_bargain = true;
    let full = plain.base.attack_threshold(&game, soldier, beside);
    let cheap = priced.base.attack_threshold(&game, soldier, beside);
    assert_eq!(
        full - cheap,
        crate::ai::BARBARIAN_BARGAIN_DISCOUNT,
        "attacking a raider must cost exactly the discount less"
    );

    // A rival's unit on the same tile is priced at full: this is about who the
    // enemy is, not about the tile.
    game.remove_unit(raider);
    let rival = game.spawn_test_unit("warrior", 1, beside);
    assert_eq!(
        priced.base.attack_threshold(&game, soldier, beside),
        plain.base.attack_threshold(&game, soldier, beside),
        "a major's unit is the same price with the gene on"
    );

    // ⚠ And it must not turn a Scout into a casualty. The Recon doctrine adds
    // +14; an 8-point discount must leave that term firmly positive.
    // The Recon doctrine term is +14, and the discount must never cancel it or
    // a Scout would be talked into a fight it cannot win.
    game.remove_unit(rival);
    let mut scout_priced = AdvancedAi::new();
    scout_priced.base.barbarian_bargain = true;
    let scout = game.spawn_test_unit("scout", 0, ring);
    let raider_again = game.spawn_test_unit("warrior", barb, beside);
    assert!(
        scout_priced.base.attack_threshold(&game, scout, beside) > 0.0,
        "a Scout must still be priced out of attacking a raider"
    );
    let _ = raider_again;
}

/// ★★★★★ WE ANSWER SLINGERS AND ARCHERS WITH SPEARMEN.
///
/// `barbarian_defense_item` asks for a melee-capable land defender whatever the
/// ring is made of. MEASURED across every live run since the melee bridge was
/// repaired: the barbarians take **45 % of their 867 attacks ranged** while we
/// take **22 % of our 290** that way — and ranged is the safe half of the
/// board. Our 65 ranged attacks killed 34 and lost the attacker **zero** times;
/// our 225 melee attacks killed 119 and lost 6. A Spearman walking at an Archer
/// eats the shot going in and the counter on arrival.
#[test]
fn a_ring_of_shooters_is_answered_by_a_shooter_and_a_melee_ring_is_not() {
    let ranged_answer = |shooters: usize, brawlers: usize, gene: bool| -> Option<String> {
        let (mut game, home) = camp_bounty_board(90_079);
        let barb = game.barb_pid.unwrap();
        let cid = game.player_city_ids(0)[0];
        let mut ring: Vec<Pos> = game
            .map
            .tiles
            .keys()
            .copied()
            .filter(|pos| {
                game.wdist(*pos, home) == 2
                    && game.map.get(*pos).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                    && game.unit_ids_at(*pos).is_empty()
                    && game.city_at(*pos).is_none()
            })
            .collect();
        ring.sort_unstable();
        for (placed, kind) in std::iter::repeat_n("archer", shooters)
            .chain(std::iter::repeat_n("warrior", brawlers))
            .enumerate()
        {
            let pos = ring[placed];
            game.spawn_test_unit(kind, barb, pos);
        }
        let mut ai = AdvancedAi::new();
        ai.base.barbarian_ranged_answer = gene;
        match ai.base.barbarian_defense_item(&game, 0, cid) {
            Some(Item::Unit { unit }) => Some(unit.to_string()),
            _ => None,
        }
    };
    let (probe, _) = camp_bounty_board(90_079);
    let shoots = |name: &str| {
        probe
            .rules
            .units
            .iter()
            .find(|(key, _)| key.as_str() == name)
            .map(|(_, spec)| spec.has_ranged_attack())
            .unwrap_or(false)
    };
    let shooter_ring = ranged_answer(2, 0, true).expect("a ring of archers asks for a defender");
    assert!(
        shoots(&shooter_ring),
        "a ring of shooters must be answered by a shooter, got {shooter_ring}"
    );
    let same_ring_without = ranged_answer(2, 0, false).expect("still asks for a defender");
    assert!(
        !shoots(&same_ring_without),
        "without the gene the historical melee answer stands, got {same_ring_without}"
    );
    // A melee ring keeps the melee answer with the gene ON: this changes WHICH
    // defender, never how many, and only when the ring is genuinely shooters.
    let brawler_ring = ranged_answer(0, 2, true).expect("a melee ring asks for a defender");
    assert!(
        !shoots(&brawler_ring),
        "a melee ring must keep its melee answer, got {brawler_ring}"
    );
}

fn camp_bounty_board(seed: u64) -> (Game, Pos) {
    let mut game = Game::new_full(2, 30, 20, seed, 120, 0, true);
    for player in 0..2 {
        let settler = game
            .player_unit_ids(player)
            .into_iter()
            .find(|uid| game.units[uid].kind == "settler")
            .expect("each player opens with a settler");
        game.current = player;
        game.apply(player, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    for player in 0..2 {
        for uid in game.player_unit_ids(player) {
            game.remove_unit(uid);
        }
    }
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        if game.units[&uid].owner == barb {
            game.remove_unit(uid);
        }
    }
    game.barb_camps.clear();
    game.current = 0;
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    (game, home)
}

fn open_ground_at(game: &Game, home: Pos, distance: i32) -> Pos {
    let open = |pos: Pos| {
        game.map
            .get(pos)
            .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
            && game.city_at(pos).is_none()
            && game.unit_ids_at(pos).is_empty()
    };
    let mut ring: Vec<Pos> = game
        .map
        .tiles
        .keys()
        .copied()
        .filter(|pos| game.wdist(*pos, home) == distance && open(*pos))
        .collect();
    ring.sort_unstable();
    ring.into_iter()
        .next()
        .expect("open ground at the distance")
}

/// The errand itself: on the same board, the same two swordsmen clear a
/// warrior-guarded camp six tiles from the capital. The default barbarian
/// response is allowed to clear it too; the bounty treatment must not make
/// the deliberate errand slower than the ordinary response.
#[test]
fn the_peacetime_errand_clears_the_camp_and_collects_the_bounty() {
    let run = |bounty: bool| -> (Option<u32>, i64) {
        let (mut game, home) = camp_bounty_board(90_079);
        let barb = game.barb_pid.unwrap();
        let camp = open_ground_at(&game, home, 6);
        // A spawn tick far in the future keeps THIS camp from raising
        // raiders mid-pin.
        game.barb_camps.insert(camp, game.turn + 1_000);
        game.map.tiles.get_mut(&camp).unwrap().improvement = Some(crate::name!("barbarian_camp"));
        game.spawn_test_unit("warrior", barb, camp);
        game.spawn_test_unit("swordsman", 0, home);
        game.spawn_test_unit("swordsman", 0, home);
        let mut ai = AdvancedAi::new();
        ai.base.camp_bounty = bounty;
        let mut cleared_by = None;
        // Seat-turns: three seats per world turn, thirty world turns of
        // margin for six tiles of walking and a fight.
        for _ in 0..90 {
            let pid = game.current;
            if pid == 0 {
                ai.take_turn(&mut game, 0);
            }
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
            if !game.barb_camps.contains_key(&camp) {
                cleared_by = Some(game.turn);
                break;
            }
        }
        let camps = game.players[0].counters.get("camps").copied().unwrap_or(0);
        (cleared_by, camps)
    };

    let (with_errand, booked) = run(true);
    assert!(
        with_errand.is_some(),
        "thirty turns is six of walking and a fight; the errand must clear \
         the camp"
    );
    assert!(
        booked >= 1,
        "the clear is booked on the counter the boosts read"
    );

    // The default barbarian response now deliberately answers a camp this
    // close, so the errand is a non-regression check rather than a claim that
    // the bounty flag is the only route to the camp.
    let (without_errand, _) = run(false);
    assert!(
        without_errand.is_some(),
        "the default barbarian response must still clear the camp"
    );
    assert!(
        with_errand.unwrap() <= without_errand.unwrap(),
        "the errand (t{:?}) must not clear the camp after the default response \
         (t{:?})",
        with_errand,
        without_errand
    );
}

/// The errand's own gates, pinned at the function: a major war stands it
/// down, a scout is never a bounty hunter, an outmatched hunter declines,
/// and the claim ledger caps the party at two camps with one hunter each.
#[test]
fn the_camp_errand_stands_down_for_war_recon_and_bad_trades() {
    let (mut game, home) = camp_bounty_board(90_080);
    let barb = game.barb_pid.unwrap();
    let near = open_ground_at(&game, home, 4);
    game.barb_camps.insert(near, game.turn + 1_000);
    game.map.tiles.get_mut(&near).unwrap().improvement = Some(crate::name!("barbarian_camp"));

    let mut ai = AdvancedAi::new();
    ai.enable_camp_bounty();
    let hunter = game.spawn_test_unit("swordsman", 0, home);
    assert_eq!(
        ai.base.camp_bounty_target(&game, 0, hunter),
        Some(near),
        "an empty camp four tiles out is the errand"
    );

    // A scout is never a bounty hunter, even though an empty camp prices
    // above the recon attack threshold.
    let scout = game.spawn_test_unit("scout", 0, home);
    assert_eq!(ai.base.camp_bounty_target(&game, 0, scout), None);

    // An outmatched hunter declines the guarded camp.
    game.spawn_test_unit("musketman", barb, near);
    let mut fresh = AdvancedAi::new();
    fresh.enable_camp_bounty();
    assert_eq!(
        fresh.base.camp_bounty_target(&game, 0, hunter),
        None,
        "a swordsman does not trade into a fortress-era guard"
    );

    // A major war stands the whole errand down.
    let guard = game.unit_ids_at(near)[0];
    game.remove_unit(guard);
    let mut wartime = AdvancedAi::new();
    wartime.enable_camp_bounty();
    game.at_war.insert((0, 1));
    game.at_war.insert((1, 0));
    assert_eq!(wartime.base.camp_bounty_target(&game, 0, hunter), None);
    game.at_war.remove(&(0, 1));
    game.at_war.remove(&(1, 0));

    // Two camps, three hunters: each camp gets one hunter, the third unit
    // keeps its ordinary job.
    let far = open_ground_at(&game, home, 5);
    game.barb_camps.insert(far, game.turn + 1_000);
    game.map.tiles.get_mut(&far).unwrap().improvement = Some(crate::name!("barbarian_camp"));
    let second = game.spawn_test_unit("swordsman", 0, home);
    let third = game.spawn_test_unit("swordsman", 0, home);
    let mut party = AdvancedAi::new();
    party.enable_camp_bounty();
    let first_claim = party.base.camp_bounty_target(&game, 0, hunter);
    let second_claim = party.base.camp_bounty_target(&game, 0, second);
    assert_eq!(first_claim, Some(near));
    assert_eq!(second_claim, Some(far));
    assert_eq!(
        party.base.camp_bounty_target(&game, 0, third),
        None,
        "two claims is the whole party"
    );

    assert!(!AdvancedAi::new().base.camp_bounty);
    assert!(!AdvancedAi::legacy().base.camp_bounty);
}

/// An empty camp is captured by movement, not a melee attack. The barbarian
/// responder used to hand this target to `tactical_step`, which correctly holds
/// an ordinary melee unit one tile from a defender but incorrectly left this
/// camp standing forever. A Scout could instead walk past it to explore. The
/// direct clear must work without the longer-range, default-off camp-bounty
/// treatment.
#[test]
fn an_adjacent_empty_camp_is_cleared_instead_of_being_held_or_explored_past() {
    for (seed, kind) in [(90_082, "warrior"), (90_083, "scout")] {
        let (mut game, home) = camp_bounty_board(seed);
        let camp = open_ground_at(&game, home, 1);
        game.barb_camps.insert(camp, game.turn + 1_000);
        game.map.tiles.get_mut(&camp).unwrap().improvement = Some(crate::name!("barbarian_camp"));
        let unit = game.spawn_test_unit(kind, 0, home);
        let plan = StrategicPlan {
            strategy: GrandStrategy::Expansion,
            target_player: None,
            target_city: None,
            threatened_city: None,
            desired_cities: 3,
            assessed_turn: game.turn,
            rush: false,
        };
        let mut ai = AdvancedAi::new();
        ai.battlefront_observation = false;

        assert!(
            !ai.base.camp_bounty,
            "the direct clear ships independently of the errand"
        );
        assert!(
            BasicAi::barbarian_presence_at_home_with_camp_radius(
                &game,
                0,
                crate::ai::HOME_CAMP_RADIUS
            ),
            "the local camp takes the barbarian-response path"
        );
        assert!(game.player_can_see(0, camp));
        assert!(ai.advanced_military_step(&mut game, 0, unit, &plan));
        assert_eq!(game.units[&unit].pos, camp, "{kind} must enter the camp");
        assert!(
            !game.barb_camps.contains_key(&camp),
            "the responder must enter the undefended camp, not stop next to it"
        );
        assert_eq!(game.players[0].counters.get("camps"), Some(&1));
    }
}

/// The adjacent camp clear ships default-ON, but this gate keeps the controller
/// treatment outside `AdvancedAi::legacy()` — the frozen anchor whose
/// fingerprint `advanced_v1_plays_the_same_game_it_always_did` pins — exactly
/// like `naval_recon`. A shared world rule may still own a protocol bump; this
/// withhold arm prices the current-controller treatment instead.
#[test]
fn the_adjacent_camp_clear_cannot_reach_the_frozen_anchor() {
    assert!(
        !AdvancedAi::legacy().adjacent_camp_clear(),
        "this controller treatment must stay outside the frozen anchor; an \
         anchor move needs a protocol decision owned by the world rule"
    );
    assert!(AdvancedAi::new().adjacent_camp_clear());
}

#[test]
fn a_charted_village_preempts_a_prewar_campaign_staging_order() {
    let mut game = Game::new_full(2, 30, 20, 90_081, 120, 0, false);
    game.map.clear_rivers();
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
        tile.resource = None;
        tile.improvement = None;
    }
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(uid);
    }

    let mut land: Vec<Pos> = game.map.tiles.keys().copied().collect();
    land.sort();
    let (home, objective_site) = land
        .iter()
        .flat_map(|home| land.iter().map(move |objective| (*home, *objective)))
        .find(|(home, objective)| {
            game.wdist(*home, *objective) >= 16
                && game.wdisk(*home, 5).len() >= 24
                && game.wdisk(*objective, 5).len() >= 24
        })
        .expect("the map has two separated interior city sites");
    for (player, site) in [(0, home), (1, objective_site)] {
        game.current = player;
        let settler = game.spawn_test_unit("settler", player, site);
        game.apply(player, &Action::FoundCity { unit: settler })
            .expect("each site can found a city");
    }
    game.current = 0;
    game.record_contact(0, 1);
    let target_city = game.player_city_ids(1)[0];
    let objective = game.cities[&target_city].pos;
    let open = |g: &Game, pos: Pos| {
        g.map
            .get(pos)
            .is_some_and(|tile| g.rules.is_passable(tile) && !g.rules.is_water(tile))
            && g.city_at(pos).is_none()
            && g.unit_ids_at(pos).is_empty()
    };
    let (assault_at, village) = game
        .wdisk(home, 4)
        .into_iter()
        .filter(|pos| open(&game, *pos) && game.wdist(*pos, home) == 4)
        .find_map(|assault_at| {
            game.wdisk(assault_at, crate::ai::VILLAGE_MILITARY_SEEK_RADIUS)
                .into_iter()
                .filter(|pos| {
                    open(&game, *pos)
                        && game.wdist(assault_at, *pos) == crate::ai::VILLAGE_MILITARY_SEEK_RADIUS
                        && game.wdist(*pos, objective) > game.wdist(assault_at, objective)
                })
                .max()
                .map(|village| (assault_at, village))
        })
        .expect("an open field unit can reach a village away from the campaign objective");
    game.map.tiles.get_mut(&village).unwrap().improvement = Some(crate::name!("goody_hut"));
    let assault = game.spawn_test_unit("warrior", 0, assault_at);
    game.players[0]
        .explored
        .extend(game.map.tiles.keys().copied());
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: Some(target_city),
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.battlefront_observation = false;
    assert!(ai.base.village_seeking);

    let before = game.wdist(assault_at, village);
    let mut historic = game.clone();
    let mut historic_ai = ai.clone();
    assert_eq!(
        historic_ai.campaign_staging_step(&mut historic, 0, assault, &plan),
        Some(true),
        "precondition: without the village priority this Warrior would stage for war"
    );
    assert!(
        historic.wdist(historic.units[&assault].pos, village) >= before,
        "the staging route must not accidentally make progress toward the village"
    );

    assert!(ai.advanced_military_step(&mut game, 0, assault, &plan));
    assert!(
        game.wdist(game.units[&assault].pos, village) < before,
        "the nearby Warrior should collect the charted village before staging for war"
    );
}

/// The dedicated barbarian response before the campaign march, mirroring the
/// Basic step's precedence.
#[test]
fn a_barbarian_raider_at_home_is_answered_without_a_major_war() {
    let mut game = Game::new_full(2, 30, 20, 90_077, 60, 0, true);
    for player in 0..2 {
        let settler = game
            .player_unit_ids(player)
            .into_iter()
            .find(|uid| game.units[uid].kind == "settler")
            .expect("each player opens with a settler");
        game.current = player;
        game.apply(player, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    for player in 0..2 {
        for uid in game.player_unit_ids(player) {
            game.remove_unit(uid);
        }
    }
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    // Clear construction-time barbarians so the scenario holds exactly the
    // raider under test.
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        if game.units[&uid].owner == barb {
            game.remove_unit(uid);
        }
    }
    game.current = 0;
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    let open = |g: &Game, pos: Pos| {
        g.map
            .get(pos)
            .is_some_and(|tile| g.rules.is_passable(tile) && !g.rules.is_water(tile))
            && g.city_at(pos).is_none()
            && g.unit_ids_at(pos).is_empty()
    };
    // Inside the home ring, outside the garrison alarm: the field
    // response, not the city garrison, is what must answer.
    let raider_at = game
        .wdisk(home, crate::ai::HOME_THREAT_RADIUS - 1)
        .into_iter()
        .filter(|pos| {
            open(&game, *pos) && game.wdist(*pos, home) > crate::ai::GARRISON_ALERT_RADIUS
        })
        .min()
        .expect("the home ring has open land");
    game.spawn_test_unit("warrior", barb, raider_at);
    // Three tiles out: the first step toward the raider is unambiguously
    // safe (still outside a warrior's move-and-attack reach), so a mover
    // that received the objective has no cautious reason to hold.
    let soldier_at = game
        .wdisk(raider_at, 3)
        .into_iter()
        .filter(|pos| open(&game, *pos) && game.wdist(*pos, raider_at) == 3)
        .min()
        .expect("open land three tiles from the raider");
    let soldier = game.spawn_test_unit("warrior", 0, soldier_at);

    assert!(
        BasicAi::barbarian_presence_at_home_with_camp_radius(
            &game,
            0,
            crate::ai::HOME_THREAT_RADIUS
        ),
        "precondition: the raider stands within the home threat radius"
    );
    assert!(
        !game
            .players
            .iter()
            .any(|p| p.id != 0 && !p.is_barbarian && game.is_at_war(0, p.id)),
        "precondition: no major war is running, which is exactly when the \
             old enemy list went empty"
    );

    // The step is exercised directly, the way the relief-column test does:
    // this is a test of the enemy list and the objective ordering, not of
    // battlefront vision, and a spawned raider starts fogged.
    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.battlefront_observation = false;
    assert_eq!(
        ai.base
            .barbarian_response_objective(&game, 0, soldier, &[barb]),
        Some(raider_at),
        "the dedicated barbarian response must claim this unit without a major war"
    );
    let acted = ai.advanced_military_step(&mut game, 0, soldier, &plan);
    assert!(
        acted,
        "the soldier must act on the raider rather than fall through to \
             the peacetime path"
    );

    let closed = game
        .units
        .get(&soldier)
        .is_some_and(|unit| game.wdist(unit.pos, raider_at) < 3);
    let answered = game
        .units
        .values()
        .find(|unit| unit.owner == barb)
        .map(|raider| raider.hp < 100)
        .unwrap_or(true);
    assert!(
        closed || answered,
        "a raider pillaging at home must draw the soldier in or take a hit; \
             the soldier stood at {:?} with the raider untouched at {raider_at:?}",
        game.units.get(&soldier).map(|unit| unit.pos)
    );
}

/// A kill that is already legal this turn is not a campaign order.  In
/// particular, a barbarian need not be inside the bounded response list:
/// leaving a one-health raider alive beside an available Warrior is never the
/// staging discipline this controller is trying to preserve.
#[test]
fn immediate_kill_priority_finishes_barbarians_and_wartime_units() {
    let mut game = Game::new_full(2, 30, 20, 90_079, 60, 0, true);
    for pid in 0..2 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|uid| game.units[uid].kind == "settler")
            .expect("each major starts with a Settler");
        game.apply(pid, &Action::FoundCity { unit: settler })
            .expect("fixture capitals must be founded");
    }
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(uid);
    }
    game.barb_camps.clear();
    game.barb_naval_camps.clear();
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    game.current = 0;
    game.at_war.insert((0, 1));

    let mut open: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(pos, tile)| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.city_at(**pos).is_none()
                && game.unit_ids_at(**pos).is_empty()
        })
        .map(|(pos, _)| *pos)
        .collect();
    open.sort_unstable();
    let (civ_target, civ_attacker_at) = open
        .iter()
        .copied()
        .find_map(|target| {
            game.nbrs(target)
                .into_iter()
                .find(|attacker| open.contains(attacker))
                .map(|attacker| (target, attacker))
        })
        .expect("fixture needs an adjacent open civ duel");
    let (barb_target, barb_attacker_at) = open
        .iter()
        .copied()
        .filter(|target| {
            game.wdist(*target, civ_target) > 4 && game.wdist(*target, civ_attacker_at) > 4
        })
        .find_map(|target| {
            game.nbrs(target)
                .into_iter()
                .find(|attacker| {
                    open.contains(attacker)
                        && game.wdist(*attacker, civ_target) > 4
                        && game.wdist(*attacker, civ_attacker_at) > 4
                })
                .map(|attacker| (target, attacker))
        })
        .expect("fixture needs a separate adjacent barbarian duel");
    let enemy_reserve_at = open
        .iter()
        .copied()
        .find(|position| {
            [civ_target, civ_attacker_at, barb_target, barb_attacker_at]
                .iter()
                .all(|other| game.wdist(*position, *other) > 6)
        })
        .expect("fixture needs a distant enemy survivor");

    let civ_attacker = game.spawn_test_unit("warrior", 0, civ_attacker_at);
    let barb_attacker = game.spawn_test_unit("warrior", 0, barb_attacker_at);
    let wartime_target = game.spawn_test_unit("warrior", 1, civ_target);
    let barbarian_target = game.spawn_test_unit("warrior", barb, barb_target);
    game.spawn_test_unit("warrior", 1, enemy_reserve_at);
    game.units.get_mut(&wartime_target).unwrap().hp = 1;
    game.units.get_mut(&barbarian_target).unwrap().hp = 1;
    assert!(
        game.is_at_war(0, 1),
        "the civilization target is a war enemy"
    );
    assert!(
        game.is_at_war(0, barb),
        "barbarians are hostile without a declaration"
    );

    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    let legal = game.legal_actions_within(0, ActionFamilies::UNITS);
    let finished = ai.prioritize_immediate_kills(&mut game, 0, &plan);
    assert_eq!(
        finished, 2,
        "each available positive exchange must finish its removable target; \
         legal={legal:?}, log={:?}",
        game.log
    );
    assert!(!game.units.contains_key(&wartime_target));
    assert!(!game.units.contains_key(&barbarian_target));
    let finishers = [civ_attacker, barb_attacker];
    assert!(
        game.log
            .iter()
            .filter(|(_, action)| {
                matches!(action, Action::Attack { unit, target }
                if finishers.contains(unit) && [civ_target, barb_target].contains(target))
            })
            .count()
            >= 2,
        "the kills must be combat strikes, not a movement side effect: {:?}",
        game.log
    );
}

/// The full unit-turn pipeline must take the same finish before its normal
/// barbarian campaign filter runs.  A distant raider is deliberately not a
/// barbarian-response objective, but an adjacent one-hit kill is still immediate
/// combat rather than a request to start chasing camps across the map.
#[test]
fn advanced_turn_finishes_a_distant_barbarian_before_campaign_filtering() {
    let mut game = Game::new_full(2, 30, 20, 90_080, 60, 0, true);
    for pid in 0..2 {
        game.current = pid;
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|uid| game.units[uid].kind == "settler")
            .expect("each major starts with a Settler");
        game.apply(pid, &Action::FoundCity { unit: settler })
            .expect("fixture capitals must be founded");
    }
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(uid);
    }
    game.barb_camps.clear();
    game.barb_naval_camps.clear();
    game.current = 0;
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    let target =
        game.map
            .tiles
            .iter()
            .filter(|(position, tile)| {
                game.wdist(**position, home) > crate::ai::HOME_THREAT_RADIUS + 1
                    && game.rules.is_passable(tile)
                    && !game.rules.is_water(tile)
                    && game.city_at(**position).is_none()
                    && game.unit_ids_at(**position).is_empty()
            })
            .map(|(position, _)| *position)
            .find(|target| {
                game.nbrs(*target).into_iter().any(|attacker| {
                    game.map.get(attacker).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    }) && game.city_at(attacker).is_none()
                })
            })
            .expect("fixture needs a distant open barbarian duel");
    let attacker_at = game
        .nbrs(target)
        .into_iter()
        .find(|position| {
            game.map
                .get(*position)
                .is_some_and(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
                && game.city_at(*position).is_none()
        })
        .expect("target needs a passable melee tile");
    let attacker = game.spawn_test_unit("warrior", 0, attacker_at);
    let raider = game.spawn_test_unit("warrior", barb, target);
    game.units.get_mut(&raider).unwrap().hp = 1;
    assert!(
        !BasicAi::barbarian_presence_at_home_with_camp_radius(
            &game,
            0,
            crate::ai::HOME_THREAT_RADIUS
        ),
        "the raider must stay outside the normal bounded barbarian target list"
    );

    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.advanced_units(&mut game, 0, &plan);

    assert!(!game.units.contains_key(&raider));
    assert!(
        game.log.iter().any(|(_, action)| {
            matches!(action, Action::Attack { unit, target: struck }
                if *unit == attacker && *struck == target)
        }),
        "the full Advanced turn must issue the distant finishing strike: {:?}",
        game.log
    );
}

/// ★★★★★ A HOME RAIDER MUST NOT FREEZE THE REST OF A PRE-WAR ARMY.
///
/// The live bridge intentionally puts the barbarian seat in `enemies`
/// while a raider threatens a city. That made the controller leave the
/// `enemies.is_empty()` branch, which contains `campaign_staging_step`.
/// Consequently, the bounded barbarian-response assignment did not merely claim
/// its responder: it paused every unclaimed assault unit until the raider
/// disappeared. On live run `civvis-20260815T190904Z`, Rome held off its
/// Netherlands declaration from turns 95 through 104 despite 337--462
/// power against 69--76, while home raiders remained in range.
#[test]
fn a_distant_campaign_unit_stays_staged_while_barbarians_are_at_home() {
    let mut game = Game::new_full(2, 30, 20, 90_078, 120, 0, true);
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
    }
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(uid);
    }

    let mut land: Vec<Pos> = game.map.tiles.keys().copied().collect();
    land.sort();
    let mut sites = None;
    'find_sites: for home in &land {
        for objective in &land {
            if game.wdist(*home, *objective) >= 16
                && game.wdisk(*home, crate::ai::HOME_THREAT_RADIUS).len() >= 24
                && game.wdisk(*objective, 4).len() >= 18
            {
                sites = Some((*home, *objective));
                break 'find_sites;
            }
        }
    }
    let (home, objective_site) = sites.expect("the map has separated interior city sites");
    for (player, site) in [(0, home), (1, objective_site)] {
        game.current = player;
        let settler = game.spawn_test_unit("settler", player, site);
        game.apply(player, &Action::FoundCity { unit: settler })
            .expect("each chosen site can found a city");
    }
    game.current = 0;
    game.record_contact(0, 1);
    let target_city = game.player_city_ids(1)[0];
    let objective = game.cities[&target_city].pos;
    let barb = game.barb_pid.expect("a barbarian-seated game has barb_pid");
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        if game.units[&uid].owner == barb {
            game.remove_unit(uid);
        }
    }
    let open = |g: &Game, pos: Pos| {
        g.map
            .get(pos)
            .is_some_and(|tile| g.rules.is_passable(tile) && !g.rules.is_water(tile))
            && g.city_at(pos).is_none()
            && g.unit_ids_at(pos).is_empty()
    };
    let raider_at = game
        .wdisk(home, crate::ai::HOME_THREAT_RADIUS - 1)
        .into_iter()
        .filter(|pos| open(&game, *pos))
        .max_by_key(|pos| (game.wdist(*pos, objective), *pos))
        .expect("the home ring has an open land tile");
    game.spawn_test_unit("warrior", barb, raider_at);
    let staging_at = game
        .wdisk(objective, 4)
        .into_iter()
        .filter(|pos| {
            open(&game, *pos)
                && game.wdist(*pos, objective) == 4
                && game.wdist(*pos, raider_at) > 10
                && game.nbrs(*pos).into_iter().any(|next| {
                    game.wdist(next, objective) == 3
                        && game.map.get(next).is_some_and(|tile| {
                            tile.owner_city
                                .and_then(|city| game.cities.get(&city))
                                .is_none_or(|city| city.owner != 1)
                        })
                })
        })
        .max_by_key(|pos| (game.wdist(*pos, raider_at), *pos))
        .expect("a legal staging tile remains outside the home-recall range");
    let assault = game.spawn_test_unit("swordsman", 0, staging_at);
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: Some(target_city),
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.battlefront_observation = false;

    assert!(
        BasicAi::barbarian_presence_at_home_with_camp_radius(
            &game,
            0,
            crate::ai::HOME_THREAT_RADIUS
        ),
        "precondition: the barbarian is inside Rome's home-threat ring"
    );
    assert!(
        ai.campaign_staging_position(&game, 0, 1, assault, objective, staging_at),
        "precondition: the assault unit already occupies a lawful 3--5 staging tile"
    );
    assert_eq!(
        ai.base
            .barbarian_response_objective(&game, 0, assault, &[barb]),
        None,
        "the assault unit is beyond the bounded recall range and stays unclaimed"
    );

    // This is the old fall-through: it treats the foreign city as a
    // tactical destination even though the only actual enemy is the
    // barbarian, and walks a correctly staged unit one tile closer.
    let mut historic = game.clone();
    let historic_ai = ai.clone();
    assert!(
        historic_ai
            .base
            .tactical_step(&mut historic, 0, assault, objective, &[barb], 1),
        "precondition: the old tactical fallback would abandon the staging ring"
    );
    assert_ne!(
        historic.units[&assault].pos, staging_at,
        "the historical fallback must move the staged unit before this regression is meaningful"
    );

    let _ = ai.advanced_military_step(&mut game, 0, assault, &plan);
    assert_eq!(
            game.units[&assault].pos, staging_at,
            "after bounded defenders get first claim, the unclaimed assault unit must hold its campaign staging tile"
        );
    assert!(
            game.units[&assault].fortified,
            "the campaign staging order must claim and hold the assault unit while the home raider is active"
        );
    assert!(
        !game.is_at_war(0, 1),
        "the pre-war staging treatment must not open the major war itself"
    );
}

/// ★★★★★ A RELIEF COLUMN MUST AIM AT THE SIEGE, NOT AT ITS OWN DOORSTEP.
///
/// `domain_objective`'s `threatened_city` arm gathers every hostile within 8
/// of the besieged city and then takes the one nearest the RELIEVING FORCE.
/// A force standing east of a burning city therefore aims at the easternmost
/// besieger — on the far side of the ring — and two force groups anchored in
/// different places aim at different enemies, so the army never converges.
///
/// ⚠⚠⚠ Measured live on run `civvis-20260803T220954Z`, t180–187, with the
/// embarkation, visibility and border repairs all running. Mediolanum went
/// 0 → 29 → 98 → 167 → 180 damage out of 200 in four turns with eight
/// hostiles inside five hexes; **five of our nine combat units stood 8 to 11
/// hexes away**, and the journalled objectives were all on the far side of
/// the ring. The city fell and the run ended in defeat holding one city.
#[test]
fn a_relief_column_aims_at_the_siege_not_at_its_own_doorstep() {
    let mut game = Game::new_full(2, 30, 18, 411_011, 120, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    game.players[0].met.insert(1);
    game.players[1].met.insert(0);
    game.apply(0, &Action::DeclareWar { player: 1 })
        .expect("the seats can go to war");

    // Our city, and a straight run of land east of it so the geometry is
    // unambiguous: the besieger is adjacent to the city, the loiterer is far
    // from the city but close to where our force is standing.
    let mut land: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(_, tile)| !game.rules.is_water(tile))
        .map(|(pos, _)| *pos)
        .collect();
    land.sort();
    let city_pos = land[0];
    let settler = game.spawn_test_unit("settler", 0, city_pos);
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("the city can be founded");
    let cid = game.player_city_ids(0)[0];

    let pick = |d: i32, from: Pos| -> Pos {
        *land
            .iter()
            .find(|pos| game.wdist(**pos, from) == d && **pos != city_pos)
            .unwrap_or_else(|| panic!("a land tile {d} from {from:?}"))
    };
    let besieger_pos = pick(1, city_pos);
    let anchor = pick(7, city_pos);
    let loiterer_pos = pick(1, anchor);

    game.spawn_test_unit("warrior", 1, besieger_pos);
    game.spawn_test_unit("warrior", 1, loiterer_pos);
    let ours = game.spawn_test_unit("warrior", 0, anchor);

    // Both hostiles are inside the city's 8-ring, so both are candidates;
    // the only question is which one the column is sent to.
    assert!(
        game.wdist(city_pos, loiterer_pos) <= 8,
        "both are candidates"
    );

    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: Some(cid),
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let enemies = [1usize];

    let mut ai = AdvancedAi::new();
    // The candidate filter honours fog when battlefront observation is on,
    // and this test is about the ORDERING, not about what can be seen.
    ai.battlefront_observation = false;
    let _ = ours;

    ai.disable_relief_targets_the_siege();
    let nearest_to_us = ai.domain_objective(&game, 0, &plan, ForceDomain::Land, anchor, &enemies);
    ai.enable_relief_targets_the_siege();
    let nearest_to_city = ai.domain_objective(&game, 0, &plan, ForceDomain::Land, anchor, &enemies);

    assert_eq!(
        nearest_to_us, loiterer_pos,
        "the historical rule aims at whatever stands nearest the force — this is \
             the defect, and it left five of nine units 8 to 11 hexes from a city at \
             180 damage out of 200"
    );
    assert_eq!(
        nearest_to_city, besieger_pos,
        "the relief column must aim at what is actually hitting the city"
    );
}

/// A passable, empty land tile exactly `distance` from `home`, at least
/// `clear` hexes from every `(tile, clear)` in `away`, with at least `room`
/// such tiles beside it; lowest coordinates first so the pick is
/// deterministic.
fn clear_land_at(game: &Game, home: Pos, distance: i32, away: &[(Pos, i32)], room: usize) -> Pos {
    let open = |pos: Pos| {
        game.map.get(pos).is_some_and(|tile| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.city_at(pos).is_none()
                && game.unit_ids_at(pos).is_empty()
        })
    };
    let mut candidates: Vec<Pos> = game
        .map
        .tiles
        .keys()
        .copied()
        .filter(|pos| game.wdist(*pos, home) == distance && open(*pos))
        .filter(|pos| {
            away.iter()
                .all(|(other, clear)| game.wdist(*pos, *other) >= *clear)
        })
        .filter(|pos| {
            game.nbrs(*pos)
                .into_iter()
                .filter(|beside| open(*beside))
                .count()
                >= room
        })
        .collect();
    candidates.sort_unstable();
    *candidates
        .first()
        .unwrap_or_else(|| panic!("no clear land tile {distance} hexes from {home:?}"))
}

/// An empty land neighbour of `of`, lowest coordinates first.
fn clear_land_beside(game: &Game, of: Pos, not: &[Pos]) -> Pos {
    let mut candidates: Vec<Pos> = game
        .nbrs(of)
        .into_iter()
        .filter(|pos| {
            game.map.get(*pos).is_some_and(|tile| {
                game.rules.is_passable(tile)
                    && !game.rules.is_water(tile)
                    && game.city_at(*pos).is_none()
                    && game.unit_ids_at(*pos).is_empty()
            }) && !not.contains(pos)
        })
        .collect();
    candidates.sort_unstable();
    *candidates
        .first()
        .unwrap_or_else(|| panic!("no clear land tile beside {of:?}"))
}

/// ★★★★★ A RELIEF COLUMN MARCHES; THE RING HOLDS.
///
/// Run `civvis-20260827T113726Z`, t161–164: Aquileia (pop 15, walled, no
/// garrison) under a Chinese Artillery, Field Cannon, three Infantry and two
/// Cuirassiers. Our main army — seven units, **1.58** local strength against
/// that stack, objective the besieger's own hex at (20,30) — logged "A land
/// force of 7 will hold … held back to cover a threat" on every frame of
/// every turn and stood at x=7–13, nine hexes west, until the city fell on
/// t164. `relieving` was `plan.threatened_city.is_some()` — true for every
/// group in the empire — and a Hold's mover target is the group's own
/// anchor. #354 measured the reach test, shipped it off, and #1194 pruned
/// it.
///
/// With the gene: a group beyond `THREAT_RELIEF_RADIUS` of the threatened
/// city that is locally superior advances on the siege; a group inside the
/// radius holds its ring exactly as before; the frozen anchor is untouched.
#[test]
fn a_relief_column_beyond_the_threat_radius_advances_on_the_siege() {
    let (mut game, capital, home) = empire_with_a_capital(71_131);
    let besieger_pos = clear_land_at(&game, home, 1, &[], 0);
    game.spawn_test_unit("warrior", 1, besieger_pos);
    // The column: two warriors nine hexes out, side by side, so the group
    // is fully mustered and twice the besieger's strength.
    let far = clear_land_at(&game, home, 9, &[], 1);
    let far_two = clear_land_beside(&game, far, &[]);
    let column_a = game.spawn_test_unit("warrior", 0, far);
    let column_b = game.spawn_test_unit("warrior", 0, far_two);
    // The ring: one warrior three hexes out, out of contact with the
    // besieger and out of the column's command radius.
    let near = clear_land_at(
        &game,
        home,
        3,
        &[(besieger_pos, 3), (far, 7), (far_two, 7)],
        0,
    );
    let ring = game.spawn_test_unit("warrior", 0, near);

    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: Some(capital),
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let group_of = |ai: &AdvancedAi, unit: u32| -> ForceGroup {
        ai.force_groups()
            .iter()
            .find(|group| group.units.contains(&unit))
            .cloned()
            .unwrap_or_else(|| panic!("unit {unit} receives a force order"))
    };

    let mut ai = AdvancedAi::new();
    // The geometry is the question, not what the turn-start frame saw.
    ai.battlefront_observation = false;
    assert!(
        !ai.relief_column_marches,
        "a repair gene ships off in the constructor"
    );

    ai.rebuild_force_groups(&game, 0, &plan);
    let column = group_of(&ai, column_a);
    assert!(column.units.contains(&column_b), "the pair is one group");
    assert!(
        !column.units.contains(&ring),
        "the ring warrior is not in the column"
    );
    assert!(
        game.wdist(column.anchor, home) > THREAT_RELIEF_RADIUS,
        "the column stands beyond the relief radius: {}",
        game.wdist(column.anchor, home)
    );
    assert!(
        column.local_strength_ratio >= LOCAL_SUPERIORITY_FLOOR,
        "two warriors against one are locally superior: {}",
        column.local_strength_ratio
    );
    assert_eq!(
        column.objective, besieger_pos,
        "the objective is the besieger"
    );
    assert_eq!(
        column.posture,
        ForcePosture::Hold,
        "the shipped rule: every group holds while any city is threatened — this \
         is the defect, nine hexes from a city at 145 damage out of 200"
    );
    assert_eq!(group_of(&ai, ring).posture, ForcePosture::Hold);
    assert_eq!(
        ai.relief_hold_point(&game, &column),
        None,
        "with the gene off a Hold stands at its anchor"
    );

    ai.enable_relief_column_marches();
    ai.rebuild_force_groups(&game, 0, &plan);
    let column = group_of(&ai, column_a);
    assert_eq!(
        column.posture,
        ForcePosture::Advance,
        "a locally superior column beyond the relief radius marches on the siege"
    );
    assert_eq!(column.objective, besieger_pos);
    let ring_group = group_of(&ai, ring);
    assert!(game.wdist(ring_group.anchor, home) <= THREAT_RELIEF_RADIUS);
    assert_eq!(
        ring_group.posture,
        ForcePosture::Hold,
        "a group inside the radius is part of the defence and holds its ring"
    );
    // Where a Hold stands: the column at the threatened city, the ring at
    // its own anchor.
    ai.plan = Some(plan.clone());
    assert_eq!(
        ai.relief_hold_point(&game, &column),
        Some(home),
        "a column too weak to advance would still hold AT the city"
    );
    assert_eq!(ai.relief_hold_point(&game, &ring_group), None);

    let mut legacy = AdvancedAi::legacy();
    legacy.battlefront_observation = false;
    legacy.rebuild_force_groups(&game, 0, &plan);
    assert_eq!(
        group_of(&legacy, column_a).posture,
        ForcePosture::Hold,
        "the frozen anchor keeps the empire-wide hold"
    );
}

/// The t160 frame of the same run: the army's posture read "Engage" with
/// its objective at the Chinese Cuirassier, but the focus — the tile the
/// Engage mover walks to — was a Chinese Apostle standing beside the
/// crossbowmen, which every unit then "declines" (worth −∞). While a city is
/// threatened, a column's focus is a combatant or a city; at peace the gene
/// changes nothing.
#[test]
fn a_relief_columns_focus_is_a_combatant_not_a_civilian() {
    let (mut game, capital, home) = empire_with_a_capital(71_132);
    let stand = clear_land_at(&game, home, 5, &[], 2);
    let ours = game.spawn_test_unit("warrior", 0, stand);
    let beside = clear_land_beside(&game, stand, &[]);
    game.spawn_test_unit("builder", 1, beside);
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: None,
        threatened_city: Some(capital),
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    };
    let calm = StrategicPlan {
        threatened_city: None,
        ..plan.clone()
    };
    let enemies = [1usize];
    let mut ai = AdvancedAi::new();
    ai.battlefront_observation = false;

    assert_eq!(
        ai.force_focus_target(&game, 0, &[ours], &enemies, &plan),
        Some(beside),
        "the shipped rule focuses on any enemy tile in reach"
    );
    ai.enable_relief_column_marches();
    assert_eq!(
        ai.force_focus_target(&game, 0, &[ours], &enemies, &plan),
        None,
        "a Builder is not what is shelling the city"
    );
    assert_eq!(
        ai.force_focus_target(&game, 0, &[ours], &enemies, &calm),
        Some(beside),
        "with no city threatened the gene is inert"
    );
    let other = clear_land_beside(&game, stand, &[beside]);
    game.spawn_test_unit("warrior", 1, other);
    assert_eq!(
        ai.force_focus_target(&game, 0, &[ours], &enemies, &plan),
        Some(other),
        "an enemy warrior in reach is still the focus"
    );
}

/// ★★★★★ A FOGGED OBJECTIVE IS NOT A DOMINATED ONE.
///
/// `local_strength_ratio` returns `3.0` — its maximum, "we dominate here" —
/// whenever `hostile <= 0.0`, and that condition cannot tell ground we can
/// see and is empty apart from ground we simply cannot see.
/// `blind_objective_strength` repaired the `g.city_at(objective)` term, but
/// an objective that is not a city has nothing left but the *visible*
/// enemy units within six tiles.
///
/// ⚠⚠⚠ Measured on live run `civvis-20260803T200117Z` (finished, t251), by
/// splitting every force-group decision on whether a known enemy city stood
/// on its objective: of **982** decisions, **523 (53.3%)** read the `3.00`
/// sentinel, and **355 of those — 68% — had no city on the objective**, so
/// no repair could reach them. The army read maximum local superiority on
/// more than a third of every decision it made, in a game it lost 343 to
/// 1214 while never once declaring war.
#[test]
fn a_fogged_objective_is_not_a_dominated_one() {
    let mut game = Game::new_full(2, 30, 18, 411_009, 120, 0, false);
    for unit in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(unit);
    }
    game.players[0].met.insert(1);
    game.players[1].met.insert(0);
    game.apply(0, &Action::DeclareWar { player: 1 })
        .expect("the seats can go to war");

    // Any two land tiles far enough apart that our own force cannot see the
    // objective. The objective is deliberately NOT a city: that is the
    // population the existing repair cannot reach.
    let mut land: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(_, tile)| !game.rules.is_water(tile))
        .map(|(pos, _)| *pos)
        .collect();
    land.sort();
    let objective = land[0];
    let staging = *land
        .iter()
        .find(|pos| game.wdist(**pos, objective) == 5)
        .expect("a land tile five hexes from the objective");

    let ours = game.spawn_test_unit("warrior", 0, staging);
    game.spawn_test_unit("warrior", 1, objective);

    // See it once, then lose sight of it. The enemy never moves and never
    // changes: the only thing that changes is whether we are looking.
    let observer = game.spawn_test_unit("scout", 0, objective);
    let mut ai = AdvancedAi::new();
    ai.belief.observe(&game, 0);
    game.remove_unit(observer);
    assert!(
        !game.player_visibility(0).contains(&objective),
        "the objective must be back in fog, or this measures nothing"
    );

    let units = [ours];
    let enemies = [1usize];

    ai.disable_blind_objective_units();
    let blind = ai.local_strength_ratio(&game, 0, &units, &enemies, objective);
    ai.enable_blind_objective_units();
    let believing = ai.local_strength_ratio(&game, 0, &units, &enemies, objective);

    assert_eq!(
        blind, 3.0,
        "without the repair a fogged objective reads as the maximum — this is \
             the defect, and it fired on 53.3% of force decisions in a live game"
    );
    assert!(
        believing < 3.0,
        "an enemy this controller has SEEN standing on the objective must still \
             count against it once it goes back into fog; got {believing}"
    );
}

#[test]
fn belief_pressure_remembers_a_hidden_contact_without_reading_current_state() {
    let mut game = Game::new_full(2, 30, 18, 411_006, 120, 0, false);
    for unit in game.player_unit_ids(1) {
        game.remove_unit(unit);
    }
    let city = found_test_city(&mut game, 0);
    let city_pos = game.cities[&city].pos;
    game.at_war.insert((0, 1));

    let hidden =
        game.wdisk(city_pos, THREAT_RELIEF_RADIUS)
            .into_iter()
            .find(|position| {
                *position != city_pos
                    && game.city_at(*position).is_none()
                    && game.unit_ids_at(*position).is_empty()
                    && !game.player_visibility(0).contains(position)
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .expect("test city has a hidden passable pressure tile");
    let enemy = game.spawn_test_unit("warrior", 1, hidden);
    let scout_candidates =
        game.wdisk(hidden, 2)
            .into_iter()
            .filter(|position| {
                *position != hidden
                    && game.city_at(*position).is_none()
                    && game.unit_ids_at(*position).is_empty()
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
            })
            .collect::<Vec<_>>();
    let scout = scout_candidates
        .into_iter()
        .find_map(|position| {
            let scout = game.spawn_test_unit("scout", 0, position);
            let sees_enemy =
                game.player_visibility(0).contains(&hidden) && game.unit_visible_to(enemy, 0);
            if sees_enemy {
                Some(scout)
            } else {
                game.remove_unit(scout);
                None
            }
        })
        .expect("an adjacent scout can observe the hidden pressure tile");

    let mut ai = AdvancedAi::new();
    ai.belief_pressure = true;
    ai.belief.observe(&game, 0);
    assert!(ai.belief.units.contains_key(&enemy));
    let observed = AdvancedAi::city_pressure(&game, 0, city);
    assert!(observed > 0.0, "the scout makes the contact visible");
    assert_eq!(
        ai.belief_city_pressure(&game, 0, city),
        observed,
        "a refreshed visible sighting must not be counted twice"
    );

    game.remove_unit(scout);
    assert!(
        !game.player_visibility(0).contains(&hidden),
        "the contact returns to fog once the scout leaves"
    );
    ai.belief.observe(&game, 0);
    assert_eq!(AdvancedAi::city_pressure(&game, 0, city), 0.0);
    let remembered = ai.belief_city_pressure(&game, 0, city);
    assert!(remembered > 0.0, "a last-seen hostile affects recovery");

    // Deleting the real hidden unit cannot change the memory term: the
    // controller is allowed to know what it saw, not what happened later.
    game.remove_unit(enemy);
    ai.belief.observe(&game, 0);
    assert_eq!(ai.belief_city_pressure(&game, 0, city), remembered);

    game.turn += BELIEF_PRESSURE_HORIZON;
    ai.belief.observe(&game, 0);
    assert_eq!(
        ai.belief_city_pressure(&game, 0, city),
        0.0,
        "a four-turn-old contact cannot sustain a recovery alarm"
    );
}

/// Factual coverage check for the evaluator arm, not an outcome claim.
/// It asks how often a current major's own observation history adds local
/// pressure, and how often that addition changes the recovery selector.
/// Run with `cargo test --profile ci belief_pressure_census -- --ignored
/// --nocapture` before spending a fresh outcome prefix.
#[test]
#[ignore = "factual mechanism census; run explicitly with --nocapture"]
fn belief_pressure_census() {
    let mut city_turns = 0u64;
    let mut memory_city_turns = 0u64;
    let mut memory_only_city_turns = 0u64;
    let mut recovery_changes = 0u64;

    for map in 0..12u64 {
        let mut game = Game::new_full(4, 44, 28, 871_000 + map, 200, 0, false);
        game.set_fog_memory(false);
        let mut fleet = AdvancedAi::fleet(&game);
        for ai in &mut fleet {
            ai.belief_pressure = true;
        }

        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            if !game.players[pid].is_minor && !game.players[pid].is_barbarian {
                // `take_turn` refreshes the live controller at exactly this
                // point. Clone it to audit that imminent calculation
                // without mutating the player who will actually act.
                let mut probe = fleet[pid].clone();
                probe.belief.observe(&game, pid);
                let stock = AdvancedAi::new().threatened_city(&game, pid);
                let remembered = probe.threatened_city(&game, pid);
                recovery_changes += u64::from(stock != remembered);
                for city in game.player_city_ids(pid) {
                    city_turns += 1;
                    let observed = AdvancedAi::city_pressure(&game, pid, city);
                    let pressure = probe.belief_city_pressure(&game, pid, city);
                    if pressure > observed {
                        memory_city_turns += 1;
                    }
                    if observed == 0.0 && pressure > 0.0 {
                        memory_only_city_turns += 1;
                    }
                }
            }
            fleet[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
        }
    }

    println!(
            "belief-pressure census: {memory_city_turns}/{city_turns} city-turns with memory, \
             {memory_only_city_turns}/{city_turns} memory-only, {recovery_changes} recovery changes"
        );
    assert!(
        memory_city_turns > 0,
        "the evaluator arm never receives a hidden remembered contact"
    );
}

/// Census, not an assertion: how often each rung of the role ladder fires
/// over real games, and what share of Bastion stamps are driven by
/// barbarians alone.
///
/// The roles half of `city_strategy` lost 120 maps at Elo -55 while the
/// emphasis half was a clean null, and the empire it produced was smaller
/// in every column (cities 2.14 against 2.77). Two candidate mechanisms
/// survive that: Bastion halting growth on barbarian contact, or
/// Forge/Specialist pulling citizens off food in empires too small for
/// `ROLE_MARGIN` to type meaningfully. Guessing between them once already
/// cost a wrong hypothesis, so this counts instead.
///
/// Run with `cargo test --release role_ladder_census -- --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn role_ladder_census() {
    let mut totals = BTreeMap::<&str, u64>::new();
    let mut lanes = BTreeMap::<&str, u64>::new();
    let mut barbarian_only_bastions = 0u64;
    let mut pressured = 0u64;
    let mut pressure_sum = 0.0f64;
    let mut extra_hammers = 0.0f64;
    // Per-turn means hide minority behaviour, and the settler window is a
    // minority of the game. Band it.
    let mut band_turns = [0u64; 4];
    let mut band_bastions = [0u64; 4];
    let mut city_turns = 0u64;
    let mut halted_pop = 0u64;

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 420_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len())
            .map(|_| {
                let mut ai = AdvancedAi::new();
                ai.city_strategy = true;
                ai.city_strategy_emphasis = false;
                ai
            })
            .collect();
        game.set_fog_memory(false);
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            if let Some(plan) = ais[0].plan.as_ref() {
                *lanes.entry(plan.strategy.as_str()).or_default() += 1;
            }
            let directives = game.players[0].city_directives.clone();
            for (cid, directive) in &directives {
                let Some(city) = game.cities.get(cid) else {
                    continue;
                };
                city_turns += 1;
                *totals.entry(directive.role.as_str()).or_default() += 1;
                let band = match game.turn {
                    0..=39 => 0,
                    40..=79 => 1,
                    80..=139 => 2,
                    _ => 3,
                };
                band_turns[band] += 1;
                if directive.role == CityRole::Bastion {
                    band_bastions[band] += 1;
                }
                if directive.pressure > 0.0 {
                    pressured += 1;
                    pressure_sum += directive.pressure;
                    extra_hammers += directive.pressure.min(2.0) * 0.80;
                }
                if directive.role != CityRole::Bastion {
                    continue;
                }
                halted_pop += city.pop.max(0) as u64;
                // Recompute the same ratio with barbarians removed. If it
                // falls under the threshold, the only thing that stamped
                // this city a Bastion was a barbarian.
                let major: f64 = game
                    .units
                    .values()
                    .filter(|unit| {
                        unit.owner != 0
                            && !game.players[unit.owner].is_barbarian
                            && game.is_at_war(0, unit.owner)
                    })
                    .filter(|unit| game.wdist(city.pos, unit.pos) <= 6)
                    .filter(|unit| game.rules.units[unit.kind].class == "military")
                    .map(|unit| {
                        crate::game::effective_strength(game.unit_strength(unit, false), unit.hp)
                    })
                    .sum();
                let friendly = game.city_strength(*cid)
                    + game
                        .units
                        .values()
                        .filter(|unit| unit.owner == 0)
                        .filter(|unit| game.wdist(city.pos, unit.pos) <= 6)
                        .filter(|unit| game.rules.units[unit.kind].class == "military")
                        .map(|unit| {
                            crate::game::effective_strength(game.unit_strength(unit, true), unit.hp)
                        })
                        .sum::<f64>();
                if major / friendly.max(1.0) < BASTION_PRESSURE
                    && ais[0].plan.as_ref().and_then(|p| p.threatened_city) != Some(*cid)
                {
                    barbarian_only_bastions += 1;
                }
            }
        }
    }

    let plan_turns: u64 = lanes.values().sum();
    println!("\n=== grand strategy in force, {plan_turns} seat-turns ===");
    for (lane, count) in &lanes {
        println!(
            "  {lane:<12} {count:>6}  ({:>5.1}%)",
            *count as f64 / plan_turns.max(1) as f64 * 100.0
        );
    }
    println!("\n=== role ladder census: {city_turns} city-turns over 8 maps ===");
    for (role, count) in &totals {
        println!(
            "  {role:<12} {count:>6}  ({:>5.1}%)",
            *count as f64 / city_turns.max(1) as f64 * 100.0
        );
    }
    println!(
            "  pressure > 0 on {pressured} of {city_turns} city-turns ({:.1}%), mean {:.2} when it fires",
            pressured as f64 / city_turns.max(1) as f64 * 100.0,
            pressure_sum / pressured.max(1) as f64
        );
    println!(
            "  mean production weight added by pressure across ALL city-turns: +{:.3} (shipped weight is 1.55)",
            extra_hammers / city_turns.max(1) as f64
        );
    for (band, label) in ["t1-39", "t40-79", "t80-139", "t140+"].iter().enumerate() {
        println!(
            "  {label:<8} bastion on {:>4} of {:>5} city-turns ({:>5.1}%)",
            band_bastions[band],
            band_turns[band],
            band_bastions[band] as f64 / band_turns[band].max(1) as f64 * 100.0
        );
    }
    let bastions = totals.get("bastion").copied().unwrap_or(0);
    println!(
        "  of {bastions} bastion stamps, {barbarian_only_bastions} were BARBARIAN-ONLY ({:.1}%)",
        barbarian_only_bastions as f64 / bastions.max(1) as f64 * 100.0
    );
    println!(
            "  population under a growth halt: {halted_pop} citizen-turns ({:.1}% of all city-turns were halted)\n",
            bastions as f64 / city_turns.max(1) as f64 * 100.0
        );
}

#[test]
fn city_pressure_matrix_matches_serial_unit_order_exactly() {
    let mut game = Game::new_full(2, 30, 18, 91_210, 80, 0, false);
    let first = found_test_city(&mut game, 0);
    let second = found_test_city(&mut game, 0);
    let enemy = found_test_city(&mut game, 1);
    game.at_war.insert((0, 1));
    let positions = [
        game.cities[&first].pos,
        game.cities[&second].pos,
        game.cities[&enemy].pos,
    ];
    for index in 0..64 {
        game.spawn_test_unit(
            "warrior",
            usize::from(index % 3 == 2),
            positions[index % positions.len()],
        );
    }
    let cities = [first, second];
    let expected = cities
        .iter()
        .map(|city| AdvancedAi::city_pressure(&game, 0, *city))
        .collect::<Vec<_>>();
    let mut one = AdvancedAi::new();
    one.work_pool = Some(Arc::new(WorkPool::new(1)));
    let mut four = AdvancedAi::new();
    four.work_pool = Some(Arc::new(WorkPool::new(4)));

    assert_eq!(one.city_pressures(&game, 0, &cities), expected);
    assert_eq!(four.city_pressures(&game, 0, &cities), expected);
}

/// Census, not an assertion: how often a city faces a locally competitive
/// hostile force that `production_value`'s `threatened` flag cannot see.
///
/// `threatened` is true only when the city is *the* empire's single worst
/// (`plan.threatened_city` returns one `Option<u32>`) or when it was hit in
/// the last four turns. `threatened_city` additionally gates on
/// `danger >= 0.90`, or `>= 0.45` with a breach or a recent hit against a
/// damaged city. So a second city under siege, or any city with an army
/// standing next to it that has not struck yet, prioritises no defenses at
/// all -- which is exactly what `early_rush`'s doc comment describes as the
/// timing rule that lane plays against.
///
/// Run with `cargo test --release blind_defense_census -- --ignored --nocapture`.
/// Why do we actually lose cities? Autopsy every loss instead of guessing.
///
/// `come_ashore` cut embarked share 15.3% -> 6.3% over 30 paired maps and
/// moved cities lost only 36 -> 33, with two paired Elo A/Bs at -44 and -29
/// (both INCONCLUSIVE). So the water is real but is not what costs us
/// cities. This records the state of each city on the turn BEFORE it was
/// lost, so the binding constraint is measured rather than assumed.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn city_loss_autopsy() {
    let mut lost = 0u64;
    let mut besieged = 0u64; // hp below full: something was shooting it
    let mut full_hp = 0u64; // lost at full hp => not a siege at all
    let mut garrisoned = 0u64; // a combat unit stood on the tile
    let mut help_within_3 = 0u64; // our military within 3 tiles
    let mut help_within_6 = 0u64;
    let mut no_help_at_all = 0u64;
    let mut enemy_adjacent = 0u64;
    let mut our_army_total = 0u64;
    let mut razed = 0u64;
    let mut taken_by_enemy = 0u64;
    let mut taken_by_minor = 0u64;
    let mut flipped_peacefully = 0u64;
    let mut revolted = 0u64;
    let mut enemy_dist_hist = [0u64; 8];
    let mut beyond_alert = 0u64;
    let mut could_strike = 0u64;
    for map in 0..30u64 {
        let mut game = Game::new_full(4, 32, 20, 770_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len())
            .map(|_| {
                let mut ai = AdvancedAi::new();
                ai.enable_live_bridge();
                ai
            })
            .collect();
        game.set_fog_memory(false);
        let mut owned: std::collections::HashSet<u32> =
            game.player_city_ids(0).into_iter().collect();
        // Snapshot of what each city looked like last time we saw it:
        // (pop, food, starving, production, gold, science, districts).
        type CitySnapshot = (i32, i32, bool, i32, i32, i32, usize);
        let mut snap: std::collections::HashMap<u32, CitySnapshot> =
            std::collections::HashMap::new();
        let mut dist_snap: std::collections::HashMap<u32, (i32, i32)> =
            std::collections::HashMap::new();
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            let now: std::collections::HashSet<u32> = game.player_city_ids(0).into_iter().collect();
            for gone in owned.difference(&now) {
                // Ground truth the live export cannot give: who holds it now.
                // ⚠ A revolt transfers the city to the FREE CITIES player,
                // which we count as at war — so `is_at_war` alone reads a
                // revolt as a conquest. Check `is_free_city` FIRST.
                match game.cities.get(gone).map(|c| c.owner) {
                    None => razed += 1,
                    Some(other) if game.players.get(other).is_some_and(|p| p.is_free_city) => {
                        revolted += 1
                    }
                    Some(other) if game.is_at_war(0, other) => taken_by_enemy += 1,
                    Some(other) if game.players.get(other).is_some_and(|p| p.is_minor) => {
                        taken_by_minor += 1
                    }
                    Some(_) => flipped_peacefully += 1,
                }
                let Some(&(hp, maxhp, garrison, near3, near6, adj, army)) = snap.get(gone) else {
                    continue;
                };
                lost += 1;
                our_army_total += army as u64;
                if let Some(&(ed, reach)) = dist_snap.get(gone) {
                    enemy_dist_hist[(ed.min(7)) as usize] += 1;
                    if ed > crate::ai::GARRISON_ALERT_RADIUS {
                        beyond_alert += 1;
                    }
                    if reach > 0 {
                        could_strike += 1;
                    }
                }
                if hp < maxhp {
                    besieged += 1;
                } else {
                    full_hp += 1;
                }
                if garrison {
                    garrisoned += 1;
                }
                if near3 > 0 {
                    help_within_3 += 1;
                }
                if near6 > 0 {
                    help_within_6 += 1;
                }
                if near6 == 0 {
                    no_help_at_all += 1;
                }
                if adj > 0 {
                    enemy_adjacent += 1;
                }
            }
            owned = now;
            let army = game
                .player_unit_ids(0)
                .into_iter()
                .filter(|u| game.rules.units[game.units[u].kind].class == "military")
                .count();
            for cid in game.player_city_ids(0) {
                let city = &game.cities[&cid];
                let pos = city.pos;
                let hp = city.hp;
                // Cities cap at 200 hp; `Game` clamps to that in its own scoring.
                let maxhp = 200;
                let garrison = game.unit_ids_at(pos).iter().any(|u| {
                    let unit = &game.units[u];
                    unit.owner == 0 && game.rules.units[unit.kind].class == "military"
                });
                let mut near3 = 0;
                let mut near6 = 0;
                let mut adj = 0;
                let mut enemy_dist = 99i32;
                let mut reach = 0i32;
                for unit in game.units.values() {
                    if game.rules.units[unit.kind].class != "military" {
                        continue;
                    }
                    let d = game.wdist(unit.pos, pos);
                    if unit.owner == 0 {
                        if d <= 3 {
                            near3 += 1;
                        }
                        if d <= 6 {
                            near6 += 1;
                        }
                    } else if game.is_at_war(0, unit.owner) {
                        if d <= 1 {
                            adj += 1;
                        }
                        if d < enemy_dist {
                            enemy_dist = d;
                        }
                        // How far this unit could come and still strike.
                        let mv = game.rules.units[unit.kind].moves.max(1.0) as i32;
                        let rng = game.unit_attack_range(unit.id).max(1);
                        if d <= mv + rng {
                            reach += 1;
                        }
                    }
                }
                snap.insert(cid, (hp, maxhp, garrison, near3, near6, adj, army));
                dist_snap.insert(cid, (enemy_dist, reach));
            }
        }
    }
    let garrison_calls = crate::ai::GARRISON_STEP_CALLS.load(std::sync::atomic::Ordering::Relaxed);
    println!("garrison_step reached {garrison_calls} times across the whole census");
    let pct = |n: u64| 100.0 * n as f64 / lost.max(1) as f64;
    println!(
        "cities lost: {lost}  (mean army alive at the moment of loss: {:.1})",
        our_army_total as f64 / lost.max(1) as f64
    );
    println!(
        "  besieged (hp < max) ....... {besieged:>3}  {:>5.1}%",
        pct(besieged)
    );
    println!(
        "  lost at FULL hp ........... {full_hp:>3}  {:>5.1}%  <- not a siege",
        pct(full_hp)
    );
    println!(
        "  an enemy stood ADJACENT ... {enemy_adjacent:>3}  {:>5.1}%",
        pct(enemy_adjacent)
    );
    println!(
        "  had a GARRISON ............ {garrisoned:>3}  {:>5.1}%",
        pct(garrisoned)
    );
    println!(
        "  our military within 3 ..... {help_within_3:>3}  {:>5.1}%",
        pct(help_within_3)
    );
    println!(
        "  our military within 6 ..... {help_within_6:>3}  {:>5.1}%",
        pct(help_within_6)
    );
    println!(
        "  NO military within 6 ...... {no_help_at_all:>3}  {:>5.1}%",
        pct(no_help_at_all)
    );
    println!("NEAREST ENEMY on the last turn we held it:");
    for (d, n) in enemy_dist_hist.iter().enumerate() {
        if *n > 0 {
            let label = if d >= 7 {
                "7+".to_string()
            } else {
                d.to_string()
            };
            println!(
                "    distance {label:<3} .................. {n:>3}  {:>5.1}%",
                pct(*n)
            );
        }
    }
    println!(
        "  BEYOND GARRISON_ALERT_RADIUS ({}) .. {beyond_alert:>3}  {:>5.1}%",
        crate::ai::GARRISON_ALERT_RADIUS,
        pct(beyond_alert)
    );
    println!(
        "  an enemy could MOVE+STRIKE it that turn {could_strike:>3}  {:>5.1}%",
        pct(could_strike)
    );
    println!("WHO HOLDS IT NOW (ground truth the live export cannot give):");
    println!(
        "  REVOLTED to Free Cities (loyalty 0) ... {revolted:>3}  {:>5.1}%",
        pct(revolted)
    );
    println!(
        "  taken by an enemy we are at war with .. {taken_by_enemy:>3}  {:>5.1}%",
        pct(taken_by_enemy)
    );
    println!(
        "  taken by a city-state/minor ........... {taken_by_minor:>3}  {:>5.1}%",
        pct(taken_by_minor)
    );
    println!(
        "  owner changed with NO war (revolt) .... {flipped_peacefully:>3}  {:>5.1}%",
        pct(flipped_peacefully)
    );
    println!(
        "  razed / gone .......................... {razed:>3}  {:>5.1}%",
        pct(razed)
    );
}

/// Does `come_ashore` actually reduce time spent embarked, and does it do
/// so without making units pace the shoreline?
///
/// The paired A/B came back −44 and −29 Elo (both INCONCLUSIVE) on the
/// first version of the fix, while the engine's own refusal ledger says
/// "cannot attack while embarked" is the single largest cause of a thrown
/// away attack. Those two facts only reconcile if the repair costs
/// something the Elo can see. Oscillation is the obvious candidate: pull a
/// unit ashore, let the objective pull it back to sea next turn, and the
/// army burns its movement on the beach.
///
/// `transitions` counts land→water and water→land crossings per unit-life.
/// A fix that works lowers `embarked_share` AND does not raise
/// `transitions`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn come_ashore_census() {
    for &flag in &[false, true] {
        let mut unit_turns = 0u64;
        let mut embarked = 0u64;
        let mut transitions = 0u64;
        let mut attacks_refused_embarked = 0u64;
        let mut cities_lost = 0u64;
        let mut city_damage_turns = 0u64;
        for map in 0..30u64 {
            let mut game = Game::new_full(4, 32, 20, 770_000 + map, 200, 1, false);
            let mut ais: Vec<AdvancedAi> = (0..game.players.len())
                .map(|_| {
                    let mut ai = AdvancedAi::new();
                    ai.enable_live_bridge();
                    if !flag {
                        ai.disable_come_ashore();
                    }
                    ai
                })
                .collect();
            game.set_fog_memory(false);
            let mut was_wet: std::collections::HashMap<u32, bool> =
                std::collections::HashMap::new();
            let mut owned: std::collections::HashSet<u32> =
                game.player_city_ids(0).into_iter().collect();
            let mut prev_hp: std::collections::HashMap<u32, i32> = std::collections::HashMap::new();
            while game.winner.is_none() && game.turn <= game.max_turns {
                let pid = game.current;
                ais[pid].take_turn(&mut game, pid);
                if game.winner.is_none() && game.current == pid {
                    let _ = game.apply(pid, &Action::EndTurn);
                }
                if pid != 0 {
                    continue;
                }
                let now: std::collections::HashSet<u32> =
                    game.player_city_ids(0).into_iter().collect();
                cities_lost += owned.difference(&now).count() as u64;
                owned = now;
                for cid in game.player_city_ids(0) {
                    let hp = game.cities[&cid].hp;
                    if prev_hp.insert(cid, hp).is_some_and(|was| hp < was) {
                        city_damage_turns += 1;
                    }
                }
                for uid in game.player_unit_ids(0) {
                    let unit = &game.units[&uid];
                    if game.rules.units[unit.kind].class != "military"
                        || game.rules.units[unit.kind].domain.as_deref() == Some("sea")
                    {
                        continue;
                    }
                    let wet = game.is_embarked(unit);
                    unit_turns += 1;
                    if wet {
                        embarked += 1;
                        if game.unit_attack_range(uid) >= 1 {
                            attacks_refused_embarked += 1;
                        }
                    }
                    if was_wet.insert(uid, wet).is_some_and(|prev| prev != wet) {
                        transitions += 1;
                    }
                }
            }
        }
        let share = 100.0 * embarked as f64 / unit_turns.max(1) as f64;
        let churn = 1000.0 * transitions as f64 / unit_turns.max(1) as f64;
        println!(
            "come_ashore={flag:<5} unit_turns={unit_turns:<6} embarked={share:>5.1}%  \
                 transitions/1000 unit-turns={churn:>6.1}  \
                 embarked-with-attack={attacks_refused_embarked}  \
                 CITIES_LOST={cities_lost}  city-damage-turns={city_damage_turns}"
        );
    }
}

#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn blind_defense_census() {
    let mut city_turns = 0u64;
    let mut pressed = 0u64;
    let mut pressed_and_blind = 0u64;
    let mut blind_by_band = [0u64; 4];
    let mut band_pressed = [0u64; 4];

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 430_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            let Some(plan) = ais[0].plan.clone() else {
                continue;
            };
            let band = match game.turn {
                0..=39 => 0,
                40..=79 => 1,
                80..=139 => 2,
                _ => 3,
            };
            for cid in game.player_city_ids(0) {
                city_turns += 1;
                let pressure = AdvancedAi::city_pressure(&game, 0, cid);
                if pressure < BASTION_PRESSURE {
                    continue;
                }
                pressed += 1;
                band_pressed[band] += 1;
                let city = &game.cities[&cid];
                let threatened = plan.threatened_city == Some(cid)
                    || (city.last_attacked > 0
                        && game.turn.saturating_sub(city.last_attacked) <= 4);
                if !threatened {
                    pressed_and_blind += 1;
                    blind_by_band[band] += 1;
                }
            }
        }
    }

    println!("\n=== blind-defense census: {city_turns} city-turns over 8 maps ===");
    println!(
        "  locally competitive hostile force present on {pressed} city-turns ({:.1}%)",
        pressed as f64 / city_turns.max(1) as f64 * 100.0
    );
    println!(
        "  of those, {pressed_and_blind} were INVISIBLE to `threatened` ({:.1}%)",
        pressed_and_blind as f64 / pressed.max(1) as f64 * 100.0
    );
    for (band, label) in ["t1-39", "t40-79", "t80-139", "t140+"].iter().enumerate() {
        println!(
            "  {label:<8} {:>4} pressed, {:>4} blind ({:>5.1}%)",
            band_pressed[band],
            blind_by_band[band],
            blind_by_band[band] as f64 / band_pressed[band].max(1) as f64 * 100.0
        );
    }
    println!();
}

/// Census, not an assertion: what a city actually decides, turn by turn.
///
/// Five arms of scripted "give the city a strategy" treatment have now
/// measured null across three seeds, so this stops proposing tilts to the
/// city's decisions and asks a different question: are any of them plainly
/// *broken*? That is the question that paid last time -- the growth halt
/// was a real -38 Elo defect and no amount of reasoning about weights
/// found it, a census did.
///
/// Run with `cargo test --release city_decision_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn city_decision_census() {
    let mut city_turns = 0u64;
    let mut idle = 0u64;
    let mut head_changes = 0u64;
    let mut stranded = 0.0f64;
    let mut kinds = BTreeMap::<&str, u64>::new();
    let mut walls_built = 0u64;
    let mut cities_seen = BTreeSet::<(u64, u32)>::new();
    let mut walled = BTreeSet::<(u64, u32)>::new();
    let mut first_wall_turn = Vec::<u32>::new();
    let mut food_now = 0.0f64;
    let mut food_ceiling = 0.0f64;
    let mut prod_now = 0.0f64;
    let mut prod_ceiling = 0.0f64;
    let mut prev_head = BTreeMap::<u32, String>::new();

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 440_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        prev_head.clear();
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            for cid in game.player_city_ids(0) {
                city_turns += 1;
                cities_seen.insert((map, cid));
                let city = &game.cities[&cid];
                match city.queue.first() {
                    None => idle += 1,
                    Some(item) => {
                        let key = match item {
                            Item::Unit { .. } | Item::Formation { .. } => "unit",
                            Item::Building { .. } => "building",
                            Item::District { .. } => "district",
                            Item::Wonder { .. } => "wonder",
                            Item::Project { .. } => "project",
                            Item::Product { .. } => "product",
                            Item::Repair { .. } => "repair",
                        };
                        *kinds.entry(key).or_default() += 1;
                        let head = format!("{item:?}");
                        if prev_head.get(&cid).is_some_and(|old| *old != head) {
                            head_changes += 1;
                        }
                        prev_head.insert(cid, head);
                    }
                }
                // Production banked against builds the city walked away
                // from. `item_remaining_cost_for_city` is what the AI
                // prices a resumed build with, so progress that is not on
                // the queue head is capital sitting idle.
                stranded += city.production_progress.values().sum::<f64>();
                if city.buildings.iter().any(|b| b.contains("walls")) && walled.insert((map, cid)) {
                    walls_built += 1;
                    first_wall_turn.push(game.turn);
                }
                // How much of the city's own ceiling do the shipped
                // weights actually claim? `city_yields_weighted` is the
                // public substitution instrument `docs/OPENINGS.md` uses to
                // bound the capital's food ceiling; asking it per city-turn
                // turns that one-off into a standing measurement.
                let now = game.city_yields(cid);
                let all_food = Yields {
                    food: 10.0,
                    ..Yields::default()
                };
                let all_prod = Yields {
                    production: 10.0,
                    ..Yields::default()
                };
                food_now += now.food;
                food_ceiling += game.city_yields_weighted(cid, all_food).food;
                prod_now += now.production;
                prod_ceiling += game.city_yields_weighted(cid, all_prod).production;
            }
        }
    }

    let pct = |n: u64| n as f64 / city_turns.max(1) as f64 * 100.0;
    println!("\n=== city decision census: {city_turns} city-turns over 8 maps ===");
    println!("  idle queue          {idle:>6}  ({:>5.1}%)", pct(idle));
    println!(
        "  queue head changed  {head_changes:>6}  ({:>5.1}% of city-turns)",
        pct(head_changes)
    );
    println!(
        "  mean production stranded off the queue head: {:.1} per city-turn",
        stranded / city_turns.max(1) as f64
    );
    println!(
        "  food claimed {:.1}% of the city's own food ceiling ({:.1} of {:.1} per city-turn)",
        food_now / food_ceiling.max(1e-9) * 100.0,
        food_now / city_turns.max(1) as f64,
        food_ceiling / city_turns.max(1) as f64
    );
    println!(
        "  production claimed {:.1}% of its ceiling ({:.1} of {:.1} per city-turn)",
        prod_now / prod_ceiling.max(1e-9) * 100.0,
        prod_now / city_turns.max(1) as f64,
        prod_ceiling / city_turns.max(1) as f64
    );
    println!("  what the queue head is:");
    for (kind, count) in &kinds {
        println!("    {kind:<10} {count:>6}  ({:>5.1}%)", pct(*count));
    }
    println!(
        "  cities that ever built walls: {walls_built} of {} ({:.1}%)",
        cities_seen.len(),
        walls_built as f64 / cities_seen.len().max(1) as f64 * 100.0
    );
    first_wall_turn.sort_unstable();
    if !first_wall_turn.is_empty() {
        println!(
            "  median turn walls appeared: {}",
            first_wall_turn[first_wall_turn.len() / 2]
        );
    }
    println!();
}

/// Census, not an assertion: how good are the sites a settler actually
/// picks, against the best site it could have picked nearby?
///
/// This is the last unmeasured city decision. #532 bounded what a city
/// works (89.3% of its food ceiling, 99.5% of its production ceiling),
/// #534 bounded what it owns (perfect border growth, p=0.7283) and #542
/// bounded where its districts go (p=0.6989). All three are downstream of
/// *where the city stands*, and nothing had measured that.
///
/// It is measured rather than granted deliberately. An oracle that
/// teleports settlers cannot work here: `AdvancedAi` founds only when a
/// settler's cached `settler_targets` entry equals its current position,
/// so a relocated settler walks back to its old target and never founds.
/// The grant would fire forever, suppress the seat's expansion entirely,
/// and report a catastrophic loss that measured the harness rather than
/// the subsystem. The ratio below asks the same question and cannot lie
/// in that direction.
///
/// The comparison set is every legal site within eight tiles of the one
/// chosen — roughly a settler's remaining walk — judged by the agent's own
/// `settle_value`, with the just-founded city excluded from the minimum
/// separation rule so the chosen tile competes on equal terms.
///
/// ## ⚠ RETRACTION: the gap this census originally reported was its own bug
///
/// The first two versions of this census (#548, #550) scored the chosen
/// site **after** the city was founded, and reported that the agent sites
/// cities at 62-70% of the best available -- billed as the one unsaturated
/// city decision. That was an artifact.
///
/// `settle_value` skips any tile another city owns
/// (`if t.owner_city.is_some() && p != pos { continue; }`), and a city
/// claims its centre and all six ring-one tiles the instant it is founded.
/// Ring one carries full weight in that sum; ring two is discounted to
/// 0.45. So founding a city destroys **54.8%** of its own site's measured
/// value -- `settle_value_before_and_after_founding` measures exactly that
/// -- while rival candidates four or more tiles away keep theirs intact.
/// The census was comparing a site stripped of its best tiles against
/// rivals that still had theirs.
///
/// Scored the turn **before** founding, which is the last moment the site
/// is still what the settler was choosing between, the answer inverts:
///
/// ```text
/// against RAW settle_value            3 tiles 99.7%   8 tiles 99.7%
/// against the AGENT'S OWN objective   99.9%
/// against its OWN settle_sites here   98.8%
/// the chosen site WAS the best available on 15 of 17 foundings (88.2%)
/// worst case 95.2%; capitals 99.0%
/// ```
///
/// **Settle siting is saturated like every other city decision.** The agent
/// takes essentially all the value on offer and picks the literal best site
/// seven times in eight.
///
/// Two things corroborate it rather than resting on this one repair.
/// `settle_search_reach_census` shows the site search discards no reachable
/// ground: over 158 settler-turns the generator offered only five
/// candidates above what the search returned and **none of the five was
/// reachable**. And a per-turn re-score of stale targets was built and
/// measured **inert** in #550 -- which is what a saturated decision looks
/// like from the inside.
///
/// The distance-discount baseline stays because it is still the right one:
/// `settle_sites` ranks by `settle_value - 0.9 * distance`, so raw
/// `settle_value` is not the objective the agent pursues.
///
/// Run with `cargo test --release settle_siting_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn settle_siting_census() {
    let ai = AdvancedAi::new();
    let mut ratios: Vec<f64> = Vec::new();
    let mut near_ratios: Vec<f64> = Vec::new();
    let mut step_away: Vec<i32> = Vec::new();
    let mut discounted_ratios: Vec<f64> = Vec::new();
    let mut offered_ratios: Vec<f64> = Vec::new();
    let mut chosen_was_best = 0u64;
    let mut founded = 0u64;
    let mut capital_ratio: Vec<f64> = Vec::new();

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 470_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        let mut known: BTreeSet<u32> = game.player_city_ids(0).into_iter().collect();
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            // ⚠ Score every tile a settler stands on BEFORE the turn runs.
            // `settle_value` skips tiles another city owns, and a city
            // claims its centre and all six ring-one tiles the instant it
            // is founded -- ring one being the full-weight ring, against
            // 0.45 for ring two. Measured after the fact, founding a city
            // destroys 54.8% of its own site's score
            // (`settle_value_before_and_after_founding`), while rival
            // candidates four or more tiles away keep theirs intact. The
            // first version of this census did exactly that and reported a
            // siting gap that was mostly its own artifact.
            let mut pre: BTreeMap<Pos, f64> = BTreeMap::new();
            if pid == 0 {
                for uid in game.player_unit_ids(0) {
                    if game.units[&uid].kind == "settler" {
                        let pos = game.units[&uid].pos;
                        pre.insert(pos, ai.settle_value(&game, 0, pos));
                    }
                }
            }
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &crate::game::Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            for cid in game.player_city_ids(0) {
                if !known.insert(cid) {
                    continue;
                }
                // A city this seat gained by conquest was never sited by
                // its settler, so it says nothing about this decision.
                let city = &game.cities[&cid];
                if city.captured_from.is_some() {
                    continue;
                }
                let chosen_pos = city.pos;
                let Some(chosen) = pre.get(&chosen_pos).copied() else {
                    continue;
                };
                // Only ground this seat had actually EXPLORED counts. A
                // settler cannot choose a site nobody has seen, and
                // scoring it against one would measure the fog rather than
                // the decision.
                let best_at = |radius: i32| {
                    game.wdisk(chosen_pos, radius)
                        .into_iter()
                        .filter(|pos| {
                            let Some(tile) = game.map.get(*pos) else {
                                return false;
                            };
                            if !game.players[0].explored.contains(pos) {
                                return false;
                            }
                            if game.rules.is_water(tile)
                                || !game.rules.is_passable(tile)
                                || game.tile_is_natural_wonder(tile)
                            {
                                return false;
                            }
                            // Every other city still enforces its
                            // separation; the one just founded must not
                            // veto its own site.
                            game.cities
                                .values()
                                .filter(|other| other.id != cid)
                                .all(|other| game.wdist(other.pos, *pos) >= 4)
                        })
                        .map(|pos| ai.settle_value(&game, 0, pos))
                        .fold(chosen, f64::max)
                };
                // How far away is the better site? `settle_value` does
                // not price the walk, so a gap three tiles off is worth
                // much less than the same gap one tile off, and the
                // distance is what makes the number readable.
                let mut best_near_pos = chosen_pos;
                let mut best_near_val = chosen;
                for pos in game.wdisk(chosen_pos, 3) {
                    let Some(tile) = game.map.get(pos) else {
                        continue;
                    };
                    if !game.players[0].explored.contains(&pos)
                        || game.rules.is_water(tile)
                        || !game.rules.is_passable(tile)
                        || game.tile_is_natural_wonder(tile)
                        || !game
                            .cities
                            .values()
                            .filter(|other| other.id != cid)
                            .all(|other| game.wdist(other.pos, pos) >= 4)
                    {
                        continue;
                    }
                    let value = ai.settle_value(&game, 0, pos);
                    if value > best_near_val {
                        best_near_val = value;
                        best_near_pos = pos;
                    }
                }
                if best_near_pos != chosen_pos {
                    step_away.push(game.wdist(chosen_pos, best_near_pos));
                }
                let near = best_at(3);
                let best = best_at(8);
                // ⚠ The comparison above is against RAW `settle_value`,
                // which is not the objective this agent actually pursues.
                // `settle_sites` ranks candidates by
                // `settle_value - 0.9 * distance`, so the agent trades
                // site quality for proximity on purpose. Scoring it
                // against a function that does not charge for the walk
                // measures a preference it never held.
                let discounted = game
                    .wdisk(chosen_pos, 8)
                    .into_iter()
                    .filter(|pos| {
                        let Some(tile) = game.map.get(*pos) else {
                            return false;
                        };
                        game.players[0].explored.contains(pos)
                            && !game.rules.is_water(tile)
                            && game.rules.is_passable(tile)
                            && !game.tile_is_natural_wonder(tile)
                            && game
                                .cities
                                .values()
                                .filter(|other| other.id != cid)
                                .all(|other| game.wdist(other.pos, *pos) >= 4)
                    })
                    .map(|pos| {
                        ai.settle_value(&game, 0, pos)
                            - game.wdist(chosen_pos, pos) as f64 * SETTLE_DISTANCE_PENALTY
                    })
                    .fold(chosen, f64::max);
                discounted_ratios.push(chosen / discounted.max(1e-9));
                // And now the decisive one: what does the agent's OWN
                // candidate generator offer from this very tile? Anything
                // the two comparisons above can see that this cannot is
                // excluded by `settle_sites`' filters -- the value >= 12.0
                // floor, foreign-owned ground, the four-tile separation --
                // rather than missed by the choice.
                let offered = ai
                    .settle_sites(&game, 0, chosen_pos, 8)
                    .into_iter()
                    .map(|(_, value)| value)
                    .fold(chosen, f64::max);
                offered_ratios.push(chosen / offered.max(1e-9));
                founded += 1;
                if best <= chosen + 1e-9 {
                    chosen_was_best += 1;
                }
                near_ratios.push(chosen / near.max(1e-9));
                let ratio = chosen / best.max(1e-9);
                ratios.push(ratio);
                if known.len() == 1 {
                    capital_ratio.push(ratio);
                }
            }
        }
    }

    ratios.sort_by(f64::total_cmp);
    let mean = ratios.iter().sum::<f64>() / ratios.len().max(1) as f64;
    println!("\n=== settle siting census: {founded} cities founded over 8 maps ===");
    let near_mean = near_ratios.iter().sum::<f64>() / near_ratios.len().max(1) as f64;
    let disc_mean = discounted_ratios.iter().sum::<f64>() / discounted_ratios.len().max(1) as f64;
    println!(
        "  against RAW settle_value  -- within 3 tiles: {:.1}%   within 8 tiles: {:.1}%",
        near_mean * 100.0,
        mean * 100.0
    );
    let off_mean = offered_ratios.iter().sum::<f64>() / offered_ratios.len().max(1) as f64;
    println!(
            "  against the AGENT'S OWN objective (settle_value - {SETTLE_DISTANCE_PENALTY}/tile): {:.1}%",
            disc_mean * 100.0
        );
    println!(
        "  against what its OWN `settle_sites` generator offers here: {:.1}%",
        off_mean * 100.0
    );
    if !ratios.is_empty() {
        println!(
            "  percentiles  p10 {:.1}%   median {:.1}%   p90 {:.1}%   worst {:.1}%",
            ratios[ratios.len() / 10] * 100.0,
            ratios[ratios.len() / 2] * 100.0,
            ratios[ratios.len() * 9 / 10] * 100.0,
            ratios[0] * 100.0
        );
    }
    println!(
            "  the chosen site WAS the best available on {chosen_was_best} of {founded} foundings ({:.1}%)",
            chosen_was_best as f64 / founded.max(1) as f64 * 100.0
        );
    step_away.sort_unstable();
    if !step_away.is_empty() {
        println!(
                "  when a better site existed within 3 tiles it was a median {} tile(s) away ({} cases)",
                step_away[step_away.len() / 2],
                step_away.len()
            );
    }
    if !capital_ratio.is_empty() {
        let cap = capital_ratio.iter().sum::<f64>() / capital_ratio.len() as f64;
        println!(
            "  capitals alone: {:.1}% ({} sampled)",
            cap * 100.0,
            capital_ratio.len()
        );
    }
    println!();
}

/// Census, not an assertion: does the settler's site search discard ground
/// it could actually reach?
///
/// `settle_siting_census` establishes that the agent founds at ~65% of what
/// its own `settle_sites` generator offers from the very tile it chose, and
/// that re-scoring a stale target changes nothing. The only machinery
/// between the generator and the choice is
/// `BasicAi::first_reachable_settle_site`, which walks the value-sorted
/// candidate list **in chunks of 40** and skips an entire chunk when
/// `route_step_to_any` reaches none of it. Because the list is sorted by
/// value descending, one failed probe on the first chunk discards the forty
/// best sites at once.
///
/// Two readings, and they call for opposite conclusions:
///
/// - the skipped sites are genuinely unreachable, so the siting census
///   overstates its gap and the axis closes like the other three; or
/// - the chunked scan is throwing away reachable ground, which is a defect.
///
/// This asks each better-than-chosen candidate the route question
/// **individually**, which is the same question the chunk asks collectively,
/// and reports how the two answers differ.
///
/// Run with `cargo test --release settle_search_reach_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn settle_search_reach_census() {
    let mut settler_turns = 0u64;
    let mut search_returned_nothing = 0u64;
    let mut better_offered = 0u64;
    let mut better_individually_reachable = 0u64;
    let mut turns_with_a_reachable_better_site = 0u64;
    let mut best_gap: Vec<f64> = Vec::new();

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 470_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            if pid == 0 {
                let probe = ais[0].clone();
                for uid in game.player_unit_ids(0) {
                    if game.units[&uid].kind != "settler" {
                        continue;
                    }
                    let from = game.units[&uid].pos;
                    let candidates = probe.settle_sites(&game, 0, from, 8);
                    if candidates.is_empty() {
                        continue;
                    }
                    settler_turns += 1;
                    let returned = BasicAi::first_reachable_settle_site(&game, uid, &candidates);
                    let floor = match returned {
                        Some((_, value)) => value,
                        None => {
                            search_returned_nothing += 1;
                            f64::NEG_INFINITY
                        }
                    };
                    let mut found_one = false;
                    for (pos, value) in &candidates {
                        if *value <= floor {
                            continue;
                        }
                        better_offered += 1;
                        // The same question the chunk asked collectively.
                        if *pos == from || game.route_step(uid, *pos, 0).is_some() {
                            better_individually_reachable += 1;
                            if !found_one {
                                found_one = true;
                                best_gap.push(value - floor.max(0.0));
                            }
                        }
                    }
                    if found_one {
                        turns_with_a_reachable_better_site += 1;
                    }
                }
            }
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &crate::game::Action::EndTurn);
            }
        }
    }

    best_gap.sort_by(f64::total_cmp);
    println!("\n=== settle search reach census: {settler_turns} settler-turns over 8 maps ===");
    println!("  the search returned NOTHING on {search_returned_nothing} of them");
    println!("  candidates the generator offered above what the search returned: {better_offered}");
    println!(
            "  of those, INDIVIDUALLY reachable by the same route query: {better_individually_reachable} ({:.1}%)",
            better_individually_reachable as f64 / better_offered.max(1) as f64 * 100.0
        );
    println!(
            "  settler-turns where a strictly better REACHABLE site was skipped: {turns_with_a_reachable_better_site} ({:.1}%)",
            turns_with_a_reachable_better_site as f64 / settler_turns.max(1) as f64 * 100.0
        );
    if !best_gap.is_empty() {
        println!(
            "  when skipped, the value left behind was median {:.1} (p90 {:.1}, max {:.1})",
            best_gap[best_gap.len() / 2],
            best_gap[best_gap.len() * 9 / 10],
            best_gap[best_gap.len() - 1]
        );
    }
    println!();
}

#[test]
fn settle_value_prices_district_adjacency_geometry() {
    // Three mountains cost the same worked yields wherever they stand.
    // Clustered around one plot they are a +3 Campus; scattered so no
    // plot touches two, the best Campus is +1. The settle score must
    // prefer the cluster — that difference is the adjacency calculator
    // speaking, not the tile mix.
    let scorer = AdvancedAi::new();
    let mut game = Game::new_full(2, 28, 18, 91_779, 200, 0, false);
    let mut land: Vec<Pos> = game.map.tiles.keys().copied().collect();
    land.sort();
    let center = land
        .into_iter()
        .find(|pos| {
            game.map
                .get(*pos)
                .is_some_and(|tile| !game.rules.is_water(tile) && game.rules.is_passable(tile))
                && game
                    .units
                    .values()
                    .all(|unit| game.wdist(unit.pos, *pos) > 5)
                && game
                    .wdisk(*pos, 3)
                    .iter()
                    .all(|ring| game.map.get(*ring).is_some())
        })
        .expect("map has an interior patch of open ground");
    // Flatten out to radius 3 so the mountains' own surroundings are
    // controlled too, and silence rivers so fresh-water and Commercial
    // Hub terms cannot differ between the two layouts.
    for pos in game.wdisk(center, 3) {
        let tile = game.map.tiles.get_mut(&pos).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
        tile.resource = None;
        tile.improvement = None;
        tile.district = None;
        tile.wonder = None;
        tile.river_edges = [false; 6];
    }
    let ring2: Vec<Pos> = game
        .wdisk(center, 2)
        .into_iter()
        .filter(|pos| game.wdist(*pos, center) == 2)
        .collect();
    assert!(ring2.len() >= 12, "interior ring two is complete");

    // Scattered: ring-two plots pairwise three apart. Two mountains a
    // plot could see together would be at most two apart, so this
    // guarantees no plot sees more than one.
    let mut scattered: Vec<Pos> = Vec::new();
    for pos in &ring2 {
        if scattered.len() < 3
            && scattered
                .iter()
                .all(|picked| game.wdist(*picked, *pos) >= 3)
        {
            scattered.push(*pos);
        }
    }
    assert_eq!(
        scattered.len(),
        3,
        "ring two admits three mutually distant peaks"
    );
    for pos in &scattered {
        game.map.tiles.get_mut(pos).unwrap().terrain = crate::name!("mountain");
    }
    let scattered_value = scorer.settle_value(&game, 0, center);
    for pos in &scattered {
        game.map.tiles.get_mut(pos).unwrap().terrain = crate::name!("plains");
    }

    // Clustered: the three ring-two neighbours of one ring-one plot.
    let anchor = game
        .nbrs(center)
        .into_iter()
        .find(|pos| game.map.get(*pos).is_some())
        .unwrap();
    let cluster: Vec<Pos> = game
        .nbrs(anchor)
        .into_iter()
        .filter(|pos| game.wdist(*pos, center) == 2)
        .collect();
    assert_eq!(
        cluster.len(),
        3,
        "a ring-one plot touches three ring-two plots"
    );
    for pos in &cluster {
        game.map.tiles.get_mut(pos).unwrap().terrain = crate::name!("mountain");
    }
    let clustered_value = scorer.settle_value(&game, 0, center);

    assert!(
        clustered_value > scattered_value,
        "clustered ridge must outscore scattered peaks: {clustered_value} vs {scattered_value}"
    );
}

/// Census, not an assertion: is `settle_siting_census` measuring the site
/// or measuring the city that was just built on it?
///
/// `settle_value` skips any tile another city owns:
/// `if t.owner_city.is_some() && p != pos { continue; }`. A city claims its
/// centre and all six ring-one tiles the moment it is founded, and ring one
/// carries the full weight in that sum while ring two is discounted to
/// 0.45. So scoring the chosen site *after* founding strips it of its
/// highest-weighted contributions, while rival candidates four or more
/// tiles away keep theirs intact.
///
/// If that is what `settle_siting_census` measured, its gap is an artifact
/// of the measurement rather than a fact about the decision, and the whole
/// "settle siting is the one unsaturated city axis" claim falls.
///
/// Run with `cargo test --release settle_value_before_and_after_founding -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn settle_value_before_and_after_founding() {
    let scorer = AdvancedAi::new();
    let mut before_after: Vec<(f64, f64)> = Vec::new();

    for map in 0..8u64 {
        let mut game = Game::new_full(4, 24, 16, 470_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        let mut known: BTreeSet<u32> = game.player_city_ids(0).into_iter().collect();
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            // Score every tile a settler is standing on BEFORE the turn
            // runs, which is the last moment the site is still unowned.
            let mut pre: BTreeMap<Pos, f64> = BTreeMap::new();
            if pid == 0 {
                for uid in game.player_unit_ids(0) {
                    if game.units[&uid].kind == "settler" {
                        let pos = game.units[&uid].pos;
                        pre.insert(pos, scorer.settle_value(&game, 0, pos));
                    }
                }
            }
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &crate::game::Action::EndTurn);
            }
            if pid != 0 {
                continue;
            }
            for cid in game.player_city_ids(0) {
                if !known.insert(cid) {
                    continue;
                }
                let city = &game.cities[&cid];
                if city.captured_from.is_some() {
                    continue;
                }
                if let Some(before) = pre.get(&city.pos) {
                    let after = scorer.settle_value(&game, 0, city.pos);
                    before_after.push((*before, after));
                }
            }
        }
    }

    let n = before_after.len().max(1) as f64;
    let before: f64 = before_after.iter().map(|(b, _)| b).sum::<f64>() / n;
    let after: f64 = before_after.iter().map(|(_, a)| a).sum::<f64>() / n;
    println!(
        "\n=== settle_value before and after founding: {} sites ===",
        before_after.len()
    );
    println!("  mean settle_value the turn BEFORE the city existed: {before:.1}");
    println!("  mean settle_value once the city owns its ring one:  {after:.1}");
    println!(
        "  founding the city destroys {:.1}% of its own site's measured value",
        (1.0 - after / before.max(1e-9)) * 100.0
    );
    println!();
}

/// Census, not an assertion: which conjunct actually blocks the settler?
///
/// #554 measured that handing a seat a free Settler while it is short of
/// its own city target more than doubles its win rate — 23.0% to 52.3% over
/// 300 games at p=0.0000, the only subsystem grant this harness has ever
/// returned HEADROOM for. Seats target six cities and finish with 2.1–2.8.
/// **The agent cannot afford the empire it has already decided it wants.**
///
/// That says the cost binds. It does not say *which* cost. The settler
/// branch of `production_value` is a five-way conjunction, and any one of
/// them turns the item's value into −10,000:
///
/// ```text
/// city_count + counts.settlers < plan.desired_cities   // target not met
///   && counts.settlers < in_flight_allowed             // serialization
///   && city.pop >= 2                                   // size gate
///   && expansion_open                                  // time window
///   && site.is_some()                                  // somewhere to go
/// ```
///
/// This counts, over every city-turn where the empire is short of its
/// target, which conjuncts were false. A conjunct that never fails cannot
/// be the constraint; one that fails almost always is where the settler
/// economy actually stalls. Shares sum past 100% because several can fail
/// at once, so the last block reports the turns where exactly one did —
/// those are the ones a single fix would unblock.
///
/// Run with `cargo test --release expansion_funnel_blocker_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn expansion_funnel_blocker_census() {
    // ⚠ `ai_eval` defaults to 24x16 at 4 players, which is 96 tiles per
    // player; the recorded large comparison runs 74x46 at 6, which is 567.
    // "No settle site in reach" is exactly the kind of
    // reading that could be pure map scarcity at the small size, so both
    // are measured and reported side by side.
    for (label, players, width, height) in [
        ("eval 4p 24x16", 4usize, 24i32, 16i32),
        ("large 6p 74x46", 6, 74, 46),
    ] {
        expansion_funnel_at(label, players, width, height);
    }
}

fn expansion_funnel_at(label: &str, players: usize, width: i32, height: i32) {
    let mut short_city_turns = 0u64;
    let mut fail_serial = 0u64;
    let mut fail_pop = 0u64;
    let mut fail_window = 0u64;
    let mut fail_site = 0u64;
    let mut all_clear = 0u64;
    let mut sole_serial = 0u64;
    let mut sole_pop = 0u64;
    let mut sole_window = 0u64;
    let mut sole_site = 0u64;
    let mut settler_turns_when_clear: Vec<f64> = Vec::new();

    for map in 0..8u64 {
        let mut game = Game::new_full(players, width, height, 480_000 + map, 200, 1, false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len()).map(|_| AdvancedAi::new()).collect();
        game.set_fog_memory(false);
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            if pid == 0 {
                if let Some(plan) = ais[0].plan.clone() {
                    let cities = game.player_city_ids(0);
                    let settlers = game
                        .player_unit_ids(0)
                        .into_iter()
                        .filter(|uid| game.units[uid].kind == "settler")
                        .count();
                    if cities.len() + settlers < plan.desired_cities {
                        let window = AdvancedAi::expansion_window_open(&game);
                        for cid in cities {
                            short_city_turns += 1;
                            let city = &game.cities[&cid];
                            let pos = city.pos;
                            let pop = city.pop;
                            let site = ais[0].best_settle_site(&game, 0, pos, 11).is_some();
                            // `in_flight_allowed` is 1 for the shipped
                            // agent, so serialization fails exactly when a
                            // settler already exists.
                            let serial_ok = settlers < 1;
                            let bad = [!serial_ok, pop < 2, !window, !site];
                            if bad[0] {
                                fail_serial += 1;
                            }
                            if bad[1] {
                                fail_pop += 1;
                            }
                            if bad[2] {
                                fail_window += 1;
                            }
                            if bad[3] {
                                fail_site += 1;
                            }
                            match bad.iter().filter(|b| **b).count() {
                                0 => {
                                    all_clear += 1;
                                    // Everything permits a settler. How
                                    // long would one take to pay for?
                                    let production = game.city_yields(cid).production.max(1.0);
                                    let cost = game.item_remaining_cost_for_city(
                                        0,
                                        cid,
                                        &Item::Unit {
                                            unit: "settler".into(),
                                        },
                                    );
                                    settler_turns_when_clear.push(cost / production);
                                }
                                1 => {
                                    if bad[0] {
                                        sole_serial += 1;
                                    } else if bad[1] {
                                        sole_pop += 1;
                                    } else if bad[2] {
                                        sole_window += 1;
                                    } else {
                                        sole_site += 1;
                                    }
                                }
                                _ => {}
                            }
                        }
                    }
                }
            }
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &crate::game::Action::EndTurn);
            }
        }
    }

    let pct = |n: u64| n as f64 / short_city_turns.max(1) as f64 * 100.0;
    println!(
        "\n=== expansion funnel [{label}]: {short_city_turns} city-turns while SHORT of target ==="
    );
    println!(
        "  a settler already walking (serialization)  {fail_serial:>6}  ({:>5.1}%)",
        pct(fail_serial)
    );
    println!(
        "  city below pop 2                           {fail_pop:>6}  ({:>5.1}%)",
        pct(fail_pop)
    );
    println!(
        "  expansion window shut                      {fail_window:>6}  ({:>5.1}%)",
        pct(fail_window)
    );
    println!(
        "  no settle site in reach                    {fail_site:>6}  ({:>5.1}%)",
        pct(fail_site)
    );
    println!(
        "  NOTHING blocking — the settler was allowed {all_clear:>6}  ({:>5.1}%)",
        pct(all_clear)
    );
    println!("  turns where EXACTLY ONE conjunct failed (a single fix would unblock these):");
    println!("    serialization {sole_serial}   pop<2 {sole_pop}   window {sole_window}   no site {sole_site}");
    if !settler_turns_when_clear.is_empty() {
        let mut t = settler_turns_when_clear.clone();
        t.sort_by(f64::total_cmp);
        println!(
                "  when allowed, a settler costs a median {:.1} turns of this city's production (p90 {:.1})",
                t[t.len() / 2],
                t[t.len() * 9 / 10]
            );
    }
    println!();
}

/// Fires-check for `expansion_pays_back`, at both map scales.
///
/// The treatment exists to unblock the 31.2% of short city-turns where
/// `expansion_funnel_blocker_census` measures the shut window as the sole
/// blocker, so the thing to verify before spending an eval is that it
/// actually opens on those turns — and that it is not simply "always open",
/// which would make it a deletion of the gate rather than a payback test.
///
/// Run with `cargo test --release expansion_payback_fires -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn expansion_payback_fires() {
    for (label, players, width, height) in [
        ("eval 4p 24x16", 4usize, 24i32, 16i32),
        ("large 6p 74x46", 6, 74, 46),
    ] {
        let mut agree = 0u64;
        let mut opened = 0u64;
        let mut closed = 0u64;
        for map in 0..6u64 {
            let mut game = Game::new_full(players, width, height, 480_000 + map, 200, 1, false);
            let mut ais: Vec<AdvancedAi> =
                (0..game.players.len()).map(|_| deployed_agent()).collect();
            let treated = {
                let mut ai = AdvancedAi::new();
                ai.expansion_pays_back = true;
                ai
            };
            game.set_fog_memory(false);
            while game.winner.is_none() && game.turn <= game.max_turns {
                let pid = game.current;
                if pid == 0 {
                    let flat = AdvancedAi::expansion_window_open(&game);
                    for cid in game.player_city_ids(0) {
                        let pays = treated.expansion_pays_back_for(&game, 0, cid);
                        match (flat, pays) {
                            (a, b) if a == b => agree += 1,
                            (false, true) => opened += 1,
                            (true, false) => closed += 1,
                            _ => {}
                        }
                    }
                }
                ais[pid].take_turn(&mut game, pid);
                if game.winner.is_none() && game.current == pid {
                    let _ = game.apply(pid, &crate::game::Action::EndTurn);
                }
            }
        }
        let total = agree + opened + closed;
        println!("\n=== expansion payback vs flat reserve [{label}]: {total} city-turns ===",);
        println!(
            "  agree                     {agree:>6}  ({:>5.1}%)",
            agree as f64 / total.max(1) as f64 * 100.0
        );
        println!(
            "  payback OPENS what the flat reserve shut   {opened:>6}  ({:>5.1}%)",
            opened as f64 / total.max(1) as f64 * 100.0
        );
        println!(
            "  payback SHUTS what the flat reserve opened {closed:>6}  ({:>5.1}%)",
            closed as f64 / total.max(1) as f64 * 100.0
        );
    }
    println!();
}

/// Census, not an assertion: where does an empire's production actually go,
/// and how much of it would the missing cities have cost?
///
/// This is the last open question on the expansion axis, and the axis is
/// worth closing properly because #554 measured real headroom there — a
/// free Settler while short of the city target more than doubles the win
/// rate (23.0% → 52.3%, p=0.0000), the only subsystem grant this harness
/// has ever returned HEADROOM for.
///
/// Every *decision* mechanism proposed for it has since measured null:
///
/// - the expansion window (#562): +0.12 cities, wins unmeasurable
/// - production preemption (`docs/EVAL.md` 2026-07-28): cities at end
///   **2.21 vs 2.21**, settlers started 2.46 vs 2.42
/// - the settler's own valuation: when a city is free it already picks the
///   settler, and the genuine free-city loss is only **2.6%**
/// - capital growth (`docs/OPENINGS.md` §12): every city after the first
///   arrives **later**, monotonically in the dose
///
/// That leaves one explanation standing, and it is not a decision at all:
/// **the empire cannot afford the settlers.** This measures it directly.
/// If the settler share of production is already large and the shortfall
/// would cost more than the empire ever produces, the axis is closed to
/// decision changes and the oracle's headroom is only reachable by having a
/// bigger economy — which #532 measured at 99.5% of its own ceiling.
///
/// Run with `cargo test --release production_allocation_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn production_allocation_census() {
    for (label, players, width, height) in [
        ("eval 4p 24x16", 4usize, 24i32, 16i32),
        ("large 6p 74x46", 6, 74, 46),
    ] {
        let mut spent = BTreeMap::<&str, f64>::new();
        let mut total = 0.0f64;
        let mut end_cities = 0.0f64;
        let mut target = 0.0f64;
        let mut shortfall_cost = 0.0f64;
        let maps = 6u64;

        for map in 0..maps {
            let mut game = Game::new_full(players, width, height, 480_000 + map, 200, 1, false);
            let mut ais: Vec<AdvancedAi> =
                (0..game.players.len()).map(|_| deployed_agent()).collect();
            game.set_fog_memory(false);
            let mut prev: BTreeMap<u32, f64> = BTreeMap::new();
            while game.winner.is_none() && game.turn <= game.max_turns {
                let pid = game.current;
                ais[pid].take_turn(&mut game, pid);
                if game.winner.is_none() && game.current == pid {
                    let _ = game.apply(pid, &crate::game::Action::EndTurn);
                }
                if pid != 0 {
                    continue;
                }
                // Production is banked per item key, so the turn-over-turn
                // rise in a city's yield is what it actually spent, and the
                // queue head says on what.
                for cid in game.player_city_ids(0) {
                    let city = &game.cities[&cid];
                    let yield_now = game.city_yields(cid).production.max(0.0);
                    let key = match city.queue.first() {
                        Some(Item::Unit { unit }) if unit.as_str() == "settler" => "settler",
                        Some(Item::Unit { unit }) => {
                            if game.rules.units[unit.as_str()].class == "military" {
                                "military unit"
                            } else {
                                "civilian unit"
                            }
                        }
                        Some(Item::Formation { .. }) => "military unit",
                        Some(Item::Building { .. }) => "building",
                        Some(Item::District { .. }) => "district",
                        Some(Item::Wonder { .. }) => "wonder",
                        Some(Item::Project { .. }) => "project",
                        Some(Item::Product { .. }) => "product",
                        Some(Item::Repair { .. }) => "repair",
                        None => "idle",
                    };
                    *spent.entry(key).or_default() += yield_now;
                    total += yield_now;
                    prev.insert(cid, yield_now);
                }
            }
            let held = game.player_city_ids(0).len() as f64;
            end_cities += held;
            let want = ais[0]
                .plan
                .as_ref()
                .map(|p| p.desired_cities as f64)
                .unwrap_or(0.0);
            target += want;
            // Civ VI escalates settler cost 80/110/140/...; price the
            // cities the empire never built at that schedule.
            let missing = (want - held).max(0.0) as usize;
            let built = held.max(1.0) as usize;
            for n in 0..missing {
                shortfall_cost += 80.0 + 30.0 * (built + n) as f64;
            }
        }

        println!(
            "\n=== production allocation [{label}]: {total:.0} production over {maps} maps ==="
        );
        let mut rows: Vec<(&&str, &f64)> = spent.iter().collect();
        rows.sort_by(|a, b| b.1.partial_cmp(a.1).unwrap());
        for (kind, amount) in rows {
            println!(
                "  {kind:<14} {amount:>10.0}  ({:>5.1}%)",
                amount / total.max(1.0) * 100.0
            );
        }
        println!(
            "  cities held {:.2} against a target of {:.2}",
            end_cities / maps as f64,
            target / maps as f64
        );
        println!(
                "  the missing cities would have cost {:.0} production — {:.1}% of everything the empire made",
                shortfall_cost / maps as f64,
                shortfall_cost / total.max(1.0) * 100.0
            );
    }
    println!();
}

/// Fires-check for `city_target_floor`, at both map scales.
///
/// ⚠ The criterion is the **outcome** — cities at end — not a mechanism
/// bucket. `docs/EVAL.md` records the last expansion fires-check choosing
/// "the every-city-mid-build bucket must collapse", which the treatment
/// could never have moved, so it was unfalsifiable in the helpful
/// direction. If cities at end do not rise, nothing else here matters.
///
/// Run with `cargo test --release city_target_floor_fires -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn city_target_floor_fires() {
    for (label, players, width, height) in [
        ("eval 4p 24x16", 4usize, 24i32, 16i32),
        ("large 6p 74x46", 6, 74, 46),
    ] {
        for floor in [3usize, 6] {
            let mut cities = 0.0f64;
            let mut target = 0.0f64;
            let mut score = 0.0f64;
            let maps = 6u64;
            for map in 0..maps {
                let mut game = Game::new_full(players, width, height, 480_000 + map, 200, 1, false);
                let mut ais: Vec<AdvancedAi> = (0..game.players.len())
                    .map(|_| {
                        let mut ai = AdvancedAi::new();
                        ai.city_target_floor = floor;
                        ai
                    })
                    .collect();
                game.set_fog_memory(false);
                while game.winner.is_none() && game.turn <= game.max_turns {
                    let pid = game.current;
                    ais[pid].take_turn(&mut game, pid);
                    if game.winner.is_none() && game.current == pid {
                        let _ = game.apply(pid, &crate::game::Action::EndTurn);
                    }
                }
                cities += game.player_city_ids(0).len() as f64;
                score += game.score(0) as f64;
                target += ais[0]
                    .plan
                    .as_ref()
                    .map(|p| p.desired_cities as f64)
                    .unwrap_or(0.0);
            }
            println!(
                "  [{label}] floor={floor}  cities {:.2} / target {:.2}   score {:.0}",
                cities / maps as f64,
                target / maps as f64,
                score / maps as f64
            );
        }
    }
    println!();
}

/// The delegation must carry the plan's target and must not leak it.
///
/// Two properties, both deterministic: with the flag off the baseline
/// governor still sees the gene, and with it on the gene is restored
/// after the turn so no later consumer — gold purchase, the `assess`
/// fallback, a census — reads the substituted value.
#[test]
fn plan_city_target_substitutes_only_inside_the_delegated_call() {
    for flag in [false, true] {
        let mut game = Game::new_full(4, 24, 16, 4_810_001, 120, 1, false);
        game.set_fog_memory(false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len())
            .map(|_| {
                let mut ai = AdvancedAi::new();
                ai.plan_city_target = flag;
                ai
            })
            .collect();
        let gene = ais[0].base.w.city_target;
        while game.winner.is_none() && game.turn <= 40 {
            let pid = game.current;
            ais[pid].take_turn(&mut game, pid);
            assert_eq!(
                ais[pid].base.w.city_target, gene,
                "the gene must be restored before the turn returns"
            );
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &crate::game::Action::EndTurn);
            }
        }
    }
}

#[test]
fn delegated_wide_expansion_extends_the_window_but_defense_stays_first() {
    let mut game = Game::new_full(2, 30, 18, 4_810_002, 500, 0, false);
    for tile in game.map.tiles.values_mut() {
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
    }
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .unwrap();
    game.apply(0, &Action::FoundCity { unit: settler }).unwrap();
    let city = game.player_city_ids(0)[0];
    game.cities.get_mut(&city).unwrap().pop = 6;
    game.turn = 200;

    let own_military: Vec<u32> = game
        .player_unit_ids(0)
        .into_iter()
        .filter(|unit| game.rules.units[game.units[unit].kind].class == "military")
        .collect();
    for unit in own_military {
        game.remove_unit(unit);
    }
    game.at_war.insert((0, 1));

    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 9,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    ai.base.book_pos = 4;
    // Prove the delegated plan, not the production constructor's own
    // defaults, opens both the target and the speed-aware time window —
    // and keep the promoted recon fleet out of the queue this fixture
    // reads, since a missing scout would otherwise outrank the Settler.
    ai.base.w.city_target = 1.0;
    ai.base.w.settler_stop_turn = 100.0;
    ai.base.w.builder_per_city = 0.25;
    ai.disable_recon_replacement();
    ai.disable_naval_recon();
    ai.delegated_cities(&mut game, 0, &plan);

    let defensive_item = game.cities[&city].queue.first().unwrap();
    assert!(matches!(
        defensive_item,
        Item::Unit { unit } if game.rules.units[unit].class == "military"
    ));
    assert_eq!(ai.base.w.city_target, 1.0);
    assert_eq!(ai.base.w.settler_stop_turn, 100.0);
    assert_eq!(ai.base.w.builder_per_city, 0.25);

    // Once the one-unit-per-city floor is restored, the same wide plan may
    // produce the Settler even though both historical genes would refuse it.
    game.at_war.clear();
    game.cities.get_mut(&city).unwrap().queue.clear();
    game.spawn_test_unit("warrior", 0, game.cities[&city].pos);
    ai.delegated_cities(&mut game, 0, &plan);
    assert!(matches!(
        game.cities[&city].queue.first(),
        Some(Item::Unit { unit }) if unit == "settler"
    ));
    assert_eq!(ai.base.w.city_target, 1.0);
    assert_eq!(ai.base.w.settler_stop_turn, 100.0);
    assert_eq!(ai.base.w.builder_per_city, 0.25);
}

/// Fires-check for `plan_city_target`, at both map scales.
///
/// The criterion is the **outcome** — cities at end — for the same reason
/// `city_target_floor_fires` gives: a mechanism bucket the treatment
/// cannot move is not falsifiable in the helpful direction. It prints the
/// plan's own target beside the cities held, because the whole claim is
/// that those two numbers currently disagree.
///
/// Run with
/// `cargo test --profile ci plan_city_target_fires -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn plan_city_target_fires() {
    for (label, players, width, height) in [
        ("eval 4p 24x16", 4usize, 24i32, 16i32),
        ("deployment 6p 74x46", 6, 74, 46),
    ] {
        for flag in [false, true] {
            let (mut cities, mut target, mut score) = (0.0f64, 0.0f64, 0.0f64);
            let maps = 6u64;
            for map in 0..maps {
                let mut game = Game::new_full(players, width, height, 482_000 + map, 200, 1, false);
                let mut ais: Vec<AdvancedAi> = (0..game.players.len())
                    .map(|_| {
                        let mut ai = AdvancedAi::new();
                        ai.plan_city_target = flag;
                        ai
                    })
                    .collect();
                game.set_fog_memory(false);
                while game.winner.is_none() && game.turn <= game.max_turns {
                    let pid = game.current;
                    ais[pid].take_turn(&mut game, pid);
                    if game.winner.is_none() && game.current == pid {
                        let _ = game.apply(pid, &crate::game::Action::EndTurn);
                    }
                }
                cities += game.player_city_ids(0).len() as f64;
                score += game.score(0) as f64;
                target += ais[0]
                    .plan
                    .as_ref()
                    .map(|p| p.desired_cities as f64)
                    .unwrap_or(0.0);
            }
            println!(
                "  [{label}] plan_city_target={flag}  cities {:.2} / plan target {:.2}   \
                     score {:.0}   gene {:.3}",
                cities / maps as f64,
                target / maps as f64,
                score / maps as f64,
                Weights::default().city_target
            );
        }
    }
    println!();
}

/// Census, not an assertion: how much of its treasury does an empire never
/// spend?
///
/// The `ablate` harness's calibration grant hands a seat 200 Gold and 100
/// Faith a turn and wins **89 of 100** — by a wide margin the largest
/// effect any grant has produced, against `ground`, `siting`, `taker`,
/// `modernity` and `attrition` all null and `expansion` at 52.3%. That
/// grant is not a subsystem and proves nothing on its own; it is the
/// instrument's proof that it can detect an advantage.
///
/// But it does raise a question nothing in `docs/` has asked: the treasury
/// is evidently worth an enormous amount, so **does this agent use the one
/// it already has?** A balance sitting idle is capital earning nothing, and
/// unlike expansion it costs no production to deploy.
///
/// Reported as *turns of income held*, because an absolute balance is not
/// interpretable on its own — 300 Gold is prudent at 5 gold per turn and
/// dead weight at 40.
///
/// Run with `cargo test --release idle_treasury_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn idle_treasury_census() {
    for (label, players, width, height) in [
        ("eval 4p 24x16", 4usize, 24i32, 16i32),
        ("large 6p 74x46", 6, 74, 46),
    ] {
        let mut gold_samples: Vec<f64> = Vec::new();
        let mut faith_samples: Vec<f64> = Vec::new();
        let mut gpt_samples: Vec<f64> = Vec::new();
        let mut gold_turns_held: Vec<f64> = Vec::new();
        let mut peak_gold = 0.0f64;
        let maps = 6u64;

        for map in 0..maps {
            let mut game = Game::new_full(players, width, height, 480_000 + map, 200, 1, false);
            let mut ais: Vec<AdvancedAi> =
                (0..game.players.len()).map(|_| deployed_agent()).collect();
            game.set_fog_memory(false);
            while game.winner.is_none() && game.turn <= game.max_turns {
                let pid = game.current;
                ais[pid].take_turn(&mut game, pid);
                if game.winner.is_none() && game.current == pid {
                    let _ = game.apply(pid, &crate::game::Action::EndTurn);
                }
                if pid != 0 {
                    continue;
                }
                let gold = game.players[0].gold;
                let faith = game.players[0].faith;
                // Income, not balance: what the empire earns each turn is
                // the yardstick a balance has to be read against.
                let gpt = game
                    .player_city_ids(0)
                    .into_iter()
                    .map(|cid| game.city_yields(cid).gold)
                    .sum::<f64>()
                    .max(0.1);
                gold_samples.push(gold);
                faith_samples.push(faith);
                gpt_samples.push(gpt);
                gold_turns_held.push(gold / gpt);
                peak_gold = peak_gold.max(gold);
            }
        }

        let mean = |v: &Vec<f64>| v.iter().sum::<f64>() / v.len().max(1) as f64;
        let median = |v: &Vec<f64>| {
            let mut c = v.clone();
            c.sort_by(f64::total_cmp);
            c[c.len() / 2]
        };
        println!(
            "\n=== idle treasury [{label}]: {} seat-turns ===",
            gold_samples.len()
        );
        println!(
            "  Gold held      mean {:.0}   median {:.0}   peak {:.0}",
            mean(&gold_samples),
            median(&gold_samples),
            peak_gold
        );
        println!("  Gold income    mean {:.1}/turn", mean(&gpt_samples));
        println!(
            "  ★ Gold held as TURNS OF INCOME   mean {:.1}   median {:.1}",
            mean(&gold_turns_held),
            median(&gold_turns_held)
        );
        println!(
            "  Faith held     mean {:.0}   median {:.0}",
            mean(&faith_samples),
            median(&faith_samples)
        );
        // The mean sits far above the median, so the distribution has a
        // tail and the tail is where any real waste lives. A seat holding
        // thirty turns of income is not keeping a prudent reserve.
        for cut in [10.0f64, 30.0, 60.0] {
            let share = gold_turns_held.iter().filter(|t| **t > cut).count() as f64
                / gold_turns_held.len().max(1) as f64
                * 100.0;
            println!("    seat-turns holding more than {cut:>4.0} turns of income: {share:>5.1}%");
        }
    }
    println!();
}

/// The agent a census must measure: the one that ships.
///
/// `AdvancedAi::new()` is the exact production controller: it forces the
/// non-gene policy deck to `Live` and keeps the reachable envoy-priority
/// reservation. The measured-null infrastructure valuation and bounded
/// recovery arms are explicit evaluator/live-bridge treatments, not stock
/// behavior. A census must not substitute a champion merely because a
/// historical champion happened to share the live deck.
fn deployed_agent() -> AdvancedAi {
    AdvancedAi::new()
}

/// Census, not an assertion: is the envoy gap a resource shortfall or an
/// allocation failure?
///
/// #602 measured `Grant::Suzerain` — suzerain of every met city-state — at
/// **56.7% against a 22.7% control**, p=0.0000 over 400 maps and 168
/// discordant cells, 150 directions for to 18 against. That is the largest
/// subsystem headroom this harness has found, larger than `expansion`.
///
/// A large ceiling is not a reachable one. Expansion has an equally real
/// ceiling and **seven consecutive treatments failed to reach it**, because
/// the oracle there removed the settler's *cost* and no decision can remove
/// a cost. So the question that decides whether this axis is worth a
/// treatment at all is which kind of gap it is:
///
/// - **`envoys_free` accumulates** → the seat earns envoys and does not
///   place them. An allocation failure, and `advanced_envoys` can fix it.
/// - **`envoys_free` sits near zero** → the seat spends everything it earns
///   and is simply outbid. A resource gap, and this goes the way expansion
///   went.
///
/// The deficit distribution decides how much it would take: being outbid by
/// one envoy at many city-states is a very different problem from being
/// outbid by ten at a few.
///
/// Census, not an assertion: the agent ends games sitting on a faith hoard.
///
/// `ai_eval`'s seat table reports mean end-of-game **faith 3174** against
/// **gold 769** — `self.faith += g.players[pid].faith` is the unspent
/// balance, not a cumulative total. Gold hoarding has had a detector since
/// the audit gained `treasury_looks_hoarded`; faith has never been measured
/// at all.
///
/// ⚠ A large balance is not by itself a defect, and the envoy lane already
/// taught this axis its lesson: **measure availability beside use**. Faith
/// without a religion or a Holy Site may have nothing worth buying, in
/// which case the hoard is structural and no decision rule reaches it.
///
/// The discriminator needs no legality API. Track whether the balance ever
/// *falls*: income is strictly positive, so a monotonically rising balance
/// means nothing is ever bought, while a sawtooth means purchases happen
/// and income simply outpaces them. Those two readings call for opposite
/// work, and the second is not a bug.
///
/// Run with `cargo test --release faith_spending_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn faith_spending_census() {
    // ⚠ The profile is the eval's, not a convenient one. `ai_eval` reports
    // the deployment row at **250 turns Online**; read at 200 turns and the
    // default speed the same agent looks like a different one, because the
    // balance grows with how far the game actually gets. A census meant to
    // explain a number in the seat table has to be run where that number
    // was produced.
    // ⚠ The victory list is part of the profile and it is the whole
    // question here. With Religious Victory switched off,
    // `victory_strategy_enabled` refuses the Religion grand strategy
    // outright, so the seat never adopts the plan that buys missionaries
    // and apostles -- the agent's main faith sink. The gate profile
    // (#658, fixed at `science,culture,domination`) therefore measures an
    // empire that earns faith and has far less to do with it, while the
    // exhibition runs all six victories.
    for (shape, players, width, height, city_states, turns, speed, victories) in [
        (
            "deployment 250t online / ALL victories",
            6usize,
            74i32,
            46i32,
            9usize,
            250u32,
            "online",
            "science,culture,religious,diplomatic,domination,score",
        ),
        (
            "deployment 250t online / GATE victories",
            6,
            74,
            46,
            9,
            250,
            "online",
            "science,culture,domination",
        ),
    ] {
        let label = shape;
        let maps = 6u64;
        let mut end_balance: Vec<f64> = Vec::new();
        let mut peak_balance: Vec<f64> = Vec::new();
        let mut earned: Vec<f64> = Vec::new();
        let mut spent: Vec<f64> = Vec::new();
        let mut purchases: Vec<f64> = Vec::new();
        let mut with_religion = 0u32;
        let mut with_holy_site = 0u32;
        let mut games = 0u32;

        for map in 0..maps {
            let mut options = crate::game::GameOptions::new(
                players,
                width,
                height,
                480_000 + map,
                turns,
                city_states,
            );
            options.speed = speed.to_string();
            let mut game = Game::new_with(options);
            game.victory_conditions = crate::game::VictoryConditions::parse(victories).unwrap();
            let mut ais: Vec<AdvancedAi> =
                (0..game.players.len()).map(|_| deployed_agent()).collect();
            game.set_fog_memory(false);
            let mut last = game.players[0].faith;
            let (mut up, mut down, mut buys, mut peak) = (0.0f64, 0.0f64, 0.0f64, 0.0f64);
            while game.winner.is_none() && game.turn <= game.max_turns {
                let pid = game.current;
                ais[pid].take_turn(&mut game, pid);
                if game.winner.is_none() && game.current == pid {
                    let _ = game.apply(pid, &crate::game::Action::EndTurn);
                }
                if pid != 0 {
                    continue;
                }
                let now = game.players[0].faith;
                // A fall in the balance is a purchase; a rise is income.
                // Both are needed, because "never spends" and "spends but
                // out-earns it" produce the same end balance.
                if now > last {
                    up += now - last;
                } else if now < last {
                    down += last - now;
                    buys += 1.0;
                }
                peak = peak.max(now);
                last = now;
            }
            games += 1;
            end_balance.push(game.players[0].faith);
            peak_balance.push(peak);
            earned.push(up);
            spent.push(down);
            purchases.push(buys);
            if game.players[0].religion.is_some() {
                with_religion += 1;
            }
            if game.player_city_ids(0).iter().any(|cid| {
                game.city_has_district_family(&game.cities[cid], crate::name!("holy_site"))
            }) {
                with_holy_site += 1;
            }
        }

        let mean = |v: &Vec<f64>| v.iter().sum::<f64>() / v.len().max(1) as f64;
        println!("\n=== faith spending [{label}]: {games} games ===");
        println!(
            "  faith earned {:.0}, spent {:.0}  ({:.0}% of income spent)",
            mean(&earned),
            mean(&spent),
            100.0 * mean(&spent) / mean(&earned).max(1e-9),
        );
        println!(
            "  ★ balance at the end {:.0}, peak {:.0}",
            mean(&end_balance),
            mean(&peak_balance),
        );
        println!(
            "  ★ turns the balance FELL (a purchase) {:.1} per game",
            mean(&purchases),
        );
        println!(
            "  -- availability -- founded a religion {}/{}, holds a Holy Site {}/{}",
            with_religion, games, with_holy_site, games,
        );
    }
    println!();
}

/// Run with `cargo test --release envoy_allocation_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn envoy_allocation_census() {
    // Both arms on the same maps, so the distribution can be read as a
    // fires-check: does pricing the suzerainty actually change where the
    // envoys go, before anyone spends eval pairs asking whether it wins?
    for (arm, priced) in [("stock", false), ("suzerainty priced", true)] {
        for (shape, players, width, height, city_states) in [
            ("eval 4p 24x16", 4usize, 24i32, 16i32, 4usize),
            // 9 city-states, not 12: this is the shape the exhibition plays,
            // and a census read on the wrong board is no safer than an effect
            // measured on one.
            ("deployment 6p 74x46", 6, 74, 46, 9),
        ] {
            let label = format!("{shape} / {arm}");
            let mut free_samples: Vec<f64> = Vec::new();
            let mut placed_samples: Vec<f64> = Vec::new();
            let mut met_samples: Vec<f64> = Vec::new();
            let mut held_samples: Vec<f64> = Vec::new();
            let mut deficits: Vec<i64> = Vec::new();
            // #608 concluded from an always-empty pool that allocation was
            // already perfect. #637 showed that does not follow: a policy that
            // spreads one envoy each and one that concentrates three are
            // indistinguishable when the hand is never larger than one. So
            // measure the BOARD the placements built, not the pool they came
            // from.
            //
            // `below` counts envoys parked in a city-state where this seat
            // holds one or two -- under the floor of three, so they buy the
            // level-1 type bonus and no suzerainty. `free_within` counts
            // city-states nobody is suzerain of that this seat could take with
            // the envoys it has parked elsewhere.
            let mut bucket = [0u64; 4];
            let mut below_threshold: Vec<f64> = Vec::new();
            let mut unclaimed: Vec<f64> = Vec::new();
            let mut unclaimed_reachable: Vec<f64> = Vec::new();
            let maps = 6u64;

            for map in 0..maps {
                let mut game = Game::new_full(
                    players,
                    width,
                    height,
                    480_000 + map,
                    200,
                    city_states,
                    false,
                );
                let mut ais: Vec<AdvancedAi> =
                    (0..game.players.len()).map(|_| deployed_agent()).collect();
                // Seat 0 only, so the measured distribution is this seat's own
                // placement policy and not a board where every rival also
                // concentrated and raised the bar it has to clear.
                ais[0].price_the_suzerainty = priced;
                game.set_fog_memory(false);
                while game.winner.is_none() && game.turn <= game.max_turns {
                    let pid = game.current;
                    ais[pid].take_turn(&mut game, pid);
                    if game.winner.is_none() && game.current == pid {
                        let _ = game.apply(pid, &crate::game::Action::EndTurn);
                    }
                    if pid != 0 {
                        continue;
                    }
                    let minors: Vec<usize> = game
                        .players
                        .iter()
                        .filter(|m| m.is_minor && m.alive && !m.is_barbarian)
                        .map(|m| m.id)
                        .filter(|m| game.has_met(0, *m))
                        .collect();
                    if minors.is_empty() {
                        continue;
                    }
                    free_samples.push(game.players[0].envoys_free as f64);
                    placed_samples
                        .push(game.players[0].envoys.iter().map(|(_, n)| *n).sum::<i64>() as f64);
                    met_samples.push(minors.len() as f64);
                    let held = minors
                        .iter()
                        .filter(|m| game.suzerain_of(**m) == Some(0))
                        .count();
                    held_samples.push(held as f64);

                    let mut stranded = 0.0;
                    let mut open = 0.0;
                    let mut open_cheap = 0.0;
                    for minor in &minors {
                        let mine = game.envoys_at(0, *minor);
                        bucket[(mine.clamp(0, 3)) as usize] += 1;
                        if (1..=2).contains(&mine) && game.suzerain_of(*minor) != Some(0) {
                            stranded += mine as f64;
                        }
                        if game.suzerain_of(*minor).is_none() {
                            open += 1.0;
                            let best_rival = game
                                .players
                                .iter()
                                .filter(|o| !o.is_minor && o.alive && o.id != 0)
                                .map(|o| game.envoys_at(o.id, *minor))
                                .max()
                                .unwrap_or(0);
                            // Nobody holds it, so the only bar is the floor of
                            // three and a strict lead over the best rival.
                            if (best_rival + 1).max(3) - mine <= 2 {
                                open_cheap += 1.0;
                            }
                        }
                    }
                    below_threshold.push(stranded);
                    unclaimed.push(open);
                    unclaimed_reachable.push(open_cheap);
                    // For each city-state it does NOT hold, how many more
                    // envoys would it have taken? That is the size of the
                    // reallocation the oracle performed for free.
                    for minor in &minors {
                        if game.suzerain_of(*minor) == Some(0) {
                            continue;
                        }
                        let best_rival = game
                            .players
                            .iter()
                            .filter(|o| !o.is_minor && o.alive && o.id != 0)
                            .map(|o| game.envoys_at(o.id, *minor))
                            .max()
                            .unwrap_or(0);
                        let want = (best_rival + 1).max(3);
                        deficits.push((want - game.envoys_at(0, *minor)).max(0));
                    }
                }
            }

            let mean = |v: &Vec<f64>| v.iter().sum::<f64>() / v.len().max(1) as f64;
            deficits.sort_unstable();
            let total_deficit: i64 = deficits.iter().sum();
            println!(
                "\n=== envoy allocation [{label}]: {} seat-turns ===",
                free_samples.len()
            );
            println!(
                "  ★ envoys UNSPENT in the pool   mean {:.2}   (a pool near zero means resource-bound)",
                mean(&free_samples)
            );
            println!(
                "  envoys placed on the board     mean {:.1}",
                mean(&placed_samples)
            );
            println!(
                "  city-states met {:.1}, suzerain of {:.1}  ({:.0}% held)",
                mean(&met_samples),
                mean(&held_samples),
                mean(&held_samples) / mean(&met_samples).max(1e-9) * 100.0
            );
            let seats = free_samples.len().max(1) as f64;
            let placed_total: f64 = bucket
                .iter()
                .enumerate()
                .skip(1)
                .map(|(n, c)| {
                    // bucket[3] is "three or more", so it undercounts the tail; it
                    // is used only for the shape of the distribution.
                    (n as f64) * (*c as f64)
                })
                .sum();
            let seen: u64 = bucket.iter().sum();
            println!(
                "  envoys per met city-state: 0 -> {:.0}%, 1 -> {:.0}%, 2 -> {:.0}%, 3+ -> {:.0}%",
                100.0 * bucket[0] as f64 / seen.max(1) as f64,
                100.0 * bucket[1] as f64 / seen.max(1) as f64,
                100.0 * bucket[2] as f64 / seen.max(1) as f64,
                100.0 * bucket[3] as f64 / seen.max(1) as f64,
            );
            println!(
                "  ★ envoys parked BELOW the floor of 3   mean {:.2} per seat-turn \
                 ({:.0}% of everything placed)",
                mean(&below_threshold),
                100.0 * mean(&below_threshold) / (placed_total / seats).max(1e-9),
            );
            println!(
                "  ★ city-states with NO suzerain at all  mean {:.2}, of which \
                 within 2 envoys for us: {:.2}",
                mean(&unclaimed),
                mean(&unclaimed_reachable),
            );
            if !deficits.is_empty() {
                println!(
                    "  when NOT suzerain, envoys short: median {}  p90 {}  max {}",
                    deficits[deficits.len() / 2],
                    deficits[deficits.len() * 9 / 10],
                    deficits[deficits.len() - 1]
                );
                println!(
                    "  ★ total shortfall {:.1} envoys per seat-turn against a pool of {:.2}",
                    total_deficit as f64 / free_samples.len().max(1) as f64,
                    mean(&free_samples)
                );
            }
        }
    }
    println!();
}

/// Census, not an assertion: does the agent ever build an envoy income?
///
/// #602 measured perfect suzerainty at **56.7% against a 22.7% control**
/// (p=0.0000, 400 maps) — the largest ceiling this harness has found. #608
/// showed the gap is not allocation: the envoy pool reads **0.00 unspent at
/// every sample** and the agent is suzerain of **3%** of the city-states it
/// meets. It spends everything it earns, and earns almost nothing.
///
/// So the live question is acquisition, and unlike the settler's production
/// cost that expansion foundered on, **every input here is a decision**.
/// `city_state_influence` accrues `influence` per turn and converts it to
/// envoys whenever it crosses the government's `influence_threshold`:
///
/// - **government** — `influence_per_turn` *and* `envoys_per_threshold`,
///   which runs 1 for chiefdom/autocracy/oligarchy/classical_republic,
///   2 for monarchy/merchant_republic/theocracy, 3 for
///   communism/democracy/fascism, 4 for the modern three
/// - **policy cards** — `charismatic_leader` (+2/turn),
///   `gunboat_diplomacy` (+4/turn)
/// - **buildings** — `consulate` (+2), `chancery` (+3)
///
/// If the agent holds an early government, slots neither card and builds
/// neither building, the shortfall is a straightforward consequence and
/// each of those three is a treatment. If it already does all three, the
/// ceiling is out of reach the way expansion's was.
///
/// Run with `cargo test --release envoy_income_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn envoy_income_census() {
    const CARDS: [&str; 2] = ["charismatic_leader", "gunboat_diplomacy"];
    const BUILDINGS: [&str; 2] = ["consulate", "chancery"];

    for (label, players, width, height, city_states) in [
        ("eval 4p 24x16", 4usize, 24i32, 16i32, 4usize),
        ("large 6p 74x46", 6, 74, 46, 12),
    ] {
        let mut govs = BTreeMap::<String, u64>::new();
        let mut envoys_per_threshold: Vec<f64> = Vec::new();
        let mut influence_rate: Vec<f64> = Vec::new();
        let mut card_turns = BTreeMap::<&str, u64>::new();
        let mut building_ever = BTreeMap::<&str, u64>::new();
        let mut turns = 0u64;
        let mut civic_turns = BTreeMap::<&str, u64>::new();
        let mut diplo_slot_turns = 0u64;
        let mut diplo_quarter_games = 0u64;
        let maps = 6u64;

        for map in 0..maps {
            let mut game = Game::new_full(
                players,
                width,
                height,
                480_000 + map,
                200,
                city_states,
                false,
            );
            let mut ais: Vec<AdvancedAi> =
                (0..game.players.len()).map(|_| deployed_agent()).collect();
            game.set_fog_memory(false);
            let mut built_here = BTreeSet::<&str>::new();
            while game.winner.is_none() && game.turn <= game.max_turns {
                let pid = game.current;
                ais[pid].take_turn(&mut game, pid);
                if game.winner.is_none() && game.current == pid {
                    let _ = game.apply(pid, &crate::game::Action::EndTurn);
                }
                if pid != 0 {
                    continue;
                }
                turns += 1;
                let seat = &game.players[0];
                let gov = seat.government.clone().unwrap_or_else(|| "none".into());
                *govs.entry(gov.to_string()).or_default() += 1;
                if let Some(spec) = seat
                    .government
                    .as_ref()
                    .and_then(|g| game.rules.governments.get(g.as_str()))
                {
                    envoys_per_threshold.push(spec.envoys_per_threshold as f64);
                    influence_rate.push(spec.influence_per_turn);
                } else {
                    envoys_per_threshold.push(0.0);
                    influence_rate.push(0.0);
                }
                for card in CARDS {
                    if seat.policies.iter().any(|p| p.as_str() == card) {
                        *card_turns.entry(card).or_default() += 1;
                    }
                }
                for civic in ["political_philosophy", "ideology"] {
                    if seat.civics.iter().any(|c| c.as_str() == civic) {
                        *civic_turns.entry(civic).or_default() += 1;
                    }
                }
                if game.gov_slots(0).diplomatic > 0 {
                    diplo_slot_turns += 1;
                }
                if game.cities.values().any(|c| {
                    c.owner == 0
                        && c.districts
                            .keys()
                            .any(|d| d.as_str() == "diplomatic_quarter")
                }) && built_here.insert("diplomatic_quarter")
                {
                    diplo_quarter_games += 1;
                }
                for b in BUILDINGS {
                    if game
                        .cities
                        .values()
                        .any(|c| c.owner == 0 && c.buildings.iter().any(|x| x.as_str() == b))
                        && built_here.insert(b)
                    {
                        *building_ever.entry(b).or_default() += 1;
                    }
                }
            }
        }

        let mean = |v: &Vec<f64>| v.iter().sum::<f64>() / v.len().max(1) as f64;
        println!("\n=== envoy income [{label}]: {turns} seat-turns over {maps} maps ===");
        println!(
            "  ★ envoys_per_threshold held   mean {:.2}   (1 = earliest tier, 4 = modern)",
            mean(&envoys_per_threshold)
        );
        println!(
            "  government influence/turn     mean {:.2}",
            mean(&influence_rate)
        );
        let mut rows: Vec<(&String, &u64)> = govs.iter().collect();
        rows.sort_by(|a, b| b.1.cmp(a.1));
        println!("  governments held (top 4):");
        for (name, count) in rows.into_iter().take(4) {
            println!(
                "    {name:<24} {:>5.1}% of turns",
                *count as f64 / turns.max(1) as f64 * 100.0
            );
        }
        println!("  ★ influence policy cards slotted:");
        for card in CARDS {
            let n = card_turns.get(card).copied().unwrap_or(0);
            println!(
                "    {card:<22} {:>5.1}% of turns",
                n as f64 / turns.max(1) as f64 * 100.0
            );
        }
        // ⚠ "never chosen" and "never available" are different findings.
        // Both cards need a *diplomatic policy slot* plus a civic, and both
        // buildings need a `diplomatic_quarter` district. Without these
        // three numbers the ones above measure the ruleset, not the agent.
        println!("  availability — was it ever even possible?");
        println!(
            "    political_philosophy held  {:>5.1}% of turns",
            civic_turns
                .get("political_philosophy")
                .copied()
                .unwrap_or(0) as f64
                / turns.max(1) as f64
                * 100.0
        );
        println!(
            "    ideology held              {:>5.1}% of turns",
            civic_turns.get("ideology").copied().unwrap_or(0) as f64 / turns.max(1) as f64 * 100.0
        );
        println!(
            "    a diplomatic slot open     {:>5.1}% of turns",
            diplo_slot_turns as f64 / turns.max(1) as f64 * 100.0
        );
        println!("    diplomatic_quarter built   in {diplo_quarter_games} of {maps} games");
        println!("  ★ influence buildings ever built:");
        for b in BUILDINGS {
            let n = building_ever.get(b).copied().unwrap_or(0);
            println!("    {b:<22} in {n} of {maps} games");
        }
    }
    println!();
}

/// A fixture that can legally build a named wonder: three cities so the
/// lane guards are satisfied, the buildings and adjacent district the
/// wonder requires, and one owned tile shaped to its terrain sheet.
fn strategic_wonder_fixture(seed: u64, wonder: &str) -> (Game, u32) {
    let mut game = Game::new_with(crate::game::GameOptions {
        barbarians: false,
        ..crate::game::GameOptions::new(2, 40, 28, seed, 250, 6)
    });
    for settler in game.player_unit_ids(0) {
        if game.units[&settler].kind == "settler" {
            let _ = game.apply(0, &Action::FoundCity { unit: settler });
        }
    }
    let city = game.player_city_ids(0)[0];
    // Three cities: the lane never opens for a two-city empire.
    let center = game.cities[&city].pos;
    for step in [5, 8] {
        let sites: Vec<Pos> = game
            .map
            .tiles
            .keys()
            .copied()
            .filter(|pos| game.wdist(center, *pos) == step)
            .collect();
        for site in sites {
            let settler = game.spawn_unit("settler", 0, site);
            if game.can_found_city(settler)
                && game.apply(0, &Action::FoundCity { unit: settler }).is_ok()
            {
                break;
            }
            game.units.remove(&settler);
        }
    }

    let spec = game.rules.wonders[wonder].clone();
    if let Some(tech) = spec.tech {
        let mut open = vec![tech];
        while let Some(node) = open.pop() {
            if game.players[0].techs.insert(node) {
                open.extend(game.rules.techs[&node].requires.iter().copied());
            }
        }
    }
    if let Some(civic) = spec.civic {
        let mut open = vec![civic];
        while let Some(node) = open.pop() {
            if game.players[0].civics.insert(node) {
                open.extend(game.rules.civics[&node].requires.iter().copied());
            }
        }
    }
    if spec.founded_religion {
        game.players[0].religion = Some("buddhism".to_string());
    }

    // Three buildings, the required ones among them.
    let mut buildings = vec![crate::name!("monument"), crate::name!("granary")];
    buildings.extend(spec.requires_buildings.iter().copied());
    buildings.extend(spec.requires_any_buildings.iter().take(1).copied());
    game.cities.get_mut(&city).unwrap().buildings = buildings;

    // The district the wonder must sit beside, and a tile beside it that
    // matches the wonder's terrain sheet.
    let district = spec
        .adjacent_district
        .as_ref()
        .map(|family| install_ai_test_district(&mut game, city, family.as_str()));
    let owned: Vec<Pos> = game.cities[&city].owned_tiles.to_vec();
    for pos in owned {
        if pos == center || game.wdist(pos, center) > 3 {
            continue;
        }
        if district.is_some_and(|seat| game.wdist(pos, seat) != 1) {
            continue;
        }
        let tile = game.map.tiles.get_mut(&pos).unwrap();
        if tile.district.is_some() || tile.wonder.is_some() {
            continue;
        }
        tile.flooded = false;
        tile.improvement = None;
        tile.resource = None;
        tile.feature = spec.feature.first().cloned();
        if let Some(terrain) = spec.terrain.first() {
            tile.terrain = *terrain;
        } else if spec.feature.is_empty() {
            tile.terrain = crate::name!("grassland");
        }
        tile.hills = spec.hills.unwrap_or(false);
        break;
    }
    game.turn = 90;
    (game, city)
}

fn wonder_plan(strategy: GrandStrategy, turn: u32) -> StrategicPlan {
    StrategicPlan {
        strategy,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: turn,
        rush: false,
    }
}

/// ★★★★★ THE DEFECT, STATED AS A NUMBER: seven of the twenty points a
/// diplomatic victory needs are wonders, and the Diplomacy-targeted agent
/// refused all three of them at the `-10_000` sentinel — not because it
/// judged them badly, but because the wonder arm never priced
/// `spec.effects` and only opened its lane for Culture and Score.
#[test]
fn a_diplomacy_agent_may_build_the_wonders_that_carry_a_third_of_its_victory() {
    let (game, city) = strategic_wonder_fixture(6_401, "mahabodhi_temple");
    let site = game
        .wonder_sites(city, "mahabodhi_temple")
        .into_iter()
        .next()
        .expect("a legal Mahabodhi site");
    let item = Item::Wonder {
        wonder: crate::name!("mahabodhi_temple"),
        pos: site,
    };
    assert!(game.can_produce(0, city, &item));

    let treated = AdvancedAi::targeting(VictoryTarget::Diplomacy);
    let mut control = AdvancedAi::targeting(VictoryTarget::Diplomacy);
    control.disable_strategic_wonders();
    let plan = wonder_plan(GrandStrategy::Diplomacy, game.turn);

    let refused = control.production_value(&game, 0, city, &item, &plan, &control.counts(&game, 0));
    assert!(
        refused <= -9_999.0,
        "the defect: a Diplomacy agent refuses a wonder worth two of its \
         twenty victory points outright ({refused})"
    );
    let priced = treated.production_value(&game, 0, city, &item, &plan, &treated.counts(&game, 0));
    assert!(
        priced > 0.0,
        "the repair: the same wonder is a legal, positively-valued build \
         ({priced})"
    );
}

/// And the lane stays shut for a wonder this victory does not need. The
/// arm opens a lane for the wonders that finish the game the agent is
/// playing for, which is not the same thing as opening it for wonders.
#[test]
fn a_wonder_the_chosen_victory_does_not_need_is_still_refused() {
    let (game, city) = strategic_wonder_fixture(6_402, "great_library");
    let site = game
        .wonder_sites(city, "great_library")
        .into_iter()
        .next()
        .expect("a legal Great Library site");
    let item = Item::Wonder {
        wonder: crate::name!("great_library"),
        pos: site,
    };
    assert!(game.can_produce(0, city, &item));

    let scientist = AdvancedAi::targeting(VictoryTarget::Science);
    let diplomat = AdvancedAi::targeting(VictoryTarget::Diplomacy);
    let beakers = scientist.production_value(
        &game,
        0,
        city,
        &item,
        &wonder_plan(GrandStrategy::Science, game.turn),
        &scientist.counts(&game, 0),
    );
    let no_votes = diplomat.production_value(
        &game,
        0,
        city,
        &item,
        &wonder_plan(GrandStrategy::Diplomacy, game.turn),
        &diplomat.counts(&game, 0),
    );
    assert!(
        beakers > 0.0,
        "the unresearched half of the tech tree, boosted, is a Science \
         wonder ({beakers})"
    );
    assert!(
        no_votes <= -9_999.0,
        "and buys a Diplomacy agent no votes, so its lane stays shut \
         ({no_votes})"
    );
}

/// ⚠ The Conquest lane is priced at nothing on purpose, and this pins it.
/// Wonders that put units on the map looked like a Domination arm and
/// measured as a cost — `victory_eval` completed the lane 1/8 with them
/// and 3/8 without. See `strategic_wonder_value`.
#[test]
fn the_conquest_lane_buys_no_wonders_and_that_is_deliberate() {
    let (game, city) = strategic_wonder_fixture(6_404, "statue_of_zeus");
    let spec = game.rules.wonders["statue_of_zeus"].clone();
    let general = AdvancedAi::targeting(VictoryTarget::Domination);
    assert_eq!(
        general.strategic_wonder_value(&game, 0, city, &spec, GrandStrategy::Conquest),
        0.0,
        "seven free units is not a reason to stop building units"
    );
}

/// Rule 2 of `strategic_wonder_value`: a rate effect is priced as the flat
/// yield it is equivalent to, so the same wonder is a different build in a
/// different city. The arm as written could not tell them apart — it read
/// only the data sheet, which is identical everywhere.
#[test]
fn a_science_multiplier_is_worth_what_the_city_it_multiplies_makes() {
    let (mut game, city) = strategic_wonder_fixture(6_403, "oxford_university");
    let ai = AdvancedAi::targeting(VictoryTarget::Science);
    let spec = game.rules.wonders["oxford_university"].clone();
    let plan = wonder_plan(GrandStrategy::Science, game.turn);

    let quiet = ai.strategic_wonder_value(&game, 0, city, &spec, GrandStrategy::Science);
    install_ai_test_district(&mut game, city, "campus");
    game.cities
        .get_mut(&city)
        .unwrap()
        .buildings
        .push(crate::name!("library"));
    game.cities.get_mut(&city).unwrap().pop += 6;
    let research = ai.strategic_wonder_value(&game, 0, city, &spec, GrandStrategy::Science);
    assert!(
        research > quiet,
        "Oxford is worth more where there is more science to multiply: \
         {research} vs {quiet}"
    );
    let _ = plan;
}

/// ★★★★ The live seat built one Scout on turn 2 and owned zero recon units
/// from t150 to the end of run civvis-20260818T212725Z, while the loyalty
/// forecast refused its four idle Settlers' candidate sites 115 times with
/// one reason: unexplored ground. `recon_replacement` was ON the whole time —
/// its rebuild logic lives in `BasicAi::pick_item`, which the strategic
/// governor never routes through. `reserve_idle_land_recon` is that
/// treatment's reach into the governor: one idle, non-threatened queue gets
/// the fastest recon unit while `recon_is_the_missing_arm` says the empire
/// is blind, and `--without recon-replacement` still withholds the whole arm.
#[test]
fn the_missing_land_eye_claims_one_idle_queue() {
    let (mut game, capital, home) = empire_with_a_capital(71_127);
    let second = found_nearby_test_city(&mut game, 0, home);
    // No recon anywhere, and dark passable land past the city lights: the
    // arm is missing in exactly the measured shape.
    for unit in game.player_unit_ids(0) {
        game.remove_unit(unit);
    }
    let known: Vec<Pos> = game.wdisk(home, 3);
    game.players[0].explored.clear();
    game.players[0].explored.extend(known);
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 5,
        assessed_turn: game.turn,
        rush: false,
    };
    let is_recon = |game: &Game, cid: u32| {
        matches!(game.cities[&cid].queue.first(),
        Some(Item::Unit { unit })
            if game.rules.units.get(unit.as_str()).is_some_and(|spec| {
                spec.class == "military" && spec.promotion_class == "recon"
            }))
    };

    // The withheld arm reserves nothing.
    {
        let mut withheld_board = game.clone();
        let mut withheld = AdvancedAi::new();
        withheld.enable_live_bridge_universe();
        withheld.disable_recon_replacement();
        withheld.reserve_idle_land_recon(&mut withheld_board, 0, &plan);
        assert!(
            !is_recon(&withheld_board, capital) && !is_recon(&withheld_board, second),
            "--without recon-replacement must also withhold the governor's reach"
        );
    }

    // The live seat claims exactly one idle queue for the missing eye.
    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    live.reserve_idle_land_recon(&mut game, 0, &plan);
    let reserved = [capital, second]
        .iter()
        .filter(|cid| is_recon(&game, **cid))
        .count();
    assert_eq!(reserved, 1, "one idle queue holds the recon unit");

    // The arm's own target governs: with two cities it retains a spare eye
    // (`RECON_ARM_MAX`), so a second call fills the second queue — and a
    // third claims nothing, because queued recon counts toward the arm.
    let mut again = game.clone();
    live.reserve_idle_land_recon(&mut again, 0, &plan);
    live.reserve_idle_land_recon(&mut again, 0, &plan);
    let after = [capital, second]
        .iter()
        .filter(|cid| is_recon(&again, **cid))
        .count();
    assert_eq!(after, 2, "the arm fills to its own target and stops");

    // A fully charted world needs no land eye at all.
    let mut charted = game.clone();
    for cid in [capital, second] {
        charted.cities.get_mut(&cid).unwrap().queue.clear();
    }
    let all: Vec<Pos> = charted.map.tiles.keys().copied().collect();
    charted.players[0].explored.extend(all);
    live.reserve_idle_land_recon(&mut charted, 0, &plan);
    assert!(
        !is_recon(&charted, capital) && !is_recon(&charted, second),
        "a charted world reserves nothing"
    );
}

/// ★★★ A STOCK LANE'S PRESSURE ACCELERATES, AND THE BAR READ IT TOO LATE TO
/// VOTE. The first game on the repaired economy (civvis-20260818T231407Z,
/// 16 cities against the best rival's 9) crossed `STOCK_DENIAL_BAR` at ~t221;
/// the game's last Congress sat at t222 with nothing reading urgent when the
/// ballot was priced, and Egypt won Culture at t232. Across the four
/// measurable culture losses the projection moves the first crossing from
/// 3/7/12/37 turns of lead to 12/12/15/66. The projection can only raise a
/// reading — a receding leader clamps to the raw number — and it feeds the
/// stock clause alone.
#[test]
fn a_rising_stock_pressure_reads_urgent_a_congress_earlier() {
    let game = Game::new_full(2, 20, 14, 71_131, 30, 0, false);
    let rising = VictoryFocus {
        strategy: GrandStrategy::Culture,
        progress: 60,
    };

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(
        live.projected_stock_denial,
        "the live seat carries the treatment"
    );
    assert!(
        live.stock_denial_lead_time,
        "the projection rides the lead-time bar"
    );

    // No history yet: a projection from a single reading is noise, so the
    // raw bar rules and 60 is not urgent.
    assert!(!live.victory_pressure_is_urgent(&game, 1, rising));

    // Eight turns of the measured Egypt ramp (~2.4/turn): 60 projected
    // fifteen turns forward clears the bar with a Congress still to come.
    live.stock_pressure_history.insert(
        1,
        (0..=8)
            .map(|i| (100 + i, 41 + (i as i32) * 12 / 5))
            .collect(),
    );
    assert!(live.victory_pressure_is_urgent(&game, 1, rising));

    // A flat or receding leader clamps to the raw reading: not urgent.
    live.stock_pressure_history
        .insert(1, (0..=8).map(|i| (100 + i, 60 - (i as i32))).collect());
    assert!(!live.victory_pressure_is_urgent(&game, 1, rising));

    // The raw bar itself is untouched: 78 stays urgent with any history.
    let at_bar = VictoryFocus {
        strategy: GrandStrategy::Culture,
        progress: STOCK_DENIAL_BAR,
    };
    assert!(live.victory_pressure_is_urgent(&game, 1, at_bar));

    // Non-stock lanes never read the projection: Science at 60 with the
    // steepest ramp on record stays non-urgent.
    live.stock_pressure_history
        .insert(1, (0..=8).map(|i| (100 + i, 40 + (i as i32) * 6)).collect());
    let science = VictoryFocus {
        strategy: GrandStrategy::Science,
        progress: 60,
    };
    assert!(!live.victory_pressure_is_urgent(&game, 1, science));

    // The withhold arm restores the raw bar exactly.
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge();
    withheld.disable_projected_stock_denial();
    withheld.stock_pressure_history.insert(
        1,
        (0..=8)
            .map(|i| (100 + i, 41 + (i as i32) * 12 / 5))
            .collect(),
    );
    assert!(!withheld.victory_pressure_is_urgent(&game, 1, rising));

    // The published withhold row reaches the same flag.
    let row = GENES
        .iter()
        .find(|gene| gene.field == "projected_stock_denial")
        .expect("the gene is published");
    assert!(row.live());
    assert_eq!(row.tag, "projected-stock-denial");
    let disable = row.disable;
    let mut via_row = AdvancedAi::new();
    via_row.enable_live_bridge();
    disable(&mut via_row);
    assert!(
        !via_row.projected_stock_denial,
        "{} row disables the flag",
        row.field
    );

    // Frozen and ordinary controllers never project.
    assert!(!AdvancedAi::new().projected_stock_denial);
    assert!(!AdvancedAi::legacy().projected_stock_denial);
}

/// Three mutually adjacent land tiles with nothing on them, and a unit with
/// movement to spare, so a whole loop fits inside one turn.
fn hex_triangle(game: &crate::game::Game) -> Option<[(i32, i32); 3]> {
    let open = |pos: (i32, i32)| {
        game.map
            .get(pos)
            .is_some_and(|tile| !game.rules.is_water(tile))
            && game.unit_ids_at(pos).is_empty()
    };
    for (a, _) in game.map.tiles.iter() {
        if !open(*a) {
            continue;
        }
        for b in game.nbrs(*a) {
            if !open(b) {
                continue;
            }
            for c in game.nbrs(*a) {
                if c != b && open(c) && game.wdist(b, c) == 1 {
                    return Some([*a, b, c]);
                }
            }
        }
    }
    None
}

/// `A -> B -> C -> A` is a wasted turn the shipped guard cannot see.
///
/// `recorded_tactical_step` remembers the single tile a unit just left, so it
/// refuses `A -> B -> A` and passes a loop one hop longer. Measured over three
/// 6-player 200-turn games, that is not a corner: the live bundle walks 329
/// routes ending where they began and **191 of them are exactly this shape**,
/// against 23 of the two-hop shape the shipped guard already covers.
#[test]
fn the_whole_turn_guard_refuses_a_three_hop_loop_that_the_shipped_one_allows() {
    let mut game = Game::new(2, 24, 16, 79, 80, 0);
    let [a, b, c] = hex_triangle(&game).expect("fixture offers three adjacent open land tiles");

    for (guard, expected) in [(false, true), (true, false)] {
        let mut board = game.clone();
        let uid = board.spawn_test_unit("horseman", 0, a);
        // Movement is not what is under test; terrain cost must not decide it.
        board.units.get_mut(&uid).unwrap().moves_left = 12.0;

        let mut ai = AdvancedAi::new();
        ai.enable_recorded_tactical_step();
        if guard {
            ai.enable_whole_turn_backtrack_guard();
        }

        assert!(ai.base.path_move(&mut board, 0, uid, b), "step to B");
        assert!(ai.base.path_move(&mut board, 0, uid, c), "step to C");
        assert_eq!(
            ai.base.path_move(&mut board, 0, uid, a),
            expected,
            "closing the loop back to the start, guard={guard}"
        );
        assert_eq!(
            board.units[&uid].pos == a,
            expected,
            "and the unit is back where it began only when the loop was allowed"
        );
    }
    let _ = &mut game;
}

/// The one-hop reversal stays refused with the wider guard on.
///
/// The wider rule has to *contain* the shipped one — a trail whose last entry
/// is the tile being proposed is still a trail that contains it — or turning
/// it on would trade one pathology for another.
#[test]
fn the_whole_turn_guard_still_refuses_the_immediate_reversal() {
    let mut game = Game::new(2, 24, 16, 79, 80, 0);
    let [a, b, _] = hex_triangle(&game).expect("fixture offers adjacent open land tiles");
    for guard in [false, true] {
        let mut board = game.clone();
        let uid = board.spawn_test_unit("horseman", 0, a);
        board.units.get_mut(&uid).unwrap().moves_left = 12.0;
        let mut ai = AdvancedAi::new();
        ai.enable_recorded_tactical_step();
        if guard {
            ai.enable_whole_turn_backtrack_guard();
        }
        assert!(ai.base.path_move(&mut board, 0, uid, b), "step to B");
        assert!(
            !ai.base.path_move(&mut board, 0, uid, a),
            "stepping straight back is refused either way, guard={guard}"
        );
    }
    let _ = &mut game;
}

/// The treatment is off in the shipped controller and on in the live bundle.
#[test]
fn the_whole_turn_guard_is_a_live_treatment() {
    assert!(!AdvancedAi::new().base.whole_turn_backtrack_guard);
    let mut live = AdvancedAi::new();
    live.enable_live_bridge_universe();
    assert!(live.base.whole_turn_backtrack_guard);
    live.disable_whole_turn_backtrack_guard();
    assert!(!live.base.whole_turn_backtrack_guard);
}

/// ★★★★ THE FAITH THAT BUYS THE PANTHEON IS ONE CARD, AND THE PLAN KEPT
/// THROWING IT AWAY. See `AdvancedAi::expansion_pantheon`: God-King is the
/// live capital's only early Faith, the portfolio replaced it at the first
/// civic after Code of Laws, and the pantheon landed at median t22 and as late
/// as t108 with 6–9 Faith banked against a price of 12.5. With the flag on the
/// card is wanted first while the pantheon is unfounded and unaffordable, and
/// released the turn it is founded; ordinary and frozen controllers keep the
/// bred deck.
#[test]
fn the_expansion_pantheon_keeps_god_king_until_the_pantheon_is_founded() {
    let slotted = |treated: bool, pantheon: Option<&str>, faith: f64| {
        let mut game = Game::new(2, 32, 24, 5_417, 250, 0);
        let settler = game
            .player_unit_ids(0)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("starting settler");
        game.apply(0, &Action::FoundCity { unit: settler })
            .expect("found city");
        // The live seat at its first civic swap: Chiefdom's lone economic
        // slot, with God-King, Urban Planning, Ilkum and Colonization all on
        // offer.
        game.players[0].government = Some("chiefdom".to_string());
        game.players[0].civics.extend([
            crate::name!("code_of_laws"),
            crate::name!("craftsmanship"),
            crate::name!("foreign_trade"),
            crate::name!("early_empire"),
        ]);
        game.players[0].policies.clear();
        game.players[0].pantheon = pantheon.map(str::to_string);
        game.players[0].faith = faith;
        let mut ai = AdvancedAi::new();
        if treated {
            ai.enable_expansion_pantheon();
        }
        ai.refresh_research_weight(&game);
        ai.strategic_policies(&mut game, 0, GrandStrategy::Expansion);
        game.players[0].policies.clone()
    };
    let god_king = crate::name!("god_king");

    // Off: the bred deck never wants the Faith card.
    assert!(
        !slotted(false, None, 0.0).contains(&god_king),
        "the ordinary controller keeps its deck"
    );
    // On, no pantheon, no Faith: God-King holds the slot.
    assert!(
        slotted(true, None, 0.0).contains(&god_king),
        "the pantheon is God-King's alone until it is founded"
    );
    // On, the price already banked: the slot goes back to the plan.
    assert!(
        !slotted(true, None, 200.0).contains(&god_king),
        "Faith enough for the pantheon frees the slot"
    );
    // On, pantheon founded: released the same turn.
    assert!(
        !slotted(true, Some("religious_settlements"), 0.0).contains(&god_king),
        "a founded pantheon releases the card"
    );

    // Frozen and ordinary controllers never carry the flag.
    assert!(!AdvancedAi::new().expansion_pantheon);
    assert!(!AdvancedAi::legacy().expansion_pantheon);
    assert!(!AdvancedAi::new().base.expansion_pantheon);
}

/// ★★★★ THE PLAZA STANDS EMPTY IN EVERY RECORDED GAME. See
/// `AdvancedAi::expansion_hall`: a Government Plaza completes at t29–57 in
/// all 35 recorded 2026-08-18/19 runs and no tier-1 plaza building is ever
/// built, because the Ancestral Hall has no yields, its district is not
/// `specialty`, and its two effects — a free Builder in every new city, +50%
/// Settlers — were priced at nothing. With the flag on the land grab pays for
/// them while it is still short of seats, and nothing when it is not; ordinary
/// and frozen controllers keep the zero.
#[test]
fn the_expansion_hall_is_priced_while_the_land_grab_is_short_of_seats() {
    let mut game = Game::new(2, 32, 24, 5_417, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let city = game.player_city_ids(0)[0];
    // A completed Government Plaza in the capital, the way the recorded games
    // hold one by t29–57.
    let plaza = game.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| {
            *position != game.cities[&city].pos
                && game.map.tiles[position].district.is_none()
                && !game.map.tiles[position].terrain.contains("ocean")
                && !game.map.tiles[position].terrain.contains("coast")
                && !game.map.tiles[position].terrain.contains("mountain")
        })
        .expect("a land tile for the plaza");
    game.map.tiles.get_mut(&plaza).unwrap().district = Some(crate::name!("government_plaza"));
    game.cities
        .get_mut(&city)
        .unwrap()
        .districts
        .insert(crate::name!("government_plaza"), plaza);
    let hall = Item::Building {
        building: crate::name!("ancestral_hall"),
    };
    let audience = Item::Building {
        building: crate::name!("audience_chamber"),
    };
    let plan = |desired_cities: usize| StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities,
        assessed_turn: game.turn,
        rush: false,
    };

    // Off: nothing prices the hall's effects.
    let control = AdvancedAi::new();
    let counts = control.counts(&game, 0);
    let unpriced = control.production_value(&game, 0, city, &hall, &plan(16), &counts);

    // On, with the land grab short of seats: the hall is owed the Builder in
    // every new city and the faster Settlers, and the Audience Chamber —
    // neither effect — is not.
    let mut live = AdvancedAi::new();
    live.enable_land_grab();
    live.enable_expansion_hall();
    let counts = live.counts(&game, 0);
    let priced = live.production_value(&game, 0, city, &hall, &plan(16), &counts);
    let chamber = live.production_value(&game, 0, city, &audience, &plan(16), &counts);
    // `production_value` normalises by (7 + turns to build), so the raw 1200
    // reads as 1200 / (7 + turns) here; the shape, not the figure, is asserted.
    assert!(
        priced > unpriced + 10.0,
        "fifteen seats short pays the full hall: {priced} against {unpriced}"
    );
    assert!(
        (chamber - unpriced).abs() < 1.0,
        "the Audience Chamber carries neither effect: {chamber} against {unpriced}"
    );
    // On, but the land grab has its seats: back to the unpriced building.
    let satisfied = live.production_value(&game, 0, city, &hall, &plan(1), &counts);
    assert!(
        (satisfied - unpriced).abs() < 1.0,
        "no seats short, nothing owed: {satisfied} against {unpriced}"
    );
    // Half the shortfall, half the price.
    let half = live.production_value(&game, 0, city, &hall, &plan(4), &counts);
    let ratio = (half - unpriced) / (priced - unpriced);
    assert!(
        (0.45..=0.55).contains(&ratio),
        "three seats short pays half of the full hall: {half} against {priced} ({ratio:.2})"
    );

    // Frozen and ordinary controllers never carry the flag.
    assert!(!AdvancedAi::new().expansion_hall);
    assert!(!AdvancedAi::legacy().expansion_hall);
}

/// Every Great Person class stays recruitable to the Information era.
///
/// ★★★★★ A CLASS THAT RUNS OUT STOPS BEING AN ECONOMY AND BECOMES FAITH.
/// `Game::unused_great_person_faith` faithfully models Civilization VI's
/// `GetFaithFromUnusedGreatPeoplePoints`: once a class has nobody left to
/// recruit, every point per turn it earns is paid out as Faith instead. That
/// is correct, and it made a content gap invisible. The shipped roster held 29
/// individuals against Gathering Storm's 213, and **every class was empty from
/// the Atomic era on** — so from the midgame the Campus, Theatre Square and
/// Harbour output an empire had spent the whole game building stopped
/// producing Great People at all.
///
/// Measured over eight 6-player 200-turn games, 48 empire-games, paired
/// against the same seeds: **26.6% of all non-prophet Great Person points were
/// converted to Faith, and seven of the eight non-prophet classes ran dry** —
/// writer by median turn 106, artist 139, scientist 159, admiral 160. With the
/// roster filled out to 65 the same measurement reports 5.4%, three classes
/// running dry and none before turn 172, and **229 Great People recruited
/// against 125**.
///
/// ⚠ Prophet is excluded on purpose, and is the one class this must not
/// demand. Civilization VI stops offering Prophets once the map's religions
/// are claimed, and `great_person_class_earnable` already models that; its
/// points becoming Faith is the rule, not a gap.
#[test]
fn every_great_person_class_is_recruitable_to_the_information_era() {
    const INFORMATION: usize = 7;
    let rules = crate::rules::Rules::shipped();
    let mut eras: std::collections::BTreeMap<&str, std::collections::BTreeSet<usize>> =
        std::collections::BTreeMap::new();
    for spec in rules.great_people.values() {
        eras.entry(spec.kind.as_str()).or_default().insert(spec.era);
    }
    assert!(
        eras.len() >= 8,
        "the roster should span every class: {eras:?}"
    );
    for (kind, present) in &eras {
        if *kind == "prophet" {
            continue;
        }
        let first = *present.iter().next().expect("a class with no era");
        let missing: Vec<usize> = (first..=INFORMATION)
            .filter(|era| !present.contains(era))
            .collect();
        assert!(
            missing.is_empty(),
            "{kind} first appears in era {first} and then has no individual for \
             era(s) {missing:?}; every point that class earns after the gap is \
             paid out as Faith instead"
        );
    }
}

#[test]
fn a_founding_is_priced_on_the_ground_the_settler_stood_on() {
    // "the site is worth N" is the INPUT to the settling decision, not a
    // reading of the city it became. `settle_value` scores the work radius,
    // and founding rewrites that radius — the growth forecast behind
    // `growth_readiness` then runs over a worked city centre.
    //
    // Priced after the apply, the number inverts: on live Chieftain run
    // `civvis-20260819T041034Z` the two sites logged most negative (-3.1,
    // -1.4) became Ravenna and Aquileia, the seat's best non-capital cities
    // at 14.2 and 13.1 science, while the single site that logged positive
    // (+2.2) became Lugdunum at 2.25. A study reading that log concludes the
    // seat settles bad ground — the opposite of what it did.
    let mut game = Game::new(2, 24, 16, 7, 80, 0);
    for unit in game
        .player_unit_ids(0)
        .into_iter()
        .chain(game.player_unit_ids(1))
    {
        game.remove_unit(unit);
    }
    game.current = 0;
    let mut candidates: Vec<Pos> = game.map.tiles.keys().copied().collect();
    candidates.sort_unstable();
    let start = candidates[0];
    let settler = game.spawn_test_unit("settler", 0, start);
    let site = candidates
        .into_iter()
        .find(|p| {
            game.units.get_mut(&settler).unwrap().pos = *p;
            game.can_found_city(settler)
        })
        .expect("the fixture map offers foundable ground");
    game.units.get_mut(&settler).unwrap().pos = site;
    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    let before = live.settle_value(&game, 0, site);
    let journal = crate::reasoning::Journal::recording();
    live.attach_journal(journal.handle());
    assert!(
        live.advanced_settler_step(&mut game, 0, settler),
        "the settler acts on ground it can found on"
    );
    assert!(
        game.cities.values().any(|c| c.owner == 0 && c.pos == site),
        "and the city exists"
    );
    let after = live.settle_value(&game, 0, site);
    // Without this the test proves nothing: if founding did not move the
    // number, both orderings would log the same value.
    assert_ne!(
        format!("{before:.1}"),
        format!("{after:.1}"),
        "founding must change what settle_value reads, or this fixture \
         cannot tell the two orderings apart"
    );
    let said: Vec<String> = journal
        .since(0)
        .thoughts
        .iter()
        .map(|t| format!("{} | {}", t.headline, t.detail))
        .collect();
    let line = said
        .iter()
        .find(|line| line.contains("the site is worth"))
        .unwrap_or_else(|| panic!("the founding is journalled; journal {said:#?}"));
    assert!(
        line.contains(&format!("the site is worth {before:.1}")),
        "the journal prices the ground the settler stood on ({before:.1}), \
         not the city it became ({after:.1}); got {line}"
    );
}

/// Fires-check for the religion genes, run by hand: four 6p games with the
/// deployment genome plus the gene on every seat, counting defensive
/// Apostles, founders and Inquisitions.
/// `cargo test --profile ci --lib -- --ignored --nocapture religion_genes_fires_check`
#[test]
#[ignore]
fn religion_genes_fires_check() {
    for seed in 0..4u64 {
        let mut game = Game::new(6, 60, 38, 611 + seed, 200, 6);
        let mut ais = AdvancedAi::fleet(&game);
        for ai in ais.iter_mut() {
            ai.enable_engine_repairs();
            ai.enable_founder_temple();
        }
        crate::ai::run_game(&mut game, &mut ais);
        let mut census = StrategyCensus::default();
        for ai in ais.iter().take(6) {
            census.absorb(&ai.strategy_census());
        }
        let founders = game
            .players
            .iter()
            .take(6)
            .filter(|p| p.religion.is_some())
            .count();
        let inquisitions = game
            .players
            .iter()
            .take(6)
            .filter(|p| p.counters.get("inquisition").copied().unwrap_or(0) > 0)
            .count();
        eprintln!(
            "FIRES seed={seed} t{} victory={:?} founders={founders} inquisitions={inquisitions}",
            game.turn, game.victory_type
        );
    }
}

use super::great_person_housing::{GreatPersonRemedy, StuckGreatPerson};

/// A two-seat world with contact made, player 0 holding a capital with a
/// Theater Square and the civic that makes an Amphitheater buildable.
fn great_person_housing_fixture(seed: u64) -> (Game, u32) {
    let mut game = Game::new_full(2, 28, 18, seed, 300, 0, false);
    game.record_contact(0, 1);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.found_city_for(pid, game.units[&settler].pos, None);
        game.remove_unit(settler);
        game.players[pid]
            .civics
            .insert(crate::name!("drama_poetry"));
        game.players[pid].techs.insert(crate::name!("writing"));
        game.players[pid].gold = 1_000.0;
    }
    game.turn = 60;
    game.current = 0;
    let capital = game.player_city_ids(0)[0];
    install_ai_test_district(&mut game, capital, "theater_square");
    (game, capital)
}

fn writing_works(game: &Game, pid: usize) -> i64 {
    game.players[pid]
        .counters
        .get("great_work:writing")
        .copied()
        .unwrap_or(0)
}

fn great_person_housing_plan(game: &Game, strategy: GrandStrategy) -> StrategicPlan {
    StrategicPlan {
        strategy,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 3,
        assessed_turn: game.turn,
        rush: false,
    }
}

/// ★★★★ A GREAT PERSON THE EMPIRE HAS EARNED AND CANNOT USE IS A RACE LOST
/// FOR NOTHING. A Science seat's Theater Square has earned a full Writer and
/// owns no Writing slot but the Palace's one: the claim is blocked, the
/// shipped agent leaves the queue empty (its production chooser vetoes the
/// Amphitheater at −10,000 off the Culture lane), and the points sit. With
/// `great_person_housing` the square's city starts the Amphitheater.
#[test]
fn a_writer_at_the_price_with_no_slot_starts_an_amphitheater_whatever_the_lane() {
    let (mut game, capital) = great_person_housing_fixture(71_301);
    let cost = game.gp_cost(0, "writer");
    game.players[0].gpp.insert("writer".to_string(), cost);
    assert!(
        !game.can_activate_current_great_person(0, "writer"),
        "two Writing slots are needed and only the Palace's universal slot exists"
    );
    let plan = great_person_housing_plan(&game, GrandStrategy::Science);
    let amphitheater = Item::Building {
        building: crate::name!("amphitheater"),
    };
    assert!(game.can_produce(0, capital, &amphitheater));

    let stock = AdvancedAi::new();
    assert_eq!(
        stock.stuck_great_people(&game, 0),
        vec![StuckGreatPerson {
            kind: "writer".to_string(),
            remedy: GreatPersonRemedy::Slots("writing", 2),
            due: true,
            turns_to_due: 0.0,
        }],
        "the Writer is the one stuck class"
    );
    let mut untouched = game.clone();
    assert!(!stock.great_person_housing(&mut untouched, 0, &plan));
    assert!(
        untouched.cities[&capital].queue.is_empty(),
        "off: nothing is reserved"
    );

    let mut ai = AdvancedAi::new();
    ai.enable_great_person_housing();
    let mut housed = game.clone();
    assert!(ai.great_person_housing(&mut housed, 0, &plan));
    assert_eq!(
        housed.cities[&capital].queue.first(),
        Some(&amphitheater),
        "on: the square's city starts the slot building"
    );
    // One reservation per class: the next turn sees the Amphitheater queued
    // and does not touch another city or re-issue the order.
    assert!(!ai.great_person_housing(&mut housed, 0, &plan));
}

/// The building starts ahead of the person — within the lead — and not for
/// points that are still forty turns out.
#[test]
fn the_slot_building_starts_within_the_lead_and_not_before() {
    let (game, capital) = great_person_housing_fixture(71_302);
    let rate = game.great_person_points_per_turn(0)["writer"];
    assert!(rate > 0.0, "a Theater Square earns Writer points");
    let cost = game.gp_cost(0, "writer");
    let plan = great_person_housing_plan(&game, GrandStrategy::Expansion);
    let mut ai = AdvancedAi::new();
    ai.enable_great_person_housing();

    let mut soon = game.clone();
    soon.players[0]
        .gpp
        .insert("writer".to_string(), cost - rate * 10.0);
    let stuck = ai.stuck_great_people(&soon, 0);
    assert_eq!(stuck.len(), 1);
    assert!(!stuck[0].due);
    assert!((stuck[0].turns_to_due - 10.0).abs() < 1e-6);
    assert!(ai.great_person_housing(&mut soon, 0, &plan));
    assert!(matches!(
        soon.cities[&capital].queue.first(),
        Some(Item::Building { building }) if *building == crate::name!("amphitheater")
    ));

    let mut far = game.clone();
    far.players[0]
        .gpp
        .insert("writer".to_string(), cost - rate * 40.0);
    assert!(ai.stuck_great_people(&far, 0).is_empty());
    assert!(!ai.great_person_housing(&mut far, 0, &plan));
    assert!(far.cities[&capital].queue.is_empty());
}

/// A due person may pause an ordinary building (its progress is kept); a
/// person still ten turns out may not, and a unit is never paused.
#[test]
fn a_due_person_pauses_a_building_but_never_a_unit() {
    let (mut game, capital) = great_person_housing_fixture(71_303);
    let cost = game.gp_cost(0, "writer");
    let rate = game.great_person_points_per_turn(0)["writer"];
    let plan = great_person_housing_plan(&game, GrandStrategy::Science);
    let mut ai = AdvancedAi::new();
    ai.enable_great_person_housing();
    let granary = Item::Building {
        building: crate::name!("granary"),
    };
    game.players[0].techs.insert(crate::name!("pottery"));
    let warrior = Item::Unit {
        unit: crate::name!("warrior"),
    };
    assert!(game.can_produce(0, capital, &granary));
    assert!(game.can_produce(0, capital, &warrior));

    let mut due = game.clone();
    due.players[0].gpp.insert("writer".to_string(), cost);
    due.cities.get_mut(&capital).unwrap().queue = vec![granary.clone()];
    assert!(ai.great_person_housing(&mut due, 0, &plan));
    assert!(matches!(
        due.cities[&capital].queue.first(),
        Some(Item::Building { building }) if *building == crate::name!("amphitheater")
    ));

    let mut soon = game.clone();
    soon.players[0]
        .gpp
        .insert("writer".to_string(), cost - rate * 10.0);
    soon.cities.get_mut(&capital).unwrap().queue = vec![granary.clone()];
    assert!(!ai.great_person_housing(&mut soon, 0, &plan));
    assert_eq!(soon.cities[&capital].queue.first(), Some(&granary));

    let mut armed = game.clone();
    armed.players[0].gpp.insert("writer".to_string(), cost);
    armed.cities.get_mut(&capital).unwrap().queue = vec![warrior.clone()];
    assert!(!ai.great_person_housing(&mut armed, 0, &plan));
    assert_eq!(armed.cities[&capital].queue.first(), Some(&warrior));
}

/// ★★★★ SELL TO MAKE ROOM. Both Writing slots of the only Amphitheater are
/// full, the Writer is due, and nothing with a Writing slot can be started
/// anywhere: the gene sells one duplicate work to a rival with an open slot,
/// which frees the slot the Palace's universal one completes, and recruits
/// the Writer the same turn — two new works for one sold, plus the Gold.
/// Off, the works stay, the Writer stays on the market, and the points sit.
/// The plan's target is never sold a work.
#[test]
fn a_due_writer_no_city_can_house_sells_a_duplicate_and_recruits() {
    let (mut game, capital) = great_person_housing_fixture(71_304);
    game.cities
        .get_mut(&capital)
        .unwrap()
        .buildings
        .push(crate::name!("amphitheater"));
    game.players[0]
        .counters
        .insert("great_work:writing".to_string(), 2);
    let rival = game.player_city_ids(1)[0];
    install_ai_test_district(&mut game, rival, "theater_square");
    game.cities
        .get_mut(&rival)
        .unwrap()
        .buildings
        .push(crate::name!("amphitheater"));
    let cost = game.gp_cost(0, "writer");
    game.players[0].gpp.insert("writer".to_string(), cost);
    assert!(!game.can_house_great_works(0, "writing", 2));
    assert!(!game.can_activate_current_great_person(0, "writer"));
    assert!(
        game.quick_deals(0)
            .iter()
            .any(|deal| deal.category == "great_work"
                && deal.direction == "sell"
                && deal.item == "writing"),
        "the market quotes the duplicate"
    );
    let plan = great_person_housing_plan(&game, GrandStrategy::Science);
    let claimed = |game: &Game| {
        game.players[0]
            .gp_claimed
            .get("writer")
            .copied()
            .unwrap_or(0)
    };

    let mut kept = game.clone();
    assert!(!AdvancedAi::new().great_person_housing(&mut kept, 0, &plan));
    assert_eq!(writing_works(&kept, 0), 2);
    assert_eq!(claimed(&kept), 0);

    let mut ai = AdvancedAi::new();
    ai.enable_great_person_housing();
    let mut sold = game.clone();
    assert!(ai.great_person_housing(&mut sold, 0, &plan));
    assert_eq!(claimed(&sold), 1, "the Writer is recruited the same turn");
    assert_eq!(writing_works(&sold, 0), 3, "one work sold, two written");
    assert_eq!(writing_works(&sold, 1), 1);
    assert!(sold.players[0].gold > 1_000.0, "the sale is paid");
    assert!(
        sold.cities[&capital].queue.is_empty(),
        "no building was reserved"
    );

    let mut targeted = game.clone();
    let mut hostile = great_person_housing_plan(&targeted, GrandStrategy::Conquest);
    hostile.target_player = Some(1);
    assert!(!ai.great_person_housing(&mut targeted, 0, &hostile));
    assert_eq!(writing_works(&targeted, 0), 2);
    assert_eq!(
        claimed(&targeted),
        0,
        "the campaign target is never sold a work"
    );
}

/// ★★★★ THE LAST RUNG. Every slot full, nothing with a slot buildable, and
/// the only other civilization at war (no market): a due Writer opens a
/// Theater Square in the city that has none. With a buyer the sale comes
/// first and no district is started.
#[test]
fn a_due_writer_with_no_buyer_opens_a_new_theater_square() {
    let (mut game, capital) = great_person_housing_fixture(71_308);
    game.cities
        .get_mut(&capital)
        .unwrap()
        .buildings
        .push(crate::name!("amphitheater"));
    game.players[0]
        .counters
        .insert("great_work:writing".to_string(), 2);
    let home = game.cities[&capital].pos;
    let second = found_nearby_test_city(&mut game, 0, home);
    game.cities.get_mut(&second).unwrap().pop = 4;
    let cost = game.gp_cost(0, "writer");
    game.players[0].gpp.insert("writer".to_string(), cost);
    game.at_war.insert((0, 1));
    game.at_war.insert((1, 0));
    assert!(game.quick_deals(0).is_empty(), "a war closes the market");
    let plan = great_person_housing_plan(&game, GrandStrategy::Science);
    let mut ai = AdvancedAi::new();
    ai.enable_great_person_housing();
    assert!(ai.great_person_housing(&mut game, 0, &plan));
    assert!(
        matches!(
            game.cities[&second].queue.first(),
            Some(Item::District { district, .. }) if game.district_family(*district) == "theater_square"
        ),
        "the city without a square starts one"
    );
    assert_eq!(writing_works(&game, 0), 2, "nothing to sell");
    assert!(
        !ai.great_person_housing(&mut game, 0, &plan),
        "one square at a time"
    );
}

/// A slot building outranks a sale: with the Amphitheater full but a second
/// city able to build one, the gene reserves that city and sells nothing.
#[test]
fn a_buildable_slot_outranks_a_sale() {
    let (mut game, capital) = great_person_housing_fixture(71_305);
    game.cities
        .get_mut(&capital)
        .unwrap()
        .buildings
        .push(crate::name!("amphitheater"));
    game.players[0]
        .counters
        .insert("great_work:writing".to_string(), 2);
    let home = game.cities[&capital].pos;
    let second = found_nearby_test_city(&mut game, 0, home);
    install_ai_test_district(&mut game, second, "theater_square");
    let rival = game.player_city_ids(1)[0];
    install_ai_test_district(&mut game, rival, "theater_square");
    game.cities
        .get_mut(&rival)
        .unwrap()
        .buildings
        .push(crate::name!("amphitheater"));
    let cost = game.gp_cost(0, "writer");
    game.players[0].gpp.insert("writer".to_string(), cost);
    let plan = great_person_housing_plan(&game, GrandStrategy::Science);
    let mut ai = AdvancedAi::new();
    ai.enable_great_person_housing();
    assert!(ai.great_person_housing(&mut game, 0, &plan));
    assert!(matches!(
        game.cities[&second].queue.first(),
        Some(Item::Building { building }) if *building == crate::name!("amphitheater")
    ));
    assert_eq!(writing_works(&game, 0), 2, "nothing sold");
}

/// The other classes: a due Scientist with no Campus reserves the Campus; a
/// Scientist still on the way does not start a district on speculation; the
/// Musician's chain walks museum before Broadcast Center.
#[test]
fn districts_are_reserved_only_for_a_due_person_and_the_music_chain_walks_its_prerequisites() {
    let (mut game, capital) = great_person_housing_fixture(71_306);
    // Room for a second district beside the Theater Square.
    game.cities.get_mut(&capital).unwrap().pop = 7;
    let mut ai = AdvancedAi::new();
    ai.enable_great_person_housing();
    let scientist = |due: bool| StuckGreatPerson {
        kind: "scientist".to_string(),
        remedy: GreatPersonRemedy::District("campus"),
        due,
        turns_to_due: if due { 0.0 } else { 8.0 },
    };
    assert!(
        ai.great_person_housing_item(&game, 0, capital, &scientist(false))
            .is_none(),
        "a district is a bet for points still eight turns out"
    );
    assert!(
        matches!(
            ai.great_person_housing_item(&game, 0, capital, &scientist(true)),
            Some(Item::District { district, .. }) if game.district_family(district) == "campus"
        ),
        "a due Scientist reserves the Campus"
    );

    let musician = StuckGreatPerson {
        kind: "musician".to_string(),
        remedy: GreatPersonRemedy::Slots("music", 2),
        due: false,
        turns_to_due: 5.0,
    };
    assert!(
        ai.great_person_housing_item(&game, 0, capital, &musician)
            .is_none(),
        "without Radio no museum brings a Broadcast Center nearer"
    );
    game.players[0].techs.insert(crate::name!("radio"));
    assert!(
        matches!(
            ai.great_person_housing_item(&game, 0, capital, &musician),
            Some(Item::Building { building }) if building == crate::name!("amphitheater")
        ),
        "Radio known and no museum yet: the chain starts at the Amphitheater"
    );
}

/// The gene is an opt-in: off in every bundle, flippable by name, in
/// `PRODUCTION_OPT_INS`.
#[test]
fn great_person_housing_is_a_native_opt_in() {
    let mut ai = AdvancedAi::new();
    ai.enable_live_bridge_universe();
    assert!(!ai.great_person_housing);
    let enable = GENES
        .iter()
        .find(|gene| gene.tag == "great-person-housing")
        .expect("an opt-in row")
        .enable;
    enable(&mut ai);
    assert!(ai.great_person_housing);
    ai.disable_great_person_housing();
    assert!(!ai.great_person_housing);
}

/// ★★★★ FIVE OF THIRTY-SIX SEATS ENDED THE PROBE GAMES WITH ENGINEER POINTS
/// AT FOURTEEN TIMES THE PRICE. Every second Engineer (Imhotep, Eiffel,
/// Tesla, Roebling, von Braun) spends charges on a wonder under construction
/// — 2 × 175 production doubled for an ancient wonder, up to 1,400 — and is
/// refused until one is queued; off the Culture lane the chooser never
/// queues one, so the points pile up for the rest of the game (198 blocked
/// seat-turns in six games, the most of any class). With the gene a due
/// wonder Engineer starts the cheapest available wonder, which the charges
/// then all but complete. An Engineer still ten turns out starts nothing.
#[test]
fn a_due_wonder_engineer_starts_the_cheapest_wonder_for_its_charges() {
    let (mut game, capital) = great_person_housing_fixture(71_307);
    game.players[0].techs.insert(crate::name!("irrigation"));
    game.cities.get_mut(&capital).unwrap().pop = 7;
    // A river edge on a flat owned tile: the Hanging Gardens become legal.
    let center = game.cities[&capital].pos;
    let bank = game.cities[&capital]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| {
            *position != center
                && game.map.tiles[position].district.is_none()
                && game.map.tiles[position].improvement.is_none()
                && game.rules.is_passable(&game.map.tiles[position])
                && game.map.tiles[position].feature.is_none()
                && game.map.tiles[position].terrain != crate::name!("coast")
                && game.map.tiles[position].terrain != crate::name!("ocean")
        })
        .expect("a flat owned tile");
    game.map.tiles.get_mut(&bank).unwrap().river_edges[0] = true;
    let (_, imhotep) = game.current_great_person("engineer").unwrap();
    assert!(
        imhotep.effects.contains_key("wonder_production"),
        "the first Engineer offered is the wonder builder"
    );
    let cheapest = BasicAi::cheapest_available_wonder(&game, 0, capital)
        .expect("the capital can start some ancient wonder");
    let cost = game.gp_cost(0, "engineer");
    let plan = great_person_housing_plan(&game, GrandStrategy::Science);
    let mut ai = AdvancedAi::new();
    ai.enable_great_person_housing();

    let mut due = game.clone();
    due.players[0].gpp.insert("engineer".to_string(), cost);
    assert!(!due.can_activate_current_great_person(0, "engineer"));
    assert_eq!(
        ai.stuck_great_people(&due, 0),
        vec![StuckGreatPerson {
            kind: "engineer".to_string(),
            remedy: GreatPersonRemedy::Wonder,
            due: true,
            turns_to_due: 0.0,
        }]
    );
    assert!(ai.great_person_housing(&mut due, 0, &plan));
    assert_eq!(due.cities[&capital].queue.first(), Some(&cheapest));
    assert!(
        due.can_activate_current_great_person(0, "engineer"),
        "the queued wonder lifts the block; the turn's end claims the Engineer"
    );

    let mut soon = game.clone();
    soon.players[0]
        .gpp
        .insert("engineer".to_string(), cost - 1.0);
    // A Theater Square earns no Engineer points: the class is not on its way.
    assert!(ai.stuck_great_people(&soon, 0).is_empty());
    install_ai_test_district(&mut soon, capital, "industrial_zone");
    let rate = soon.great_person_points_per_turn(0)["engineer"];
    assert!(rate > 0.0);
    soon.players[0]
        .gpp
        .insert("engineer".to_string(), cost - rate * 10.0);
    let stuck = ai.stuck_great_people(&soon, 0);
    assert_eq!(stuck.len(), 1, "ten turns out is inside the lead");
    assert!(!stuck[0].due);
    assert!(!ai.great_person_housing(&mut soon, 0, &plan));
    assert!(
        soon.cities[&capital].queue.is_empty(),
        "a wonder is not started on speculation"
    );
}

/// An Admiral who leads a formation waits on a military sea unit (75 blocked
/// seat-turns in the probe), not on a Harbor: the remedy is read from the
/// person's effects, and a coastal city builds the ship.
#[test]
fn a_due_formation_admiral_is_answered_with_a_ship_not_a_harbor() {
    let effects: std::collections::BTreeMap<String, f64> =
        [("naval_unit_formation".to_string(), 1.0)]
            .into_iter()
            .collect();
    assert_eq!(
        AdvancedAi::great_person_remedy("admiral", &effects),
        Some(GreatPersonRemedy::SeaUnit)
    );
    let trade: std::collections::BTreeMap<String, f64> =
        [("free_lighthouse".to_string(), 1.0)].into_iter().collect();
    assert_eq!(
        AdvancedAi::great_person_remedy("admiral", &trade),
        Some(GreatPersonRemedy::District("harbor"))
    );
    let promotion: std::collections::BTreeMap<String, f64> =
        [("land_unit_promotion_level".to_string(), 1.0)]
            .into_iter()
            .collect();
    assert_eq!(
        AdvancedAi::great_person_remedy("general", &promotion),
        Some(GreatPersonRemedy::LandUnit)
    );
    let imhotep: std::collections::BTreeMap<String, f64> =
        [("wonder_production".to_string(), 175.0)]
            .into_iter()
            .collect();
    assert_eq!(
        AdvancedAi::great_person_remedy("engineer", &imhotep),
        Some(GreatPersonRemedy::Wonder)
    );
    let leonardo: std::collections::BTreeMap<String, f64> =
        [("modern_tech_boosts".to_string(), 1.0)]
            .into_iter()
            .collect();
    assert_eq!(
        AdvancedAi::great_person_remedy("engineer", &leonardo),
        Some(GreatPersonRemedy::District("industrial_zone"))
    );
}

/// Census, not an assertion: how long does a Settler walk before it founds?
///
/// `settle_siting_census` shows the chosen site is almost always the best
/// one on offer under the agent's own objective, `settle_value - 0.9/tile`.
/// That objective prices the WALK in tiles, not in turns, and a city founded
/// ten turns later is ten turns of yields the empire never sees. Nothing
/// measured the walk itself: turns from the Settler standing in its home
/// city to the city standing, how far it went, how often it changed its
/// mind, and what the extra walk bought against the nearest site it could
/// have taken. This does.
///
/// The seats play the deployment genome (`enable_engine_repairs`, which
/// ends in the gene ledger), on the gene screen's 6-player 60×38 Online
/// profile, so the turns reported are the turns the screen plays.
/// `CIVVIS_CENSUS_OPT_INS=tag,tag` switches the named `PRODUCTION_OPT_INS`
/// genes on for every major seat, so a settling gene can be read against
/// the same maps; `CIVVIS_CENSUS_MAPS` sets the map count (default 8).
///
/// First reading (2026-08-21, deployment genome): 249 foundings and 60
/// Settlers lost over 8 maps; mean 7.3 turns from build to founding,
/// median 5, p90 16, max 93; 18% walked more than ten turns; Settlers
/// walked 1.57× their straight-line distance and one in five changed
/// target at least once. That is what `settle_sooner` exists to move.
///
/// Run with `cargo test --release settler_walk_census -- --ignored --nocapture`.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn settler_walk_census() {
    struct Walk {
        owner: usize,
        born: u32,
        origin: Pos,
        last: Pos,
        tiles: i32,
        targets: BTreeSet<Pos>,
        /// Raw `settle_value` of the best LEGAL site (four tiles from every
        /// city) within six tiles of the origin, read the turn the Settler
        /// appeared — the near site it could have taken instead.
        near_value: f64,
        near_site: Option<Pos>,
    }
    let opt_ins: Vec<String> = std::env::var("CIVVIS_CENSUS_OPT_INS")
        .ok()
        .map(|text| {
            text.split(',')
                .filter(|t| !t.is_empty())
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default();
    let maps = std::env::var("CIVVIS_CENSUS_MAPS")
        .ok()
        .and_then(|text| text.parse::<u64>().ok())
        .unwrap_or(8);
    let mut walks: BTreeMap<(u64, u32), Walk> = BTreeMap::new();
    // (turns, straight-line tiles, tiles walked, targets, chosen value,
    //  near value, born turn)
    let mut founded: Vec<(u32, i32, i32, usize, f64, f64, u32)> = Vec::new();
    let mut lost: Vec<(u32, i32)> = Vec::new();
    for map in 0..maps {
        let seed = 97_000_000 + map;
        let mut game = Game::new_with(GameOptions {
            speed: "online".to_string(),
            randomize_civs: true,
            ..GameOptions::new(6, 60, 38, seed, 250, 6)
        });
        game.set_fog_memory(false);
        game.set_war_ledger(false);
        let mut ais: Vec<AdvancedAi> = (0..game.players.len())
            .map(|pid| {
                let mut ai = AdvancedAi::new();
                if !game.players[pid].is_minor && !game.players[pid].is_barbarian {
                    ai.enable_engine_repairs();
                    for tag in &opt_ins {
                        let enable = GENES
                            .iter()
                            .find(|gene| gene.tag == *tag && gene.opt_in())
                            .unwrap_or_else(|| panic!("{tag} is not an opt-in gene"))
                            .enable;
                        enable(&mut ai);
                    }
                }
                ai
            })
            .collect();
        let mut known_cities: BTreeSet<u32> = game.cities.keys().copied().collect();
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            let major = !game.players[pid].is_minor && !game.players[pid].is_barbarian;
            let mut pre: BTreeMap<u32, f64> = BTreeMap::new();
            if major {
                for uid in game.player_unit_ids(pid) {
                    let unit = &game.units[&uid];
                    if unit.kind != "settler" {
                        continue;
                    }
                    pre.insert(uid, ais[pid].settle_value(&game, pid, unit.pos));
                    if walks.contains_key(&(seed, uid)) {
                        continue;
                    }
                    let origin = unit.pos;
                    let mut near_value = f64::NEG_INFINITY;
                    let mut near_site = None;
                    for pos in game.wdisk(origin, 6) {
                        let Some(tile) = game.map.get(pos) else {
                            continue;
                        };
                        if game.rules.is_water(tile)
                            || !game.rules.is_passable(tile)
                            || game.tile_is_natural_wonder(tile)
                            || game
                                .cities
                                .values()
                                .any(|city| game.wdist(city.pos, pos) < 4)
                            || tile
                                .owner_city
                                .is_some_and(|cid| game.cities[&cid].owner != pid)
                        {
                            continue;
                        }
                        let value = ais[pid].settle_value(&game, pid, pos);
                        if value > near_value {
                            near_value = value;
                            near_site = Some(pos);
                        }
                    }
                    walks.insert(
                        (seed, uid),
                        Walk {
                            owner: pid,
                            born: game.turn,
                            origin,
                            last: origin,
                            tiles: 0,
                            targets: BTreeSet::new(),
                            near_value,
                            near_site,
                        },
                    );
                }
            }
            ais[pid].take_turn(&mut game, pid);
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
            if !major {
                continue;
            }
            let new_cities: Vec<(u32, Pos)> = game
                .cities
                .iter()
                .filter(|(cid, city)| {
                    city.owner == pid && city.captured_from.is_none() && !known_cities.contains(cid)
                })
                .map(|(cid, city)| (*cid, city.pos))
                .collect();
            for (cid, _) in &new_cities {
                known_cities.insert(*cid);
            }
            let tracked: Vec<(u64, u32)> =
                walks.keys().filter(|(s, _)| *s == seed).copied().collect();
            for key in tracked {
                let uid = key.1;
                let Some(walk) = walks.get_mut(&key) else {
                    continue;
                };
                if walk.owner != pid {
                    continue;
                }
                match game.units.get(&uid) {
                    Some(unit) if unit.owner == pid => {
                        walk.tiles += game.wdist(walk.last, unit.pos);
                        walk.last = unit.pos;
                        if let Some(target) = ais[pid].settler_targets.get(&uid) {
                            walk.targets.insert(*target);
                        }
                    }
                    _ => {
                        let walk = walks.remove(&key).expect("just read");
                        let turns = game.turn.saturating_sub(walk.born);
                        let city = new_cities
                            .iter()
                            .find(|(_, pos)| game.wdist(*pos, walk.last) <= 1)
                            .map(|(_, pos)| *pos);
                        match city {
                            Some(pos) => {
                                let chosen = pre.get(&uid).copied().unwrap_or(f64::NAN);
                                founded.push((
                                    turns,
                                    game.wdist(walk.origin, pos),
                                    walk.tiles,
                                    walk.targets.len(),
                                    chosen,
                                    if walk.near_site.is_some() {
                                        walk.near_value
                                    } else {
                                        f64::NAN
                                    },
                                    walk.born,
                                ));
                            }
                            None => lost.push((turns, walk.tiles)),
                        }
                    }
                }
            }
        }
        // Settlers still walking when the game ended never founded.
        let stranded: Vec<(u64, u32)> = walks.keys().filter(|(s, _)| *s == seed).copied().collect();
        for key in stranded {
            let walk = walks.remove(&key).expect("just read");
            lost.push((game.turn.saturating_sub(walk.born), walk.tiles));
        }
    }

    let percentile = |sorted: &[u32], p: f64| -> u32 {
        if sorted.is_empty() {
            return 0;
        }
        sorted[((sorted.len() - 1) as f64 * p).round() as usize]
    };
    let mut turns: Vec<u32> = founded.iter().map(|row| row.0).collect();
    turns.sort_unstable();
    let mean =
        |values: &[u32]| values.iter().map(|&v| v as f64).sum::<f64>() / values.len().max(1) as f64;
    println!(
        "\n=== settler walk census: {} settlers founded, {} lost, over {maps} maps (6p 60x38 online, deployment genome{}) ===",
        founded.len(),
        lost.len(),
        if opt_ins.is_empty() { String::new() } else { format!(" + {}", opt_ins.join(",")) }
    );
    println!(
        "  turns from build to founding: mean {:.1}   p10 {}   median {}   p90 {}   max {}",
        mean(&turns),
        percentile(&turns, 0.1),
        percentile(&turns, 0.5),
        percentile(&turns, 0.9),
        turns.last().copied().unwrap_or(0)
    );
    for bound in [3u32, 6, 10, 15, 20] {
        let over = turns.iter().filter(|&&t| t > bound).count();
        println!(
            "    walked more than {bound:>2} turns: {over:>4} ({:.1}%)",
            over as f64 / turns.len().max(1) as f64 * 100.0
        );
    }
    let straight: Vec<u32> = founded.iter().map(|row| row.1.max(0) as u32).collect();
    let walked: Vec<u32> = founded.iter().map(|row| row.2.max(0) as u32).collect();
    let mut straight_sorted = straight.clone();
    straight_sorted.sort_unstable();
    println!(
        "  tiles from the home city, straight line: mean {:.1}   median {}   p90 {}",
        mean(&straight),
        percentile(&straight_sorted, 0.5),
        percentile(&straight_sorted, 0.9)
    );
    println!(
        "  tiles actually walked: mean {:.1}   (walked/straight {:.2})",
        mean(&walked),
        mean(&walked) / mean(&straight).max(1e-9)
    );
    let retargeted = founded.iter().filter(|row| row.3 > 1).count();
    let many = founded.iter().filter(|row| row.3 > 2).count();
    println!(
        "  settlers that changed target at least once: {retargeted} ({:.1}%); twice or more: {many} ({:.1}%)",
        retargeted as f64 / founded.len().max(1) as f64 * 100.0,
        many as f64 / founded.len().max(1) as f64 * 100.0
    );
    // What did the walk buy? For every expansion Settler (the opening
    // Settlers found where they stand or a step away), compare the chosen
    // site's raw value with the best legal site within six tiles of where
    // it was built, read on the day it was built.
    let mut bought: Vec<(u32, f64, f64)> = founded
        .iter()
        .filter(|row| row.6 > 1 && row.4.is_finite() && row.5.is_finite())
        .map(|row| (row.0, row.4 - row.5, row.4))
        .collect();
    bought.sort_by_key(|a| a.0);
    if !bought.is_empty() {
        let mean_value = bought.iter().map(|row| row.2).sum::<f64>() / bought.len() as f64;
        println!(
            "  expansion foundings with a legal site within six tiles of home at birth: {} (mean chosen raw value {mean_value:.1})",
            bought.len()
        );
        for (lo, hi) in [(0u32, 3u32), (4, 6), (7, 10), (11, 15), (16, 1000)] {
            let rows: Vec<f64> = bought
                .iter()
                .filter(|(t, _, _)| *t >= lo && *t <= hi)
                .map(|(_, delta, _)| *delta)
                .collect();
            if rows.is_empty() {
                continue;
            }
            let m = rows.iter().sum::<f64>() / rows.len() as f64;
            let worse = rows.iter().filter(|d| **d < 0.0).count();
            println!(
                "    walks of {lo:>2}-{hi:<4} turns: {:>4} foundings, chosen minus best-legal-within-6-of-home = {m:+.1} raw value ({worse} founded a WORSE site than one within six tiles of home)",
                rows.len()
            );
        }
    }
    let mut by_era = [(0u32, 0.0f64); 4];
    for row in &founded {
        let slot = match row.6 {
            0..=49 => 0,
            50..=99 => 1,
            100..=149 => 2,
            _ => 3,
        };
        by_era[slot].0 += 1;
        by_era[slot].1 += row.0 as f64;
    }
    for (slot, label) in ["t0-49", "t50-99", "t100-149", "t150+"].iter().enumerate() {
        if by_era[slot].0 > 0 {
            println!(
                "    settlers built {label:>8}: {:>4}, mean walk {:.1} turns",
                by_era[slot].0,
                by_era[slot].1 / by_era[slot].0 as f64
            );
        }
    }
    if !lost.is_empty() {
        let mut lost_turns: Vec<u32> = lost.iter().map(|row| row.0).collect();
        lost_turns.sort_unstable();
        println!(
            "  lost without founding: {} — they had walked a median {} turns (p90 {})",
            lost.len(),
            percentile(&lost_turns, 0.5),
            percentile(&lost_turns, 0.9)
        );
    }
    println!();
}

// ---------------------------------------------------------------- opportunistic war

/// Two majors at peace with their capitals founded, a second city for us,
/// every unit removed, and the ground between flattened so that reach is
/// `wdist`. Returns the game, our capital's position and theirs.
fn raid_fixture() -> (Game, Pos, Pos) {
    let mut game = Game::new_full(2, 28, 18, 8_131, 250, 0, false);
    let mut capitals = Vec::new();
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("each fixture major starts with a settler");
        let position = game.units[&settler].pos;
        capitals.push(game.found_city_for(pid, position, None));
        game.remove_unit(settler);
    }
    for pid in 0..2 {
        for unit in game.player_unit_ids(pid) {
            game.remove_unit(unit);
        }
    }
    let ours = game.cities[&capitals[0]].pos;
    let theirs = game.cities[&capitals[1]].pos;
    found_nearby_test_city(&mut game, 0, ours);
    for position in game.map.tiles.keys().copied().collect::<Vec<_>>() {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        if game.rules.is_water(tile) {
            continue;
        }
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
        tile.wonder = None;
        game.players[0].explored.insert(position);
    }
    game.record_contact(0, 1);
    game.players[0].met.insert(1);
    game.players[1].met.insert(0);
    game.turn = 30;
    game.current = 0;
    (game, ours, theirs)
}

/// An open land tile at exactly `distance` from `anchor`, and no further than
/// `home_limit` from `home`.
fn raid_tile_at(game: &Game, anchor: Pos, distance: i32, home: Pos, home_limit: i32) -> Pos {
    game.map
        .tiles
        .keys()
        .copied()
        .filter(|position| {
            g_is_open_land(game, *position)
                && game.unit_ids_at(*position).is_empty()
                && game.wdist(anchor, *position) == distance
                && game.wdist(home, *position) <= home_limit
        })
        .min()
        .expect("fixture has an open tile at that distance")
}

/// Our warrior three tiles out from the capital, their Settler two tiles
/// beyond it — inside the warrior's two-turn reach and its sight.
fn raid_settler_board() -> (Game, u32, u32) {
    let (mut game, ours, _) = raid_fixture();
    let warrior_at = raid_tile_at(&game, ours, 3, ours, 3);
    let warrior = game.spawn_test_unit("warrior", 0, warrior_at);
    let settler_at = raid_tile_at(&game, warrior_at, 2, ours, RAID_SETTLER_HOME_RADIUS);
    let settler = game.spawn_test_unit("settler", 1, settler_at);
    assert!(
        game.player_can_see(0, settler_at),
        "the fixture Settler must stand in the warrior's sight"
    );
    (game, warrior, settler)
}

/// The gene is an opt-in: off in every bundle, flippable by name, in
/// `PRODUCTION_OPT_INS`, and switching it off forgets any open raid.
#[test]
fn opportunistic_war_is_a_native_opt_in() {
    let mut ai = AdvancedAi::new();
    ai.enable_live_bridge_universe();
    assert!(!ai.opportunistic_war);
    let enable = GENES
        .iter()
        .find(|gene| gene.tag == "opportunistic-war")
        .expect("an opt-in row")
        .enable;
    enable(&mut ai);
    assert!(ai.opportunistic_war);
    ai.raid_war = Some(opportunistic_war::RaidWar {
        target: 1,
        declared: 30,
        value: SETTLER_PRIZE,
        settlers: 1,
        builders: 0,
        pillage_tiles: 0,
    });
    ai.disable_opportunistic_war();
    assert!(!ai.opportunistic_war);
    assert!(ai.raid_war.is_none());
    assert!(!ai.raid_pillage_prizes);
    let enable = GENES
        .iter()
        .find(|gene| gene.tag == "raid-pillage-prizes")
        .expect("the pillage half has its own row")
        .enable;
    enable(&mut ai);
    assert!(ai.raid_pillage_prizes);
    ai.disable_raid_pillage_prizes();
    assert!(!ai.raid_pillage_prizes);
}

/// An unescorted enemy Settler two tiles from our warrior is a prize worth a
/// war: the gene declares by surprise, the warrior walks onto the Settler the
/// same turn, and the Settler is ours.
#[test]
fn an_unescorted_settler_in_reach_opens_a_surprise_war_and_is_taken_that_turn() {
    let (mut game, warrior, settler) = raid_settler_board();
    let mut ai = AdvancedAi::new();
    ai.enable_opportunistic_war();
    let opportunity = ai
        .raid_opportunity(&game, 0)
        .expect("an unescorted Settler in reach is an opportunity");
    assert_eq!(opportunity.target, 1);
    assert!(opportunity.value >= RAID_WAR_MIN_VALUE);
    assert!(matches!(
        opportunity.prizes.as_slice(),
        [opportunistic_war::RaidPrize::Settler { .. }]
    ));
    // Without the gene the same board is not an opportunity at all.
    let mut stock = AdvancedAi::new();
    stock.disable_opportunistic_war();
    assert!(stock.raid_opportunity(&game, 0).is_none());

    assert!(!game.is_at_war(0, 1));
    ai.take_turn(&mut game, 0);
    assert!(game.is_at_war(0, 1), "the raid declares war");
    let raid = ai.raid_war.clone().expect("the raid is recorded");
    assert_eq!((raid.target, raid.declared, raid.settlers), (1, 30, 1));
    assert_eq!(game.players[0].counters.get("raid_wars"), Some(&1));
    assert_eq!(
        game.units[&settler].owner, 0,
        "the warrior walked onto the Settler this turn"
    );
    assert_eq!(game.units[&warrior].pos, game.units[&settler].pos);
    assert_eq!(game.players[0].counters.get("captured:settler"), Some(&1));
}

/// A Settler under an enemy soldier is an attack problem, not a capture, and
/// is not priced as a prize.
#[test]
fn a_guarded_settler_is_no_raid_prize() {
    let (mut game, _, settler) = raid_settler_board();
    let settler_at = game.units[&settler].pos;
    let guard = game.spawn_test_unit("warrior", 1, settler_at);
    let mut ai = AdvancedAi::new();
    ai.enable_opportunistic_war();
    assert!(ai.raid_opportunity(&game, 0).is_none());
    // An escort standing beside the Settler is a guard too.
    let beside = game
        .nbrs(settler_at)
        .into_iter()
        .find(|position| g_is_open_land(&game, *position) && game.unit_ids_at(*position).is_empty())
        .unwrap();
    game.relocate(guard, beside);
    assert!(ai.raid_opportunity(&game, 0).is_none());
    game.remove_unit(guard);
    assert!(ai.raid_opportunity(&game, 0).is_some());
}

/// The prize is taken by movement, but the answer to the declaration is an
/// army: a neighbour past `RAID_POWER_RATIO` of our strength is not raided.
#[test]
fn a_stronger_neighbour_is_not_raided_for_a_settler() {
    let (mut game, _, _) = raid_settler_board();
    let (_, _, theirs) = raid_fixture();
    let mut ai = AdvancedAi::new();
    ai.enable_opportunistic_war();
    assert!(ai.raid_opportunity(&game, 0).is_some());
    for _ in 0..3 {
        let post = raid_tile_at(&game, theirs, 1, theirs, 1);
        game.spawn_test_unit("swordsman", 1, post);
    }
    assert!(game.military_power(1) > game.military_power(0) * RAID_POWER_RATIO + RAID_POWER_MARGIN);
    assert!(ai.raid_opportunity(&game, 0).is_none());
}

/// A Settler we could not use — one of our own already walking, or no site
/// left to found — is not a prize; the capture guard would refuse the tile.
#[test]
fn a_settler_we_could_not_use_is_no_raid_prize() {
    let (mut game, _, _) = raid_settler_board();
    let mut ai = AdvancedAi::new();
    ai.enable_opportunistic_war();
    assert!(ai.raid_opportunity(&game, 0).is_some());
    let capital = game.player_city_ids(0)[0];
    let home = game.cities[&capital].pos;
    game.spawn_test_unit("settler", 0, home);
    assert!(ai.raid_opportunity(&game, 0).is_none());
}

/// While the raid is the only major war, the grand strategy keeps its
/// economic plan: no "already at war" Conquest, and no power-gap Recovery.
#[test]
fn a_raid_is_not_a_reason_to_plan_a_conquest() {
    let (mut game, _, _) = raid_settler_board();
    let mut ai = AdvancedAi::new();
    ai.enable_opportunistic_war();
    ai.take_turn(&mut game, 0);
    assert!(game.is_at_war(0, 1));
    assert!(ai.raid_only_war(&game, 0));
    game.turn += 1;
    let plan = ai.assess(&game, 0);
    assert_ne!(
        plan.strategy,
        GrandStrategy::Conquest,
        "a raid-only war does not pin the plan on Conquest"
    );
    assert_ne!(plan.strategy, GrandStrategy::Recovery);
    // The same war without the gene's bookkeeping reads "already at war".
    let stock = AdvancedAi::new();
    let stock_plan = stock.assess(&game, 0);
    assert_eq!(stock_plan.strategy, GrandStrategy::Conquest);
}

/// Once the engine's minimum war length has passed and nothing is left in
/// reach, the raid proposes peace; before that it does not.
#[test]
fn a_raid_sues_for_peace_once_it_has_paid() {
    let (mut game, _, _) = raid_settler_board();
    let mut ai = AdvancedAi::new();
    ai.enable_opportunistic_war();
    ai.take_turn(&mut game, 0);
    let raid = ai.raid_war.clone().expect("raid opened");
    let plan = ai.assess(&game, 0);
    let peace_offered = |game: &Game| {
        game.pending_deals
            .iter()
            .any(|deal| deal.peace && deal.from == 0 && deal.to == 1)
    };
    // `take_turn` hands the turn on; the diplomacy pass acts as seat 0.
    game.current = 0;
    game.turn = raid.declared + game.standard_duration(RAID_PEACE_EARLIEST) - 1;
    ai.peace_offers.clear();
    assert!(!ai.opportunistic_war_diplomacy(&mut game, 0, &plan));
    assert!(
        !peace_offered(&game),
        "no peace before the war can legally end"
    );
    game.turn = raid.declared + game.standard_duration(RAID_PEACE_EARLIEST);
    ai.peace_offers.clear();
    assert!(!ai.opportunistic_war_diplomacy(&mut game, 0, &plan));
    assert!(
        peace_offered(&game),
        "the prize is taken and nothing is left in reach"
    );
    assert!(ai.peace_offers.contains(&1));
    // The rival accepting the offer closes the raid's bookkeeping and
    // stands the empire down from fresh wars for a while.
    game.at_war.clear();
    ai.opportunistic_war_diplomacy(&mut game, 0, &plan);
    assert!(ai.raid_war.is_none());
    assert_eq!(
        ai.peace_until,
        game.turn + game.standard_duration(RAID_REPEAT_COOLDOWN)
    );
    assert!(ai.raid_opportunity(&game, 0).is_none());
}

/// Unpillaged improvements beside our soldiers are a prize too — enough of
/// them in a later era clear the bar with no civilian in sight — and a
/// soldier standing on one pillages it once the war is open.
#[test]
fn a_cluster_of_improvements_in_reach_is_a_pillage_raid() {
    let (mut game, ours, theirs) = raid_fixture();
    let their_city = game.player_city_ids(1)[0];
    let ring: Vec<Pos> = game.cities[&their_city]
        .owned_tiles
        .iter()
        .copied()
        .filter(|position| *position != theirs && g_is_open_land(&game, *position))
        .collect();
    assert!(
        ring.len() >= 6,
        "the fixture capital owns at least six open tiles"
    );
    for position in ring.iter().take(6) {
        let tile = game.map.tiles.get_mut(position).unwrap();
        tile.improvement = Some(crate::name!("mine"));
        tile.pillaged = false;
    }
    let post = raid_tile_at(&game, theirs, 2, theirs, 2);
    let warrior = game.spawn_test_unit("warrior", 0, post);
    let _ = ours;
    let mut ai = AdvancedAi::new();
    ai.enable_opportunistic_war();
    game.world_era = 2;
    assert!(
        ai.raid_opportunity(&game, 0).is_none(),
        "without `raid-pillage-prizes` tiles are not prizes"
    );
    ai.enable_raid_pillage_prizes();
    game.world_era = 0;
    assert!(
        ai.raid_opportunity(&game, 0).is_none(),
        "six ancient mines at {} each do not clear {}",
        PILLAGE_PRIZE_BASE,
        RAID_WAR_MIN_VALUE
    );
    game.world_era = 2;
    let opportunity = ai
        .raid_opportunity(&game, 0)
        .expect("six medieval mines in reach are a raid");
    assert!(opportunity
        .prizes
        .iter()
        .all(|prize| matches!(prize, opportunistic_war::RaidPrize::Pillage { .. })));
    assert_eq!(opportunity.prizes.len(), 6);
    let plan = ai.assess(&game, 0);
    assert!(ai.opportunistic_war_diplomacy(&mut game, 0, &plan));
    assert!(game.is_at_war(0, 1));
    // Walk the warrior onto a mine and let the raid step pillage it.
    let mine = *ring
        .iter()
        .take(6)
        .find(|position| game.unit_ids_at(**position).is_empty())
        .unwrap();
    game.relocate(warrior, mine);
    game.units.get_mut(&warrior).unwrap().moves_left = 2.0;
    assert!(game.pillageable_at(0, mine));
    let acted = ai
        .raid_prize_step(&mut game, 0, warrior, &plan, false)
        .expect("a soldier on a raid prize acts");
    assert!(acted);
    assert!(game.map.get(mine).unwrap().pillaged);
    assert_eq!(game.players[0].counters.get("pillages"), Some(&1));
}

/// The only soldier in one of our cities reaches a Settler, not a tile of
/// pillage: the answer to a raid is a counter-raid, and an empty city is its
/// prize.
#[test]
fn a_lone_garrison_counts_for_a_settler_but_not_for_pillage() {
    let (mut game, ours, theirs) = raid_fixture();
    let their_city = game.player_city_ids(1)[0];
    let ring: Vec<Pos> = game.cities[&their_city]
        .owned_tiles
        .iter()
        .copied()
        .filter(|position| *position != theirs && g_is_open_land(&game, *position))
        .collect();
    for position in ring.iter().take(6) {
        game.map.tiles.get_mut(position).unwrap().improvement = Some(crate::name!("mine"));
    }
    game.world_era = 2;
    let post = raid_tile_at(&game, theirs, 2, theirs, 2);
    let warrior = game.spawn_test_unit("warrior", 0, post);
    let settler_at = raid_tile_at(&game, post, 2, ours, RAID_SETTLER_HOME_RADIUS);
    game.spawn_test_unit("settler", 1, settler_at);
    let mut ai = AdvancedAi::new();
    ai.enable_opportunistic_war();
    ai.enable_raid_pillage_prizes();
    let striker = |lone_garrison: bool| opportunistic_war::RaidStriker {
        uid: warrior,
        pos: post,
        reach: 4,
        lone_garrison,
    };
    let roaming = ai.raid_prizes_against(&game, 0, 1, &[striker(false)]);
    assert_eq!(
        roaming
            .iter()
            .filter(|prize| matches!(prize, opportunistic_war::RaidPrize::Pillage { .. }))
            .count(),
        6
    );
    assert_eq!(
        roaming
            .iter()
            .filter(|prize| matches!(prize, opportunistic_war::RaidPrize::Settler { .. }))
            .count(),
        1
    );
    let garrisoned = ai.raid_prizes_against(&game, 0, 1, &[striker(true)]);
    assert!(
        garrisoned
            .iter()
            .all(|prize| matches!(prize, opportunistic_war::RaidPrize::Settler { .. })),
        "a lone garrison reaches the Settler and none of the tiles: {garrisoned:?}"
    );
    assert_eq!(garrisoned.len(), 1);
    // And the flag is read off the board: alone in one of our cities.
    let capital = game.player_city_ids(0)[0];
    let home = game.cities[&capital].pos;
    game.relocate(warrior, home);
    assert!(AdvancedAi::lone_garrison(&game, 0, warrior));
    game.spawn_test_unit("warrior", 0, home);
    assert!(!AdvancedAi::lone_garrison(&game, 0, warrior));
}

// ---------------------------------------------------------------------------
// The air surge. See `advanced/air_surge.rs`.
// ---------------------------------------------------------------------------

/// Every ancestor of Advanced Flight except the two that make the beeline a
/// beeline. Read from the ruleset rather than listed, so a tech-tree edit
/// moves the fixture with it instead of silently leaving it three techs out
/// of a chain that is now four long.
fn air_surge_prerequisites(game: &Game) -> Vec<Name> {
    game.rules
        .tech_ancestors
        .get(air_surge::AIR_SURGE_GOAL_TECH)
        .expect("the ruleset must reach Advanced Flight")
        .iter()
        .filter(|tech| tech.as_str() != "flight" && tech.as_str() != "radio")
        .map(|tech| Name::new(tech))
        .collect()
}

/// A two-city empire exactly three technologies short of the Bomber: the
/// chain still to walk is `flight -> radio -> advanced_flight`.
///
/// The returned objective is a rival city founded 4-10 tiles from our capital,
/// so the wing's reach is a property of the fixture rather than of the seed's
/// map: `timed_war_fixture` puts the two capitals wherever the generator does,
/// which on some seeds is past a Bomber's range 10 and appoints no surge at
/// all.
fn air_surge_fixture(seed: u64) -> (Game, u32, u32) {
    let (mut game, second, _) = timed_war_fixture(seed);
    for tech in air_surge_prerequisites(&game) {
        game.players[0].techs.insert(tech);
    }
    let capital = game.cities[&game.player_city_ids(0)[0]].pos;
    let objective = found_nearby_test_city(&mut game, 1, capital);
    // Grow the empire out of the founding turn. `air_surge_affordable` divides
    // the chain by the science the cities actually make, and two pop-1 cities
    // make 2.95 a turn — which prices `flight -> radio -> advanced_flight` at
    // 1,390 turns and refuses every appointment. An empire holding twenty-two
    // of Advanced Flight's twenty-four ancestors is not a pair of new
    // foundings, and the fixture should not pretend it is.
    for cid in game.player_city_ids(0) {
        game.cities.get_mut(&cid).expect("own city").pop = 12;
    }
    (game, second, objective)
}

fn air_surge_ai() -> AdvancedAi {
    let mut ai = AdvancedAi::new();
    ai.enable_air_surge();
    ai
}

/// Grant the breakthrough and two improved Aluminum sources. Gathering Storm
/// produces two Aluminum per improved source, so this is the live-run shape
/// the user reported: +4 a turn, enough to sustain a four-Bomber ceiling.
fn air_surge_arm(game: &mut Game) {
    game.players[0]
        .techs
        .insert(Name::new(air_surge::AIR_SURGE_GOAL_TECH));
    game.players[0].techs.insert(crate::name!("flight"));
    game.players[0].techs.insert(crate::name!("radio"));
    game.players[0]
        .strategic_resources
        .insert(crate::name!("aluminum"), 400.0);
    let mut sources = Vec::new();
    for city in game.player_city_ids(0) {
        let city = &game.cities[&city];
        for position in &city.owned_tiles {
            if *position != city.pos {
                sources.push(*position);
                if sources.len() == 2 {
                    break;
                }
            }
        }
        if sources.len() == 2 {
            break;
        }
    }
    assert_eq!(
        sources.len(),
        2,
        "fixture needs two owned improvement tiles"
    );
    for position in sources {
        let tile = game.map.tiles.get_mut(&position).expect("owned tile");
        tile.resource = Some(crate::name!("aluminum"));
        tile.improvement = Some(crate::name!("mine"));
        tile.pillaged = false;
    }
    assert_eq!(game.strategic_resource_rate(0, "aluminum"), 4.0);
}

/// The gene is off in production, and an inactive surge must be invisible:
/// no appointment, no research goal, and no change to a single production
/// score. This is the property every opt-in row claims and the one a screen
/// cannot recover if it is false.
#[test]
fn an_unopted_air_surge_appoints_nothing_and_prices_nothing() {
    let (mut game, _, _) = air_surge_fixture(941_100);
    let mut ai = AdvancedAi::new();
    assert!(!ai.air_surge, "the gene ships off");

    ai.maintain_air_surge(&game, 0);
    assert!(ai.air_surge_plan.is_none());
    assert!(!ai.air_surge_active());
    assert!(ai.air_surge_research_goal(&game, 0).is_none());
    assert_eq!(
        ai.air_surge_production_value(
            &game,
            0,
            &Item::Unit {
                unit: crate::name!("bomber"),
            },
            1.0,
        ),
        None
    );
    assert!(!ai.air_surge_production(&mut game, 0));

    // And the twin puts an opted-in seat back exactly.
    let mut opted = air_surge_ai();
    assert!(opted.air_surge);
    opted.disable_air_surge();
    assert!(!opted.air_surge);
}

/// The window has two edges. The horizon refuses a beeline so deep it is the
/// empire's whole research policy; the clock (its own test below) refuses one
/// that cannot finish. Inside both, the surge appoints — including with the
/// Bomber already in hand, where the buildout is all that is left.
#[test]
fn the_surge_window_is_bounded_by_the_horizon_and_the_clock() {
    let (mut game, _, _) = air_surge_fixture(941_101);
    let ai = air_surge_ai();

    assert_eq!(AdvancedAi::air_surge_missing_techs(&game, 0), 3);
    assert!(ai.air_surge_open(&game, 0));

    // Past the horizon the window is shut however affordable the chain is.
    let mut distant = game.clone();
    for tech in air_surge_prerequisites(&distant)
        .into_iter()
        .take(air_surge::AIR_SURGE_TECH_HORIZON)
    {
        distant.players[0].techs.remove(&tech);
    }
    assert!(AdvancedAi::air_surge_missing_techs(&distant, 0) > air_surge::AIR_SURGE_TECH_HORIZON);
    assert!(!ai.air_surge_open(&distant, 0));

    // And with the Bomber already in hand there is nothing left to beeline,
    // but the surge still opens — the buildout is the rest of the plan.
    air_surge_arm(&mut game);
    assert_eq!(AdvancedAi::air_surge_missing_techs(&game, 0), 0);
    assert!(ai.air_surge_open(&game, 0));
}

/// ★★★★ The gate that matters. The seat reaches its closest approach to
/// Advanced Flight at turn 258 of 300 with 79 turns of research still to pay
/// (`air_surge_census_at_deployment_scale`, seed 941200). A gate on the
/// technology count alone would appoint that: a beeline that spends the last
/// forty turns researching a unit it can never build.
#[test]
fn a_chain_that_cannot_finish_in_time_is_never_appointed() {
    let (mut game, _, _) = air_surge_fixture(941_114);
    let ai = air_surge_ai();
    assert!(ai.air_surge_affordable(&game, 0));
    assert!(ai.air_surge_open(&game, 0));

    let (research, production) = ai.air_surge_launch_estimate(&game, 0);
    assert!(research > 0 && production > 0, "both halves are priced");

    // Move the end of the game inside the estimate and the appointment goes
    // away, while every other condition is untouched.
    game.max_turns = game.turn + research + production;
    assert!(!ai.air_surge_affordable(&game, 0));
    assert!(!ai.air_surge_open(&game, 0));
    assert!(
        AdvancedAi::air_surge_missing_techs(&game, 0) <= air_surge::AIR_SURGE_TECH_HORIZON,
        "the technology gate still says yes; only the clock says no"
    );

    // A richer empire researches and builds the same chain sooner, so the same
    // clock admits it.
    game.max_turns = game.turn + research + production + game.standard_duration(60);
    assert!(ai.air_surge_affordable(&game, 0));
}

/// The appointment names a target, a city, and the body that will take it —
/// and it refuses a city the wing cannot reach, which is the one condition
/// the melee package has no analogue for.
#[test]
fn the_appointment_names_a_city_the_wing_can_reach() {
    let (game, _, objective) = air_surge_fixture(941_102);
    let ai = air_surge_ai();

    let plan = ai
        .choose_air_surge(&game, 0)
        .expect("a reachable rival city is an appointable surge");
    assert_eq!(plan.target_player, 1);
    assert_eq!(plan.objective_city, objective);
    assert_eq!(plan.objective_pos, game.cities[&objective].pos);
    assert_eq!(plan.phase, air_surge::AirSurgePhase::Beeline);
    assert_eq!(
        game.cities[&plan.objective_city].owner, 1,
        "the objective belongs to the appointed target"
    );
    let objective = game.cities[&plan.objective_city].pos;
    let range = game.rules.units[crate::name!("bomber")].range;
    assert!(
        game.player_city_ids(0)
            .into_iter()
            .any(|cid| game.wdist(game.cities[&cid].pos, objective) <= range),
        "the objective must sit under one of our airfields"
    );

    // Move the whole empire out of the wing's reach and there is no surge to
    // appoint, however valuable the city is.
    let mut distant = game.clone();
    for cid in distant.player_city_ids(0) {
        let city = distant.cities.get_mut(&cid).expect("own city");
        city.pos = (0, 0);
    }
    assert!(
        ai.choose_air_surge(&distant, 0).is_none(),
        "a city no bomber can strike is not an air surge"
    );
}

/// A Bomber cannot take a city; it can only empty one. The capture body is a
/// cavalry line by preference, and the surge says so when the empire can
/// field none.
#[test]
fn the_capture_body_is_cavalry_when_the_empire_can_field_one() {
    let (mut game, _, _) = air_surge_fixture(941_103);
    let (body, is_cavalry) =
        AdvancedAi::air_surge_body(&game, 0).expect("some land body is always buildable");
    assert!(is_cavalry, "{body} was chosen over the cavalry lines");
    assert!(matches!(
        game.rules.units[body].promotion_class.as_str(),
        "light_cavalry" | "heavy_cavalry"
    ));

    // Strip every cavalry technology and the surge falls back to melee rather
    // than refusing to attack at all.
    for tech in ["horseback_riding", "stirrups", "military_tactics"] {
        game.players[0].techs.remove(&Name::new(tech));
    }
    let (fallback, is_cavalry) =
        AdvancedAi::air_surge_body(&game, 0).expect("melee is always available");
    assert!(!is_cavalry, "{fallback} is still a cavalry line");
    assert!(game.rules.units[fallback].is_melee_capable());
}

/// The beeline is the point of the appointment: while it runs, research is
/// forced onto the cheapest legal step toward Advanced Flight instead of the
/// argmax the lane would otherwise take.
#[test]
fn the_beeline_forces_research_along_the_chain() {
    let (mut game, _, _) = air_surge_fixture(941_104);
    let mut ai = air_surge_ai();
    ai.maintain_air_surge(&game, 0);
    assert_eq!(
        ai.air_surge_research_goal(&game, 0),
        Some(air_surge::AIR_SURGE_GOAL_TECH)
    );

    game.players[0].research = None;
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    ai.advanced_research(&mut game, 0, &plan);
    assert_eq!(
        game.players[0].research.as_deref(),
        Some("flight"),
        "the first step of `flight -> radio -> advanced_flight` is the only \
         available one"
    );

    // The goal retires the moment the breakthrough lands, so the appointment
    // never holds the research slot past its own purpose.
    air_surge_arm(&mut game);
    ai.maintain_air_surge(&game, 0);
    assert!(ai.air_surge_research_goal(&game, 0).is_none());
}

/// The airfield is claimed before anything else in the package: no Bomber can
/// be trained anywhere else, so a wing ordered first is a wing ordered nowhere.
#[test]
fn the_airfield_is_claimed_before_the_wing() {
    let (mut game, _, _) = air_surge_fixture(941_105);
    air_surge_arm(&mut game);
    let mut ai = air_surge_ai();
    ai.maintain_air_surge(&game, 0);
    assert!(ai.air_surge_active());
    for cid in game.player_city_ids(0) {
        game.cities.get_mut(&cid).expect("own city").queue.clear();
    }

    assert!(
        ai.air_surge_production(&mut game, 0),
        "an idle empire with no airfield claims one"
    );
    let claimed = game
        .player_city_ids(0)
        .into_iter()
        .filter_map(|cid| game.cities[&cid].queue.first().cloned())
        .next()
        .expect("the claim writes a queue");
    assert!(
        matches!(claimed, Item::District { district, .. }
                 if game.district_family(district) == crate::name!("aerodrome")),
        "claimed {claimed:?} instead of the airfield"
    );

    // A second call does not start a duplicate: the queue already counts.
    let before: Vec<_> = game
        .player_city_ids(0)
        .into_iter()
        .map(|cid| game.cities[&cid].queue.clone())
        .collect();
    ai.air_surge_production(&mut game, 0);
    let after: Vec<_> = game
        .player_city_ids(0)
        .into_iter()
        .map(|cid| game.cities[&cid].queue.clone())
        .collect();
    assert!(
        after
            .iter()
            .flatten()
            .filter(|item| matches!(item, Item::District { district, .. }
                                    if game.district_family(*district)
                                        == crate::name!("aerodrome")))
            .count()
            <= 1,
        "before {before:?} after {after:?}"
    );
}

/// With the airfield standing the wing is the next claim, and the package is
/// priced above every ordinary candidate wherever the strategic scorer runs.
#[test]
fn the_wing_follows_the_airfield_and_outbids_the_ordinary_ranking() {
    let (mut game, _, _) = air_surge_fixture(941_106);
    air_surge_arm(&mut game);
    let mut ai = air_surge_ai();
    ai.maintain_air_surge(&game, 0);
    let plan = ai.air_surge_plan.clone().expect("an appointed surge");

    let bomber = Item::Unit {
        unit: crate::name!("bomber"),
    };
    let body = Item::Unit {
        unit: plan.body_unit,
    };
    let bystander = Item::Unit {
        unit: crate::name!("builder"),
    };

    let bomber_value = ai
        .air_surge_production_value(&game, 0, &bomber, 1.0)
        .expect("the wing is part of the package");
    let body_value = ai
        .air_surge_production_value(&game, 0, &body, 1.0)
        .expect("the escort is part of the package");
    assert_eq!(
        ai.air_surge_production_value(&game, 0, &bystander, 1.0),
        None,
        "a Builder is not part of the package"
    );
    assert!(
        bomber_value > body_value,
        "the wing is the scarce half: {bomber_value} vs {body_value}"
    );
    assert!(
        body_value > 7_000.0,
        "the package must outbid the ordinary ranking, not join it"
    );

    // Once the wing is complete it stops being priced, so the surge cannot
    // spend the rest of the game building bombers it does not need.
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    for _ in 0..air_surge::AIR_SURGE_BOMBERS {
        game.spawn_test_unit("bomber", 0, home);
    }
    ai.maintain_air_surge(&game, 0);
    assert_eq!(
        ai.air_surge_production_value(&game, 0, &bomber, 1.0),
        None,
        "a complete wing asks for nothing further"
    );
}

/// The metal is revealed one technology before the Bomber, so the appointment
/// cannot price it up front. It waits a bounded number of turns and then gives
/// the wing up rather than holding the empire's research and queues forever.
#[test]
fn the_surge_stands_down_when_no_aluminium_arrives() {
    let (mut game, _, _) = air_surge_fixture(941_107);
    game.players[0]
        .techs
        .insert(Name::new(air_surge::AIR_SURGE_GOAL_TECH));
    game.players[0].techs.insert(crate::name!("flight"));
    game.players[0].techs.insert(crate::name!("radio"));
    let mut ai = air_surge_ai();
    ai.maintain_air_surge(&game, 0);
    assert!(
        ai.air_surge_active(),
        "the surge appoints without the metal"
    );

    // Inside the grace period it holds: a Builder is still walking to the
    // deposit `radio` revealed.
    let breakthrough = game.turn;
    ai.air_surge_plan.as_mut().expect("live surge").tech_turn = Some(breakthrough);
    game.turn = breakthrough + game.standard_duration(air_surge::AIR_SURGE_ALUMINUM_GRACE) - 1;
    ai.maintain_air_surge(&game, 0);
    assert!(ai.air_surge_active());

    game.turn = breakthrough + game.standard_duration(air_surge::AIR_SURGE_ALUMINUM_GRACE);
    ai.maintain_air_surge(&game, 0);
    assert!(
        !ai.air_surge_active(),
        "a wing with no metal is not a surge"
    );
    assert_eq!(
        ai.air_surge_census.aborts.get("no Aluminum for the wing"),
        Some(&1)
    );

    // ⚠ And it stays down. The lifecycle ends by appointing whenever none is
    // live, so without the cooldown this stand-down is undone by the call that
    // recorded it and re-recorded every turn afterwards.
    ai.maintain_air_surge(&game, 0);
    assert!(!ai.air_surge_active());
    assert_eq!(
        ai.air_surge_census.aborts.get("no Aluminum for the wing"),
        Some(&1),
        "one situation is one stand-down"
    );
    game.turn += game.standard_duration(air_surge::AIR_SURGE_ABORT_COOLDOWN);
    game.players[0]
        .strategic_resources
        .insert(crate::name!("aluminum"), 400.0);
    ai.maintain_air_surge(&game, 0);
    assert!(
        ai.air_surge_active(),
        "the cooldown expires and the metal has arrived"
    );
}

/// The first two Bombers and two capture bodies are the launch package. The
/// other two Bombers and bodies are follow-through for the continent, not a
/// reason to leave a vulnerable neighbour alive.
#[test]
fn the_declaration_launches_at_two_bombers_and_two_capture_bodies() {
    let (mut game, _, _) = air_surge_fixture(941_108);
    air_surge_arm(&mut game);
    let mut ai = air_surge_ai();
    ai.maintain_air_surge(&game, 0);
    let plan = ai.air_surge_plan.clone().expect("an appointed surge");
    let home = game.cities[&game.player_city_ids(0)[0]].pos;
    // The formal route to war, as `preferred_war_opening` walks it: the surge
    // denounces while the wing is being built and declares once the clock has
    // run. Seeding it here keeps this test about the package, not about the
    // diplomacy timer.
    game.players[0].denounced_until.insert(1, game.turn + 25);
    game.players[0].denounced_since.insert(1, game.turn - 5);

    // One bomber and no escort: the surge owns the war-opening decision and
    // deliberately spends it on nothing.
    game.spawn_test_unit("bomber", 0, home);
    ai.maintain_air_surge(&game, 0);
    assert_eq!(
        ai.air_surge_plan.as_ref().map(|plan| plan.phase),
        Some(air_surge::AirSurgePhase::Arm)
    );
    assert!(ai.air_surge_opening(&mut game, 0, 1));
    assert!(
        !game.is_at_war(0, 1),
        "an incomplete package must not declare"
    );

    assert_eq!(
        AdvancedAi::air_surge_bomber_goal(&game, 0),
        air_surge::AIR_SURGE_BOMBERS,
        "+4 Aluminum per turn sustains all four Bombers"
    );
    for _ in 1..air_surge::AIR_SURGE_LAUNCH_BOMBERS {
        game.spawn_test_unit("bomber", 0, home);
    }
    for _ in 0..air_surge::AIR_SURGE_LAUNCH_BODIES {
        game.spawn_test_unit(plan.body_unit.as_str(), 0, home);
    }
    ai.maintain_air_surge(&game, 0);
    assert_eq!(
        ai.air_surge_plan.as_ref().map(|plan| plan.phase),
        Some(air_surge::AirSurgePhase::Strike),
        "the initial strike package is owed a declaration"
    );

    assert!(ai.air_surge_opening(&mut game, 0, 1));
    assert!(game.is_at_war(0, 1), "the initial package opens the war");
    assert_eq!(ai.air_surge_census.declarations, 1);
    assert_eq!(
        ai.air_surge_plan.as_ref().map(|plan| plan.phase),
        Some(air_surge::AirSurgePhase::Exploit)
    );
    assert_eq!(
        ai.air_surge_plan
            .as_ref()
            .and_then(|plan| plan.declared_turn),
        Some(game.turn)
    );
    assert!(
        ai.air_surge_production_value(
            &game,
            0,
            &Item::Unit {
                unit: crate::name!("bomber"),
            },
            1.0,
        )
        .is_some(),
        "war starts at two, while +4 Aluminum keeps building toward four"
    );
}

/// `--fresh-board` recreates city ids every frame. The objective coordinate
/// is the stable identity, so an unrelated current-board id cannot make a
/// still-Macedonian city look as though it changed owner.
#[test]
fn a_fresh_board_rebinds_the_air_surge_objective_by_coordinate() {
    let (mut game, stale_city, _) = air_surge_fixture(941_115);
    air_surge_arm(&mut game);
    let mut ai = air_surge_ai();
    ai.maintain_air_surge(&game, 0);
    let plan = ai.air_surge_plan.as_mut().expect("an appointed surge");
    let objective = plan.objective_city;
    let objective_pos = plan.objective_pos;
    assert_ne!(stale_city, objective, "the stale id must name another city");
    plan.objective_city = stale_city;
    assert_eq!(plan.objective_pos, objective_pos);

    // This is the exact condition after a fresh mirror rebuild: the retained
    // id now names a different city, while the City Center coordinate remains
    // Pella's durable identity.
    game.turn += 1;
    ai.maintain_air_surge(&game, 0);
    let rebound = ai
        .air_surge_plan
        .expect("the target still belongs to the rival");
    assert_eq!(rebound.objective_city, objective);
    assert_eq!(rebound.objective_pos, objective_pos);
    assert_eq!(
        ai.air_surge_census.aborts.get("objective changed owner"),
        None,
        "a reconstruction id change is not a capture or a stand-down"
    );
}

/// From Strike onward the surge owns the grand strategy, exactly as an
/// appointed timed war does — and deliberately not before, because three
/// technologies of Conquest posture would pay for the wing with the economy
/// that has to build it.
#[test]
fn the_surge_takes_the_strategy_only_once_it_is_ready_to_launch() {
    let (mut game, _, _) = air_surge_fixture(941_109);
    air_surge_arm(&mut game);
    let mut ai = air_surge_ai();
    ai.maintain_air_surge(&game, 0);
    let surge = ai.air_surge_plan.clone().expect("an appointed surge");

    let mut plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    ai.apply_air_surge_to_strategy(&mut plan);
    assert_eq!(
        plan.strategy,
        GrandStrategy::Science,
        "the buildout leaves the economy its own plan"
    );

    ai.air_surge_plan.as_mut().expect("live surge").phase = air_surge::AirSurgePhase::Strike;
    ai.apply_air_surge_to_strategy(&mut plan);
    assert_eq!(plan.strategy, GrandStrategy::Conquest);
    assert_eq!(plan.target_player, Some(surge.target_player));
    assert_eq!(plan.target_city, Some(surge.objective_city));

    // A home emergency still outranks the appointment.
    let mut recovering = StrategicPlan {
        strategy: GrandStrategy::Recovery,
        ..plan.clone()
    };
    recovering.target_player = None;
    ai.apply_air_surge_to_strategy(&mut recovering);
    assert_eq!(recovering.strategy, GrandStrategy::Recovery);
    assert_eq!(recovering.target_player, None);
}

/// One appointed package at a time. Two would bid for the same idle queues and
/// the same declaration, and the cross-gate has to hold in both directions.
#[test]
fn the_two_appointed_packages_never_run_together() {
    let (mut game, _, objective) = air_surge_fixture(941_110);
    let mut ai = air_surge_ai();
    ai.timed_war = true;

    ai.war_plan = Some(timed_plan(
        &game,
        objective,
        crate::name!("stirrups"),
        crate::name!("knight"),
        None,
        None,
        WarPhase::Mobilize,
    ));
    assert!(
        !ai.air_surge_open(&game, 0),
        "a live melee appointment keeps the queues"
    );

    ai.war_plan = None;
    ai.maintain_air_surge(&game, 0);
    assert!(ai.air_surge_active());
    assert!(
        !ai.may_form_war_plan(&game, 0),
        "a live surge keeps the queues"
    );

    // And with the gene off the cross-gate is an exact no-op: `timed_war`
    // sees the board it always saw.
    let mut melee = AdvancedAi::new();
    melee.timed_war = true;
    let mut treated = AdvancedAi::new();
    treated.timed_war = true;
    treated.disable_air_surge();
    assert_eq!(
        melee.may_form_war_plan(&game, 0),
        treated.may_form_war_plan(&game, 0)
    );
    let _ = &mut game;
}

/// A census, not an assertion: play a full game with the gene on, sample the
/// distance to the Bomber every turn, and report what the surge actually did.
///
/// ★★★★ THIS INSTRUMENT IS WHY [`air_surge::AIR_SURGE_TECH_HORIZON`] IS NOT
/// THREE AND WHY [`AdvancedAi::air_surge_affordable`] EXISTS. At the 300-turn
/// deployment shape the seat's closest approach to Advanced Flight was six to
/// fifteen technologies, reached between turns 147 and 285, with 79 to 278
/// turns of research still to pay for. Run it before believing either that the
/// lane helps or that it hurts: a screen cannot tell "the gene lost" from "the
/// gene never fired", and this can.
///
/// `--turns` is the axis worth varying. 300 says whether the shipped shape can
/// reach the air at all; 600 says whether the machinery works when it can.
#[test]
#[ignore = "census, not an assertion; run explicitly with --nocapture"]
fn air_surge_census_at_deployment_scale() {
    let turns: u32 = std::env::var("CIVVIS_AIR_SURGE_TURNS")
        .ok()
        .and_then(|value| value.parse().ok())
        .unwrap_or(300);
    for seed in 941_200..941_204u64 {
        let mut game = Game::new(6, 74, 46, seed, turns, 9);
        let mut me = air_surge_ai();
        let mut others = AdvancedAi::fleet(&game);
        let mut closest = usize::MAX;
        let mut closest_turn = 0;
        let mut first_affordable = None;
        let (mut peak_bombers, mut peak_fields, mut peak_metal) = (0usize, 0usize, 0i32);
        while game.winner.is_none() && game.turn <= game.max_turns {
            let pid = game.current;
            if pid == 0 {
                let missing = AdvancedAi::air_surge_missing_techs(&game, 0);
                if missing < closest {
                    closest = missing;
                    closest_turn = game.turn;
                }
                if first_affordable.is_none() && me.air_surge_affordable(&game, 0) {
                    let (research, production) = me.air_surge_launch_estimate(&game, 0);
                    first_affordable = Some((game.turn, missing, research, production));
                }
                me.take_turn(&mut game, pid);
                peak_bombers = peak_bombers.max(
                    game.player_unit_ids(0)
                        .into_iter()
                        .filter(|uid| game.units[uid].kind == "bomber")
                        .count(),
                );
                peak_fields = peak_fields.max(
                    game.player_city_ids(0)
                        .into_iter()
                        .filter(|cid| {
                            game.city_has_district_family(
                                &game.cities[cid],
                                crate::name!("aerodrome"),
                            )
                        })
                        .count(),
                );
                peak_metal = peak_metal.max(game.connected_resource_count(0, "aluminum"));
            } else {
                others[pid].take_turn(&mut game, pid);
            }
            if game.winner.is_none() && game.current == pid {
                let _ = game.apply(pid, &Action::EndTurn);
            }
        }
        let bombers = game
            .player_unit_ids(0)
            .into_iter()
            .filter(|uid| game.units[uid].kind == "bomber")
            .count();
        println!(
            "seed {seed} ({turns}t): appointments {} breakthroughs {} declarations {} \
             captures {} aborts {:?}",
            me.air_surge_census.appointments,
            me.air_surge_census.breakthroughs,
            me.air_surge_census.declarations,
            me.air_surge_census.objectives_captured,
            me.air_surge_census.aborts,
        );
        println!(
            "  closest {closest} at turn {closest_turn} | first affordable \
             {first_affordable:?} | peak: fields {peak_fields} aluminium {peak_metal} \
             bombers {peak_bombers} | techs {} bombers {bombers} cities {} score {}",
            game.players[0].techs.len(),
            game.player_city_ids(0).len(),
            game.score(0),
        );
    }
}

/// The counter. A Bomber is as useful against a civilization attacking us as
/// against one we chose, and the empire that most needs a wing is the one
/// already being invaded — so a surge appointed into a running war arms
/// without a declaration, and keeps its beeline while it does.
#[test]
fn a_surge_appointed_into_a_running_war_arms_without_declaring() {
    let (mut game, _, objective) = air_surge_fixture(941_111);
    game.at_war.insert((0, 1));
    game.at_war.insert((1, 0));
    let mut ai = air_surge_ai();
    ai.maintain_air_surge(&game, 0);

    let plan = ai
        .air_surge_plan
        .clone()
        .expect("a running war is a counter, not a refusal");
    assert!(plan.opened_at_war);
    assert_eq!(
        plan.target_player, 1,
        "the counter arms against the invader"
    );
    assert_eq!(plan.objective_city, objective);
    assert_eq!(
        plan.phase,
        air_surge::AirSurgePhase::Exploit,
        "there is nothing left to declare"
    );

    // ⚠ The beeline is keyed off the technology, not the phase: a counter is
    // in `Exploit` from its first turn and is exactly the appointment that
    // most needs the three techs.
    assert_eq!(
        ai.air_surge_research_goal(&game, 0),
        Some(air_surge::AIR_SURGE_GOAL_TECH)
    );
    assert!(
        !ai.air_surge_opening(&mut game, 0, 1),
        "a counter never consumes the war-opening decision"
    );

    // Peace closes it, exactly as a declaration of our own would have been.
    game.at_war.remove(&(0, 1));
    game.at_war.remove(&(1, 0));
    ai.maintain_air_surge(&game, 0);
    assert!(!ai.air_surge_active());
    assert_eq!(
        ai.air_surge_census.aborts.get("peace closed the war"),
        Some(&1)
    );
}

/// Two fronts is a war the empire is losing, and a three-technology beeline is
/// not the answer to it.
#[test]
fn a_second_front_closes_the_surge_window() {
    let (mut game, _, _) = air_surge_fixture(941_112);
    let ai = air_surge_ai();
    assert!(
        ai.air_surge_open(&game, 0),
        "peace appoints the elective attack"
    );

    game.at_war.insert((0, 1));
    game.at_war.insert((1, 0));
    assert!(ai.air_surge_open(&game, 0), "one front is the counter");

    // A three-major board with two of them fighting us.
    let mut crowded = Game::new_full(3, 32, 20, 941_113, 1_000, 0, false);
    for pid in 0..3 {
        let settler = crowded
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| crowded.units[unit].kind == "settler")
            .expect("each major starts with a settler");
        let position = crowded.units[&settler].pos;
        crowded.found_city_for(pid, position, None);
        crowded.remove_unit(settler);
    }
    let capital = crowded.cities[&crowded.player_city_ids(0)[0]].pos;
    found_nearby_test_city(&mut crowded, 0, capital);
    for tech in air_surge_prerequisites(&crowded) {
        crowded.players[0].techs.insert(tech);
    }
    crowded.turn = 60;
    crowded.current = 0;
    for other in 1..3 {
        crowded.players[0].met.insert(other);
        crowded.players[other].met.insert(0);
        crowded.at_war.insert((0, other));
        crowded.at_war.insert((other, 0));
    }
    assert!(
        !ai.air_surge_open(&crowded, 0),
        "two fronts shut the window"
    );
}

/// The religious-corps genes are registered, discoverable by name, and
/// reversible. The bare controller starts them off; the deployment ledger
/// currently promotes `religious-defence-scales` and
/// `religious-units-heal-first`. See `advanced/religion.rs`.
#[test]
fn the_religious_corps_genes_are_registered_reversible_opt_ins() {
    let mut ai = AdvancedAi::new();
    for (field, tag) in [
        ("religious_defence_scales", "religious-defence-scales"),
        ("guru_heals_the_corps_2", "guru-heals-the-corps-2"),
        ("religious_units_heal_first", "religious-units-heal-first"),
        (
            "holy_site_where_the_threat_is",
            "holy-site-where-the-threat-is",
        ),
        ("enhancer_for_the_corps", "enhancer-for-the-corps"),
    ] {
        assert!(
            GENES
                .iter()
                .any(|gene| gene.opt_in() && gene.field == field && gene.tag == tag),
            "{tag} must be a registered native opt-in"
        );
        assert!(
            crate::ai::advanced::gene_ledger::screenable(tag),
            "{tag} must be screenable, so the ledger can price it"
        );
        assert!(
            crate::ai::advanced::gene_ledger::ledger_default_on(tag).is_some(),
            "{tag}: the batch rule decides its default from its batch columns"
        );
    }
    assert!(
        !ai.religious_defence_scales,
        "the bare controller starts it off"
    );
    assert!(
        !ai.guru_heals_the_corps_2,
        "the bare controller starts it off"
    );
    assert!(
        !ai.religious_units_heal_first,
        "the bare controller starts it off"
    );
    assert!(
        !ai.holy_site_where_the_threat_is,
        "the bare controller starts it off"
    );
    assert!(
        !ai.enhancer_for_the_corps,
        "the bare controller starts it off"
    );
    ai.enable_religious_defence_scales();
    ai.enable_guru_heals_the_corps_2();
    ai.enable_religious_units_heal_first();
    ai.enable_holy_site_where_the_threat_is();
    ai.enable_enhancer_for_the_corps();
    assert!(ai.religious_defence_scales);
    assert!(ai.guru_heals_the_corps_2);
    assert!(ai.religious_units_heal_first);
    assert!(ai.holy_site_where_the_threat_is);
    assert!(ai.enhancer_for_the_corps);
    ai.disable_religious_defence_scales();
    ai.disable_guru_heals_the_corps_2();
    ai.disable_religious_units_heal_first();
    ai.disable_holy_site_where_the_threat_is();
    ai.disable_enhancer_for_the_corps();
    assert!(!ai.religious_defence_scales);
    assert!(!ai.guru_heals_the_corps_2);
    assert!(!ai.religious_units_heal_first);
    assert!(!ai.holy_site_where_the_threat_is);
    assert!(!ai.enhancer_for_the_corps);
}

/// `religious_defence_scales`: the shipped defensive corps is
/// `(1 + targets.div_ceil(2)).min(2)`, which answers three slipping cities
/// exactly as it answers one. The gene answers one spreader per threatened
/// city, and never fewer than the shipped rule, up to its own ceiling of four.
#[test]
fn the_defensive_corps_answers_the_number_of_cities_only_with_the_gene() {
    let off = AdvancedAi::new();
    let mut on = AdvancedAi::new();
    on.enable_religious_defence_scales();
    // (targets, shipped) pairs straight off the shipped expression.
    for (targets, shipped) in [(0_usize, 0_usize), (1, 2), (2, 2), (3, 2), (5, 2), (9, 2)] {
        assert_eq!(
            off.defensive_missionary_cap(targets, shipped),
            shipped,
            "the gene off is the shipped constant, exactly"
        );
    }
    assert_eq!(on.defensive_missionary_cap(1, 2), 2, "one city: unchanged");
    assert_eq!(on.defensive_missionary_cap(2, 2), 3);
    assert_eq!(on.defensive_missionary_cap(3, 2), 4, "three cities, three…");
    assert_eq!(
        on.defensive_missionary_cap(9, 2),
        4,
        "…and never past the ceiling, whatever the pressure"
    );
    assert_eq!(
        on.defensive_missionary_cap(0, 0),
        1,
        "a caller that asked for none still gets the gene's floor of one"
    );
}

/// `guru_heals_the_corps_2`: `guru_cap` is `offensive && apostles > 0`, so
/// the founder defending its own cities can never buy the only unit that
/// heals a religious corps. The gene answers yes only when there is a damaged
/// unit to heal, even without home conversion pressure, and the defensive
/// purchase orders name the Guru so the cap can bite.
#[test]
fn a_damaged_corps_buys_a_guru_only_with_the_v2_gene() {
    let mut game = Game::new_full(2, 30, 18, 7_116, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    let home = game.player_city_ids(0)[0];
    install_test_holy_site(&mut game, home);
    game.players[0].techs.insert(crate::name!("astrology"));
    game.players[0].civics.insert(crate::name!("theology"));
    game.players[0].religion = Some("Our Faith".to_string());
    game.players[0].holy_city = Some(home);
    let pressure = &mut game.cities.get_mut(&home).unwrap().pressure;
    pressure.insert("Our Faith".to_string(), 1_000.0);
    game.players[0].faith = game.game_speed.scale(4_000.0);
    // A damaged spreader already in the field is the thing a Guru is for.
    let wounded = game.spawn_test_unit("missionary", 0, game.cities[&home].pos);
    game.units.get_mut(&wounded).unwrap().hp = 45;
    game.units.get_mut(&wounded).unwrap().religion = Some("Our Faith".to_string());

    let gurus = |game: &Game| {
        game.units
            .values()
            .filter(|unit| unit.owner == 0 && unit.kind == "guru")
            .count()
    };

    let mut control = game.clone();
    let mut off = AdvancedAi::new();
    for _ in 0..6 {
        off.religious_spending_with_reserve(&mut control, 0, false, 80.0);
    }
    assert_eq!(
        gurus(&control),
        0,
        "the shipped orders never name a Guru off the offensive"
    );

    let mut treated = game.clone();
    let mut on = AdvancedAi::new();
    on.enable_guru_heals_the_corps_2();
    for _ in 0..6 {
        on.religious_spending_with_reserve(&mut treated, 0, false, 80.0);
    }
    assert_eq!(gurus(&treated), 1, "the defence buys its one heal");

    // Nothing damaged: the gene has no reason to spend, and does not.
    let mut healthy = game.clone();
    healthy.units.get_mut(&wounded).unwrap().hp = 100;
    let mut spare = AdvancedAi::new();
    spare.enable_guru_heals_the_corps_2();
    for _ in 0..6 {
        spare.religious_spending_with_reserve(&mut healthy, 0, false, 80.0);
    }
    assert_eq!(
        gurus(&healthy),
        0,
        "a corps at full health is not a reason to buy a Guru"
    );
}

/// `religious_units_heal_first`: a religious unit heals only on a turn it takes
/// no action at all — `end_turn` heals when `!acted` and every move sets
/// `acted` — while `do_spread` scales the pressure a charge adds by `hp/100`.
/// The gene holds a wounded spreader that is standing in its own Holy Site's
/// heal ring, and stands aside for a city that cannot wait.
#[test]
fn a_wounded_spreader_holds_to_heal_only_with_the_gene() {
    let mut game = Game::new_full(2, 30, 18, 7_116, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    let home = game.player_city_ids(0)[0];
    let holy_site = install_ai_test_district(&mut game, home, "holy_site");
    game.cities.get_mut(&home).unwrap().buildings =
        vec![crate::name!("shrine"), crate::name!("temple")];
    game.players[0].religion = Some("Our Faith".to_string());
    game.players[0].holy_city = Some(home);
    game.players[1].religion = Some("Rival Faith".to_string());
    // Our faith holds this city comfortably, so nothing here cannot wait.
    let pressure = &mut game.cities.get_mut(&home).unwrap().pressure;
    pressure.insert("Our Faith".to_string(), 1_000.0);

    let wounded = game.spawn_test_unit("missionary", 0, holy_site);
    game.units.get_mut(&wounded).unwrap().hp = 45;
    game.units.get_mut(&wounded).unwrap().religion = Some("Our Faith".to_string());
    assert!(
        game.unit_heal_rate(wounded) > 0,
        "the fixture must actually stand in a heal ring, or the gene is inert"
    );

    let off = AdvancedAi::new();
    assert!(
        !off.religious_unit_holds_to_heal(&game, 0, wounded),
        "the gene off never holds"
    );
    let mut on = AdvancedAi::new();
    on.enable_religious_units_heal_first();
    assert!(
        on.religious_unit_holds_to_heal(&game, 0, wounded),
        "a wounded spreader in its own ring waits for the wound to close"
    );
    // And the hold is what the step actually does with it. Give the empire a
    // second city that IS slipping, several tiles away: without the gene the
    // wounded unit sets off for it at 45 hit points, which is the march this
    // gene is there to postpone.
    let mut sites: Vec<Pos> = game
        .map
        .tiles
        .values()
        .filter(|tile| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.city_at(tile.pos).is_none()
                && game.wdist(tile.pos, holy_site) > 4
        })
        .map(|tile| tile.pos)
        .collect();
    sites.sort_by_key(|position| (game.wdist(*position, holy_site), *position));
    game.current = 0;
    let distant = sites
        .into_iter()
        .find(|position| {
            let settler = game.spawn_test_unit("settler", 0, *position);
            let founded = game.can_found_city(settler)
                && game.apply(0, &Action::FoundCity { unit: settler }).is_ok();
            if !founded {
                game.remove_unit(settler);
            }
            founded
        })
        .expect("fixture needs a second settlement site");
    let slipping = game.city_at(distant).expect("the second city stands");
    let pressure = &mut game.cities.get_mut(&slipping).unwrap().pressure;
    pressure.insert("Rival Faith".to_string(), 900.0);
    assert!(
        AdvancedAi::city_needs_religious_support(&game, 0, &game.cities[&slipping], "Our Faith"),
        "the distant city must actually be slipping, or nothing marches"
    );

    let mut spent = game.clone();
    assert!(
        off.advanced_missionary_step(&mut spent, 0, wounded, false),
        "without the gene the wounded unit marches on the distant city"
    );
    let mut held = game.clone();
    assert!(
        on.religious_unit_holds_to_heal(&held, 0, wounded),
        "a city four tiles away is not one this turn's Spread could reach"
    );
    assert!(
        !on.advanced_missionary_step(&mut held, 0, wounded, false),
        "holding is reported as no action, which is how the unit heals"
    );
    assert_eq!(
        held.units[&wounded].pos, holy_site,
        "…and it is still standing in the ring that heals it"
    );
    assert_eq!(
        held.units[&wounded].charges, game.units[&wounded].charges,
        "…having spent no charge"
    );

    // A healthy unit is never held.
    let mut whole = game.clone();
    whole.units.get_mut(&wounded).unwrap().hp = 100;
    assert!(!on.religious_unit_holds_to_heal(&whole, 0, wounded));

    // Nor is a wounded one whose own city is losing its majority: the
    // defensive conversion is the whole point of holding a corps.
    let mut urgent = game.clone();
    let pressure = &mut urgent.cities.get_mut(&home).unwrap().pressure;
    pressure.insert("Rival Faith".to_string(), 900.0);
    assert!(
        !on.religious_unit_holds_to_heal(&urgent, 0, wounded),
        "a city under pressure cannot wait three turns"
    );

    // Nor is one standing where the engine would not heal it anyway.
    let mut stranded = game.clone();
    let far = stranded
        .map
        .tiles
        .keys()
        .copied()
        .find(|position| stranded.wdist(*position, holy_site) > 3)
        .expect("the test map is bigger than the heal ring");
    stranded.units.get_mut(&wounded).unwrap().pos = far;
    stranded.relocate(wounded, far);
    assert_eq!(stranded.unit_heal_rate(wounded), 0);
    assert!(
        !on.religious_unit_holds_to_heal(&stranded, 0, wounded),
        "the hold never strands a unit somewhere it would not recover"
    );
}

/// `holy_site_where_the_threat_is`: a religious unit is purchasable only in a
/// city that itself holds a Holy Site, so a founder whose only Holy Site is
/// its Holy City cannot buy a defender for the city that is actually slipping.
/// The gene claims the district there; it never touches a city that is not.
#[test]
fn the_slipping_city_claims_a_holy_site_only_with_the_gene() {
    let mut game = Game::new_full(2, 30, 18, 7_116, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    let home = game.player_city_ids(0)[0];
    install_test_holy_site(&mut game, home);
    // The district itself is gated on Astrology; without it the gene is
    // correctly inert and the test would be measuring the tech, not the gene.
    game.players[0].techs.insert(crate::name!("astrology"));
    game.players[0].religion = Some("Our Faith".to_string());
    game.players[0].holy_city = Some(home);
    game.players[1].religion = Some("Rival Faith".to_string());
    game.cities
        .get_mut(&home)
        .unwrap()
        .pressure
        .insert("Our Faith".to_string(), 1_000.0);

    // A second city of ours, with no Holy Site, losing its majority.
    let home_pos = game.cities[&home].pos;
    let mut sites: Vec<Pos> = game
        .map
        .tiles
        .values()
        .filter(|tile| {
            game.rules.is_passable(tile)
                && !game.rules.is_water(tile)
                && game.city_at(tile.pos).is_none()
                && game.wdist(tile.pos, home_pos) > 4
        })
        .map(|tile| tile.pos)
        .collect();
    sites.sort_by_key(|position| (game.wdist(*position, home_pos), *position));
    let distant = sites
        .into_iter()
        .find(|position| {
            let settler = game.spawn_test_unit("settler", 0, *position);
            let founded = game.can_found_city(settler)
                && game.apply(0, &Action::FoundCity { unit: settler }).is_ok();
            if !founded {
                game.remove_unit(settler);
            }
            founded
        })
        .expect("fixture needs a second settlement site");
    let slipping = game.city_at(distant).expect("the second city stands");
    game.cities
        .get_mut(&slipping)
        .unwrap()
        .pressure
        .insert("Rival Faith".to_string(), 900.0);
    assert!(
        !game.city_has_district_family(&game.cities[&slipping], crate::name!("holy_site")),
        "the slipping city has nowhere to buy a defender"
    );
    // The queue leg, not the purchase leg.
    game.players[0].gold = 0.0;
    // Make the plot question unambiguous: a fresh pop-1 city's ring can be all
    // forest and jungle, which the placement rules exclude until Mining and
    // Bronze Working, and its specialty capacity is one. Clearing the ring and
    // growing the city keeps this test about the gene rather than the terrain.
    game.cities.get_mut(&slipping).unwrap().pop = 4;
    let ring: Vec<Pos> = game.cities[&slipping]
        .owned_tiles
        .iter()
        .copied()
        .filter(|position| *position != distant && game.wdist(*position, distant) <= 3)
        .collect();
    for position in ring {
        let tile = game.map.tiles.get_mut(&position).unwrap();
        tile.feature = None;
        tile.resource = None;
        tile.improvement = None;
    }
    let holy_site_district = crate::ai::BasicAi::civ_district(&game, 0, "holy_site");
    let site = game
        .district_sites(slipping, holy_site_district)
        .into_iter()
        .next()
        .expect("the slipping city must have somewhere to put one");
    assert!(
        game.can_produce(
            0,
            slipping,
            &Item::District {
                district: holy_site_district,
                pos: site
            }
        ),
        "the fixture must be able to build the district, or the gene is untested"
    );

    let holy_sites = |game: &Game, cid: u32| {
        game.city_has_district_family(&game.cities[&cid], crate::name!("holy_site"))
    };
    let queued_holy_site = |game: &Game, cid: u32| {
        matches!(
            game.cities[&cid].queue.first(),
            Some(Item::District { district, .. }) if *district == holy_site_district
        )
    };

    let mut control = game.clone();
    AdvancedAi::new().holy_site_where_the_threat_is(&mut control, 0);
    assert!(
        !queued_holy_site(&control, slipping),
        "the gene off is an exact no-op"
    );

    let mut treated = game.clone();
    let mut on = AdvancedAi::new();
    on.enable_holy_site_where_the_threat_is();
    on.holy_site_where_the_threat_is(&mut treated, 0);
    assert!(
        queued_holy_site(&treated, slipping),
        "the city that is losing its majority claims the district"
    );
    assert!(
        holy_sites(&treated, home) && !holy_sites(&treated, slipping),
        "…and the Holy City keeps the one it already had"
    );

    // A comfortable empire is untouched: nothing is slipping, nothing claimed.
    let mut calm = game.clone();
    calm.cities
        .get_mut(&slipping)
        .unwrap()
        .pressure
        .insert("Our Faith".to_string(), 5_000.0);
    let mut quiet = AdvancedAi::new();
    quiet.enable_holy_site_where_the_threat_is();
    quiet.holy_site_where_the_threat_is(&mut calm, 0);
    assert!(
        !queued_holy_site(&calm, slipping),
        "a city holding its majority is not a threat to answer"
    );
}

/// `enhancer_for_the_corps`: the `EvangelizeBelief` table scores by victory
/// lane and gives every belief it does not name 100 — the same number for
/// `scripture`, which multiplies the pressure of every charge, as for a
/// worship building. The gene scores the five corps enhancers above the lane
/// pick while the corps has a job, and is inert when it has none.
#[test]
fn the_corps_enhancers_outrank_the_lane_pick_only_with_the_gene() {
    let mut game = Game::new_full(2, 30, 18, 7_116, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    let home = game.player_city_ids(0)[0];
    game.players[0].religion = Some("Our Faith".to_string());
    game.players[1].religion = Some("Rival Faith".to_string());
    // Home under conversion pressure: the corps has a job.
    let pressure = &mut game.cities.get_mut(&home).unwrap().pressure;
    pressure.insert("Our Faith".to_string(), 1_000.0);
    pressure.insert("Rival Faith".to_string(), 700.0);

    let off = AdvancedAi::new();
    let mut on = AdvancedAi::new();
    on.enable_enhancer_for_the_corps();
    for belief in [
        "holy_order",
        "scripture",
        "itinerant_preachers",
        "missionary_zeal",
        "defender_of_the_faith",
    ] {
        assert_eq!(
            off.corps_enhancer_score(&game, 0, belief),
            None,
            "the gene off scores nothing, so the lane table is untouched"
        );
        let score = on
            .corps_enhancer_score(&game, 0, belief)
            .unwrap_or_else(|| panic!("{belief} is a corps multiplier"));
        assert!(
            score >= 300,
            "{belief} must reach the lane table's own maximum, or it can never win"
        );
    }
    assert!(
        on.corps_enhancer_score(&game, 0, "holy_order")
            > on.corps_enhancer_score(&game, 0, "defender_of_the_faith"),
        "cheaper units outrank a defensive combat bonus"
    );
    // A worship building is not a corps multiplier and keeps its lane score.
    for belief in ["cathedral", "wat", "pagoda", "tithe"] {
        assert_eq!(on.corps_enhancer_score(&game, 0, belief), None);
    }

    // A comfortable founder with nothing in the field keeps the lane pick.
    let mut calm = game.clone();
    calm.cities
        .get_mut(&home)
        .unwrap()
        .pressure
        .remove("Rival Faith");
    assert!(!calm
        .units
        .values()
        .any(|unit| unit.owner == 0 && calm.rules.units[unit.kind].religious_spread > 0.0));
    assert_eq!(
        on.corps_enhancer_score(&calm, 0, "scripture"),
        None,
        "no city slipping and no campaign in the field: the corps has no job"
    );

    // …but a campaign in the field is a job on its own.
    let mut campaigning = calm.clone();
    let spreader = campaigning.spawn_test_unit("missionary", 0, campaigning.cities[&home].pos);
    campaigning.units.get_mut(&spreader).unwrap().religion = Some("Our Faith".to_string());
    assert!(campaigning.units[&spreader].charges > 0);
    assert_eq!(
        on.corps_enhancer_score(&campaigning, 0, "scripture"),
        Some(380)
    );
}

// ---------------------------------------------------------------------------
// The air surge, version two: the science–domination loop. See
// `advanced/air_surge.rs`, gene `air-surge-2`.
// ---------------------------------------------------------------------------

/// One version of the family plays: enabling v2 turns v1 off (the
/// `science_victory_drive_2` convention), the surge machinery runs for
/// either version through `air_surge_enabled`, and a plain seat feels
/// nothing.
#[test]
fn the_v2_surge_replaces_v1_and_a_plain_seat_feels_nothing() {
    let (game, _, _) = air_surge_fixture(941_150);
    let mut ai = air_surge_ai();
    ai.enable_air_surge_2();
    assert!(
        !ai.air_surge && ai.air_surge_2,
        "one version of the family plays"
    );
    assert!(ai.air_surge_enabled());

    ai.maintain_air_surge(&game, 0);
    assert!(
        ai.air_surge_active(),
        "the surge machinery appoints under version two"
    );

    // The twin stands the whole family down.
    ai.disable_air_surge_2();
    assert!(!ai.air_surge_enabled());
    ai.maintain_air_surge(&game, 0);
    assert!(!ai.air_surge_active());

    // Defaults: off for the stock and frozen controllers.
    assert!(!AdvancedAi::new().air_surge_2);
    assert!(!AdvancedAi::legacy().air_surge_2);
}

/// The Formal-War clock runs through the buildout. A lane seat assesses no
/// rival, so `advanced_diplomacy` needs the surge to hand it a target while
/// the wing arms — v1 never does, v2 does, and a counter appointed into a
/// running war still borrows no decision it was not given.
#[test]
fn the_buildout_denounce_needs_no_assessed_target() {
    let (game, _, _) = air_surge_fixture(941_152);

    let mut v1 = air_surge_ai();
    v1.maintain_air_surge(&game, 0);
    assert!(v1.air_surge_active());
    assert_eq!(
        v1.air_surge_diplomacy_target(),
        None,
        "version one leaves the diplomacy pass exactly as it was"
    );

    let mut v2 = AdvancedAi::new();
    v2.enable_air_surge_2();
    v2.maintain_air_surge(&game, 0);
    let surge_target = v2.air_surge_plan.as_ref().expect("appointed").target_player;
    assert_eq!(v2.air_surge_diplomacy_target(), Some(surge_target));

    // Appointed into a war already running there is nothing to open.
    v2.air_surge_plan.as_mut().expect("appointed").opened_at_war = true;
    assert_eq!(v2.air_surge_diplomacy_target(), None);

    // And with no appointment at all, nothing is offered.
    v2.air_surge_plan = None;
    assert_eq!(v2.air_surge_diplomacy_target(), None);
}

/// The loop's second surge is nearly free, and only v2 knows it: with the
/// airfield standing and a Bomber alive, v1 re-prices the whole package from
/// scratch and the endgame clock refuses a follow-up that v2 admits.
#[test]
fn a_standing_wing_makes_the_follow_up_surge_affordable() {
    let (mut game, _, _) = air_surge_fixture(941_151);
    air_surge_arm(&mut game);

    let v1 = air_surge_ai();
    let mut v2 = AdvancedAi::new();
    v2.enable_air_surge_2();

    // With nothing standing the two versions price the launch identically.
    assert_eq!(
        v1.air_surge_launch_estimate(&game, 0),
        v2.air_surge_launch_estimate(&game, 0),
        "the first appointment costs the same under either version"
    );

    // The airfield stands and one Bomber flies.
    let first = game.player_city_ids(0)[0];
    install_ai_test_district(&mut game, first, "aerodrome");
    game.spawn_test_unit("bomber", 0, game.cities[&first].pos);
    let (v1_research, v1_production) = v1.air_surge_launch_estimate(&game, 0);
    let (v2_research, v2_production) = v2.air_surge_launch_estimate(&game, 0);
    assert_eq!(v1_research, v2_research, "the research half is untouched");
    assert!(
        v2_production < v1_production,
        "v2 prices only the missing package: {v2_production} vs {v1_production}"
    );

    // Squeeze the clock between the two estimates: the follow-up fits only
    // when the standing package is subtracted.
    let reserve = game.standard_duration(air_surge::AIR_SURGE_ENDGAME_RESERVE);
    game.max_turns = game.turn + v2_research + v2_production + reserve + 1;
    assert!(v2.air_surge_affordable(&game, 0));
    assert!(
        !v1.air_surge_affordable(&game, 0),
        "version one still prices a whole new wing and refuses the follow-up"
    );
}

/// Conquest keeps the labs: under version two a Conquest plan prices the
/// Campus (below the Encampment, so war infrastructure keeps first claim),
/// and under version one it does not.
#[test]
fn conquest_prices_the_campus_only_under_v2() {
    let mut game = Game::new(2, 32, 24, 5_414, 250, 0);
    let settler = game
        .player_unit_ids(0)
        .into_iter()
        .find(|unit| game.units[unit].kind == "settler")
        .expect("starting settler");
    game.apply(0, &Action::FoundCity { unit: settler })
        .expect("found city");
    let city = game.player_city_ids(0)[0];
    game.players[0].techs.insert(crate::name!("writing"));

    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    };
    let campus = Item::District {
        district: crate::name!("campus"),
        pos: game.cities[&city].pos,
    };

    let mut looped = AdvancedAi::new();
    looped.enable_air_surge_2();
    looped.refresh_research_weight(&game);
    let mut plain = AdvancedAi::new();
    plain.refresh_research_weight(&game);
    let counts = looped.counts(&game, 0);

    let with_loop = looped.production_value(&game, 0, city, &campus, &plan, &counts);
    let without = plain.production_value(&game, 0, city, &campus, &plan, &counts);
    assert!(
        with_loop > without,
        "the loop's Conquest window still pays for science: {with_loop} vs {without}"
    );
}

