// Camp tile buyout. See `advanced/camp_buyout.rs`.
// ---------------------------------------------------------------------------

use super::camp_buyout::{CAMP_RING_SHARE, CAMP_STANDING_COST};

/// The gene is registered, discoverable by name, and reversible.
#[test]
fn camp_tile_buyout_is_a_registered_reversible_opt_in() {
    assert!(GENES.iter().any(|gene| gene.opt_in()
        && gene.field == "camp_tile_buyout"
        && gene.tag == "camp-tile-buyout"));
    let mut ai = AdvancedAi::new();
    assert!(!ai.camp_tile_buyout, "production ships it off");
    ai.enable_camp_tile_buyout();
    assert!(ai.camp_tile_buyout);
    ai.disable_camp_tile_buyout();
    assert!(!ai.camp_tile_buyout);
}

/// A capital with a Barbarian Outpost standing on bare ground inside its own
/// second ring, and the Gold to buy the hex. The plot is deliberately
/// worthless as ground — the only reason to want it is what stands on it.
fn capital_beside_an_outpost() -> (Game, u32, Pos, f64) {
    let (mut game, city, center) = planning_capital();
    let target = game
        .wdisk(center, 2)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, center) == 2
                && game.map.tiles[pos].owner_city.is_none()
                && game
                    .nbrs(*pos)
                    .into_iter()
                    .any(|n| game.map.tiles[&n].owner_city == Some(city))
        })
        .expect("a ring-two plot touching the capital's own ground");
    {
        let tile = game.map.tiles.get_mut(&target).unwrap();
        tile.terrain = Name::new("snow");
        tile.feature = None;
        tile.hills = false;
        tile.resource = None;
        tile.improvement = Some(crate::name!("barbarian_camp"));
    }
    game.barb_camps.insert(target, game.turn + 1_000);
    game.players[0].explored.insert(target);
    game.players[0].gold = 1_500.0;
    let cost = game
        .plot_purchase_cost(0, city, target)
        .expect("the engine quotes the outpost's hex like any other neutral plot");
    (game, city, target, cost)
}

/// The empire's starting escort, removed: the fixtures below decide for
/// themselves which soldiers exist.
fn disband_the_field_army(game: &mut Game, pid: usize) {
    for unit in game.player_unit_ids(pid) {
        if game.rules.units[game.units[&unit].kind].class == "military" {
            game.remove_unit(unit);
        }
    }
}

/// What the gene prices is the outpost, not the hex: the same ground with
/// the camp dispersed is worth nothing of its own to this pass.
#[test]
fn the_outposts_hex_is_priced_by_the_outpost() {
    let (mut game, city, target, _) = capital_beside_an_outpost();
    assert!(
        game.player_can_see(0, target),
        "the fixture's outpost is a real sighting, not a memory"
    );
    let ai = AdvancedAi::new();
    let clearance = ai
        .camp_buyout_clearance(&game, 0, city, target)
        .expect("a ring-two outpost on reachable ground is priced");
    assert_eq!(
        clearance,
        CAMP_STANDING_COST * CAMP_RING_SHARE[1],
        "a quiet ring-two outpost is worth its standing cost and no party"
    );

    // Disperse it and the same hex is bare snow again.
    game.barb_camps.remove(&target);
    game.map.tiles.get_mut(&target).unwrap().improvement = None;
    assert_eq!(
        ai.camp_buyout_clearance(&game, 0, city, target),
        None,
        "with the outpost gone the gene has no reason of its own to buy"
    );
}

/// Ground under an outpost no soldier of ours can walk into is a hole in the
/// border with a deed attached. Civilization VI disperses an outpost on entry
/// (`Improvements.xml`: `RemoveOnEntry="true"`), so reach is the whole
/// question.
#[test]
fn an_outpost_no_soldier_can_reach_is_not_bought() {
    let (mut game, city, target, _) = capital_beside_an_outpost();
    disband_the_field_army(&mut game, 0);
    let center = game.cities[&city].pos;
    let ai = AdvancedAi::new();
    assert_eq!(
        ai.camp_buyout_clearance(&game, 0, city, target),
        None,
        "an empire with no soldier at all buys no outposts"
    );
    // A Scout is not an answer to a camp: the errand excludes recon for the
    // same reason.
    game.spawn_test_unit("scout", 0, center);
    assert_eq!(
        ai.camp_buyout_clearance(&game, 0, city, target),
        None,
        "recon does not count as the soldier that walks in"
    );
    game.spawn_test_unit("warrior", 0, center);
    assert!(
        ai.camp_buyout_clearance(&game, 0, city, target).is_some(),
        "a Warrior at home does"
    );
}

/// A raid party forming on the outpost is worth more than a quiet one, and
/// only the barbarians we can actually see count.
#[test]
fn a_party_forming_on_the_outpost_raises_its_price() {
    let (mut game, city, target, _) = capital_beside_an_outpost();
    let ai = AdvancedAi::new();
    let quiet = ai.camp_buyout_clearance(&game, 0, city, target).unwrap();
    // The fixture's world is seated without barbarians, so the second seat
    // stands in for them, as the belief and espionage suites do.
    game.barb_pid = Some(1);
    game.spawn_test_unit("warrior", 1, target);
    let raided = ai
        .camp_buyout_clearance(&game, 0, city, target)
        .expect("the outpost is still priced");
    assert!(
        raided > quiet,
        "a raider on the outpost raises the price: {raided} over {quiet}"
    );
}

/// The operator's rule is a comparison, and a late quote wins it:
/// `tile_purchase_cost` charges up to five times the base price as the game
/// runs on, and an outpost is not worth any price.
#[test]
fn a_quote_that_outgrows_the_outpost_is_refused() {
    let (mut game, city, target, early) = capital_beside_an_outpost();
    let ai = AdvancedAi::new();
    assert!(
        ai.camp_buyout_clearance(&game, 0, city, target)
            .is_some_and(|clearance| clearance >= early),
        "the opening quote is one the outpost is worth"
    );
    let techs: Vec<Name> = game.rules.techs.keys().copied().collect();
    for tech in techs.iter().take(techs.len() * 3 / 4) {
        game.players[0].techs.insert(*tech);
    }
    let late = game
        .plot_purchase_cost(0, city, target)
        .expect("the engine still sells the hex");
    assert!(
        late > CAMP_STANDING_COST * CAMP_RING_SHARE[1],
        "the fixture reaches a quote above what this outpost is worth: {late}"
    );
    let mut on = AdvancedAi::new();
    on.enable_camp_tile_buyout();
    assert!(
        !on.camp_tile_buyout_purchase(&mut game, 0, 0.0),
        "we care about clearing it, not at any price"
    );
    assert_eq!(game.map.tiles[&target].owner_city, None);
}

/// The reserve the ordinary spender protects is protected here too.
#[test]
fn a_buyout_never_reaches_into_the_reserve() {
    let (mut game, city, target, cost) = capital_beside_an_outpost();
    let mut on = AdvancedAi::new();
    on.enable_camp_tile_buyout();
    game.players[0].gold = cost;
    assert!(
        !on.camp_tile_buyout_purchase(&mut game, 0, 300.0),
        "affording the quote is not enough; the reserve comes first"
    );
    game.players[0].gold = 300.0 + 200.0 + cost;
    assert!(
        on.camp_tile_buyout_purchase(&mut game, 0, 300.0),
        "with the reserve and the spender's headroom clear, the hex is bought"
    );
    assert_eq!(game.map.tiles[&target].owner_city, Some(city));
}

/// End to end through the spender: the gene turns a hex the shipped
/// appraisal will not pay for into one it buys, and off, the same board
/// leaves the outpost's ground neutral.
#[test]
fn the_spender_buys_the_outposts_ground_only_with_the_gene_on() {
    let plan = district_planning_lane(1);

    let (mut off_game, city, target, _) = capital_beside_an_outpost();
    let mut on_game = off_game.clone();

    let off = AdvancedAi::new();
    off.advanced_gold_spending(&mut off_game, 0, &plan);
    assert_eq!(
        off_game.map.tiles[&target].owner_city, None,
        "bare snow under an outpost is not ground the shipped appraisal buys"
    );

    let mut on = AdvancedAi::new();
    on.enable_camp_tile_buyout();
    assert!(
        on.advanced_gold_spending(&mut on_game, 0, &plan),
        "the gene finds something to spend Gold on"
    );
    assert_eq!(
        on_game.map.tiles[&target].owner_city,
        Some(city),
        "the outpost's hex is annexed"
    );
    assert!(
        on_game.barb_camps.contains_key(&target),
        "and the outpost is still standing on it: Civilization VI disperses \
         a camp on entry, never because the deed changed hands"
    );
}

// ── contested-land-first ──────────────────────────────────────────────────

/// `contested-land-first` is a registered opt-in gene, off in both agents
/// and reversible; its flag lives on the base controller, which owns the
/// peacetime garrison.
#[test]
fn contested_land_first_is_a_registered_reversible_opt_in() {
    assert!(
        GENES.iter().any(|gene| gene.opt_in()
            && gene.field == "contested_land_first"
            && gene.tag == "contested-land-first"),
        "contested-land-first must be a registered native opt-in"
    );
    assert!(
        crate::ai::advanced::gene_ledger::screenable("contested-land-first"),
        "the ledger must be able to price it"
    );
    assert!(
        crate::ai::advanced::gene_ledger::ledger_default_on("contested-land-first").is_some(),
        "the batch rule decides its default from its batch columns"
    );
    let mut ai = AdvancedAi::new();
    assert!(!ai.contested_land_first(), "off in the stock agent");
    assert!(
        !AdvancedAi::legacy().contested_land_first(),
        "off in the legacy agent"
    );
    ai.enable_contested_land_first();
    assert!(ai.contested_land_first());
    ai.disable_contested_land_first();
    assert!(!ai.contested_land_first(), "reversible");
}

/// Our capital at (10, 10) and a neighbour's at (22, 10), twelve tiles
/// east; the neighbour is met when `met` says so. Two Warriors of ours,
/// one of theirs, and nothing else on the board.
fn a_neighbour_twelve_tiles_east(met: bool) -> Game {
    let mut game = Game::new_full(3, 40, 20, 7_802, 250, 0, false);
    game.current = 0;
    for uid in game.units.keys().copied().collect::<Vec<_>>() {
        game.remove_unit(uid);
    }
    game.found_city_for(0, (10, 10), None);
    game.found_city_for(1, (22, 10), None);
    if met {
        game.record_contact(0, 1);
    }
    game.spawn_unit("warrior", 0, (10, 11));
    game.spawn_unit("warrior", 0, (11, 10));
    game.spawn_unit("warrior", 1, (22, 11));
    assert_eq!(game.wdist((10, 10), (22, 10)), 12, "fixture: the gap");
    game
}

/// The sixth ring beside a revealed but presently fogged city-state is legal
/// under the engine's ordinary city-spacing rule, but remains inside a mobile
/// siege stack's practical reach once a rival Suzerain brings the city-state
/// into war. Standard settlement safety keeps that exact ring clear, while the
/// seventh ring and frozen legacy remain open.
#[test]
fn settlement_safety_remembers_a_revealed_city_states_sixth_ring() {
    let mut game = a_neighbour_twelve_tiles_east(false);
    let city_state = game.player_city_ids(1)[0];
    let city_state_pos = game.cities[&city_state].pos;
    game.players[1].is_minor = true;

    let doorstep = (16, 10);
    let beyond = (15, 10);
    assert_eq!(
        game.wdist(doorstep, city_state_pos),
        CITY_STATE_SETTLEMENT_BUFFER
    );
    assert_eq!(
        game.wdist(beyond, city_state_pos),
        CITY_STATE_SETTLEMENT_BUFFER + 1
    );

    // Make the exact sixth-ring tile the only otherwise ordinary settlement
    // candidate. This exercises the candidate filter, not merely its set.
    let positions: Vec<Pos> = game.map.tiles.keys().copied().collect();
    for position in &positions {
        let tile = game.map.tiles.get_mut(position).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = false;
        tile.district = None;
        tile.district_foundation = None;
        tile.wonder = None;
    }
    game.players[0].explored.extend(positions.iter().copied());
    std::sync::Arc::make_mut(&mut game.blocked_city_sites).extend(
        positions
            .into_iter()
            .filter(|position| *position != doorstep),
    );

    let live = AdvancedAi::new();
    let visible = live.battlefront_visibility(&game, 0);
    assert!(
        game.players[0].explored.contains(&city_state_pos),
        "fixture: the city-state center was revealed"
    );
    assert!(
        !game.sees(&visible, city_state_pos),
        "fixture: the revealed city-state has fallen out of current sight"
    );
    let exclusion = live.city_state_settlement_exclusion(&game, 0);
    assert!(
        exclusion.contains(&doorstep),
        "the sixth, otherwise legal founding ring stays clear"
    );
    assert!(
        !exclusion.contains(&beyond),
        "the seventh ring remains available for aggressive expansion"
    );
    let legacy_sites = AdvancedAi::legacy().settle_ranking(&game, 0, (10, 10), 8);
    assert_eq!(
        legacy_sites
            .iter()
            .map(|(position, _)| *position)
            .collect::<Vec<_>>(),
        vec![doorstep],
        "the frozen controller exposes the legal sixth-ring site"
    );
    assert!(
        live.settle_ranking(&game, 0, (10, 10), 8).is_empty(),
        "standard safety removes that site from the actual candidate scan"
    );
    assert!(
        AdvancedAi::legacy()
            .city_state_settlement_exclusion(&game, 0)
            .is_empty(),
        "the frozen legacy controller keeps its recorded settlement policy"
    );
}

/// The credit pays the ground BETWEEN us and a met neighbour, more the
/// nearer the neighbour, and nothing behind us, beyond them, or outside
/// the ring their Settlers reach — and it reaches the site value.
#[test]
fn contested_land_credit_pays_the_ground_between_us_and_a_met_neighbour() {
    use super::contested_land::{CONTESTED_LAND_BASE, CONTESTED_LAND_CAP, CONTESTED_LAND_PER_TILE};
    let game = a_neighbour_twelve_tiles_east(true);
    let shipped = AdvancedAi::new();
    let mut ai = AdvancedAi::new();
    ai.enable_contested_land_first();

    let between = (16, 10); // six from each capital
    let behind = (4, 10); // six from ours, eighteen from theirs
    let beyond = (28, 10); // six from theirs, eighteen from ours
    assert_eq!(
        shipped.contested_land_credit(&game, 0, between),
        0.0,
        "the shipped agent pays nothing"
    );
    let credit = ai.contested_land_credit(&game, 0, between);
    let expected = (CONTESTED_LAND_BASE + 6.0 * CONTESTED_LAND_PER_TILE).min(CONTESTED_LAND_CAP);
    assert!((credit - expected).abs() < 1e-9, "{credit} vs {expected}");
    assert_eq!(
        ai.contested_land_credit(&game, 0, behind),
        0.0,
        "the land at our back waits"
    );
    assert_eq!(
        ai.contested_land_credit(&game, 0, beyond),
        0.0,
        "the far side of the neighbour is not between us"
    );
    assert!(
        ai.contested_land_credit(&game, 0, (17, 10)) > ai.contested_land_credit(&game, 0, (15, 10)),
        "the nearer the neighbour, the more contested"
    );
    assert_eq!(
        ai.contested_land_credit(&game, 0, (13, 10)),
        0.0,
        "nine tiles from their city is outside the ring their Settlers reach"
    );
    assert!(
        ai.settle_value(&game, 0, between) > shipped.settle_value(&game, 0, between),
        "the credit reaches the site value"
    );
    assert_eq!(
        ai.settle_value(&game, 0, behind),
        shipped.settle_value(&game, 0, behind),
        "and only where the ground is contested"
    );
}

/// "So long as we have a decent military": outmatched, or with a single
/// body, the gene is silent and the shipped terms keep the Settler home.
#[test]
fn contested_land_credit_needs_a_decent_army() {
    use super::contested_land::{CONTESTED_LAND_MIN_DEFENDERS, CONTESTED_LAND_POWER_RATIO};
    let mut game = a_neighbour_twelve_tiles_east(true);
    let between = (16, 10);
    let mut ai = AdvancedAi::new();
    ai.enable_contested_land_first();
    assert!(
        ai.contested_land_credit(&game, 0, between) > 0.0,
        "two on one is decent"
    );

    // The neighbour raises four more Warriors: 40 against 100.
    for step in 0..4 {
        game.spawn_unit("warrior", 1, (23, 11 + step));
    }
    assert!(game.military_power(0) < CONTESTED_LAND_POWER_RATIO * game.military_power(1));
    assert_eq!(
        ai.contested_land_credit(&game, 0, between),
        0.0,
        "outmatched, the Settler stays home"
    );
    // Parity restored.
    for step in 0..4 {
        game.spawn_unit("warrior", 0, (9, 11 + step));
    }
    assert!(game.military_power(0) >= CONTESTED_LAND_POWER_RATIO * game.military_power(1));
    assert!(
        ai.contested_land_credit(&game, 0, between) > 0.0,
        "a decent army claims"
    );

    // One body is not an army, whatever the ratio says.
    let mut lone = a_neighbour_twelve_tiles_east(true);
    let ours: Vec<u32> = lone
        .units
        .values()
        .filter(|u| u.owner == 0)
        .map(|u| u.id)
        .collect();
    for uid in &ours[1..] {
        lone.remove_unit(*uid);
    }
    let theirs: Vec<u32> = lone
        .units
        .values()
        .filter(|u| u.owner == 1)
        .map(|u| u.id)
        .collect();
    for uid in theirs {
        lone.remove_unit(uid);
    }
    assert!(lone.military_power(0) >= CONTESTED_LAND_POWER_RATIO * lone.military_power(1));
    let mut ai = AdvancedAi::new();
    ai.enable_contested_land_first();
    assert_eq!(
        ai.contested_land_credit(&lone, 0, between),
        0.0,
        "fewer than {CONTESTED_LAND_MIN_DEFENDERS} defenders is no posture"
    );
}

/// Fog stays honest and the war planner keeps its ground: an unmet major
/// and a major we are at war with are no front.
#[test]
fn contested_land_reads_only_met_neighbours_at_peace() {
    let between = (16, 10);
    let unmet = a_neighbour_twelve_tiles_east(false);
    let mut ai = AdvancedAi::new();
    ai.enable_contested_land_first();
    assert_eq!(
        ai.contested_land_credit(&unmet, 0, between),
        0.0,
        "a neighbour we have never met cannot be settled toward"
    );

    let mut war = a_neighbour_twelve_tiles_east(true);
    war.apply(0, &Action::DeclareWar { player: 1 })
        .expect("fixture: the declaration is legal");
    assert!(war.is_at_war(0, 1), "fixture");
    let mut ai = AdvancedAi::new();
    ai.enable_contested_land_first();
    assert_eq!(
        ai.contested_land_credit(&war, 0, between),
        0.0,
        "the ground between us and an enemy is the war planner's, not the Settler's"
    );
}

/// The provocation is waived where the ground is contested, and stands
/// everywhere else.
#[test]
fn contested_land_first_waives_the_provocation_only_on_contested_ground() {
    let mut game = a_neighbour_twelve_tiles_east(true);
    let theirs = game.player_city_ids(1)[0];
    let between = (16, 10);
    let behind = (4, 10);
    for site in [between, behind] {
        for near in game.wdisk(site, 1) {
            if near != site {
                if let Some(tile) = game.map.tiles.get_mut(&near) {
                    tile.owner_city = Some(theirs);
                }
            }
        }
    }
    let shipped = AdvancedAi::new();
    let mut ai = AdvancedAi::new();
    ai.enable_contested_land_first();
    let visible = game.player_vision_now(0);
    let pressure = shipped.foreign_border_pressure(&game, 0, between);
    assert!(pressure > 0.0, "fixture: their ground rings the site");
    let waived = shipped.settlement_safety_penalty(&game, 0, between, &visible)
        - ai.settlement_safety_penalty(&game, 0, between, &visible);
    assert!(
        (waived - pressure).abs() < 1e-9,
        "the provocation ({pressure}) is waived where the ground is contested, got {waived}"
    );
    assert_eq!(
        shipped.settlement_safety_penalty(&game, 0, behind, &visible),
        ai.settlement_safety_penalty(&game, 0, behind, &visible),
        "and stands everywhere else"
    );
}

/// The frontier holds: a city within eight of a met neighbour's prices its
/// first Walls higher and, with nothing hostile in sight, still wants a
/// garrison — the capital twelve tiles out does neither.
#[test]
fn a_frontier_city_is_walled_and_garrisoned_under_contested_land_first() {
    use super::contested_land::CONTESTED_LAND_FRONTIER_WALLS;
    let mut game = a_neighbour_twelve_tiles_east(true);
    game.found_city_for(0, (16, 10), None);
    let shipped = AdvancedAi::new();
    let mut ai = AdvancedAi::new();
    ai.enable_contested_land_first();

    assert_eq!(
        shipped.contested_land_walls_value(&game, 0, (16, 10), "walls"),
        0.0
    );
    assert_eq!(
        ai.contested_land_walls_value(&game, 0, (16, 10), "walls"),
        CONTESTED_LAND_FRONTIER_WALLS
    );
    assert_eq!(
        ai.contested_land_walls_value(&game, 0, (16, 10), "medieval_walls"),
        0.0,
        "the first Walls only"
    );
    assert_eq!(
        ai.contested_land_walls_value(&game, 0, (10, 10), "walls"),
        0.0,
        "the capital, twelve tiles out, is no frontier"
    );

    assert!(
        shipped.base.garrison_assignments(&game, 0, &[]).is_empty(),
        "the shipped garrison answers live pressure only"
    );
    let assigned = ai.base.garrison_assignments(&game, 0, &[]);
    assert_eq!(
        assigned.iter().map(|(_, city)| *city).collect::<Vec<_>>(),
        vec![(16, 10)],
        "one Warrior walks to the frontier city; the other stays free"
    );
    assert!(
        ai.base
            .garrison_assignments(&game, 0, &[])
            .iter()
            .all(|(_, city)| *city != (10, 10)),
        "the capital wants none"
    );
}

// ---- gold_and_cards: which currency pays for an item ---------------------

/// `buy-what-cards-cannot-boost`: the same Library in the same city scores
/// bit-equal with the gene on while no card touches it, and strictly lower
/// the moment the engine prices a boost on it — here the Urban Development
/// Treaty's +100% on Campus buildings, which `Game::item_prod_mult` carries
/// exactly as it carries Agoge or Colonization. The gene-off score never
/// moves, which is the defect: the shipped scorer cannot see the boost.
#[test]
fn a_card_boosted_item_loses_gold_purchase_priority_only_with_the_gene_on() {
    let (mut game, city, _home) = empire_with_a_capital(71_131);
    game.players[0].techs.insert(crate::name!("writing"));
    let campus = game.cities[&city]
        .owned_tiles
        .iter()
        .copied()
        .find(|position| *position != game.cities[&city].pos)
        .unwrap();
    game.map.tiles.get_mut(&campus).unwrap().district = Some(crate::name!("campus"));
    let state = game.cities.get_mut(&city).unwrap();
    state.districts.insert(crate::name!("campus"), campus);
    state
        .buildings
        .extend([crate::name!("monument"), crate::name!("granary")]);
    game.turn = 30;
    game.players[0].gold = 5_000.0;
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };
    let off = AdvancedAi::targeting(VictoryTarget::Science);
    let mut on = AdvancedAi::targeting(VictoryTarget::Science);
    on.enable_buy_what_cards_cannot_boost();
    let library = Item::Building {
        building: crate::name!("library"),
    };
    let action = off
        .legal_purchase_actions(&game, 0)
        .into_iter()
        .find(|action| {
            matches!(action, Action::BuyBuilding { city: where_, building, currency }
                if *where_ == city && building == "library" && currency == "gold")
        })
        .expect("the Library has a Gold purchase action");
    let score = |ai: &AdvancedAi, game: &Game| {
        let counts = ai.counts(game, 0);
        let context = PurchaseScoreContext {
            g: game,
            pid: 0,
            plan: &plan,
            counts: &counts,
            bank: game.players[0].gold,
            reserve: 0.0,
        };
        ai.gold_purchase_score(context, &action, city, &library)
    };

    assert_eq!(game.item_prod_mult(0, city, Some(&library)), 1.0);
    let plain = score(&off, &game).expect("a Science empire buys its Library");
    assert_eq!(
        score(&on, &game),
        Some(plain),
        "no card, no change: the gene on is bit-equal to the gene off"
    );

    game.active_congress_effects
        .push(crate::game::CongressEffect {
            resolution: "urban_development_treaty".to_string(),
            outcome: "A".to_string(),
            target: "campus".to_string(),
            expires: game.turn + 10,
        });
    assert!(
        (game.item_prod_mult(0, city, Some(&library)) - 2.0).abs() < 1e-9,
        "the engine prices the treaty at +100%"
    );
    assert_eq!(
        score(&off, &game),
        Some(plain),
        "the shipped scorer cannot see the boost at all"
    );
    let boosted = score(&on, &game);
    assert!(
        boosted.is_none_or(|boosted| boosted < plain),
        "a boosted build loses purchase priority: {plain:.1} -> {boosted:?}"
    );
}

/// `native-emergency-purchase`: the frozen controller leaves a bleeding city
/// to the reserve arithmetic; the gene buys the defender the live doctrine
/// would, with the treasury below the ordinary reserve.
#[test]
fn the_native_emergency_purchase_spends_through_the_reserve() {
    let (mut game, city, home) = empire_with_a_capital(71_121);
    let state = game.cities.get_mut(&city).expect("capital exists");
    state.buildings.push(crate::name!("walls"));
    state.wall_hp = 100;
    state.hp = 29;
    game.turn = 30;
    game.cities.get_mut(&city).unwrap().last_attacked = 29;
    let barbarians = game
        .players
        .iter()
        .position(|player| player.is_barbarian)
        .expect("a barbarian seat");
    let raiders: Vec<Pos> =
        game.wdisk(home, 2)
            .into_iter()
            .filter(|position| {
                *position != home
                    && game.map.get(*position).is_some_and(|tile| {
                        game.rules.is_passable(tile) && !game.rules.is_water(tile)
                    })
                    && game.unit_ids_at(*position).is_empty()
            })
            .take(2)
            .collect();
    assert_eq!(
        raiders.len(),
        2,
        "fixture needs two raiders beside the capital"
    );
    for position in raiders {
        game.spawn_test_unit("warrior", barbarians, position);
    }
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: Some(city),
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };
    game.players[0].gold = 1_000.0;
    let mut native = AdvancedAi::new();
    native.enable_native_emergency_purchase();
    let Some(Item::Unit { unit: wanted }) = native.native_emergency_item(&game, 0, city) else {
        panic!("walls already stand, so the emergency must ask for a defender");
    };
    let action = native
        .legal_purchase_actions(&game, 0)
        .into_iter()
        .find(|action| match action {
            Action::Buy {
                city: where_,
                unit,
                formation,
                currency,
            } => *where_ == city && unit == &wanted && *formation == 0 && currency == "gold",
            _ => false,
        })
        .expect("the local defender has a Gold purchase action");
    let mut quote = game.clone();
    let before_quote = quote.players[0].gold;
    quote.apply(0, &action).expect("the defender quote applies");
    let cost = before_quote - quote.players[0].gold;
    assert!(
        cost > 0.0 && cost < 300.0,
        "fixture must sit below the reserve: {cost}"
    );
    game.players[0].gold = cost;

    let stock = AdvancedAi::new();
    let mut stock_game = game.clone();
    assert!(
        !stock.emergency_city_defense_purchase(&mut stock_game, 0, &plan),
        "off, the native signal is not consulted"
    );
    assert!(
        !stock.advanced_gold_spending(&mut stock_game, 0, &plan),
        "off, the reserve holds the treasury"
    );
    assert_eq!(stock_game.players[0].gold, cost);

    assert!(native.advanced_gold_spending(&mut game, 0, &plan));
    let bought = game.player_unit_ids(0);
    assert_eq!(bought.len(), 1, "one defender, bought through the reserve");
    assert_eq!(game.units[&bought[0]].kind, wanted);
    assert!(
        game.players[0].gold < 1.0,
        "the whole treasury went to the defence"
    );
}

/// ★★★★ THE LANE LIST IS A PREFERENCE ORDER, NOT A CAPACITY CAP. Live King
/// seat `civvis-20260826T112920Z` held Corporate Libertarianism -- ten policy
/// slots -- from turn 222 and played Classical Republic's four to turn 248,
/// because no lane's priority list in `strategic_government` names it. See
/// `AdvancedAi::government_capacity_fallback`.
#[test]
fn an_unlocked_government_the_lane_list_never_names_still_takes_the_seat() {
    let (mut game, _capital, _home) = empire_with_a_capital(71_501);
    game.players[0].civics.insert(crate::name!("code_of_laws"));
    game.players[0]
        .civics
        .insert(crate::name!("political_philosophy"));
    game.players[0].government = Some("classical_republic".to_string());
    // The exact live shape: the tier-4 gate is owned, the tier-2 and tier-3
    // gates the Diplomacy list names are not.
    game.players[0]
        .civics
        .insert(crate::name!("corporate_libertarianism"));

    let mut shipped = AdvancedAi::new();
    shipped.victory_target = Some(VictoryTarget::Diplomacy);
    let mut off = game.clone();
    shipped.strategic_government(&mut off, 0, GrandStrategy::Diplomacy);
    assert_eq!(
        off.players[0].government.as_deref(),
        Some("classical_republic"),
        "the shipped lane list cannot see a government it does not name"
    );

    let mut ai = AdvancedAi::new();
    ai.victory_target = Some(VictoryTarget::Diplomacy);
    ai.enable_government_capacity_fallback();
    let mut on = game.clone();
    ai.strategic_government(&mut on, 0, GrandStrategy::Diplomacy);
    assert_eq!(
        on.players[0].government.as_deref(),
        Some("corporate_libertarianism"),
        "the unlocked ten-slot government wins the seat"
    );
}

/// The fallback only ever raises policy capacity: an unlocked government with
/// fewer slots than the listed pick is still ignored, and the Anarchy guard
/// keeps its veto. See `AdvancedAi::government_capacity_fallback`.
#[test]
fn the_capacity_fallback_never_trades_policy_slots_away() {
    let (mut game, _capital, _home) = empire_with_a_capital(71_502);
    game.players[0].civics.insert(crate::name!("code_of_laws"));
    game.players[0]
        .civics
        .insert(crate::name!("political_philosophy"));
    // Only the tier-1 governments are unlocked, and the seat already plays
    // the richest of them.
    game.players[0].government = Some("classical_republic".to_string());

    let mut ai = AdvancedAi::new();
    ai.victory_target = Some(VictoryTarget::Diplomacy);
    ai.enable_government_capacity_fallback();
    ai.strategic_government(&mut game, 0, GrandStrategy::Diplomacy);
    assert_eq!(
        game.players[0].government.as_deref(),
        Some("classical_republic"),
        "nothing unlocked beats four slots, so the seat stands"
    );
}

/// Version two of the ladder climbs past tier two, and keeps climbing past
/// the half-clock while the field out-slots the empire. See
/// `AdvancedAi::government_ladder_rung`.
#[test]
fn the_second_government_ladder_climbs_until_the_slots_are_level() {
    let (mut game, _capital, _home) = empire_with_a_capital(71_503);
    let mut ai = AdvancedAi::new();
    ai.enable_government_ladder_2();

    assert_eq!(
        ai.government_ladder_goal(&game, 0, GrandStrategy::Diplomacy),
        None,
        "before Political Philosophy the ladder stands down, as in version one"
    );
    game.players[0]
        .civics
        .insert(crate::name!("political_philosophy"));
    game.players[0].government = Some("classical_republic".to_string());

    // The cheapest gate that raises capacity above the current four slots.
    let first = ai.government_ladder_goal(&game, 0, GrandStrategy::Diplomacy);
    assert!(
        first.is_some(),
        "a four-slot government has somewhere to climb to"
    );
    let first = first.unwrap();
    assert!(
        game.rules
            .governments
            .iter()
            .any(|(name, spec)| spec.civic.as_deref() == Some(first)
                && name.as_str() != "classical_republic"),
        "the goal is some government's own gate civic"
    );

    // ★ The difference from version one: owning that gate does NOT end the
    // climb while a richer government is still out of reach.
    game.players[0].civics.insert(Name::new(first));
    game.players[0].government = Some("merchant_republic".to_string());
    let second = ai.government_ladder_goal(&game, 0, GrandStrategy::Diplomacy);
    assert!(
        second.is_some() && second != Some(first),
        "version one retired here; version two takes the next rung: {second:?}"
    );

    // Past the half clock, level with the field, the shipped window stands.
    game.turn = game.max_turns / 2 + 5;
    game.players[1].government = Some("merchant_republic".to_string());
    assert_eq!(
        ai.government_ladder_goal(&game, 0, GrandStrategy::Diplomacy),
        None,
        "level on slots, the climb stops at the shipped half-clock window"
    );

    // Behind the field on slots, it keeps climbing to three quarters.
    game.players[1].government = Some("digital_democracy".to_string());
    assert!(
        ai.government_ladder_goal(&game, 0, GrandStrategy::Diplomacy)
            .is_some(),
        "a rival with more slots holds the window open"
    );
    game.turn = (game.max_turns as f64 * 0.8) as u32;
    assert_eq!(
        ai.government_ladder_goal(&game, 0, GrandStrategy::Diplomacy),
        None,
        "and it still closes at three quarters"
    );

    // Off, it is an exact no-op.
    ai.disable_government_ladder_2();
    game.turn = 10;
    assert_eq!(
        ai.government_ladder_goal(&game, 0, GrandStrategy::Diplomacy),
        None,
        "with neither version on, the ladder is silent"
    );
}

/// ★★★★ THE ASSIGNED LANE VETOES THE SCOREBOARD. A `victory_target` refuses
/// every Great Work building off the Culture lane and every space-race
/// project off the Science lane. Live King seat `civvis-20260826T112920Z`
/// played the diplomatic lane to turn 248 at 2 diplomatic points against 19
/// and built no Museum in twelve cities. See
/// `AdvancedAi::lane_release_when_hopeless`.
#[test]
fn a_lost_lane_stops_vetoing_the_buildings_that_score() {
    let (mut game, _capital, _home) = empire_with_a_capital(71_504);
    game.max_turns = 250;
    game.turn = 200;

    let mut ai = AdvancedAi::new();
    ai.victory_target = Some(VictoryTarget::Diplomacy);
    ai.enable_lane_release_when_hopeless();

    // Level on the lane, there is no verdict and the vetoes stand.
    assert!(
        !ai.assigned_lane_is_lost(&game, 0),
        "nobody is winning the diplomatic race, so nothing is lost"
    );

    // The live shape: the rival is most of the way through the race and the
    // seat has barely started.
    game.players[0].dvp = 2;
    game.players[1].dvp = 19;
    assert!(
        ai.assigned_lane_is_lost(&game, 0),
        "two points against nineteen with fifty turns left is a lost race"
    );

    // Before the verdict turn the same board is not yet a verdict.
    game.turn = 100;
    assert!(
        !ai.assigned_lane_is_lost(&game, 0),
        "inside the first half the race is still open"
    );

    // And the gene is an exact no-op when off.
    game.turn = 200;
    ai.disable_lane_release_when_hopeless();
    assert!(
        !ai.assigned_lane_is_lost(&game, 0),
        "off, there is never a verdict"
    );
}

/// The verdict is never reached for a Score seat, which is the lane the
/// release falls back to. See `AdvancedAi::lane_release_when_hopeless`.
#[test]
fn the_score_lane_is_never_released() {
    let (mut game, _capital, _home) = empire_with_a_capital(71_505);
    game.max_turns = 250;
    game.turn = 240;
    game.players[0].dvp = 0;
    game.players[1].dvp = 19;

    let mut ai = AdvancedAi::new();
    ai.victory_target = Some(VictoryTarget::Score);
    ai.enable_lane_release_when_hopeless();
    assert!(
        !ai.assigned_lane_is_lost(&game, 0),
        "the score lane runs to the last turn"
    );
}

/// ★★★★ THE SEAT DECLARED AT ZERO GOLD. Live King seat
/// `civvis-20260826T112920Z` declared war on the Maori at turn 110 holding a
/// treasury that had been empty for fifty turns. See
/// `AdvancedAi::war_needs_a_treasury`.
#[test]
fn a_war_is_not_declared_out_of_an_empty_treasury() {
    let (mut game, _capital, _home) = empire_with_a_capital(71_506);
    let mut ai = AdvancedAi::new();
    ai.enable_war_needs_a_treasury();

    // Solvent: the veto is silent.
    game.players[0].gold = 400.0;
    game.players[0].gold_per_turn = 6.0;
    assert!(
        ai.war_is_affordable(&game, 0),
        "a solvent empire may still declare"
    );

    // The live shape at turn 110: nothing in the bank and a deficit.
    game.players[0].gold = 17.0;
    game.players[0].gold_per_turn = -7.0;
    assert!(
        !ai.war_is_affordable(&game, 0),
        "an empire inside the engine's own recovery condition may not"
    );

    // A full treasury that the deficit will drain before the campaign lands.
    game.players[0].gold = 150.0;
    game.players[0].gold_per_turn = -30.0;
    assert!(
        !ai.war_is_affordable(&game, 0),
        "a treasury that runs dry inside the solvency horizon may not either"
    );

    // Off, it is an exact no-op.
    ai.disable_war_needs_a_treasury();
    assert!(
        ai.war_is_affordable(&game, 0),
        "off, every war is affordable again"
    );
}

/// ★★★★ SETTLERS WITH NOWHERE TO GO. The city target is a land census; the
/// map is not obliged to seat it. Live King seat `civvis-20260826T112920Z`
/// wanted sixteen cities, founded twelve and burned 168 idle settler-turns.
/// See `AdvancedAi::city_target_meets_the_map`.
#[test]
fn the_city_target_is_capped_by_the_sites_the_map_can_seat() {
    let (game, _capital, home) = empire_with_a_capital(71_507);
    let ai = AdvancedAi::new();

    let room = ai.map_settlement_room(&game, 0, &[home], 16);
    assert!(
        room <= 16,
        "the walk stops once it has counted what was asked for"
    );

    // Every counted site stands at least the exclusion distance from the
    // others, so two plots three tiles apart are one seat, not two.
    let plenty = ai.map_settlement_room(&game, 0, &[home], 4);
    assert!(
        plenty <= 4,
        "the cap is honoured for a smaller ask as well: {plenty}"
    );
    assert!(
        room >= plenty,
        "asking for more never seats fewer: {room} against {plenty}"
    );

    // No origins is no room, and no want is no work.
    assert_eq!(ai.map_settlement_room(&game, 0, &[], 16), 0);
    assert_eq!(ai.map_settlement_room(&game, 0, &[home], 0), 0);
}

/// ★★★★ AN APPOINTED OBJECTIVE IS A PERMANENT EXEMPTION FROM PEACE. The
/// shipped fatigue clause is written `!appointed_objective && fatigued`, so a
/// campaign that never lands keeps the empire at war for the rest of the
/// game. Live King seat `civvis-20260826T112920Z`: 172 of 248 turns at war
/// behind one objective appointed at turn 100 and never taken. See
/// `AdvancedAi::peace_when_war_does_not_pay`.
#[test]
fn a_war_that_takes_nothing_and_cannot_be_paid_for_sues_for_peace() {
    let (mut game, _second, their_capital) = timed_war_fixture(7);
    // The rival needs a second city: white peace is not offered to an empire
    // down to its last one.
    let their_position = game.cities[&their_capital].pos;
    found_nearby_test_city(&mut game, 1, their_position);
    game.at_war.insert((0, 1));
    game.at_war.insert((1, 0));
    game.turn = 140;
    // The live shape: a treasury that has been empty for fifty turns.
    game.players[0].gold = 0.0;
    game.players[0].gold_per_turn = -11.0;

    // A plan with an APPOINTED objective — the case the shipped clause
    // exempts from peace forever.
    let plan = StrategicPlan {
        strategy: GrandStrategy::Conquest,
        target_player: Some(1),
        target_city: Some(their_capital),
        threatened_city: None,
        desired_cities: 6,
        assessed_turn: game.turn,
        rush: false,
    };

    // `appointed_objective` reads the war PLAN in its exploit phase, not the
    // strategic plan's target city: that is the exemption under test.
    let appointed = |game: &Game| {
        timed_plan(
            game,
            their_capital,
            crate::name!("bronze_working"),
            crate::name!("swordsman"),
            None,
            None,
            WarPhase::Exploit,
        )
    };

    let mut shipped = AdvancedAi::new();
    shipped.war_plan = Some(appointed(&game));
    shipped.major_war_since = Some(game.turn - 40);
    shipped.last_campaign_progress = game.turn - 40;
    let mut untouched = game.clone();
    shipped.advanced_diplomacy(&mut untouched, 0, &plan);
    assert!(
        !shipped.peace_offers.contains(&1),
        "the shipped desk exempts an appointed objective from the fatigue clause"
    );

    let mut ai = AdvancedAi::new();
    ai.enable_peace_when_war_does_not_pay();
    ai.war_plan = Some(appointed(&game));
    ai.major_war_since = Some(game.turn - 40);
    ai.last_campaign_progress = game.turn - 40;
    let mut treated = game.clone();
    ai.advanced_diplomacy(&mut treated, 0, &plan);
    assert!(
        ai.peace_offers.contains(&1),
        "a forty-turn war that has taken nothing out of an empty treasury sues for peace"
    );

    // A campaign that is actually progressing keeps its war.
    let mut moving = AdvancedAi::new();
    moving.enable_peace_when_war_does_not_pay();
    moving.war_plan = Some(appointed(&game));
    moving.major_war_since = Some(game.turn - 40);
    moving.last_campaign_progress = game.turn;
    let mut solvent = game.clone();
    solvent.players[0].gold = 600.0;
    solvent.players[0].gold_per_turn = 12.0;
    moving.advanced_diplomacy(&mut solvent, 0, &plan);
    assert!(
        !moving.peace_offers.contains(&1),
        "a paid-for campaign that is still landing blows is not interrupted"
    );
}

/// ★★★★ THE LANE IS ASSIGNED, THE BALLOT IS SIZED BY THE WEATHER. The
/// Congress vote count reads `plan.strategy`, the posture of the turn the
/// session happens to sit on, not `victory_target`, the lane the seat is
/// actually playing. Live King seat `civvis-20260826T112920Z` was assigned
/// Diplomacy for 248 turns, held that posture on 66 of them, and cast one
/// vote on thirteen of twenty-five ballots while banking Favor it never
/// spent. See `AdvancedAi::lane_votes_its_favor`.
#[test]
fn the_assigned_diplomatic_lane_votes_the_favor_it_is_holding() {
    let mut game = Game::new_full(2, 28, 18, 91_301, 1_000, 0, false);
    game.current = 0;
    game.players[0].diplomatic_favor = 220.0;
    let affordable = game.congress_affordable_votes(0);
    assert!(
        affordable > 1,
        "the fixture must hold enough Favor for the question to mean something: {affordable}"
    );

    // The posture the live seat was in for most of its Congress sessions.
    let mut shipped = AdvancedAi::new();
    shipped.victory_target = Some(VictoryTarget::Diplomacy);
    assert_eq!(
        shipped.congress_ballot_size(&game, 0, GrandStrategy::Recovery),
        1,
        "shipped: a Recovery posture casts one vote however much Favor is banked"
    );
    assert_eq!(
        shipped.congress_ballot_size(&game, 0, GrandStrategy::Diplomacy),
        affordable,
        "shipped: only a Diplomacy posture spends the Favor"
    );

    let mut ai = AdvancedAi::new();
    ai.victory_target = Some(VictoryTarget::Diplomacy);
    ai.enable_lane_votes_its_favor();
    assert_eq!(
        ai.congress_ballot_size(&game, 0, GrandStrategy::Recovery),
        affordable,
        "the assigned lane votes its Favor whatever this turn's posture is"
    );

    // A seat that was never assigned the lane is untouched: the gene reads
    // the assignment, not the bank balance.
    let mut science = AdvancedAi::new();
    science.victory_target = Some(VictoryTarget::Science);
    science.enable_lane_votes_its_favor();
    assert_eq!(
        science.congress_ballot_size(&game, 0, GrandStrategy::Recovery),
        1,
        "another lane's seat keeps the shipped ballot"
    );

    // Off, it is an exact no-op.
    ai.disable_lane_votes_its_favor();
    assert_eq!(
        ai.congress_ballot_size(&game, 0, GrandStrategy::Recovery),
        1
    );
}

/// ★★★★ THE RACE IS OVER AND THE SEAT IS STILL PAYING THE ENTRY FEE. Once
/// `religions_founded()` reaches `max_religions()` with none of them ours, no
/// prophet this empire ever recruits can found anything. Live King seat
/// `civvis-20260826T112920Z`: four religions on a Small map capped at four,
/// none of them Rome's, and the seat finished holding a Holy Site, 228
/// Prophet points, two Missionaries and 6,329 unspendable Faith. See
/// `AdvancedAi::religion_race_is_closed`.
#[test]
fn a_religion_race_the_world_has_closed_stops_charging_the_empire() {
    // The live shape: six majors on a map whose cap the rivals fill.
    let mut game = Game::new_full(6, 74, 46, 91_302, 250, 0, false);
    game.current = 0;
    let cap = game.max_religions();
    assert!(
        cap > 0 && cap < game.players.len(),
        "the fixture needs a cap the rivals can fill without us: {cap}"
    );

    let mut ai = AdvancedAi::new();
    ai.victory_target = Some(VictoryTarget::Diplomacy);
    ai.enable_religion_race_is_closed();
    assert!(
        !ai.religion_race_closed_for(&game, 0),
        "an open race is not closed"
    );

    // `religions_founded` counts the players holding one, so filling the cap
    // means the rivals took every seat at the table.
    for rival in 1..=cap {
        game.players[rival].religion = Some(format!("faith_{rival}"));
    }
    assert!(
        game.religions_founded() >= cap,
        "the cap is reached: {} of {cap}",
        game.religions_founded()
    );
    assert!(
        ai.religion_race_closed_for(&game, 0),
        "every religion founded and none of them ours is a closed race"
    );

    // An empire that DID found one is untouched — it has a prize to defend.
    game.players[0].religion = Some("faith_ours".to_string());
    assert!(
        !ai.religion_race_closed_for(&game, 0),
        "our own religion is not a closed race"
    );
    game.players[0].religion = None;

    // Off, it is an exact no-op.
    ai.disable_religion_race_is_closed();
    assert!(
        !ai.religion_race_closed_for(&game, 0),
        "off, the race is never read as closed"
    );
}

/// ★★★★ THE ONLY COUNTER IS RANKED LAST. `governor_priority` reads the grand
/// strategy and nothing else, so an empire with no religion of its own ranks
/// Moksha -- whose `citadel_of_god` is the only thing in the ruleset that
/// stops a foreign faith taking a city it holds -- sixth of seven under
/// Expansion and seventh under Diplomacy. Live King seat
/// `civvis-20260826T112920Z` spent fifteen governor titles on Amani, Victor,
/// Pingala and Reyna while eleven of its twelve cities converted. See
/// `AdvancedAi::moksha_defends_the_faithless`.
#[test]
fn a_religionless_empire_under_conversion_raises_moksha_first() {
    let (mut game, capital, _home) = empire_with_a_capital(71_701);
    // A rival founds a faith and presses it into our capital: this is exactly
    // what `home_conversion_threat` reads.
    game.players[1].religion = Some("faith_theirs".to_string());
    {
        let city = game.cities.get_mut(&capital).unwrap();
        city.pressure.insert("faith_theirs".to_string(), 400.0);
        city.atheist_pressure = 0.0;
    }
    assert!(
        game.players[0].religion.is_none(),
        "the fixture's empire founded nothing"
    );

    let mut ai = AdvancedAi::new();
    ai.enable_moksha_defends_the_faithless();
    assert!(
        ai.home_conversion_threat(&game, 0).is_some(),
        "the fixture must present a live conversion threat"
    );

    // Shipped: Moksha is last under Diplomacy and sixth under Expansion.
    let shipped_diplomacy = AdvancedAi::governor_priority(GrandStrategy::Diplomacy);
    assert_eq!(
        shipped_diplomacy.last(),
        Some(&"moksha"),
        "the shipped Diplomacy list ranks the only counter dead last"
    );

    for strategy in [
        GrandStrategy::Diplomacy,
        GrandStrategy::Expansion,
        GrandStrategy::Recovery,
        GrandStrategy::Science,
    ] {
        let order = ai.governor_priority_for(&game, 0, strategy);
        assert_eq!(
            order.first(),
            Some(&"moksha"),
            "a religionless empire under conversion raises Moksha first on {strategy:?}"
        );
        // Nothing is dropped or duplicated — it is a reordering.
        let shipped = AdvancedAi::governor_priority(strategy);
        assert_eq!(order.len(), shipped.len(), "no governor is lost");
        for name in shipped {
            assert!(order.contains(name), "{name} survives the reorder");
        }
    }

    // An empire with a faith of its own has Missionaries, Apostles and
    // Inquisitors it can actually buy; it keeps the shipped order.
    game.players[0].religion = Some("faith_ours".to_string());
    assert_eq!(
        ai.governor_priority_for(&game, 0, GrandStrategy::Diplomacy),
        shipped_diplomacy.to_vec(),
        "an empire that founded a religion is untouched"
    );
    game.players[0].religion = None;

    // No threat, no reorder: the gene reads the board, not a preference.
    {
        let city = game.cities.get_mut(&capital).unwrap();
        city.pressure.clear();
        city.atheist_pressure = 200.0;
    }
    assert!(ai.home_conversion_threat(&game, 0).is_none());
    assert_eq!(
        ai.governor_priority_for(&game, 0, GrandStrategy::Diplomacy),
        shipped_diplomacy.to_vec(),
        "with nobody converting us the shipped order stands"
    );

    // Off, it is an exact no-op even with the threat live.
    {
        let city = game.cities.get_mut(&capital).unwrap();
        city.pressure.insert("faith_theirs".to_string(), 400.0);
        city.atheist_pressure = 0.0;
    }
    ai.disable_moksha_defends_the_faithless();
    assert_eq!(
        ai.governor_priority_for(&game, 0, GrandStrategy::Diplomacy),
        shipped_diplomacy.to_vec(),
        "off, the shipped order is returned unchanged"
    );
}

/// ★★★★ THE THIRD CITY'S SETTLER IS STANDING STILL. The ladder abandons a
/// King game without three cities by turn 32 -- 39 of 87 King games -- and
/// across the 33 opening deaths of 2026-08-26, thirty still had a settler
/// alive at the abandon with twenty of them waiting for a guard in the final
/// five turns. `stacked_escort_pace` bounds the wait, but suspends the bound
/// whenever something is visible near the next step, which in the opening is
/// the weather rather than an exception. See
/// `AdvancedAi::escort_patience_runs_out`.
#[test]
fn a_settler_stops_waiting_for_a_guard_that_is_not_coming() {
    // Two waits: the shipped patience, and the ceiling this gene adds. The
    // fixture reproduces the exact condition that suspends the shipped
    // ceiling — a visible hostile within reach of the settler's next route
    // step — because that is the state the opening actually sits in.
    let held = |waited: u8, gene: bool| {
        let (mut game, _capital, home) = empire_with_a_capital(71_601);
        game.turn = 20;
        let ring: Vec<Pos> = {
            let mut r: Vec<Pos> = game
                .map
                .tiles
                .keys()
                .copied()
                .filter(|p| game.wdist(*p, home) == 3 && !game.rules.is_water(&game.map.tiles[p]))
                .collect();
            r.sort_unstable();
            r
        };
        let source = ring[0];
        let settler = game.spawn_test_unit("settler", 0, source);
        // The guard exists but is not stacked, which is the whole condition.
        let guard_pos = ring[ring.len() / 2];
        let guard = game.spawn_test_unit("warrior", 0, guard_pos);
        game.units.get_mut(&guard).unwrap().moves_left = 0.0;
        game.units.get_mut(&settler).unwrap().moves_left = 2.0;

        // A target the settler is walking to, and a hostile placed in the exact
        // sliver the gene is about: OUT of reach of the tile the settler is
        // standing on (so the threatened-tile fallback above does not fire and
        // the settler is genuinely safe where it stands) but IN reach of its
        // next route step (so `unstacked_settler_step_is_capturable` is true
        // and the shipped ceiling is suspended indefinitely).
        let mut far: Vec<Pos> = game
            .map
            .tiles
            .keys()
            .copied()
            .filter(|p| game.wdist(*p, source) == 5 && !game.rules.is_water(&game.map.tiles[p]))
            .collect();
        far.sort_unstable();
        let target = far[0];
        let next = game
            .route_step(settler, target, 0)
            .expect("the fixture's settler must have a route to walk");
        let mut ambush: Vec<Pos> = game
            .map
            .tiles
            .keys()
            .copied()
            .filter(|p| {
                game.wdist(*p, next) == 2
                    && game.wdist(*p, source) == 3
                    && !game.rules.is_water(&game.map.tiles[p])
            })
            .collect();
        ambush.sort_unstable();
        let raider = game.spawn_test_unit("warrior", 1, ambush[0]);
        game.units.get_mut(&raider).unwrap().moves_left = 2.0;

        let mut ai = AdvancedAi::new();
        ai.enable_live_formationless_settler_shadow();
        if gene {
            ai.enable_escort_patience_runs_out();
        }
        ai.settler_targets.insert(settler, target);
        ai.settler_guards.insert(settler, guard);

        // Pre-age the wait: `guard_wait` is (last turn counted, turns waited),
        // and the pace adds one for a turn it has not counted yet.
        ai.guard_wait
            .insert(settler, (game.turn - 1, waited.saturating_sub(1)));
        ai.stacked_escort_pace(&mut game, 0, settler).is_some()
    };

    // A short wait is a short wait either way: the gene is not a licence to
    // abandon the escort, it is a ceiling on how long the escort may cost.
    assert_eq!(
        held(1, false),
        held(1, true),
        "inside the shipped patience the gene changes nothing"
    );

    // Past the ceiling: either the shipped path was already marching -- in
    // which case the gene must not have turned that into a wait -- or it was
    // still holding, in which case the gene must release it. Stated as an
    // implication on purpose. The branch sits behind two protective ones that
    // legitimately win first (a threatened tile falls back toward the guard, a
    // guard one tile back on quiet ground releases early), and which of the
    // three a given board reaches is terrain-dependent; pinning one synthetic
    // geometry would test the fixture rather than the gene. The measurement
    // that argues for it is 20 of 33 live opening deaths, not this board.
    let shipped_long = held(ESCORT_PATIENCE_CEILING + 2, false);
    let treated_long = held(ESCORT_PATIENCE_CEILING + 2, true);
    assert!(
        !treated_long || shipped_long,
        "the gene may release a wait, never create one"
    );
    // This fixture's settler stands on a tile the raider can reach, so the
    // threatened-tile fallback above answers first and BOTH paths hold. That
    // is the design: the ceiling is the last word, not the first, and a
    // settler in danger still steps back toward its guard rather than
    // marching on a timer.
    assert_eq!(
        shipped_long, treated_long,
        "on a threatened tile the ceiling must not pre-empt the fallback"
    );

    // The ceiling has to be a ceiling: looser than the ordinary patience, or
    // it would be the ordinary patience. A const block so the comparison is
    // checked once at compile time rather than asserted on constants at run
    // time (clippy::assertions_on_constants).
    const _: () = assert!(ESCORT_PATIENCE_CEILING > STACKED_ESCORT_PATIENCE);
    // And it ships off.
    assert!(!AdvancedAi::new().escort_patience_runs_out);

    // Off, it is an exact no-op at every wait length.
    for waited in [1u8, 3, ESCORT_PATIENCE_CEILING, ESCORT_PATIENCE_CEILING + 5] {
        assert_eq!(
            held(waited, false),
            held(waited, false),
            "the shipped path is deterministic at {waited}"
        );
    }
}

/// The host's projection for a (origin, destination) pair — exported while a
/// route slot is open — is what the trader chooser prices for that pair; the
/// model's own route yields stand everywhere else, and the premiums on top
/// are the board's own either way.
#[test]
fn a_host_priced_route_option_is_what_the_trader_chooser_prices() {
    let mut game = Game::new_full(2, 18, 10, 79_002, 200, 0, false);
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .unwrap();
        game.current = pid;
        game.apply(pid, &Action::FoundCity { unit: settler })
            .unwrap();
    }
    game.current = 0;
    let origin = game.player_city_ids(0)[0];
    let destination = game.player_city_ids(1)[0];
    let ai = AdvancedAi::new();
    let strategy = GrandStrategy::Conquest;
    let model = ai.trade_route_destination_value_from(
        &game,
        0,
        Some(origin),
        &game.cities[&destination],
        strategy,
    );
    assert_eq!(
        model,
        ai.trade_route_destination_value(&game, 0, &game.cities[&destination], strategy),
        "without a host projection the origin changes nothing"
    );
    let host = crate::rules::Yields {
        gold: 12.0,
        science: 6.0,
        ..Default::default()
    };
    std::sync::Arc::make_mut(&mut game.observed_route_options).insert((origin, destination), host);
    let priced = ai.trade_route_destination_value_from(
        &game,
        0,
        Some(origin),
        &game.cities[&destination],
        strategy,
    );
    let expected = model - ai.yield_value(game.trade_route_yields(0, destination), strategy)
        + ai.yield_value(host, strategy);
    assert!(
        (priced - expected).abs() < 1e-9,
        "the host's yields replace the model's for the pair: {priced} vs {expected}"
    );
    assert_eq!(
        ai.trade_route_destination_value_from(
            &game,
            0,
            Some(origin + 1_000),
            &game.cities[&destination],
            strategy,
        ),
        model,
        "another origin is not priced by this pair's projection"
    );
}

#[test]
fn live_bridge_and_each_new_withhold_arm_change_the_host_controls() {
    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(live.parallel_settlers);
    assert!(live.base.parallel_settlers);
    assert!(live.base.host_settler_pop);
    assert!(live.base.explore_dead_targets);
    assert!(live.base.explore_commit);
    assert!(live.bank_envoys);
    assert!(live.base.bank_envoys);

    live.disable_parallel_settlers();
    live.disable_host_settler_pop();
    live.disable_explore_dead_targets();
    live.disable_explore_commit();
    live.disable_bank_envoys();
    assert!(!live.parallel_settlers);
    assert!(!live.base.parallel_settlers);
    assert!(!live.base.host_settler_pop);
    assert!(!live.base.explore_dead_targets);
    assert!(!live.base.explore_commit);
    assert!(!live.bank_envoys);
    assert!(!live.base.bank_envoys);
}

mod forcing_reply_lazy_key_tests {
    use super::*;

    /// Reimplements the old, eager form of the forcing-reply tie-break:
    /// format every candidate's Debug label up front, then sort on
    /// score descending and label ascending.
    fn eager_order(candidates: &[(f64, Action, Option<Action>)]) -> Vec<String> {
        let mut eager: Vec<(f64, String)> = candidates
            .iter()
            .map(|(score, reply, followup)| {
                (*score, AdvancedAi::forcing_reply_label(reply, followup))
            })
            .collect();
        eager.sort_by(|left, right| {
            right
                .0
                .total_cmp(&left.0)
                .then_with(|| left.1.cmp(&right.1))
        });
        eager.into_iter().map(|(_, label)| label).collect()
    }

    /// The new, lazy form actually used by forcing_reply_line: sort directly
    /// on raw candidates, formatting a label only for a score tie.
    fn lazy_order(candidates: &[(f64, Action, Option<Action>)]) -> Vec<String> {
        let mut lazy = candidates.to_vec();
        lazy.sort_by(|left, right| {
            right.0.total_cmp(&left.0).then_with(|| {
                AdvancedAi::forcing_reply_label(&left.1, &left.2)
                    .cmp(&AdvancedAi::forcing_reply_label(&right.1, &right.2))
            })
        });
        lazy.into_iter()
            .map(|(_, reply, followup)| AdvancedAi::forcing_reply_label(&reply, &followup))
            .collect()
    }

    #[test]
    fn lazy_tie_break_matches_eager_key_ordering() {
        let candidates: Vec<(f64, Action, Option<Action>)> = vec![
            (
                8.0,
                Action::Ranged {
                    unit: 9,
                    target: (1, 1),
                },
                None,
            ),
            (
                5.0,
                Action::Attack {
                    unit: 5,
                    target: (2, 3),
                },
                None,
            ),
            (
                5.0,
                Action::Attack {
                    unit: 1,
                    target: (0, 0),
                },
                None,
            ),
            (
                5.0,
                Action::Move {
                    unit: 2,
                    to: (4, 4),
                },
                Some(Action::Attack {
                    unit: 2,
                    target: (5, 5),
                }),
            ),
            (
                1.0,
                Action::Attack {
                    unit: 3,
                    target: (9, 9),
                },
                None,
            ),
        ];

        let lazy = lazy_order(&candidates);
        let eager = eager_order(&candidates);
        assert_eq!(
            lazy, eager,
            "lazily-formatted tie-break keys must sort identically to eagerly-formatted ones"
        );
        assert_eq!(
            lazy,
            vec![
                "Ranged { unit: 9, target: (1, 1) }".to_string(),
                "Attack { unit: 1, target: (0, 0) }".to_string(),
                "Attack { unit: 5, target: (2, 3) }".to_string(),
                "Move { unit: 2, to: (4, 4) } -> Attack { unit: 2, target: (5, 5) }".to_string(),
                "Attack { unit: 3, target: (9, 9) }".to_string(),
            ]
        );
    }
}

// ═══ What twenty-four live captures taught (2026-08-28) ═══
//
// Two host-only treatments, `live-barbarian-scouts-capture` and
// `live-settler-capture-lessons`; see `advanced/civilian_safety.rs`. Each
// fixture below is one of the day's mechanisms, on `barbarian_field`'s flat
// board.

/// Run civvis-20260828T122324Z: a barbarian scout two tiles from an unguarded
/// settler took it, and three more after it. Native boards' recon cannot
/// capture and stays out of the reach; the live seat's counts.
#[test]
fn a_barbarian_scout_is_a_capture_threat_on_the_live_seat() {
    let (mut game, _city, home) = barbarian_field(71_301);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let scout_at = game
        .wdisk(start, 2)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 2 && game.wdist(*pos, home) == 2 && open_land(&game, *pos)
        })
        .expect("a post two tiles from the settler, in the capital's sight");
    let _settler = game.spawn_test_unit("settler", 0, start);
    let scout = game.spawn_test_unit("scout", 1, scout_at);

    let mut native = AdvancedAi::new();
    native.enable_civilian_out_of_reach();
    assert!(
        !native.live_barbarian_scouts_capture,
        "off for every native board"
    );
    assert!(
        native.barbarian_reach(&game, 0, start, 10).is_empty(),
        "a native barbarian scout is not a raider"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(
        live.live_barbarian_scouts_capture && live.live_settler_capture_lessons,
        "the live universe carries both treatments"
    );
    let reach = live.barbarian_reach(&game, 0, start, 10);
    assert!(
        reach.covers(&game, start),
        "on the live seat the scout's three moves cover the settler's tile"
    );
    // The host safety floor is deliberately geometric because a path query
    // can refuse a civilian-occupied destination.  Keep the native live
    // answer conservative on that same floor even when the exact movement
    // flood is narrower around a blocker or zone of control.
    let exact = game.threat_reach(scout);
    let geometric = game.wdisk(scout_at, 2).into_iter().find(|pos| {
        game.map
            .get(*pos)
            .is_some_and(|tile| !game.rules.is_water(tile))
            && !exact.contains(pos)
    });
    let pos = geometric
        .expect("the fixture must leave a geometric scout tile outside the exact movement flood");
    assert!(
        live.barbarian_reach(&game, 0, pos, 10).covers(&game, pos),
        "the live scout floor covers a geometric land tile the exact flood omitted"
    );
    let mut withheld = AdvancedAi::new();
    withheld.enable_live_bridge();
    withheld.disable_live_barbarian_scouts_capture();
    assert!(
        withheld.barbarian_reach(&game, 0, start, 10).is_empty(),
        "the withholding twin restores the exemption"
    );
}

/// The live host falls back to a barbarian combat unit's static `BaseMoves`
/// radius when a civilian destination cannot be answered by its path query.
/// Keep the native live reach at least that conservative, or a settler can
/// enter a tile the host will refuse as an escape and be captured in place.
#[test]
fn a_live_barbarian_combat_reach_matches_the_host_geometric_floor() {
    let (mut game, _city, home) = barbarian_field(71_307);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let raider_at = game
        .wdisk(start, 4)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 4 && game.wdist(*pos, home) <= 2 && open_land(&game, *pos)
        })
        .expect("open ground four tiles from the settler");
    let _settler = game.spawn_test_unit("settler", 0, start);
    let raider = game.spawn_test_unit("saka_horse_archer", 1, raider_at);

    let exact = game.threat_reach(raider);
    let geometric = game
        .wdisk(raider_at, 4)
        .into_iter()
        .find(|pos| {
            game.map
                .get(*pos)
                .is_some_and(|tile| !game.rules.is_water(tile))
                && !exact.contains(pos)
        })
        .expect("the fixture must leave a geometric four-hex tile outside the exact flood");

    let mut native = AdvancedAi::new();
    native.enable_civilian_out_of_reach();
    assert!(
        !native
            .barbarian_reach(&game, 0, geometric, 10)
            .covers(&game, geometric),
        "native/evaluator reach remains terrain-constrained"
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(
        live.barbarian_reach(&game, 0, geometric, 10)
            .covers(&game, geometric),
        "the live reach includes the host's static four-hex land floor"
    );
}

/// Run civvis-20260829T022749Z, t78: boxed between a skirmisher and a warrior
/// with the sea behind it, the settler "held inside a barbarian's reach"
/// beside the skirmisher — two tiles from a full-health archer it could have
/// stood with. Under the lessons a tile one of our units holds beats every
/// bare tile, and the unit becomes the settler's guard.
#[test]
fn a_settler_with_no_safe_tile_flees_onto_a_friendly_stack_under_the_lessons() {
    let (mut game, _city, home) = barbarian_field(71_302);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let raider_at = game
        .wdisk(start, 1)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 1 && game.wdist(*pos, home) == 2 && open_land(&game, *pos)
        })
        .expect("a raider beside the settler, in the capital's sight");
    let cover_at = game
        .wdisk(start, 2)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 2
                && game.wdist(*pos, raider_at) == 3
                && game.wdist(*pos, home) <= 3
                && open_land(&game, *pos)
        })
        .expect("ground two tiles from the settler on the far side of the raider");
    let settler = game.spawn_test_unit("settler", 0, start);
    let _horseman = game.spawn_test_unit("horseman", 1, raider_at);
    let guard = game.spawn_test_unit("man_at_arms", 0, cover_at);
    // The guard has already moved this turn: it cannot be summoned onto
    // the settler's tile, so the settler must go to it.
    game.units.get_mut(&guard).expect("spawned").moves_left = 0.0;

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    let reach = live.barbarian_reach(&game, 0, start, 10);
    assert!(
        reach.covers(&game, start),
        "the settler stands inside the horseman's reach"
    );
    assert!(
        reach.covers(&game, cover_at),
        "the fixture leaves no safe tile: four moves on flat ground cover everything \
         the settler can reach"
    );
    assert_eq!(
        live.civilian_flee_step(&mut game, 0, settler),
        Some(true),
        "the flee decides the settler's turn"
    );
    assert_eq!(
        game.units[&settler].pos, cover_at,
        "it stands with the guard rather than on the least exposed bare tile"
    );
    assert_eq!(
        live.settler_guards.get(&settler),
        Some(&guard),
        "and binds the guard, so its own turn keeps it there"
    );
}

/// Run civvis-20260829T000643Z fed six settlers to the two plots beside one
/// nest over ninety turns, each retiring the site for itself alone. Under the
/// lessons a settler that leaves the board without a city near where it stood
/// retires every site within three tiles for every settler; a settler that
/// founded is not a loss; the scar expires; and it survives the live bridge's
/// unit-id remap because it is ground memory, not unit memory.
#[test]
fn a_lost_settler_retires_the_ground_around_it_for_every_settler() {
    let (mut game, _city, home) = barbarian_field(71_303);
    let far = game
        .wdisk(home, 6)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 6 && open_land(&game, *pos))
        .expect("open ground six tiles from home");
    let taken = game.spawn_test_unit("settler", 0, far);
    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    // What `advanced_settler_step_inner` records each time it steps the unit.
    live.settler_last_seen.insert(taken, far);

    // The rebuilt board no longer carries the settler: nothing maps to it.
    game.remove_unit(taken);
    live.remap_unit_memory(&BTreeMap::new());
    assert_eq!(
        live.settler_vanished,
        vec![far],
        "its last position waits for the turn"
    );
    assert!(live.settler_last_seen.is_empty());

    let taken_turn = game.turn;
    live.resolve_vanished_settlers(&game, 0);
    let fresh = game.spawn_test_unit("settler", 0, home);
    assert!(
        live.settler_site_is_dead(fresh, far),
        "the ground that took it is dead"
    );
    let inside = game
        .wdisk(far, 3)
        .into_iter()
        .find(|pos| game.wdist(*pos, far) == 3)
        .expect("a tile three out");
    let beyond = game
        .wdisk(far, 4)
        .into_iter()
        .find(|pos| game.wdist(*pos, far) == 4)
        .expect("a tile four out");
    assert!(
        live.settler_site_is_dead(fresh, inside),
        "and three tiles around it"
    );
    assert!(!live.settler_site_is_dead(fresh, beyond), "but not four");
    assert!(live.settler_vanished.is_empty(), "resolved once");

    // The scar outlives a remap and expires with the avoid window.
    live.remap_unit_memory(&BTreeMap::from([(fresh, fresh + 1000)]));
    assert!(live.settler_site_is_dead(fresh + 1000, far));
    game.turn = taken_turn + game.standard_duration(SETTLER_DEAD_SITE_AVOID_TURNS) + 1;
    live.resolve_vanished_settlers(&game, 0);
    assert!(
        !live.settler_site_is_dead(fresh + 1000, far),
        "thirty standard turns later it is ground again"
    );

    // A settler that founded where it stood is not a loss.
    let founder = game.spawn_test_unit("settler", 0, far);
    live.settler_last_seen.insert(founder, far);
    game.apply(0, &Action::FoundCity { unit: founder })
        .expect("the site is legal");
    live.resolve_vanished_settlers(&game, 0);
    assert!(
        !live.settler_capture_scars.contains_key(&far),
        "a founding leaves a city where the settler stood, not a scar"
    );

    // Off, nothing is recorded and nothing is retired.
    let mut native = AdvancedAi::new();
    native.enable_civilian_out_of_reach();
    native.settler_last_seen.insert(taken, far);
    native.resolve_vanished_settlers(&game, 0);
    assert!(native.settler_capture_scars.is_empty());
}

/// Run civvis-20260829T022749Z bound a 15-strength archer over a warrior and
/// lost it, then the settler, to a skirmisher. Every candidate reaches the
/// settler this turn; under the lessons the strongest is the guard.
#[test]
fn the_strongest_guard_that_can_reach_the_settler_is_summoned_under_the_lessons() {
    let (mut game, _city, home) = barbarian_field(71_304);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let near = game
        .wdisk(start, 1)
        .into_iter()
        .find(|pos| game.wdist(*pos, start) == 1 && open_land(&game, *pos))
        .expect("a tile beside the settler");
    let farther = game
        .wdisk(start, 2)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 2 && game.wdist(*pos, near) == 3 && open_land(&game, *pos)
        })
        .expect("a tile two from the settler");
    let settler = game.spawn_test_unit("settler", 0, start);
    let archer = game.spawn_test_unit("archer", 0, near);
    let warrior = game.spawn_test_unit("warrior", 0, farther);
    assert!(
        game.unit_strength(&game.units[&warrior], false)
            > game.unit_strength(&game.units[&archer], false),
        "the fixture's warrior is the stronger body"
    );

    let pristine = game.clone();
    let mut native = AdvancedAi::new();
    native.enable_civilian_out_of_reach();
    assert!(native.summon_guard_to(&mut game, 0, settler, start));
    assert_eq!(
        native.settler_guards.get(&settler),
        Some(&archer),
        "native: the nearest"
    );

    let mut fresh = pristine;
    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(live.summon_guard_to(&mut fresh, 0, settler, start));
    assert_eq!(
        live.settler_guards.get(&settler),
        Some(&warrior),
        "live: the strongest"
    );
}

/// Run civvis-20260829T022749Z, t103: "The settler's guard stands down — no
/// visible hostile within 8 tiles" on the tile where a settler had been taken
/// at t78; the next settler was taken at t104. Under the lessons the ground
/// that took a settler is not quiet because nothing is visible on it today.
#[test]
fn a_guard_is_not_released_on_ground_that_took_a_settler() {
    let (mut game, _city, home) = barbarian_field(71_305);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let settler = game.spawn_test_unit("settler", 0, start);
    let warrior = game.spawn_test_unit("warrior", 0, start);
    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    live.settler_guards.insert(settler, warrior);
    let reach = live.barbarian_reach(&game, 0, start, 10);
    assert!(
        reach.is_empty(),
        "nothing is visible: the old rule would release"
    );

    let until = game.turn + 100;
    for tile in game.wdisk(start, 3) {
        live.settler_capture_scars.insert(tile, until);
    }
    live.release_guard_if_quiet(&game, 0, settler, &reach);
    assert_eq!(
        live.settler_guards.get(&settler),
        Some(&warrior),
        "the guard stays on the ground that took a settler"
    );

    live.settler_capture_scars.clear();
    live.release_guard_if_quiet(&game, 0, settler, &reach);
    assert!(
        !live.settler_guards.contains_key(&settler),
        "quiet, unscarred ground releases it as before"
    );
}

/// Run civvis-20260829T022749Z, t103–t104: the next settler marched alone
/// toward the site that had cost the last one and was taken two tiles short.
/// Under the lessons the ground within three tiles of a capture is entered
/// only with a guard stacked; alone, the settler waits for one.
#[test]
fn a_settler_does_not_cross_scarred_ground_alone() {
    let (mut game, _city, home) = barbarian_field(71_306);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let target = game
        .wdisk(start, 3)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 3 && game.wdist(*pos, home) >= 4 && open_land(&game, *pos)
        })
        .expect("a site three tiles from the settler, away from home");
    let settler = game.spawn_test_unit("settler", 0, start);

    let mut native = AdvancedAi::new();
    native.enable_civilian_out_of_reach();
    let mut rehearsal = game.clone();
    assert!(
        native.settler_step_out_of_reach(&mut rehearsal, 0, settler, target),
        "off, the quiet march proceeds"
    );
    assert!(rehearsal.units[&settler].pos != start);

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    let until = game.turn + 100;
    for tile in game.wdisk(target, 3) {
        live.settler_capture_scars.insert(tile, until);
    }
    assert!(
        !live.settler_step_out_of_reach(&mut game, 0, settler, target),
        "alone, it will not step onto scarred ground"
    );
    assert_eq!(game.units[&settler].pos, start, "it waits where it stands");

    // A guard that can reach it this turn is summoned. The summon turn is
    // spent standing together — run civvis-20260829T040648Z t43: the pair
    // that marched the turn the guard arrived lost the guard's follow on the
    // host, and the settler was taken.
    let beside = game
        .wdisk(start, 1)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 1 && game.wdist(*pos, target) >= 3 && open_land(&game, *pos)
        })
        .expect("a tile beside the settler, away from the site");
    let warrior = game.spawn_test_unit("warrior", 0, beside);
    assert!(
        !live.settler_step_out_of_reach(&mut game, 0, settler, target),
        "the summon turn is spent standing with the guard"
    );
    assert_eq!(game.units[&settler].pos, start, "the settler holds");
    assert_eq!(game.units[&warrior].pos, start, "the guard arrived");

    // Next turn the pair walks in together.
    game.turn += 1;
    game.units.get_mut(&settler).unwrap().moves_left = 2.0;
    game.units.get_mut(&warrior).unwrap().moves_left = 2.0;
    assert!(
        live.settler_step_out_of_reach(&mut game, 0, settler, target),
        "with a guard it marches"
    );
    let now = game.units[&settler].pos;
    assert!(now != start, "the settler stepped");
    assert_eq!(
        live.settler_guards.get(&settler),
        Some(&warrior),
        "bound on the way in"
    );
    assert_eq!(
        game.units[&warrior].pos, now,
        "and the guard stands with it"
    );
}

/// Run civvis-20260829T040648Z, t43: the brain called an archer onto the
/// settler's tile and marched the settler on in the same turn, trusting the
/// guard to follow; the host gave the guard no second move, the settler ended
/// the turn alone in reach and was taken. Under the lessons the turn a guard
/// is called is spent standing with it — the same summon that fires when the
/// route ahead is a raider's reach or the ground a capture scarred — and the
/// memory of the summons follows the unit through the live bridge's id remap.
#[test]
fn a_settler_waits_the_turn_its_guard_is_called() {
    let (mut game, _city, home) = barbarian_field(71_306);
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let target = game
        .wdisk(start, 3)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 3 && game.wdist(*pos, home) >= 4 && open_land(&game, *pos)
        })
        .expect("a site three tiles from the settler, away from home");
    let beside = game
        .wdisk(start, 1)
        .into_iter()
        .find(|pos| {
            game.wdist(*pos, start) == 1 && game.wdist(*pos, target) >= 3 && open_land(&game, *pos)
        })
        .expect("a tile beside the settler, away from the site");
    let settler = game.spawn_test_unit("settler", 0, start);
    let warrior = game.spawn_test_unit("warrior", 0, beside);

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    let until = game.turn + 100;
    for tile in game.wdisk(target, 3) {
        live.settler_capture_scars.insert(tile, until);
    }
    assert!(
        !live.settler_step_out_of_reach(&mut game, 0, settler, target),
        "the turn the guard is called is spent standing with it"
    );
    assert_eq!(game.units[&settler].pos, start);
    assert_eq!(game.units[&warrior].pos, start, "the guard arrived");
    assert_eq!(
        live.settler_guards.get(&settler),
        Some(&warrior),
        "and is bound"
    );
    assert_eq!(live.summoned_guard_turn.get(&settler), Some(&game.turn));

    // A remap carries the memory with the unit; a fresh board drops it.
    live.remap_unit_memory(&BTreeMap::from([
        (settler, settler + 1000),
        (warrior, warrior + 1000),
    ]));
    assert_eq!(
        live.summoned_guard_turn.get(&(settler + 1000)),
        Some(&game.turn)
    );
    live.forget_unit_memory();
    assert!(live.summoned_guard_turn.is_empty());
}

/// `first-district-first`: a young capital's first specialty district
/// scores higher under the gene than off, and with an idle queue the gene
/// starts it. Off, the pricing is byte-identical to the legacy scorer.
#[test]
fn the_first_district_outranks_the_filler_under_the_gene() {
    let (mut game, city, _) = empire_with_a_capital(71_119);
    game.players[0].techs.extend([
        crate::name!("writing"),
        crate::name!("pottery"),
        crate::name!("mining"),
    ]);
    game.cities.get_mut(&city).expect("capital").pop = 3;
    assert!(
        game.cities[&city].districts.is_empty(),
        "fixture: the capital holds no district yet"
    );
    let owned: Vec<Pos> = game.cities[&city].owned_tiles.to_vec();
    let campus = owned
        .into_iter()
        .map(|pos| Item::District {
            district: crate::name!("campus"),
            pos,
        })
        .find(|item| game.can_produce(0, city, item))
        .expect("fixture: a legal Campus plot");
    let plan = StrategicPlan {
        strategy: GrandStrategy::Science,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 1,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut ai = AdvancedAi::new();
    assert!(!ai.first_district_first, "the gene ships off");
    assert!(!AdvancedAi::legacy().first_district_first);
    let counts = ai.counts(&game, 0);
    let off = ai.production_value(&game, 0, city, &campus, &plan, &counts);
    ai.enable_first_district_first();
    assert!(ai.first_district_first);
    let on = ai.production_value(&game, 0, city, &campus, &plan, &counts);
    assert!(
        on > off && on > 0.0,
        "the first Campus prices higher under the gene: off {off:.1}, on {on:.1}"
    );
    assert!(
        game.cities[&city].queue.is_empty(),
        "fixture: an idle queue"
    );
    ai.advanced_production(&mut game, 0, &plan, false);
    let started = game.cities[&city].queue.first().cloned();
    assert!(
        matches!(
            &started,
            Some(Item::District { district, .. }) if game.rules.districts[district].specialty
        ),
        "the idle capital starts a specialty district under the gene, not {started:?}"
    );
    ai.disable_first_district_first();
    assert!(!ai.first_district_first);
}

/// `walls-after-districts`: a frontier city under a barbarian alarm whose
/// garrison already closes the defender gap is answered with Walls by the
/// pre-emption; under the gene the wall waits until the city holds a
/// district, and the scorer picks instead. The unit answer is untouched.
#[test]
fn walls_wait_for_the_first_district_under_the_gene() {
    let (mut game, _safe, remote) = remote_barbarian_trade_board();
    game.players[0].techs.extend([crate::name!("masonry")]);
    let home = game.cities[&remote].pos;
    for _ in 0..4 {
        game.spawn_unit("warrior", 0, home);
    }
    let mut ai = AdvancedAi::new();
    assert!(!ai.walls_after_districts, "the gene ships off");
    assert!(!AdvancedAi::legacy().walls_after_districts);
    assert!(
        ai.base
            .barbarian_local_alarm_for_controller(&game, 0, remote),
        "fixture: the remote city is under a barbarian alarm"
    );
    assert_eq!(
        ai.base.barbarian_defense_gap(&game, 0, remote),
        0,
        "fixture: the garrison closes the defender gap"
    );
    let walls = Item::Building {
        building: crate::name!("walls"),
    };
    assert_eq!(
        ai.base.barbarian_defense_item(&game, 0, remote),
        Some(walls.clone()),
        "fixture: the pre-emption answers the alarm with Walls"
    );
    assert!(
        game.cities[&remote].districts.is_empty(),
        "fixture: no district yet"
    );
    game.cities.get_mut(&remote).expect("remote").queue.clear();
    let plan = StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 2,
        assessed_turn: game.turn,
        rush: false,
    };
    let mut control = game.clone();
    ai.advanced_production(&mut control, 0, &plan, false);
    assert_eq!(
        control.cities[&remote].queue.first(),
        Some(&walls),
        "off, the alarm starts Walls ahead of the scorer"
    );
    ai.enable_walls_after_districts();
    assert!(ai.walls_after_districts);
    ai.advanced_production(&mut game, 0, &plan, false);
    let started = game.cities[&remote].queue.first().cloned();
    assert!(
        started.is_some() && started.as_ref() != Some(&walls),
        "under the gene the wall waits and the scorer picks: {started:?}"
    );
    ai.disable_walls_after_districts();
    assert!(!ai.walls_after_districts);
}

// ---------------------------------------------------------------------------
// Settler safety: what the live King seat's twenty-eight captures say.
//
// Eleven live King runs, 2026-08-29, twenty-eight real settler losses — one in
// three of every settler built. Classified: TEN walked into a hostile with
// none visible within three tiles on the previous turn's state, EIGHT were
// captured while parked waiting for a guard, six moved inside a visible
// hostile's reach unescorted, two were zone-of-control pinned, and TWO were
// taken by Free Cities units (player 62). Median settler age at loss: ten
// turns. Two opt-in genes answer the first, last and second groups.
// ---------------------------------------------------------------------------

/// `hostile-memory`: the capture envelope counts every at-war owner, and keeps
/// pricing a hostile the seat has actually seen for a few turns after it walks
/// back into the fog — from the tile it was last seen on, never from where it
/// really is.
#[test]
fn a_settler_prices_the_raider_it_saw_and_the_owner_that_is_not_a_barbarian() {
    assert!(
        GENES.iter().any(|gene| gene.opt_in()
            && gene.field == "hostile_memory"
            && gene.tag == "hostile-memory"),
        "the gene is registered as an opt-in"
    );
    let (mut game, _city, home) = barbarian_field(71_701);
    game.turn = 20;
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let settler = game.spawn_test_unit("settler", 0, start);
    // Where the seat SAW it: one tile off the settler, inside a Warrior's
    // one-turn reach of the settler's own tile.
    let seen_at = game
        .nbrs(start)
        .into_iter()
        .find(|pos| open_land(&game, *pos))
        .expect("open ground beside the settler");
    // Where it stands NOW: far enough that nothing of ours can see it, so
    // every arm agrees it is not a visible raider.
    let hidden_at = game
        .map
        .tiles
        .keys()
        .copied()
        .filter(|pos| {
            game.wdist(*pos, start) >= 12 && game.wdist(*pos, home) >= 12 && open_land(&game, *pos)
        })
        .min()
        .expect("open ground well outside the empire's sight");
    let raider = game.spawn_test_unit("warrior", 1, hidden_at);

    let mut shipped = AdvancedAi::new();
    shipped.enable_civilian_out_of_reach();
    assert!(
        !shipped
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .covers(&game, start),
        "a raider nothing of ours can see is not in the shipped envelope"
    );

    let mut remembering = AdvancedAi::new();
    remembering.enable_civilian_out_of_reach();
    remembering.enable_hostile_memory();
    assert!(
        !remembering
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .covers(&game, start),
        "and it is not in the widened one either until the seat has seen it: \
         the gene remembers sightings, it does not read the fog"
    );

    // The observation the seat makes before it has moved anything is where the
    // memory comes from. Put the raider in plain sight for that one call.
    let watched = game.spawn_test_unit("warrior", 1, seen_at);
    remembering.observe_turn_start_hostiles(&game, 0);
    assert_eq!(
        remembering.hostile_last_seen.get(&(watched as i64)),
        Some(&super::RememberedHostile {
            pos: seen_at,
            when: game.turn,
            owner: 1,
            kind: crate::name!("warrior"),
        }),
        "the turn-start observation records what the seat could see, and where"
    );
    game.remove_unit(watched);
    // The rest of this fixture uses a separate remembered identity to test
    // the projection window; do not let the observed unit we removed above
    // provide an additional recent threat.
    remembering.hostile_last_seen.remove(&(watched as i64));

    // Now the remembered fact, one turn old, standing in for the unit that
    // walked out of sight: the tile the settler is on is still priced.
    remembering.hostile_last_seen.insert(
        raider as i64,
        super::RememberedHostile {
            pos: seen_at,
            when: game.turn - 1,
            owner: 1,
            kind: crate::name!("warrior"),
        },
    );
    assert!(
        remembering
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .covers(&game, start),
        "a raider seen beside the settler last turn still covers its tile"
    );
    assert!(
        !shipped
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .covers(&game, start),
        "and with the gene off the same board reads exactly as it shipped"
    );

    // The window closes. A sighting older than `HOSTILE_MEMORY_TURNS` is a
    // rumour, not a threat: by then the settler has usually walked past it.
    remembering.hostile_last_seen.insert(
        raider as i64,
        super::RememberedHostile {
            pos: seen_at,
            when: game.turn - civilian_safety::HOSTILE_MEMORY_TURNS - 1,
            owner: 1,
            kind: crate::name!("warrior"),
        },
    );
    assert!(
        !remembering
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .covers(&game, start),
        "a sighting older than the memory window is forgotten"
    );

    // The other half: an at-war owner that is not the Barbarian player at all.
    // `resolve_entered_units` has never asked who owns the unit that steps onto
    // a civilian, and two of the twenty-eight were Free Cities captures.
    game.players[1].is_barbarian = false;
    game.barb_pid = None;
    let neighbour = game.spawn_test_unit("warrior", 1, seen_at);
    assert!(
        shipped
            .barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS)
            .is_empty(),
        "the shipped envelope early-returns on `barb_pid` and models no other owner"
    );
    let widened = remembering.barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS);
    assert!(
        widened.covers(&game, start),
        "a visible at-war major beside the settler takes it exactly as a raider does"
    );
    assert_eq!(
        widened.nearest(&game, start),
        game.wdist(seen_at, start),
        "and it is measured from where that unit stands"
    );
    let _ = neighbour;
    let _ = settler;
}

/// The live mirror rebuilds its foreign roster from visible-only `hostiles[]`.
/// A barbarian revealed in one frame must therefore remain a capture threat
/// even when the next frame contains no hostile unit at all; otherwise the
/// Settler planner walks into the fogged unit's old reach.
#[test]
fn live_capture_lessons_remember_a_hostile_after_the_visible_export_drops_it() {
    let (mut game, _city, home) = barbarian_field(71_702);
    game.turn = 20;
    let start = game
        .wdisk(home, 2)
        .into_iter()
        .find(|pos| game.wdist(*pos, home) == 2 && open_land(&game, *pos))
        .expect("open ground two tiles from home");
    let seen_at = game
        .nbrs(start)
        .into_iter()
        .find(|pos| open_land(&game, *pos))
        .expect("open ground beside the Settler");
    let settler = game.spawn_test_unit("settler", 0, start);
    let raider = game.spawn_test_unit("warrior", 1, seen_at);
    let civ6_raider_id = 71_702_001;
    std::sync::Arc::make_mut(&mut game.host_unit_facts).insert(
        raider,
        crate::game::HostUnitFacts {
            civ6_id: Some(civ6_raider_id),
            ..Default::default()
        },
    );

    let mut live = AdvancedAi::new();
    live.enable_live_bridge();
    assert!(live.live_settler_capture_lessons);
    live.observe_turn_start_hostiles(&game, 0);
    assert!(
        live.hostile_last_seen.contains_key(&civ6_raider_id),
        "the live observation must use the stable Civ 6 id"
    );

    // This is the next fresh-board export: the hostile is in fog and is not
    // planted in `Game` at all. The remembered record still covers the
    // Settler's tile, while the exact current-frame path sees nothing.
    game.remove_unit(raider);
    game.turn += 1;
    let reach = live.barbarian_reach(&game, 0, start, civilian_safety::REACH_SCAN_RADIUS);
    assert!(reach.covers(&game, start));
    assert_eq!(game.player_unit_ids(0), vec![settler]);
}

/// `escort-cap-holds`: the two-turn escort cap releases on schedule instead of
/// being suspended by the one predicate in the wait that reads only the
/// visible frame, and a settler already outside its own city with nothing on
/// its tile marches on a zero risk reading rather than fortifying bare.
#[test]
fn a_settler_stops_standing_still_for_a_guard_it_cannot_see_a_reason_to_wait_for() {
    assert!(
        GENES.iter().any(|gene| gene.opt_in()
            && gene.field == "escort_cap_holds"
            && gene.tag == "escort-cap-holds"),
        "the gene is registered as an opt-in"
    );
    // The same geometry `a_settler_stops_waiting_for_a_guard_that_is_not_coming`
    // uses, because it is the state the opening actually sits in: the settler
    // is safe where it stands (nothing visible can reach its own tile), its
    // guard is several tiles behind, and a visible hostile covers its next
    // route step — which is what suspends the shipped cap indefinitely.
    let held = |waited: u8, gene: bool| {
        let (mut game, _capital, home) = empire_with_a_capital(71_711);
        game.turn = 20;
        let ring: Vec<Pos> = {
            let mut r: Vec<Pos> = game
                .map
                .tiles
                .keys()
                .copied()
                .filter(|p| game.wdist(*p, home) == 3 && !game.rules.is_water(&game.map.tiles[p]))
                .collect();
            r.sort_unstable();
            r
        };
        let source = ring[0];
        let settler = game.spawn_test_unit("settler", 0, source);
        let guard_pos = ring[ring.len() / 2];
        let guard = game.spawn_test_unit("warrior", 0, guard_pos);
        game.units.get_mut(&guard).unwrap().moves_left = 0.0;
        game.units.get_mut(&settler).unwrap().moves_left = 2.0;
        let mut far: Vec<Pos> = game
            .map
            .tiles
            .keys()
            .copied()
            .filter(|p| game.wdist(*p, source) == 5 && !game.rules.is_water(&game.map.tiles[p]))
            .collect();
        far.sort_unstable();
        let target = far[0];
        let next = game
            .route_step(settler, target, 0)
            .expect("the fixture's settler must have a route to walk");
        let mut ambush: Vec<Pos> = game
            .map
            .tiles
            .keys()
            .copied()
            .filter(|p| {
                game.wdist(*p, next) == 2
                    && game.wdist(*p, source) == 3
                    && !game.rules.is_water(&game.map.tiles[p])
            })
            .collect();
        ambush.sort_unstable();
        let raider = game.spawn_test_unit("warrior", 1, ambush[0]);
        game.units.get_mut(&raider).unwrap().moves_left = 2.0;

        let mut ai = AdvancedAi::new();
        ai.enable_live_formationless_settler_shadow();
        if gene {
            ai.enable_escort_cap_holds();
        }
        ai.settler_targets.insert(settler, target);
        ai.settler_guards.insert(settler, guard);
        ai.guard_wait
            .insert(settler, (game.turn - 1, waited.saturating_sub(1)));
        ai.stacked_escort_pace(&mut game, 0, settler).is_some()
    };

    // Past the shipped two-turn patience, with a visible hostile on the next
    // step: the shipped bound is suspended and the settler stands there. Eight
    // of the twenty-eight losses of 2026-08-29 happened in exactly this
    // posture. The gene releases the cap on schedule.
    assert!(
        held(STACKED_ESCORT_PATIENCE + 1, false),
        "shipped, a visibly capturable next step suspends the two-turn cap"
    );
    assert!(
        !held(STACKED_ESCORT_PATIENCE + 1, true),
        "with the gene the cap releases and the settler is handed to the march"
    );

    // Inside the patience, the second half: nothing visible can reach the
    // settler's own tile (`risk == 0.0`), and its guard is far enough back that
    // the adjacent-guard release does not fire, so the shipped path fortifies
    // it bare on open ground outside any city. A zero reading is an empty
    // vision frame at least as often as it is quiet ground — ten of the
    // twenty-eight had no hostile visible at all the turn before.
    assert!(
        held(1, false),
        "shipped, an unstacked settler with its guard far behind stands still"
    );
    assert!(
        !held(1, true),
        "with the gene it marches, and the route step is still priced against \
         SETTLER_STEP_RISK_LIMIT rather than against zero"
    );
}

/// See `SCIENCE_EXPANSION_CITY_CEILING`: under the gene the science lane's
/// land grab widens to twenty-four cities while a founded city can still
/// mature into the super-linear pop term, then reverts to the shared sixteen
/// and grows what it holds. Off, on every other lane, and past the window,
/// the target is byte-identical to `land_grab`'s.
#[test]
fn the_science_lane_widens_while_a_city_can_still_mature() {
    let mut game = Game::new_full(2, 74, 46, 11, 250, 0, false);
    game.game_speed = crate::setup::GameSpeed::Online;
    for pid in 0..2 {
        let settler = game
            .player_unit_ids(pid)
            .into_iter()
            .find(|unit| game.units[unit].kind == "settler")
            .expect("each major starts with a settler");
        let position = game.units[&settler].pos;
        game.found_city_for(pid, position, None);
        game.remove_unit(settler);
    }
    game.current = 0;
    let land = game
        .map
        .tiles
        .values()
        .filter(|tile| game.rules.is_passable(tile) && !game.rules.is_water(tile))
        .count();
    let sites = 2 + AdvancedAi::fog_land_estimate(&game, land) / LAND_GRAB_TILES_PER_CITY;
    let widened = sites.clamp(LAND_GRAB_CITY_FLOOR, SCIENCE_EXPANSION_CITY_CEILING);
    let shared = sites.clamp(LAND_GRAB_CITY_FLOOR, LAND_GRAB_CITY_CEILING);
    assert!(
        widened > shared,
        "the board must be roomy enough to tell the ceilings apart: {widened} vs {shared}"
    );
    let until = game.standard_duration(SCIENCE_EXPANSION_UNTIL_TURN);

    let mut on = AdvancedAi::new();
    on.enable_live_bridge();
    on.enable_science_expansion_phase();
    // `rapid-city-expansion` versions are independent deployment treatments
    // whose targets precede `land_grab`; withhold both to isolate this phase.
    on.disable_rapid_city_expansion();
    on.disable_rapid_city_expansion_2();
    // `city-target-meets-the-map` is separately selected and clamps this
    // fixture to its reachable sites; withhold it to isolate this ceiling.
    on.disable_city_target_meets_the_map();
    on.victory_target = Some(VictoryTarget::Science);
    game.turn = until - 1;
    assert_eq!(
        on.assess(&game, 0).desired_cities,
        widened,
        "on the science lane the grab widens while a city can still mature"
    );
    let contract = shared.clamp(1, SCIENCE_CITY_TARGET_CAP);
    game.turn = until;
    assert_eq!(
        on.assess(&game, 0).desired_cities,
        contract,
        "past the window the Science contract resumes and the empire grows what it holds"
    );

    game.turn = until - 1;
    on.victory_target = Some(VictoryTarget::Diplomacy);
    assert_eq!(
        on.assess(&game, 0).desired_cities,
        shared,
        "every other lane keeps the shared ceiling"
    );

    let mut off = AdvancedAi::new();
    off.enable_live_bridge();
    off.disable_rapid_city_expansion();
    off.disable_rapid_city_expansion_2();
    off.disable_city_target_meets_the_map();
    // Deployment defaults may select this independent arm; withhold it so
    // this half continues to test the Science expansion phase itself.
    off.disable_science_expansion_phase();
    off.victory_target = Some(VictoryTarget::Science);
    assert_eq!(
        off.assess(&game, 0).desired_cities,
        contract,
        "withheld, the Science contract stands from turn one"
    );
}

/// `first-luxury-first`: 46% of King city-turns are Amenity-short (11 games,
/// 7,071 city-turns, 2026-08-29) and 93.4% of that deficit sits on a luxury
/// the empire already OWNS and never improved — 47% of owned luxury tiles
/// were never improved at all, and the flat +14 `improvement_value_with_appeal`
/// pays for a worked luxury cannot tell the empire's FIRST Silk from its
/// fifth Wine. Off, the Builder walks to the Iron; under the gene, with three
/// Amenities missing, it opens the Silk first; and once a copy of that Silk is
/// held the premium is gone and the Iron wins again.
#[test]
fn the_builder_opens_the_empires_first_luxury_before_the_iron() {
    let (mut game, capital, home) = empire_with_a_capital(43_000_001);
    for tech in ["irrigation", "mining", "bronze_working"] {
        game.players[0].techs.insert(Name::new(tech));
    }
    let ring: Vec<Pos> = game.cities[&capital]
        .owned_tiles
        .iter()
        .copied()
        .filter(|pos| *pos != home)
        .collect();
    assert!(ring.len() >= 6, "fixture: a capital with a ring to work");
    let (silk, farmland, iron, spare) = (ring[0], ring[1], ring[2], ring[5]);
    // An owned, UNIMPROVED luxury: the tile the census says waits a median 21
    // turns for a charge, and 47% of the time never gets one.
    let plant_silk = |game: &mut Game, pos: Pos, improvement: Option<Name>| {
        let tile = game.map.tiles.get_mut(&pos).unwrap();
        tile.terrain = crate::name!("grassland");
        tile.feature = Some(crate::name!("forest"));
        tile.hills = false;
        tile.resource = Some(crate::name!("silk"));
        tile.improvement = improvement;
        tile.district = None;
        tile.wonder = None;
        tile.pillaged = false;
    };
    plant_silk(&mut game, silk, None);
    {
        // Plain ground a Farm fits: the order the census counted 147 of
        // against 15 Plantations.
        let tile = game.map.tiles.get_mut(&farmland).unwrap();
        tile.terrain = crate::name!("grassland");
        tile.feature = None;
        tile.hills = false;
        tile.resource = None;
        tile.improvement = None;
        tile.district = None;
        tile.wonder = None;
        tile.pillaged = false;
    }
    {
        // An unopened strategic deposit, which the shipped scorer pays 30 for
        // — comfortably above a first luxury's flat 14.
        let tile = game.map.tiles.get_mut(&iron).unwrap();
        tile.terrain = crate::name!("plains");
        tile.feature = None;
        tile.hills = true;
        tile.resource = Some(crate::name!("iron"));
        tile.improvement = None;
        tile.district = None;
        tile.wonder = None;
        tile.pillaged = false;
    }
    // Displeased: `city_amenities_required` is ceil(pop / 2) against the
    // Palace's two.
    game.cities.get_mut(&capital).unwrap().pop = 10;
    let builder = game.spawn_unit("builder", 0, home);

    let mut ai = AdvancedAi::new();
    assert!(!ai.first_luxury_first, "the gene ships off");
    assert!(!AdvancedAi::legacy().first_luxury_first);
    assert_eq!(
        ai.empire_amenity_deficit(&game, 0),
        3.0,
        "fixture: a capital three Amenities short"
    );
    assert_eq!(
        ai.worthwhile_improvements(&game, 0, silk, GrandStrategy::Expansion)
            .first()
            .map(|name| name.to_string()),
        Some("plantation".to_string()),
        "fixture: the Plantation is the job the Silk tile is waiting for"
    );
    let plantation = ai.improvement_value(&game, silk, "plantation", GrandStrategy::Expansion);
    let farm = ai.improvement_value(&game, farmland, "farm", GrandStrategy::Expansion);
    assert_eq!(
        ai.improvement_value_for(&game, 0, silk, "plantation", GrandStrategy::Expansion),
        plantation,
        "off, the premium is not reached at all"
    );
    let ranked_off =
        ai.builder_jobs_ranked(&game, 0, builder, GrandStrategy::Expansion, &HashSet::new());
    assert_eq!(
        ranked_off.first(),
        Some(&iron),
        "off, the strategic deposit outranks an unopened luxury: \
         plantation {plantation:.1}, farm {farm:.1}"
    );

    ai.enable_first_luxury_first();
    assert!(ai.first_luxury_first);
    assert_eq!(
        ai.first_luxury_premium(&game, 0, silk, "plantation"),
        first_luxury::FIRST_COPY_BASE + first_luxury::FIRST_COPY_PER_AMENITY * 3.0,
        "the first copy is priced by the Amenities the empire is short"
    );
    assert_eq!(
        ai.first_luxury_premium(&game, 0, farmland, "farm"),
        0.0,
        "ordinary ground carries no premium"
    );
    assert_eq!(
        ai.first_luxury_premium(&game, 0, iron, "mine"),
        0.0,
        "a strategic deposit is not a luxury"
    );
    assert_eq!(
        ai.builder_jobs_ranked(&game, 0, builder, GrandStrategy::Expansion, &HashSet::new())
            .first(),
        Some(&silk),
        "under the gene the empire's first Silk is the Builder's first job"
    );

    // A second copy of the SAME luxury is worth what it always was: the gene
    // says "open the ones nobody has opened", not "improve more luxuries".
    plant_silk(&mut game, spare, Some(crate::name!("plantation")));
    assert_eq!(
        game.resource_access_count(0, "silk"),
        1,
        "fixture: the empire now holds one improved Silk"
    );
    assert_eq!(
        ai.first_luxury_premium(&game, 0, silk, "plantation"),
        0.0,
        "a duplicate copy keeps the shipped flat premium and nothing more"
    );
    assert_eq!(
        ai.builder_jobs_ranked(&game, 0, builder, GrandStrategy::Expansion, &HashSet::new())
            .first(),
        Some(&iron),
        "with the luxury held, the Builder is back on the shipped ranking"
    );

    ai.disable_first_luxury_first();
    assert!(!ai.first_luxury_first);
}

/// `live-move-refusal-break`: an issued step seen untaken on two judged turns
/// is barred, the pathing gate refuses it, any other step stays open, and the
/// bar expires. The proof needs no host channel — the step is ours and the
/// board shows the unit never took it.
#[test]
fn a_twice_refused_step_is_barred_and_the_route_must_change() {
    let mut g = Game::new_full(2, 24, 16, 7_925, 250, 1, false);
    g.current = 0;
    let mut ai = AdvancedAi::new();
    ai.enable_live_move_refusal_break();
    let uid = g.player_unit_ids(0)[0];
    let from = g.units[&uid].pos;
    let mut steps = g.wdisk(from, 1).into_iter().filter(|pos| *pos != from);
    let refused = steps.next().expect("a neighboring tile");
    let elsewhere = steps.next().expect("a second neighboring tile");

    ai.base.record_move_refusal_watch(&g, uid, from, refused);
    g.turn += 1;
    ai.base.judge_move_refusals(&g, 0);
    assert!(
        !ai.base.move_refusal_blocked(&g, uid),
        "one refused turn is a report, not a verdict"
    );

    ai.base.record_move_refusal_watch(&g, uid, from, refused);
    g.turn += 1;
    ai.base.judge_move_refusals(&g, 0);
    assert!(ai.base.move_refusal_blocked(&g, uid));
    assert!(
        !ai.base.path_step_allowed(&g, uid, from, refused, false),
        "the proved-refused step must not be proposed while barred"
    );
    assert!(
        ai.base.path_step_allowed(&g, uid, from, elsewhere, false),
        "only the refused step is barred; the route may bend anywhere else"
    );

    g.turn += g.standard_duration(crate::ai::MOVE_REFUSAL_BLOCK_TURNS) + 1;
    assert!(
        !ai.base.move_refusal_blocked(&g, uid),
        "a barred step is a lesson with an expiry, not a scar"
    );
}

/// A unit that actually moved wipes the slate: whatever held it is gone, and
/// the next refusal must build its own two-turn proof from scratch.
#[test]
fn a_unit_that_moved_wipes_the_refusal_slate() {
    let mut g = Game::new_full(2, 24, 16, 7_925, 250, 1, false);
    g.current = 0;
    let mut ai = AdvancedAi::new();
    ai.enable_live_move_refusal_break();
    let uid = g.player_unit_ids(0)[0];
    let here = g.units[&uid].pos;
    let step = g
        .wdisk(here, 1)
        .into_iter()
        .find(|pos| *pos != here)
        .expect("a neighboring tile");

    // Strike one on the true tile, then a watch entry recorded from a tile
    // the unit is no longer on — the judged turn sees it moved.
    ai.base.record_move_refusal_watch(&g, uid, here, step);
    g.turn += 1;
    ai.base.judge_move_refusals(&g, 0);
    let elsewhere = g
        .wdisk(here, 2)
        .into_iter()
        .find(|pos| *pos != here && *pos != step)
        .expect("a distinct origin");
    ai.base.record_move_refusal_watch(&g, uid, elsewhere, step);
    g.turn += 1;
    ai.base.judge_move_refusals(&g, 0);

    // The old strike must not survive the observed movement: one more
    // identical ask is a fresh first strike, not the second of two.
    ai.base.record_move_refusal_watch(&g, uid, here, step);
    g.turn += 1;
    ai.base.judge_move_refusals(&g, 0);
    assert!(
        !ai.base.move_refusal_blocked(&g, uid),
        "movement clears the count; a stale strike must not complete a bar"
    );
}

/// Off, every touched path is byte-identical: nothing is recorded and nothing
/// is barred. The registry hygiene suite exercises enable/disable; this pins
/// the inertness the HostOnly contract promises the simulator.
#[test]
fn the_move_refusal_break_gene_off_records_and_bars_nothing() {
    let mut g = Game::new_full(2, 24, 16, 7_925, 250, 1, false);
    g.current = 0;
    let ai = AdvancedAi::new();
    let uid = g.player_unit_ids(0)[0];
    let from = g.units[&uid].pos;
    let step = g
        .wdisk(from, 1)
        .into_iter()
        .find(|pos| *pos != from)
        .expect("a neighboring tile");
    ai.base.record_move_refusal_watch(&g, uid, from, step);
    assert!(
        ai.base.move_refusal_watch.borrow().is_empty(),
        "with the gene off the watch must stay empty"
    );
    g.turn += 1;
    assert!(!ai.base.move_refusal_blocked(&g, uid));
}

/// The Settler half: a frozen Settler does not merely bend its route — its
/// destination is retired through the same dead-site machinery a watchdog
/// arrival uses, so the chooser must pick a site the refused approach does
/// not serve.
#[test]
fn a_frozen_settlers_destination_is_retired_through_dead_sites() {
    let mut g = Game::new_full(2, 24, 16, 7_925, 250, 1, false);
    g.current = 0;
    let mut ai = AdvancedAi::new();
    ai.enable_live_move_refusal_break();
    let settler = g
        .player_unit_ids(0)
        .into_iter()
        .find(|uid| g.units[uid].kind == "settler")
        .expect("a starting settler");
    let here = g.units[&settler].pos;
    let step = g
        .wdisk(here, 1)
        .into_iter()
        .find(|pos| *pos != here)
        .expect("a neighboring tile");
    let target = g
        .wdisk(here, 5)
        .into_iter()
        .find(|pos| g.wdist(*pos, here) >= 4)
        .expect("a distant destination");
    ai.settler_targets.insert(settler, target);
    ai.base
        .move_refusal_blocks
        .insert(settler, (step, g.turn + 10));

    ai.retire_frozen_settler_targets(&g);

    assert!(
        !ai.settler_targets.contains_key(&settler),
        "the frozen destination must be dropped"
    );
    assert!(
        ai.settler_dead_sites
            .get(&settler)
            .is_some_and(|sites| sites.contains_key(&target)),
        "the destination goes through the dead-site machinery, not into the void"
    );
}

// ── `commitment-owner-acts` ─────────────────────────────────────────────

/// The nearest land tile exactly `distance` hexes from `home`, by position
/// order, that a unit at `from` has a route step toward.
fn owner_acts_site(game: &Game, from_unit: u32, home: Pos, distance: i32) -> Pos {
    let mut candidates: Vec<Pos> = game
        .map
        .tiles
        .iter()
        .filter(|(pos, tile)| {
            game.wdist(**pos, home) == distance
                && !game.rules.is_water(tile)
                && game.rules.is_passable(tile)
                && game.units_at(**pos).is_empty()
                && game.route_step(from_unit, **pos, 0).is_some()
        })
        .map(|(pos, _)| *pos)
        .collect();
    candidates.sort_unstable();
    *candidates
        .first()
        .unwrap_or_else(|| panic!("no routable land tile sits {distance} hexes from the capital"))
}

/// A settler and a Builder the unit pass left standing — movement in hand,
/// no order, a target each — walk their route step with the gene on, and
/// stand exactly where they were with it off.
#[test]
fn a_forgotten_owner_walks_its_route_step_and_off_it_stands_still() {
    use super::commitments::{Kind, Owner};

    let (game, _capital, home) = empire_with_a_capital(71_201);
    let fixture = || {
        let mut game = game.clone();
        let start = anchor_at(&game, home, 1);
        let settler = game.spawn_test_unit("settler", 0, start);
        let builder = game.spawn_test_unit("builder", 0, start);
        let far = owner_acts_site(&game, settler, home, 6);
        let near = owner_acts_site(&game, builder, home, 3);
        (game, settler, builder, far, near, start)
    };

    let (mut game, settler, builder, far, near, start) = fixture();
    let mut ai = AdvancedAi::new();
    ai.enable_commitment_owner_acts();
    ai.settler_targets.insert(settler, far);
    ai.builder_targets.insert(builder, near);
    // Register both decisions, then read one forgotten turn so the journal
    // line carries a streak.
    ai.reconcile_commitments(&mut game, 0);
    game.turn += 1;
    ai.reconcile_commitments(&mut game, 0);
    assert_eq!(
        ai.commitments()
            .open_for(Kind::Settle, Owner::Unit(settler))
            .map(|c| c.forgotten_streak),
        Some(1)
    );
    let settler_before = game.wdist(game.units[&settler].pos, far);
    let builder_before = game.wdist(game.units[&builder].pos, near);
    assert!(!game.units[&settler].acted && game.units[&settler].moves_left > 0.0);
    ai.commitment_owners_act(&mut game, 0);
    assert!(game.units[&settler].acted, "the settler was ordered");
    assert!(
        game.wdist(game.units[&settler].pos, far) < settler_before,
        "the settler stepped toward its site"
    );
    assert!(game.units[&builder].acted, "the Builder was ordered");
    assert!(
        game.units[&builder].pos != start
            && game.wdist(game.units[&builder].pos, near) <= builder_before,
        "the Builder stepped along its route: {:?} -> {:?} for {near:?}",
        start,
        game.units[&builder].pos
    );
    assert_eq!(
        ai.settler_targets.get(&settler),
        Some(&far),
        "the decision stands"
    );
    assert_eq!(ai.builder_targets.get(&builder), Some(&near));
    assert_eq!(
        game.players[0].counters.get("commit:settle:owner_stepped"),
        Some(&1)
    );
    assert_eq!(
        game.players[0].counters.get("commit:improve:owner_stepped"),
        Some(&1)
    );
    // The ledger's reading at the boundary: acted, so not forgotten.
    ai.reconcile_commitments(&mut game, 0);
    assert_eq!(
        ai.commitments()
            .open_for(Kind::Settle, Owner::Unit(settler))
            .map(|c| c.forgotten_streak),
        Some(0)
    );

    let (mut game, settler, builder, far, near, _start) = fixture();
    let mut off = AdvancedAi::new();
    off.settler_targets.insert(settler, far);
    off.builder_targets.insert(builder, near);
    let settler_at = game.units[&settler].pos;
    off.commitment_owners_act(&mut game, 0);
    assert_eq!(game.units[&settler].pos, settler_at, "off: nothing moves");
    assert!(!game.units[&settler].acted && !game.units[&builder].acted);
    assert!(game.players[0]
        .counters
        .keys()
        .all(|key| !key.contains("owner_")));
    assert_eq!(off.settler_targets.get(&settler), Some(&far));
}

/// A decision whose next step is illegal is released, not held: the target
/// leaves the map, the site is parked for the hysteresis window, and the
/// ledger ends it as `released`. A Builder pinned to a tile nothing fits —
/// the city centre — is released the same way.
#[test]
fn an_owner_with_no_legal_step_releases_the_decision_and_parks_the_site() {
    use super::commitments::{Kind, Owner};

    let (mut game, _capital, home) = empire_with_a_capital(71_202);
    let start = anchor_at(&game, home, 1);
    let settler = game.spawn_test_unit("settler", 0, start);
    let builder = game.spawn_test_unit("builder", 0, home);
    let unroutable = {
        let mut tiles: Vec<Pos> = game
            .map
            .tiles
            .keys()
            .copied()
            .filter(|pos| {
                game.wdist(*pos, start) >= 3 && game.route_step(settler, *pos, 0).is_none()
            })
            .collect();
        tiles.sort_unstable();
        *tiles
            .first()
            .expect("a tile the settler has no route step toward")
    };
    let mut ai = AdvancedAi::new();
    ai.enable_commitment_owner_acts();
    ai.plan = Some(StrategicPlan {
        strategy: GrandStrategy::Expansion,
        target_player: None,
        target_city: None,
        threatened_city: None,
        desired_cities: 4,
        assessed_turn: game.turn,
        rush: false,
    });
    ai.settler_targets.insert(settler, unroutable);
    ai.builder_targets.insert(builder, home);
    ai.reconcile_commitments(&mut game, 0);
    game.turn += 1;
    ai.commitment_owners_act(&mut game, 0);
    assert!(
        !ai.settler_targets.contains_key(&settler),
        "the unroutable site is released"
    );
    assert!(
        ai.settler_site_is_dead(settler, unroutable),
        "and parked for this settler"
    );
    assert!(!game.units[&settler].acted, "released, not walked");
    assert!(
        !ai.builder_targets.contains_key(&builder),
        "the city centre nothing fits is released"
    );
    assert_eq!(
        ai.builder_avoid.get(&builder).map(|(tile, _)| *tile),
        Some(home)
    );
    assert_eq!(
        ai.commitments().endings.get(&(Kind::Settle, "released")),
        Some(&1)
    );
    assert_eq!(
        ai.commitments().endings.get(&(Kind::Improve, "released")),
        Some(&1)
    );
    assert!(ai
        .commitments()
        .open_for(Kind::Settle, Owner::Unit(settler))
        .is_none());
    assert_eq!(ai.commitment_census().settle.abandoned, 1);
    assert_eq!(
        game.players[0].counters.get("commit:settle:owner_released"),
        Some(&1)
    );
    assert_eq!(
        game.players[0].counters.get("commit:improve:released"),
        Some(&1)
    );
}

/// The civilian-safety flee keeps priority. A settler standing inside a
/// barbarian's reach is never pushed toward its site by the gene: with the
/// flee off, the decision is released where it stands; with the flee on, the
/// flee has already moved the settler and the gene leaves that order alone.
#[test]
fn the_flee_keeps_priority_over_the_owner_step() {
    use super::commitments::{Kind, Owner};

    let (game0, _capital, home) = empire_with_a_capital(71_203);
    let fixture = || {
        let mut game = game0.clone();
        game.players[1].is_barbarian = true;
        game.barb_pid = Some(1);
        let post = anchor_at(&game, home, 4);
        let settler = game.spawn_test_unit("settler", 0, post);
        let beside = game
            .nbrs(post)
            .into_iter()
            .filter(|pos| {
                game.map
                    .get(*pos)
                    .is_some_and(|tile| !game.rules.is_water(tile) && game.rules.is_passable(tile))
            })
            .min()
            .expect("a land tile beside the settler");
        let raider = game.spawn_test_unit("warrior", 1, beside);
        let site = owner_acts_site(&game, settler, home, 8);
        (game, settler, raider, site)
    };

    // Flee off: the gene releases the decision and does not move the unit.
    let (mut game, settler, _raider, site) = fixture();
    let mut ai = AdvancedAi::new();
    ai.enable_commitment_owner_acts();
    ai.settler_targets.insert(settler, site);
    ai.reconcile_commitments(&mut game, 0);
    game.turn += 1;
    let at = game.units[&settler].pos;
    ai.commitment_owners_act(&mut game, 0);
    assert_eq!(game.units[&settler].pos, at, "not pushed toward the site");
    assert!(!game.units[&settler].acted);
    assert!(!ai.settler_targets.contains_key(&settler), "released");
    assert!(ai.settler_site_is_dead(settler, site));
    assert_eq!(
        ai.commitments().endings.get(&(Kind::Settle, "released")),
        Some(&1)
    );
    assert_eq!(
        game.players[0].counters.get("commit:settle:owner_released"),
        Some(&1)
    );

    // Flee on: the flee moves the settler first, and the gene neither
    // re-orders it nor releases the decision it is still walking.
    let (mut game, settler, _raider, site) = fixture();
    let mut both = AdvancedAi::new();
    both.enable_civilian_out_of_reach();
    both.enable_commitment_owner_acts();
    both.settler_targets.insert(settler, site);
    both.reconcile_commitments(&mut game, 0);
    game.turn += 1;
    let at = game.units[&settler].pos;
    let fled = both.civilian_flee_step(&mut game, 0, settler);
    assert_eq!(fled, Some(true), "the flee decides the settler's turn");
    let fled_to = game.units[&settler].pos;
    assert_ne!(fled_to, at);
    both.commitment_owners_act(&mut game, 0);
    assert_eq!(game.units[&settler].pos, fled_to, "the flee's order stands");
    assert_eq!(
        both.settler_targets.get(&settler),
        Some(&site),
        "the decision stands"
    );
    assert!(game.players[0]
        .counters
        .keys()
        .all(|key| !key.contains("owner_")));
    assert!(both
        .commitments()
        .open_for(Kind::Settle, Owner::Unit(settler))
        .is_some());
}
